window.kbParts["entries-ac82d8098cad04dc"] = {"nodes":{"k-76f3ab01b88b79f9":{"review":{"title":"制度型开放","type":"概念与词义","definition":"制度型开放是通过推动国内外规则、规制、管理和标准相通相容来扩大对外开放，涉及贸易、投资、金融等领域。","explanation":"党的二十届三中全会《决定》（2024年）提出，主动对接国际高标准经贸规则，在产权保护、产业补贴、政府采购、电子商务等领域打造透明稳定可预期的制度环境。商品和要素流动型开放着眼于商品、资本、劳动力等的跨境流动，制度型开放着眼于规范这些活动的制度安排。","basis":"据关联原题及所列出处编释。","references":[{"source":"reform","location":"稳步扩大制度型开放"},{"source":"web-21837864c10860b7","location":"行业篇“金融服务业外商投资发展情况”，第42页“取消外资持股比例限制”","quote":"全面取消金融服务业领域对外资的准入限制"},{"source":"web-5683460e7c2a818a","location":"第四十章第一节","quote":"稳妥推进银行、证券、保险、基金、期货等金融领域开放"}],"domain":"经济","examFocus":{"政治理论必刷100题#13":"核对制度型开放涉及哪些制度安排，并与市场准入、多边贸易体制及自贸试验区建设的部署相区分。","政治理论必刷100题#17":"区分开放所涉及的对象和实现开放的方式，核对规则、规制、管理和标准所对应的政策用语。","政治理论必刷100题#35":"从开放政策、消费群体、利用外资制度和社会环境四方面核对外商来华投资的条件。","政治理论必刷100题#31":"把自主开放、单边开放和制度型开放的表述，与外贸发展、自贸区网络及境外经贸合作的部署分别核对。","政治理论必刷100题#42":"区分制度型开放的重点举措与高水平开放的国内经济条件，并核对西部开发与开放的政策关系。","国考 2025 副省级 行测#12":"按党的二十届三中全会部署，分别核对经贸规则对接的方向、市场开放范围和全球经济治理举措。","江苏 2024 B类 行测#2":"区分开放方式的转变、外资准入措施和营商环境建设，核对题中各项表述的适用范围。"}},"aspects":[{"title":"规则、规制、管理和标准的开放","uses":[{"unit":"Q1","role":"直接考查","use":"本题的④把规则、规制、管理和标准纳入制度型开放，符合2025年3月28日会见国际工商界代表时的讲话。①②④正确，选A。","evidence":"④对外开放是中国的基本国策，中国正在推进高水平对外开放，稳步扩大规则、规制、\n\n管理、标准等制度型开放","qids":["政治理论必刷100题#13"]},{"unit":"Q2","role":"解题依据","use":"本题的D项把2025年3月28日讲话中的“制度型开放”写成“要素型开放”，因此排除D。本题选C。","evidence":"故“要素型开放”表述错误，应为“制度型开放”。","qids":["政治理论必刷100题#17"]},{"unit":"Q4","role":"直接考查","use":"本题以2025年3月28日会见国际工商界代表时的讲话为背景，将稳步扩大制度型开放列入外商来华投资的政策环境。①④正确，选B。","evidence":"①对外开放是中国的基本国策，中国正在推进高水平对外开放，稳步扩大制度型开放","qids":["政治理论必刷100题#35"]}]},{"title":"高水平对外开放部署","uses":[{"unit":"Q3","role":"直接考查","use":"本题的①把有序扩大自主开放和单边开放、稳步扩大制度型开放并列，符合解析所引2025年2月15日《人民日报》的表述。①③④正确，选D。","evidence":"有序扩大自主开放和单边开放，稳步扩大制度型开放","qids":["政治理论必刷100题#31"]},{"unit":"Q5","role":"解题依据","use":"本题的B项符合2023年7月11日中央全面深化改革委员会第二次会议关于建设更高水平开放型经济新体制的部署，这项部署以制度型开放为重点。题目要求选择不正确的一项，所给答案为A，解析末句将正确表述归结为“以大开放促进大开发”。","evidence":"以制度型开放为重点，聚焦投资、贸易、金融、创\n\n新等对外交流合作的重点领域深化体制机制改革","qids":["政治理论必刷100题#42"]}]},{"title":"二十届三中全会的具体举措","uses":[{"unit":"Q6","role":"直接考查","use":"本题均要求选择不恰当的举措，三卷均选A。《决定》要求主动对接国际高标准经贸规则，A项主张构建不同于国际经贸规则的体系。B、C、D分别对应有序扩大有关市场开放、参与全球经济治理和扩大对最不发达国家单边开放。","evidence":"主动对接国际高标准经贸规则","qids":["国考 2025 副省级 行测#12","国考 2025 地市级 行测#12","国考 2025 行政执法 行测#12"]}]},{"title":"开放方式的转变","uses":[{"unit":"Q7","role":"直接考查","use":"本题的④将开放方向写成“推动要素流动开放向管理标准开放转变”。题附解析引用的2020年中央文件表述为由商品和要素流动型开放向规则等制度型开放转变。所给答案A纳入①②③。就①而言，《中国外商投资报告2023》所述的取消限制有明确范围，指2020年版外资准入负面清单中的金融服务业外资准入限制。“十四五”规划纲要对银行、保险等金融领域开放使用“稳妥推进”。据此可确认外资准入方面的具体开放措施，①将其概括为“促进金融保险业的全面开放”能否判对仍待核实。","evidence":"推动由商品和要素流动型开放向规则等制度型开\n\n放转变","qids":["江苏 2024 B类 行测#2"]}]}],"sources":[{"id":"31699340f47012e7","label":"制度型开放","topic":"产业、科技与对外开放","category":"非时政","text":"1.制度型开放\n“制度型开放”是 2018 年中央经济工作会议关于开放的新表述。会议要求，推动全方\n位对外开放。要适应新形势、把握新特点，推动由商品和要素流动型开放向规则等制度型开\n放转变。党的十九届四中全会、二十大、二十届三中全会以及第十四届全国人民代表大会\n《2025 年国务院政府工作报告》均强调“稳步扩大制度型开放”。\n制度型开放的核心要义是通过系统性、高质量的制度供给，增强开放的包容性、兼容\n性和可预期性，为各类市场主体营造稳定公平的发展环境。制度型开放为国家治理现代化提\n供了外部动力与实践路径，通过对接国际高标准规则倒逼国内制度改革创新，破解治理体系\n中的堵点难点","source":{"doc":"6cbfb01fe723bba64b75","first":31,"last":31,"page":31,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-6e663bb030341b18":{"review":{"title":"国内大循环","type":"概念与词义","definition":"国内大循环是国民经济的生产、分配、交换、消费等环节在国内相互衔接、持续运行所形成的经济循环。它是国内国际双循环相互促进的新发展格局的主体。","explanation":"畅通国内大循环有赖于各环节协同发力，使生产要素在各环节有机衔接、循环流转。党的二十大报告提出，依托我国超大规模市场优势，以国内大循环吸引全球资源要素，增强国内国际两个市场两种资源联动效应。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"加快构建新发展格局"}],"related":["k-0a6da28c772630a4"],"domain":"经济","examFocus":{"政治理论必刷100题#21":"核对高水平对外开放的相关表述，区分吸引全球资源要素的依托与国内国际市场之间的联动。","政治理论必刷100题#29":"辨别新发展格局中的因果关系，分清哪一循环的畅通带来对全球资源要素吸引力的增强。"}},"aspects":[{"title":"国内循环对全球资源要素的吸引","uses":[{"unit":"Q1","role":"解题依据","use":"④将党的二十大报告中吸引全球资源要素所依托的国内大循环写成国际大循环，因而不能列入正确组合。","evidence":"依托我国超大规模市场优势，以国内大循环吸引全球资源要素","qids":["政治理论必刷100题#21"]},{"unit":"Q2","role":"直接考查","use":"题目要求选出关于新发展格局的不正确表述。2020年《求是》刊载的《国家中长期经济社会发展战略若干重大问题》将全球资源要素吸引力的增强与国内循环更加顺畅相联系。A项把这里的国内循环写成国际循环，因此选A。","evidence":"国内循环越顺畅，越能形成对全球资源要素的引力场","qids":["政治理论必刷100题#29"]}]}],"sources":[{"id":"b524569d860543e7","label":"国内大循环","topic":"经济指标与宏观调控","category":"非时政","text":"1.国内大循环\n面对外部环境的不确定性，习近平总书记提出的“以国内大循环为主体、国内国际双循\n环相互促进”的新发展格局，既是应对全球治理体系变革的战略选择，更是发挥大国经济内\n生优势的必然要求。做强国内大循环，就是将发展的立足点牢牢置于扩大内需战略基点。","source":{"doc":"6cbfb01fe723bba64b75","first":17,"last":17,"page":17,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-07ef47dc10f156ad":{"review":{"title":"新质生产力","type":"概念与词义","definition":"新质生产力是由创新主导，具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态。","explanation":"新质生产力由技术革命性突破、生产要素创新性配置和产业深度转型升级催生，以全要素生产率大幅提升为核心标志。科技创新成果应用于产业，可以改造提升传统产业，也可以培育壮大新兴产业、布局建设未来产业。","basis":"据关联原题及所列出处编释。","references":[{"source":"new","location":"新质生产力的基本内涵"},{"source":"web-6d5bb8ed851267ee","location":"2023年9月8日听取黑龙江省委和省政府工作汇报后，关于以科技创新引领产业全面振兴的段落","quote":"整合科技创新资源，引领发展战略性新兴产业和未来产业，加快形成新质生产力。"}],"related":["k-9b15547988c8ddb9","k-0b5dc68bbfc10583"],"examFocus":{"政治理论必刷100题#25":"辨明新质生产力的基本特征及其与新发展理念的关系，分清生产力质态与发展政策目标。","江苏 2024 B类 行测#3":"区分新质生产力的形成动力与产业发展路径，辨别各项表述把二者放在什么位置。","政治理论必刷100题#50":"对照“十五五”谋划部署，辨清总体发展要求、根本价值取向和摆在突出位置的战略任务。","江苏 2025 A类 申论#4":"从文博会、文创项目和青年创业服务中选取事例，论证文化创新经过哪些环节转化为产业发展动能。"}},"aspects":[{"title":"基本内涵与特征","uses":[{"unit":"Q1","role":"直接考查","use":"本题依据2024年1月31日二十届中央政治局第十一次集体学习讲话，判定①所列高科技、高效能、高质量特征及其与新发展理念的关系正确。①与③④合计三项，选C。","evidence":"新质生产力具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态","qids":["政治理论必刷100题#25"]}]},{"title":"创新驱动与产业转型","uses":[{"unit":"Q3","role":"直接考查","use":"本题以2023年9月黑龙江考察为背景。所给答案A认可生产力跃迁、符合高质量发展要求、以创新驱动为关键三项，排除④。同期讲话在部署传统制造业升级的同时，提出整合科技创新资源、引领发展战略性新兴产业和未来产业。由此可把④的问题理解为将传统产业转型升级这一可行路径表述为普遍必要的路径。此项解释仍待命题方依据确认。","evidence":"③依靠创新驱动是形成新质生产力的关键④形成新质生产力要靠传统产业的转型升级","qids":["江苏 2024 B类 行测#3"]}]},{"title":"“十五五”谋划中的战略位置","uses":[{"unit":"Q2","role":"直接考查","use":"本题是选非题。题据所引2025年4月30日部分省区市“十五五”时期经济社会发展座谈会讲话，要求把因地制宜发展新质生产力摆在更加突出的战略位置。C将这一具体部署表述为推动高质量发展，故选C。D所列传统产业转型升级、发展新兴产业和超前布局未来产业并举，符合该次讲话。","evidence":"“十五五”时期，必须把推动高质量发展摆在更加突出的战略位置","qids":["政治理论必刷100题#50"]}]},{"title":"文化创新赋能","uses":[{"unit":"Q4","role":"解题依据","use":"本题依据给定资料7关于激发全民族文化创新创造活力的指示展开论述。长三角文博会数字体验、苏州文创跨界融合和扬州青年文创服务，可分别说明数字技术催生文化新业态、跨界融合拓展产业空间、版权服务和产学研协作支持持续创新。","evidence":"文化创新赋能新质生产力，文化创造助力奋进新征程","qids":["江苏 2025 A类 申论#4"]}]}],"sources":[{"id":"cd67a12c3d0c8d5b","label":"新质生产力","topic":"产业、科技与对外开放","category":"非时政","text":"1.新质生产力\n新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、\n高效能、高质量特征，符合新发展理念的先进生产力质态。\n（1）催生：由技术革命性突破、生产要素创新性配置、产业深度转型升级而催生。\n（2）基本内涵：以劳动者、劳动资料、劳动对象及其优化组合的跃升为基本内涵。\n（3）核心标志：以全要素生产率大幅提升为核心标志。\n（4）关键：关键在质优。\n（5）特点：特点是创新。\n（6）本质：本质是先进生产力。\n（7）显著特点：新质生产力的显著特点是创新，既包括技术和业态模式层面的创新，\n也包括管理和制度层面的创新。\n（8）核心要素：科技创新能够催生新产业、新模式、新动能，是发展新质生产力的核\n心要素。\n（9）本身：新质生产力本身就是绿色生产力。\n（10）基本路径：科技创新和产业创新，是发展新质生产力的基本路径。","source":{"doc":"6cbfb01fe723bba64b75","first":16,"last":16,"page":16,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-deaf678e08e0ae9c":{"review":{"definition":"规则开放是制度型开放的一项基础内容，包括遵守现行国际经贸规则，以及通过参与全球治理共建新的国际经贸规则。世界贸易组织规则和区域贸易协定规则是典型对象。","explanation":"按杨继军《以制度型开放建设更高水平开放型经济新体制》的划分，规则开放着眼于国际经贸活动共同遵循的准则，规制开放着眼于政府监管规则的协调。A项说规则开放为制度型开放提供基本行为准则，符合原文。选非题的错误在C项，原文概括管理开放的核心时用的是“简政放权”。","references":[{"source":"web-cba87052d87a44ca","location":"“制度型开放的主要内容”之“规则开放”段","quote":"共建国际经贸新规则"}],"evidence":"规则开放是制度型开放的基础，为制度型开放提供基本行为准则。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-d31bfec672cb999c":{"review":{"definition":"按《以制度型开放建设更高水平开放型经济新体制》的表述，管理开放主要针对政府管理模式，以简政放权为核心，并通过优化政务服务提升行政效能。","explanation":"国际贸易“单一窗口”和“证照分离”是文章列举的政府管理模式改革。C项保留了管理开放的对象和服务目标，却把文章明确写出的核心“简政放权”换成“放管结合”，因此是本题应选的错误项。","references":[],"evidence":"管理开放主要针对政府管理模式，其核心是简政放权","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0a6da28c772630a4":{"review":{"title":"全国统一大市场","type":"概念与词义","definition":"全国统一大市场是在全国范围内以统一的市场基础制度规则为基础，使商品和要素资源能够跨地区顺畅流动、经营主体能够公平竞争的市场体系。","explanation":"2024年党的二十届三中全会《决定》提出推动市场基础制度规则统一、市场监管公平统一、市场设施高标准联通。《关于完善价格治理机制的意见》要求废止妨碍全国统一大市场建设和公平竞争的价格政策，防止政府对价格形成的不当干预。","basis":"据关联原题及所列出处编释。","references":[{"source":"reform","location":"构建全国统一大市场"}],"related":["k-89c1d03096d04b0b","k-6e663bb030341b18"],"domain":"经济","examFocus":{"政治理论必刷100题#41":"从基本公共服务收费、市场价格监管和公共数据定价入手，辨清政府管理与市场调节的边界。","江苏 2025 A类 行测#6":"按改革举措所针对的对象，核对其在党的二十届三中全会《决定》中的归属。"}},"aspects":[{"title":"清理妨碍公平竞争的价格政策","uses":[{"unit":"Q1","role":"直接考查","use":"本题要求选出不正确的价格治理表述。C项关于废止妨碍统一市场和公平竞争的价格政策符合《意见》。B项将公办养老、托育、医疗机构基本服务收费写为全面放开，相关基本服务收费实行政府指导价管理，故选B。","evidence":"废止妨碍全国统一大市场建设和公平竞争的价格政策","qids":["政治理论必刷100题#41"]}]},{"title":"规则统一、监管公平与设施联通","uses":[{"unit":"Q2","role":"直接考查","use":"本题三卷同题。②对应《决定》中构建全国统一大市场的部署，属于构建高水平社会主义市场经济体制的举措，与③④同选，答案为D。","evidence":"推动市场基础制度规则统一、市场监管公平统一、市场设施高标准联通","qids":["江苏 2025 A类 行测#6","江苏 2025 B类 行测#6","江苏 2025 C类 行测#6"]}]}],"sources":[{"id":"4c18d7c76ff0f014","label":"全国统一大市场建设","topic":"发展与治理","category":"非时政","text":"1.全国统一大市场建设\n建设全国统一大市场，不仅是构建新发展格局、推动高质量发展的需要，而且是赢得国\n际竞争主动权的需要。我国作为全球第二大消费市场，必须把全国统一大市场建设好，增强\n我们从容应对风险挑战的底气。\n纵深推进全国统一大市场建设，基本要求是“五统一、一开放”。“五统一”，就是统\n一市场基础制度，特别是实现产权保护、公平竞争、质量标准等制度的统一；统一市场基础\n设施，打通物流、资金流、信息流，健全现代商贸流通体系；统一政府行为尺度，地方在推\n动经济发展特别是招商引资时，哪些能干哪些不能干有明确规矩，不能各行其是；统一市场\n监管执法，明确市场监管行政处罚裁量基准，一把尺子量到底；统一要素资源市场，促进自\n由流动、高效配置，减少资源错配和闲置浪费。“一开放”，就是持续扩大开放，实行对内\n对外开放联通，不搞封闭运行。\n——《求是》杂志","source":{"doc":"6cbfb01fe723bba64b75","first":7,"last":8,"page":7,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-aa052a4589f73e60":{"review":{"title":"共同富裕","type":"概念与词义","definition":"共同富裕是全体人民逐步实现物质生活和精神生活都富裕的发展目标，也是中国式现代化的重要特征。","explanation":"共同富裕面向全体人民，需要在高质量发展中循序渐进地推进。各地可以因地制宜探索路径，全国目标从全局统筹。推进过程中要兼顾效率和公平，使初次分配、再分配、三次分配协调配套。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"中国式现代化的中国特色"}],"related":["k-a00a8fcb9d224472","k-abc7a40f1ee48790","k-bea39803d34d2724"],"examFocus":{"政治理论必刷100题#47":"对照“十五五”经济社会发展座谈会讲话，区分发展规划的民生取向、经济布局和地区规划要求。","国考 2023 地市级 行测#5":"核对共同富裕的覆盖范围、地方探索与总体目标的关系，以及增长和分配的安排。","江苏 2024 C类 行测#5":"比较“千万工程”的实践范围与各项表述所称成效的覆盖范围，核对其对生态、农村发展和城乡融合的作用。"}},"aspects":[{"title":"“十五五”规划谋划中的民生要求","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题。C符合2025年4月30日部分省区市“十五五”时期经济社会发展座谈会讲话，将造福人民、在发展中保障和改善民生与稳步推动共同富裕联系起来。本题选A，错误在于把“基本实现社会主义现代化”写成了“全面实现社会主义现代化”。","evidence":"把造福人民作为根本价值取向，坚持在发展中保障和改善民生，稳步推动共同富裕","qids":["政治理论必刷100题#47"]}]},{"title":"共同富裕的内涵与实现路径","uses":[{"unit":"Q2","role":"直接考查","use":"本题选C。①涵盖全体人民的物质生活和精神生活，③强调三次分配协调配套，④把共同奋斗促进增长与合理制度安排改善分配联系起来。②前半句的因地制宜有题据支持，错误在于主张城乡和各区域各自确定共同富裕指标。","evidence":"各提各的指标，要从全局上来看。","qids":["国考 2023 地市级 行测#5"]}]},{"title":"地方工程成效与全国目标","uses":[{"unit":"Q3","role":"解题依据","use":"本题选C。题中的浙江“千万工程”通过改善人居环境、发展生产等促进农民富裕。②把这一地方实践的成效写成已经实现全体人民共同富裕，超出了题据支持的范围，因此正确组合为①③④。","evidence":"②实现了全体人民共同富裕的奋斗目标","qids":["江苏 2024 C类 行测#5"]}]}],"sources":[{"id":"c1c181c77df0cdd7","label":"全体人民共同富裕","topic":"发展与治理","category":"非时政","text":"1.全体人民共同富裕\n党的二十大报告指出，到二〇三五年，全体人民共同富裕取得更为明显的实质性进展。\n全体人民共同富裕是一个总体概念，它不是也不可能是所有人都同时富裕，不同人群不\n仅实现富裕的程度有高有低，时间上也会有先有后；它不是也不可能是所有地区同时达到一\n个富裕水准，不同地区富裕程度还会存在一定差异，而不是齐头并进。","source":{"doc":"6cbfb01fe723bba64b75","first":18,"last":18,"page":18,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-9b15547988c8ddb9":{"review":{"title":"现代化产业体系","type":"概念与词义","definition":"现代化产业体系是以实体经济为根基，由传统产业、新兴产业等相互协同，具备较强创新能力和产业链配套能力的产业体系。","explanation":"2025年4月30日关于谋划“十五五”的座谈会强调以科技创新为引领，把传统产业转型升级、新兴产业发展和未来产业布局结合起来。2023年7月江苏考察提出以先进制造业为骨干，同时提高产业基础和产业链的现代化水平。","basis":"据关联原题和解析编释。","references":[],"related":["k-07ef47dc10f156ad","k-0b5dc68bbfc10583"],"domain":"经济","examFocus":{"政治理论必刷100题#50":"核对“十五五”谋划中产业布局与战略重点的表述，辨别传统产业、新兴产业和未来产业各自的部署。","江苏 2025 A类 行测#3":"对照江苏考察提出的“四个新”，判断各项措施分别回应哪项任务，核对产业链建设与现代化产业体系之间的关系。"}},"aspects":[{"title":"传统产业、新兴产业和未来产业并举","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题。D项准确列出“十五五”谋划中建设现代化产业体系的三项并举部署。C项写错应摆在更加突出战略位置的任务，故选C。","evidence":"坚持全面推进传统产业转型升级、积极发展新兴产业、超前布局未来产业并举","qids":["政治理论必刷100题#50"]}]},{"title":"江苏以先进制造业为骨干","uses":[{"unit":"Q2","role":"直接考查","use":"②提出巩固传统产业领先地位、培育战略性新兴产业集群和提升产业链现代化水平，符合江苏强链补链延链任务。①至④均正确，三卷均选D。","evidence":"全面提升产业基础高级化和产业链现代化水平，加快构建以先进制造业为骨干的现代化产业体系","qids":["江苏 2025 A类 行测#3","江苏 2025 B类 行测#3","江苏 2025 C类 行测#3"]}]}],"sources":[{"id":"af8bc6ff1a9b111f","label":"现代化产业体系","topic":"产业、科技与对外开放","category":"非时政","text":"3.现代化产业体系\n现代化产业体系以实体经济为根基，以科技创新为核心驱动，以先进制造业为骨干，涵\n盖优化提升的传统产业、壮大的新兴产业和未来产业、优质高效的服务业，以及现代化基础\n设施体系的有机整体，具备智能化、绿色化、融合化特征，是支撑高质量发展的产业支撑。","source":{"doc":"6cbfb01fe723bba64b75","first":16,"last":17,"page":16,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-a329c346aba5023e":{"review":{"definition":"银发经济是围绕老年人的产品和服务需求，以及为老龄阶段做准备而开展的经济活动。","explanation":"本题①对应《关于深化养老服务改革发展的意见》中的产业发展部署。研发和推广老年用品可以丰富产品供给，拓展养老服务场景可以更好地满足老年人的多样化需求，两者都有助于释放养老消费潜力。因此①正确。","references":[],"evidence":"大力发展银发经济，丰富养老服务场景，释放养老消费潜力","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"a7aa1c1117e2d655","label":"银发经济","topic":"就业、社保与公共服务","category":"非时政","text":"3.银发经济\n银发经济，也称银色经济、银发产业，是向老年人提供产品或服务，以及为老龄阶段做\n准备等一系列经济活动的总和。\n截至 2025 年底，我国 60 岁及以上老年人口达 3.2 亿人，预计到 2035 年，这一群体数\n量将超 4 亿人，银发经济规模有望突破 30 万亿元。","source":{"doc":"6cbfb01fe723bba64b75","first":43,"last":43,"page":43,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-4ee933ef5be993e7":{"review":{"definition":"浦江经验是以领导干部主动下访、接待群众和解决实际问题为主要做法的群众工作经验。","explanation":"2003年，习近平在浙江浦江带头下访接待群众，推动领导干部深入基层听取群众诉求。第73题第①项写的正是变群众上访为领导下访，却对应到“枫桥经验”，因此该项错误。","references":[],"evidence":"变群众上访为领导下访，深入基层，联系群众","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3e0519a056c604c7":{"review":{"definition":"枫桥经验形成于20世纪60年代初的浙江诸暨枫桥，强调依靠群众、在基层就地解决问题。改革开放后的发展概括包括“小事不出村、大事不出镇、矛盾不上交”。","explanation":"1963年的经验总结已体现依靠群众解决当地问题。题解所引的三句完整表述见于改革开放后对枫桥经验的概括。第73题①的“变群众上访为领导下访”对应浦江经验，①配错后，②至⑤四项对应正确。","references":[{"source":"web-7333466755f272db","location":"1963年经验总结和推广段、文末基本内涵段","quote":"相信依靠群众，加强基层基础，就地解决问题"},{"source":"web-8d2d63c49f76d185","location":"收录的《人民日报》短评《“枫桥经验”值得总结和推广》","quote":"小事不出村,大事不出镇,矛盾不上交"}],"evidence":"小事不出村、大事不出镇、矛盾不上交","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-8624982e9c630b63":{"review":{"definition":"晋江经验是2002年总结提出的县域经济发展经验，以发展实体经济为根基，强调发挥市场作用和加强政府引导服务。","explanation":"这一经验着眼于本地产业发展，重视传统产业与高新技术产业协调互促。第73题第④项的“紧紧咬住实体经济发展不放松”抓住了它的产业发展重点，因此对应正确。","references":[],"evidence":"该经验强调以实体经济为根基","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-843675050c632a63":{"review":{"title":"党性修养","type":"概念与词义","definition":"党性修养是共产党员通过理论学习、党内政治生活和实践锻炼，自觉增强党性并把党性要求落实到行动中的过程。","explanation":"2025年6月30日，习近平在中共中央政治局第二十一次集体学习时强调，推进自我革命必须固本培元、增强党性。增强党性重在坚定理想信念，也要求铸牢对党忠诚、厚植为民情怀、纯正道德品质、保持清正廉洁。党员可在履职实践和党内政治生活中锻炼党性，自觉接受教育和监督。","basis":"据关联原题及所列出处编释。","references":[{"source":"primary","location":"加强党性修养"}],"related":["k-1632ca8680fadb9b","k-ce1e1cc79bdb2c0f"],"examFocus":{"政治理论必刷100题#81":"区分推进党的自我革命的根本保证、党性要求和实践举措，核对题中各项要求所处的层次。","政治理论必刷100题#83":"核对纠治“四风”相关论述，分清党性修养的重点、作风建设的作用与自我革命在跳出历史周期率中的定位。"}},"aspects":[{"title":"党的自我革命中的党性要求","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题。A项所述固本培元、增强党性是推进自我革命的要求。答案C误将完善党内法规体系列为根本保证。所附解析引用2024年第24期《求是》刊载的《深入推进党的自我革命》，其中明确以坚持党中央集中统一领导为根本保证。","evidence":"推进自我革命，必须固本培元、增强党性","qids":["政治理论必刷100题#81"]},{"unit":"Q2","role":"直接考查","use":"本题在落实中央八项规定精神、纠治“四风”长效机制的语境中考查坚定理想信念对增强党性的重要性，D项表述成立。题目选不正确项，答案A错在把自我革命列为跳出历史周期率的第一个答案。按2025年6月30日讲话，自我革命是第二个答案。","evidence":"推进自我革命，必须固本培元、增强党性。增强党性，重在坚定理想信念","qids":["政治理论必刷100题#83"]}]}],"sources":[{"id":"956d0ec506441030","label":"增强共产党人的党性","topic":"党政制度与理论","category":"非时政","text":"3.增强共产党人的党性\n《决定》把“增强共产党人的党性”摆在战略任务部署的第一部分，并且从 5 个方面\n作出了具体部署。一是强化对党忠诚教育。深刻领悟“两个确立”的决定性意义，增强“四\n个意识”、坚定“四个自信”、做到“两个维护”，严明党的政治纪律和政治规矩，净化\n党内政治生态。二是坚持用党的创新理论凝心铸魂。把学习、领悟、运用党的创新理论作\n为加强党性修养的根本途径，深入学习贯彻习近平党建思想，丰富理论学习教育方式，弘\n扬马克思主义学风。三是用党的优良传统和中华优秀传统文化涵养党性。发扬党的优良作\n风，传承红色基因，赓续共产党人精神血脉，挖掘用好中华优秀传统文化中的道德观念。\n四是在实践中锤炼党性。在贯彻落实党中央决策部署、完成急难险重任务、应对重大风浪\n考验中锤炼党性，在处理是和非、公和私、得和失等关系中磨砺党性，发挥党内政治生活\n“大熔炉”作用。五是加强党性鉴别。把党性作为干部考察和党员民主评议的重要内容，\n在干部选拔任用和评优评先中用好党性鉴别结果。","source":{"doc":"41195a191a57c1c36332","first":14,"last":14,"page":14,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-4a2f90cb291e60e3":{"review":{"definition":"共青团是促进青年健康成长的政治学校，政治性是共青团的第一属性。","explanation":"“政治学校”说明共青团在促进青年成长中承担的政治教育功能，“第一属性”说明政治性在共青团组织属性中的地位。D项同时准确复述了这两层定位，它们也是文章要求把政治引领摆在首位的依据。","references":[],"evidence":"共青团是促进青年健康成长的政治学校，政治性是共青团的第一属性。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-be03b113032c1281":{"review":{"definition":"在干部作风建设中，头雁效应指领导干部身体力行、以上率下，以自身行动带动下级改进作风。","explanation":"2017年12月关于纠正形式主义、官僚主义的指示，以「头雁效应」概括领导干部主动示范的作用。「羊群效应」通常指个体随群体行动。第④项把「以上率下」对应的「头雁效应」写成「羊群效应」，因此错误。","references":[],"evidence":"故“羊群效应”表述有误，应为“头雁效应”。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ea46679950d6c6b3":{"review":{"definition":"产业安全关注产业的稳定运行和持续发展，是国家经济安全的重要组成部分。","explanation":"第99题解析把产业安全放在经济安全框架下，并用它衡量国家发展水平和质量。B项把解析归于能源安全的整组表述用来定位产业安全，因此是本题要求选出的错误项。","references":[],"evidence":"产业安全是国家经济安全的重要组成部分","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b6e50d0d362ea434":{"review":{"definition":"原题引文：能源安全是国家安全的重要支撑，是社会向前发展进步的必要动力。","explanation":"国务院新闻办公室白皮书以“能源”为主语，称其为人类文明进步的基础和动力。能源安全强调的是这种能源供给的可靠性。第99题B项把有关能源及其供应保障作用的表述套在产业安全上，按标准答案应选B。","references":[{"source":"web-e0481920366336ed","location":"前言首段","quote":"能源是人类文明进步的基础和动力"},{"source":"web-541606bcbd15f17a","location":"第一部分，保障能源安全的重要意义","quote":"充足的能源供给是国家稳定、经济发展、国防巩固的生命线"}],"evidence":"能源安全是国家安全的重要支撑，是社会向前发展进步的必要动力。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-7c5e36ff9cccd58e":{"review":{"definition":"党的十八大报告将中国特色社会主义理论体系定位为行动指南，为推进中国特色社会主义实践提供理论指导。","explanation":"第100题中，道路探索、制度完善和文化发展都体现了理论体系对实践的指导作用。B项把这一功能写成“伟大旗帜”，与报告中的“行动指南”对应错误，因此应选B。","references":[],"evidence":"其定位是行动指南。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d28d3f03804913b4":{"review":{"definition":"党的十八大报告将中国特色社会主义道路定位为实现途径。这条道路是在中国共产党领导下，全国各族人民在长期实践中形成的。","explanation":"第100题A项的“实现途径”指实现社会主义现代化和中华民族伟大复兴所走的道路。理论体系为实践提供指导，制度为事业发展提供保障，三者各有对应的功能定位，A项对应正确。","references":[],"evidence":"中国特色社会主义道路是实现途径","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c70b2e63a0914ce8":{"review":{"definition":"中国特色社会主义制度是一整套相互衔接、相互支撑的制度。党的十八大报告将其定位为根本保障。","explanation":"第100题C项的“根本保障”指这套制度为中国特色社会主义事业提供制度支撑。与A项道路所对应的“实现途径”相比，C项说的是事业发展所依托的制度条件，表述正确。","references":[],"evidence":"中国特色社会主义制度是根本保障","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-df6bd77ec1873bd1":{"review":{"definition":"党的十九大报告将中国特色社会主义文化表述为激励全党全国各族人民奋勇前进的强大精神力量。","explanation":"第100题D项的“精神力量”概括了十九大报告所说的激励作用。题中理论体系对应对实践的理论指导，文化对应对全党全国各族人民的精神激励，因此D项正确。","references":[],"evidence":"各族人民奋勇前进的强大精神力量","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-36c581b64278d507":{"review":{"definition":"本题中的比较优势，指承接地相对于其他备选地点，能为拟迁入企业提供的有利条件，如较低的生产要素成本、产业链配套和有助于稳定队伍的用工条件。","explanation":"N市招商局负责人提出，承接外部产业要突出本地比较优势。乐原市可据此向新远眼镜公司说明，当地物流、土地和水电气成本相对较低，金属深加工基地和电镀园区可为镜架生产提供配套，企业已有较多本省户籍工人，有利于稳定技工队伍。返租和技能培训则是围绕这些条件提出的合作措施。","references":[],"evidence":"突出比较优势，才能培育本地产业和承接外部产","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8fd374e4d543289b":{"review":{"definition":"中国式现代化是中国共产党领导的社会主义现代化，既有各国现代化的共同特征，也有基于中国国情的中国特色。","explanation":"党的二十大报告以十四亿多人口整体迈进现代化社会为例，指出如此大的人口规模使发展途径和推进方式必然具有自身特点。第④项将各国现代化具有的“共同特征”说成各国都遵循的“共同模式”，并把遵循该模式说成中国式现代化道路的基本经验，因此错误。","references":[],"evidence":"既有各国现代化的共同特征，更有基于自己国情的中国特色","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-29367887b7abca95":{"review":{"definition":"《庄子·知北游》有“天和将至”一语。“天和”可指人的元气，也可指天地的祥和之气或自然和顺之理。","explanation":"贺词中的“天和”指中国空间站天和核心舱。C项把“祝融”“羲和”“天和”一并归为古代神话人物，其中“天和”在《庄子》中表达的是一种和顺状态，归类有误。","references":[],"evidence":"若正汝形，一汝视，天和将至","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-012377087db2d7d5":{"review":{"definition":"岩石圈由地壳和上地幔顶部的刚性部分组成，分为若干板块。这些板块在下方的软流层之上缓慢移动。","explanation":"本题A项把软流层上方的板块直接说成构成地壳的板块，混用了地壳与岩石圈两个概念。公开题文沿用了这一措辞。所给答案选D，针对外地核成分误写为铁和铬，A项按教材口径也存在表述偏差。","references":[{"source":"web-405b44451075b792","location":"图2「地殼及上地幔層的基本構造」","quote":"包括地殼及上部地幔"},{"source":"web-4be9b54b3801abde","location":"地球圈层题A项","quote":"由几个漂浮在地幔表层的固体岩石板块构成"}],"evidence":"地壳：由几个漂浮在地幔表层的固体岩石板块构成","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-bd2e936b37cb058b":{"review":{"title":"独树一帜","type":"概念与词义","definition":"独树一帜本指单独树立一面旗帜，比喻自成一家，形成独特的风格、主张或做法。","explanation":"“独树一帜”着重于在某个领域自成一格。“与众不同”涵盖的范围更广，也可以形容一般的差异。","basis":"据关联原题和解析编释。","references":[],"related":[],"examFocus":{"国考 2023 副省级 行测#23":"首空比较北斗与其他导航系统的构型选择，次空结合发送容量的变化，判断“无需”后适合接哪类措辞行为。"}},"readings":[{"origin":"k-bd2e936b37cb058b","title":"独树一帜","qs":["国考 2023 副省级 行测#23","国考 2023 地市级 行测#25"],"definition":"独树一帜本指单独树立一面旗帜，比喻自成一家，形成独特的风格、主张或做法。","explanation":"“独树一帜”着重于在某个领域自成一格。“与众不同”涵盖的范围更广，也可以形容一般的差异。","evidence":"","doubt":"","references":[]},{"origin":"k-70413d6156f43ba0","title":"独树一帜","qs":["国考 2023 行政执法 行测#25"],"definition":"比喻自成一家，形成独特的风格、主张或做法。","explanation":"题干以其他系统采用单一轨道星座构型作参照，用混合星座和首创短文通报模式体现北斗系统自成一格的做法。“与众不同”也能概括第一空的差异，第二空的“字斟句酌”使B项整组最贴切。","evidence":"坚定选择了混合星座的特色发展之路","doubt":"","references":[]}],"aspects":[{"title":"技术路线与服务模式的独特性","uses":[{"unit":"Q1","role":"直接考查","use":"北斗系统选择混合星座构型并开创通信导航一体化服务，体现首空所说的自成一格。“与众不同”在首空也可表达差异，第二空用“字斟句酌”呼应传输容量增加后无须逐字推敲的语境，整组选B。","evidence":"坚定选择了混合星座的特色发展之路，并首创短文通报模式，开创了通信导航一体化的独特服务模式","qids":["国考 2023 副省级 行测#23","国考 2023 地市级 行测#25"]}]}]},"k-1093001e80c5db03":{"review":{"definition":"字斟句酌指说话或写作时逐字逐句仔细推敲措辞。","explanation":"按题干所述，单次发送容量从120个汉字增至1200个汉字，遇到突发情况可以一次交代清楚，因而无需为节省字数而反复推敲措辞。“字斟句酌”说的是推敲的过程，“言简意赅”说的是表达简明而意思完备的结果。","references":[],"evidence":"信息发送能力从一次120个汉字提升到一次1200个汉字","disposition":"独立词条","basis":"据原题和解析编释。","title":"字斟句酌","related":[],"examFocus":{"国考 2023 副省级 行测#23":"第二空结合北斗单次发送容量的变化，判断“无需”后应接表示哪类表达行为或特点的成语。"}},"readings":[{"origin":"k-1093001e80c5db03","title":"字斟句酌","qs":["国考 2023 副省级 行测#23"],"definition":"字斟句酌指说话或写作时逐字逐句仔细推敲措辞。","explanation":"按题干所述，单次发送容量从120个汉字增至1200个汉字，遇到突发情况可以一次交代清楚，因而无需为节省字数而反复推敲措辞。“字斟句酌”说的是推敲的过程，“言简意赅”说的是表达简明而意思完备的结果。","evidence":"信息发送能力从一次120个汉字提升到一次1200个汉字","doubt":"","references":[]},{"origin":"k-603eabbee2f76392","title":"字斟句酌","qs":["国考 2023 地市级 行测#25"],"definition":"指写作或说话时慎重细致地逐字逐句推敲措辞。","explanation":"按题干给出的信息，北斗系统单次可发送的汉字数从120个增至1200个，遇到突发情况时，发送者无需为有限的字数反复推敲措辞，就能一次把情节说清楚，因此第二空选“字斟句酌”。“言简意赅”形容语言简明而意思完备，侧重表达效果。","evidence":"信息发送能力从一次120个汉字提升到一次1200个汉字","doubt":"","references":[]},{"origin":"k-b6e743312ddd6d14","title":"字斟句酌","qs":["国考 2023 行政执法 行测#25"],"definition":"指说话或写作时逐字逐句地仔细推敲措辞。","explanation":"按题干给出的数据，单次可发送的文字量从120个汉字增加到1200个汉字，遇到突发情况时有更多篇幅一次说清情节，可减少为适应字数限制而反复推敲的需要。“字斟句酌”说的是推敲措辞的过程，“言简意赅”说的是简明而完整的表达效果，因此第二空选B项用词。","evidence":"信息发送能力从一次120个汉字提升到一次1200个汉字","doubt":"","references":[]}]},"k-7e0782d0d7deddc8":{"review":{"title":"别无二致","type":"概念与词义","definition":"别无二致指所比较的两个事物在所谈的方面没有差别。","explanation":"“二致”指差别。“几乎别无二致”表示高度相似，仍留有细微差别的余地。","basis":"据关联原题和解析编释。","references":[],"related":[],"examFocus":{"国考 2023 副省级 行测#24":"首空看“几乎”限定了怎样的古今比较，次空看施肥时间、地点、肥料种类和施用方法的列举突出了体系的什么特点。"}},"readings":[{"origin":"k-7e0782d0d7deddc8","title":"别无二致","qs":["国考 2023 副省级 行测#24","国考 2023 地市级 行测#27"],"definition":"别无二致指所比较的两个事物在所谈的方面没有差别。","explanation":"“二致”指差别。“几乎别无二致”表示高度相似，仍留有细微差别的余地。","evidence":"","doubt":"","references":[]},{"origin":"k-b16248df6128b36a","title":"别无二致","qs":["国考 2023 行政执法 行测#27"],"definition":"“别无二致”指所比较的事物没有差别。","explanation":"题中以“几乎”限定“别无二致”，表示古人保养土地的方法与当代耕作学关注的措施高度相似。这一比较本身未交代传承关系。“如出一辙”也能表达相似，整组答案还取决于第二空能否概括施肥体系各环节齐备的特点。","evidence":"几千年间古人对于土地的保养，几乎与当代耕作学关注的措施","doubt":"","references":[]}],"aspects":[{"title":"比较古今耕作措施的相似程度","uses":[{"unit":"Q1","role":"直接考查","use":"首空与“几乎”连用，描述古代保养土地的做法与当代耕作措施高度相似。次空用“完整”概括施肥时地、肥料种类和施用方法等环节，整组选C。","evidence":"古人对于土地的保养，几乎与当代耕作学关注的措施","qids":["国考 2023 副省级 行测#24","国考 2023 地市级 行测#27"]}]}]},"k-13ea937121f39a41":{"review":{"definition":"深入人心指理论、观念、政策等为人们深切理解和认同。","explanation":"第一空以“新时代党的创新理论”为主语，紧接着写“社会主义核心价值观广泛传播”，两句共同描述思想观念的传播与接受。“深入人心”补出了理解和认同的程度，“振聋发聩”则侧重语言文字唤醒人的作用。","references":[],"evidence":"社会主义核心价值观广泛传播","disposition":"独立词条","basis":"据原题和解析编释。","title":"深入人心","related":[],"examFocus":{"国考 2023 副省级 行测#25":"第一空看词语与“新时代党的创新理论”的搭配及其与后一分句的关系，第二空看词语能否与“根本性”并列修饰“转变”。"}},"readings":[{"origin":"k-13ea937121f39a41","title":"深入人心","qs":["国考 2023 副省级 行测#25"],"definition":"深入人心指理论、观念、政策等为人们深切理解和认同。","explanation":"第一空以“新时代党的创新理论”为主语，紧接着写“社会主义核心价值观广泛传播”，两句共同描述思想观念的传播与接受。“深入人心”补出了理解和认同的程度，“振聋发聩”则侧重语言文字唤醒人的作用。","evidence":"社会主义核心价值观广泛传播","doubt":"","references":[]},{"origin":"k-4c62650c4488c543","title":"深入人心","qs":["国考 2023 行政执法 行测#29"],"definition":"“深入人心”指理论、学说、政策等为人们深切理解并得到认同或信服。","explanation":"第一空以“新时代党的创新理论”为陈述对象，强调理论获得认同。相邻的“社会主义核心价值观广泛传播”同样着眼于思想观念的传播效果。“振聋发聩”侧重用言辞使人警醒，与这一语意重点有别。","evidence":"新时代党的创新理论       ，社会主义核心价值观广泛传播","doubt":"","references":[]}]},"k-idiom":{"review":{"title":"另辟蹊径","type":"概念与词义","definition":"另外开辟一条路，比喻另找一种方法，或创出一种新风格。","explanation":"“辟”指开辟，“蹊径”指小路。这个成语强调所走的路与原有或常见的路径不同，也可用拟人手法形容动物形成了不同于其他动物的取食方式。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典另闢蹊徑","location":"“另闢蹊徑”词目"}],"examFocus":{"国考 2023 副省级 行测#26":"结合传统逆周期调节的局限与下文对跨周期调节的说明，辨别第二空形容的是调控方法的哪种变化。","国考 2025 地市级 行测#38":"结合大熊猫面临的取食限制和所选食物，判断引号中的成语怎样概括这种取食方式。"}},"aspects":[{"title":"另寻解决问题的方法","uses":[{"unit":"Q1","role":"直接考查","use":"传统逆周期调节擅长应对短期波动，题干面对长期结构性调整引出跨周期调节。第二空用“另辟蹊径”点明宏观调控寻求新办法，对应 B 项。","evidence":"而跨周期调节正是在顶层设计的宏观调控框架下，促进不同政策工具的关联匹配","qids":["国考 2023 副省级 行测#26"]}]},{"title":"拟人化地形容独特的取食方式","uses":[{"unit":"Q2","role":"直接考查","use":"题干对照其他食草动物的取食条件，用带引号的“另辟蹊径”形容大熊猫形成以箭竹为主食的独特食性，两卷均选 D。","evidence":"选择了其他动物不吃的食物种类","qids":["国考 2025 地市级 行测#38","国考 2025 行政执法 行测#38"]}]}]},"k-90b489fd5656394f":{"review":{"definition":"比喻趁局面混乱捞取利益。","explanation":"第28题首空用“浑水摸鱼者”指趁国潮成分混杂而谋利的人，与紧接的“泥沙俱下”相呼应。“急功近利”侧重急于见成效、贪图眼前利益，少了借混乱局面取利这一层。","references":[],"evidence":"但任何潮流，难免有       者，也不无泥沙俱下时","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-733e93058cf39cdc":{"review":{"definition":"略作尝试便停止，比喻做事或钻研只停留在初步阶段，缺少深入探究。","explanation":"第28题第二空与“浮于表面”并列，形容部分创作者把国潮做成符号堆砌和元素拼贴，对历史语境和文化内涵缺少深入钻研。“不求甚解”也能表达理解不深，D项由首空的“浑水摸鱼”进一步确定。","references":[],"evidence":"“浅尝辄止”指稍稍尝试一下就停止，比喻做事不肯下功夫深入钻研","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1df63b2ff79f438c":{"review":{"definition":"比喻取用不留余地，只顾眼前利益，缺少长远打算。","explanation":"第29题首空形容地方政府只图短期利益和政绩、损害长远发展的做法。“本末倒置”也能说明所重有误，“竭泽而渔”更直接呼应短期取利与长期发展的冲突。D项还由第二空的“杀鸡取卵”得到确认。","references":[],"evidence":"不能只追求短期利益，只追求政绩","disposition":"独立词条","basis":"据原题和解析编释。","title":"竭泽而渔","related":[],"examFocus":{"国考 2023 副省级 行测#29":"联系首空前的“只追求短期利益”和第二空前列举的后果，分别判断两处成语应侧重什么。"}},"readings":[{"origin":"k-1df63b2ff79f438c","title":"竭泽而渔","qs":["国考 2023 副省级 行测#29"],"definition":"比喻取用不留余地，只顾眼前利益，缺少长远打算。","explanation":"第29题首空形容地方政府只图短期利益和政绩、损害长远发展的做法。“本末倒置”也能说明所重有误，“竭泽而渔”更直接呼应短期取利与长期发展的冲突。D项还由第二空的“杀鸡取卵”得到确认。","evidence":"不能只追求短期利益，只追求政绩","doubt":"","references":[]},{"origin":"k-39d3c3bf33c8d457","title":"竭泽而渔","qs":["国考 2023 地市级 行测#26"],"definition":"比喻获取利益时取之不留余地，只顾眼前，缺乏长远打算。","explanation":"第一空形容地方政府一味追求短期利益和政绩的做法。下文强调考核要重视民生和社会的长远发展，与“竭泽而渔”体现的短视相呼应。“本末倒置”也能形容把政绩摆在民众利益之前，第二空的“杀鸡取卵”进一步对应损害长远发展的后果，使D项两空都契合。","evidence":"不能只追求短期利益，只追求政绩","doubt":"","references":[]}]},"k-2dd9e94ee7543266":{"review":{"definition":"比喻为取得眼前的好处而损害长远利益。","explanation":"第29题第二空概括只图眼前政绩、破坏可持续发展并损害民众利益的现象。“抱薪救火”强调试图消除祸患却因方法不当使祸患扩大，题干强调的是短期获益以长期受损为代价。","references":[],"evidence":"避免破坏可持续发展大局、损害民众利益","disposition":"独立词条","basis":"据原题和解析编释。","title":"杀鸡取卵","related":[],"examFocus":{"国考 2023 副省级 行测#29":"辨析两空的成语时，留意文段如何对照短期政绩与长远发展，以及第二空要概括哪类现象。"}},"readings":[{"origin":"k-2dd9e94ee7543266","title":"杀鸡取卵","qs":["国考 2023 副省级 行测#29"],"definition":"比喻为取得眼前的好处而损害长远利益。","explanation":"第29题第二空概括只图眼前政绩、破坏可持续发展并损害民众利益的现象。“抱薪救火”强调试图消除祸患却因方法不当使祸患扩大，题干强调的是短期获益以长期受损为代价。","evidence":"避免破坏可持续发展大局、损害民众利益","doubt":"","references":[]},{"origin":"k-a7c7a4581dae0412","title":"杀鸡取卵","qs":["国考 2023 地市级 行测#26"],"definition":"比喻为了眼前的好处而损害长远利益。","explanation":"第二空概括题干所说的短期逐利造成的后果，即破坏可持续发展、损害民众利益。“杀鸡取卵”同时点出眼前收益和长远损失，因此选D。“抱薪救火”侧重因处置方法不当而使原有祸患扩大。","evidence":"破坏可持续发展大局、损害民众利益","doubt":"","references":[]}]},"k-055156d33c7415e4":{"review":{"definition":"使紧张、困难、不良状况等的程度减轻。","explanation":"第30题已给出区域迅速增温和冰川快速退缩的背景，“缓解冰川消融”表示减轻消融程度或放慢消融速度。“避免”“防止”侧重使某种情况不发生，程度更强。“干预”只表示介入，单凭这个词无法确定变化会减轻。","references":[],"evidence":"在当前区域迅速增温、冰川快速退缩的情境下","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bcb945010657dec6":{"review":{"definition":"指某一现象或指标能够显示相关状态或变化的性质。","explanation":"第30题第一空用“指示性”说明冰川对气候变暖的反映作用。下文以变暖背景下全球冰川加速消融为例，具体说明冰川变化可以反映气候变化。“动态性”只强调冰川本身会变化，未表达这种反映关系。","references":[],"evidence":"由于气候变暖，全球冰川加速消融","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-609c765def1f3ff9":{"review":{"definition":"“出其不意”指趁对方没有料到时采取行动。“猝不及防”指事情突然发生，来不及防备。","explanation":"第31题第二空直接修饰“快速部署到位”，句子的主语是采取行动的航母，语意是其行动出乎对方预料，因此用“出其不意”。“猝不及防”描述的是遇到突发情况的一方，常说“让人猝不及防”。","references":[],"evidence":"“出其不意”指趁对方没有料到就采取行动","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1a52f06587b5b55d":{"review":{"definition":"“共存”指多种事物同时存在。“统一”在本题所涉义项中强调一致或结合为一个整体。","explanation":"第32题第二空把焦裕禄精神与井冈山精神、延安精神、雷锋精神、红旗渠精神等并列，后文说明这样的精神共同构成民族的精神力量。“共存”能保留各自作为一种精神同时存在的含义，“统一”则会引入彼此一致或合成一体的含义。","references":[],"evidence":"“共存”指某一事物与其他事物共同或同时存在","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8df34ad8e0ed37e9":{"review":{"definition":"原指把稀少的货物囤积起来，等待高价出售。也比喻把稀有或独占的事物当作谋取利益的资本。","explanation":"第二空前说注册制全面推进后新股上市数量会增多，后面说某个时代「一去不返」。「奇货可居」把过去上市公司数量较少带来的优势比作稀缺筹码。「待价而沽」侧重等待有利条件，「一枝独秀」侧重表现出众，只有「奇货可居」直接扣住上市公司曾经较为稀少这一层意思。","references":[],"evidence":"新股上市数量势必增多","disposition":"独立词条","basis":"据原题和解析编释。","title":"奇货可居","related":[],"examFocus":{"国考 2023 副省级 行测#33":"结合新股上市数量的变化，判断第二空的成语能否概括“一去不返”的市场处境。"}},"readings":[{"origin":"k-8df34ad8e0ed37e9","title":"奇货可居","qs":["国考 2023 副省级 行测#33"],"definition":"原指把稀少的货物囤积起来，等待高价出售。也比喻把稀有或独占的事物当作谋取利益的资本。","explanation":"第二空前说注册制全面推进后新股上市数量会增多，后面说某个时代「一去不返」。「奇货可居」把过去上市公司数量较少带来的优势比作稀缺筹码。「待价而沽」侧重等待有利条件，「一枝独秀」侧重表现出众，只有「奇货可居」直接扣住上市公司曾经较为稀少这一层意思。","evidence":"新股上市数量势必增多","doubt":"","references":[]},{"origin":"k-d1e16f2fd6b24cc0","title":"奇货可居","qs":["国考 2023 地市级 行测#35"],"definition":"原指囤起稀有货物，等待高价出售，比喻把稀缺或独占的事物作为谋利的资本。","explanation":"第35题第二空用它形容上市公司过去凭稀缺性获得的优势。文段预计新股上市数量增多，因此说这种优势一去不返。「待价而沽」侧重等待有利条件，「一枝独秀」侧重在同类中表现突出。","evidence":"新股上市数量势必增多","doubt":"","references":[]}]},"k-e85c45b8f7b115b9":{"review":{"definition":"自觉指自己认识到某件事应该做，并主动去做。自强指依靠自身努力使自己强大起来。","explanation":"题干把完整、清楚地披露信息称为上市公司的法定责任和立身之本，末句又要求企业诚实、负责地「自我介绍」。第一空强调市场主体主动履行披露责任，用「自觉」贴切。「自强」强调提升自身实力，与后文具体要求的重心不同。","references":[],"evidence":"将自身相关信息说完整、说清楚，既是上市公司的法定责任，也是逐浪资本市场的立身之本","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1d85004a69d41a4a":{"review":{"definition":"比喻事物表面繁荣或声势很大，实际根基薄弱，容易消散。","explanation":"第三空与「快餐式」并列，又与戏曲「可重复欣赏和耐咀嚼」的特点对照。作者用「泡沫化」突出某些网络传播内容一时热闹却难以持久的特点。「肤浅化」侧重缺少深度，「机械化」侧重缺少变化。「难以反复品味」是本段对照带出的意思。","references":[],"evidence":"其可重复欣赏和耐咀嚼的品格显得更为可贵","disposition":"独立词条","basis":"据原题和解析编释。","title":"泡沫化","related":[],"examFocus":{"国考 2023 副省级 行测#34":"第三空既要和“快餐式”并列，又要与戏曲可反复欣赏、耐咀嚼的特点形成对照。"}},"readings":[{"origin":"k-1d85004a69d41a4a","title":"泡沫化","qs":["国考 2023 副省级 行测#34"],"definition":"比喻事物表面繁荣或声势很大，实际根基薄弱，容易消散。","explanation":"第三空与「快餐式」并列，又与戏曲「可重复欣赏和耐咀嚼」的特点对照。作者用「泡沫化」突出某些网络传播内容一时热闹却难以持久的特点。「肤浅化」侧重缺少深度，「机械化」侧重缺少变化。「难以反复品味」是本段对照带出的意思。","evidence":"其可重复欣赏和耐咀嚼的品格显得更为可贵","doubt":"","references":[]},{"origin":"k-d07874cd4696526c","title":"泡沫化","qs":["国考 2023 行政执法 行测#37"],"definition":"“泡沫化”可比喻事物呈现出表面繁荣、实际虚浮且难以持久的状态。","explanation":"本题把“泡沫化”与“快餐式”并列，用短暂、易消散的传播热度反衬戏曲“可重复欣赏和耐咀嚼”的特点。“肤浅化”也能与“耐咀嚼”形成深浅对照，而“泡沫化”的易逝意味还能与“可重复欣赏”形成对照。这里是材料对传播现象的比喻性评价。","evidence":"像泡沫一样，一碰就破，瞬间消失","doubt":"","references":[]}]},"k-d9c30964760ff0be":{"review":{"definition":"比喻在紧要关头，为保全整体而果断舍弃局部。","explanation":"第一空紧接「破的勇气」，后文明确要舍弃的是落后产能，目的是给新产业发展创造条件。「壮士断腕」具体体现了为整体发展舍弃部分旧产能的决断。「破釜沉舟」侧重下定决心干到底。首空两者都有决断之意，第二空的「并行不悖」进一步确定了D项。","references":[],"evidence":"为保存整体不惜牺牲局部","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-054961e70dcbcb88":{"review":{"definition":"并行不悖指同时进行而互不抵触。互为表里指两者关系紧密，彼此构成表与里的关系。","explanation":"第二空说的是淘汰落后产能和培育绿色产能可以一同推进，后面的「相辅相成」进一步点出两者能够配合。末句给出了具体关系，破除无效产能可以为新产业腾出发展空间。这种关系适合用「并行不悖」，题干并未给出两项工作彼此构成内外层面的关系。","references":[],"evidence":"才能给新产业发展创造条件，增加有效供给","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-84201ae4d61b6f0c":{"review":{"definition":"点集的凸包是包含该点集全部点的最小凸集，且包含于任何覆盖这些点的凸集中。对于有限个不全共线的平面点，凸包是由最外围的若干点围成的凸多边形及其内部。","explanation":"第94题用黑色方块表示生物已知、推断或预计出现的位点，并用这些位点的凸包表示分布区。A把所有位点纳入边界或内部，每个内角都不超过180度，边界也无法在保持覆盖的前提下继续收紧。B有内凹处，C的右侧漏掉一个位点，D的左下角和右侧尖角还能向内收紧，因此选A。","references":[],"evidence":"该最小凸边形的每个内角不能超过180度，并要包含所有出现的位点。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0c9e09c2cbaf3855":{"review":{"definition":"花海指像海洋一样广阔的成片花群，书山指像山一样堆得很高的书籍。","explanation":"两词都把所描写的对象放在前面，把用来比拟的事物放在后面。B项“车流”用水流比拟连续行驶的车辆，“人潮”用潮水比拟涌动的人群，顺序与题干一致。D项“龙舟”的“龙”在前，说明船的形状，“木马”的“木”在前，说明马的材质。","references":[],"evidence":"花海指的是像海洋般广阔的花群，书山指的是像山峰般高耸的书籍","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-06d4ce551a193870":{"review":{"title":"猛药去疴","type":"概念与词义","definition":"本义是用药力强的药去除疾病，比喻用有力的措施解决严重问题或积弊。","explanation":"“疴”指疾病。用于比喻时，“疴”对应待解决的问题，“猛药”对应解决问题所用的强力措施。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典猛藥","location":"“猛藥”词目"}],"examFocus":{"国考 2023 副省级 行测#97":"拆开每个四字短语，比较前后两部分是手段与目的、条件与结果，还是其他关系。"}},"aspects":[{"title":"手段与目的关系","uses":[{"unit":"Q1","role":"解题依据","use":"题干将“猛药去疴”与“重典治乱”并列。两句内部都以手段指向目的，即用猛药去病、用重典治乱，与C项用内心宁静修身、用节俭养德的结构一致。（国考 2023 副省级 行测第97题、国考 2023 地市级 行测第92题）","evidence":"“猛药去疴”意思是通过威力大的药达到去除疾病的目的","qids":["国考 2023 副省级 行测#97","国考 2023 地市级 行测#92"]}]}]},"k-de829a34c1c83d32":{"review":{"title":"重典治乱","type":"概念与词义","definition":"指用严厉的法令或刑罚治理乱象。","explanation":"“典”在这里取法令义。“治乱”的着眼点是整治失序局面，惩处违法行为是这一语境下的治理手段。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典重典","location":"“重典”词目"}],"examFocus":{"国考 2023 副省级 行测#97":"分别拆开每组的两个四字短语，辨别短语内部是手段与目的、条件与结果，还是其他关系。"}},"aspects":[{"title":"手段与目的关系","uses":[{"unit":"Q1","role":"解题依据","use":"“重典”是治理手段，“治乱”是目的，与题干前一短语“猛药去疴”的内部关系相同。C项“静以修身”和“俭以养德”也各自以手段指向目的。（国考 2023 副省级 行测第97题、国考 2023 地市级 行测第92题）","evidence":"“重典治乱”意思是通过严酷的刑罚达到惩治坏人的目的","qids":["国考 2023 副省级 行测#97","国考 2023 地市级 行测#92"]}]}]},"k-825852a83f3425f7":{"review":{"definition":"一眼望去看不到边际，形容空间非常宽广。","explanation":"“一望无垠”用望不到边际的景象表现“辽阔”，两者核心意思相近。B项“耳提面命”突出恳切地教导，也符合成语与普通词语之间的近义关系。","references":[],"evidence":"“一望无垠”意思是宽广、辽阔，一眼望去看不到边际","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f0549383ca10c73d":{"review":{"definition":"形容面对面地恳切教导。","explanation":"“耳提面命”的核心意思是“教导”，并突出教导时的恳切。B项可以据此与题干类比，正如“一望无垠”用望不到边际的景象表现“辽阔”。","references":[],"evidence":"形容恳切地教诲，与“教导”是近义关系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1692457566a5136d":{"review":{"definition":"别人怎么说，自己也跟着怎么说，形容没有主见、随声附和，含贬义。","explanation":"A项的“重复”是中性词，可以指再次说出自己的话，也可以指同一事物再次出现。“人云亦云”特指在言论或观点上随声附和他人，二者的核心含义有差别，因此A项与题干的近义关系不同。","references":[],"evidence":"指没有主见，随声附和别人，是贬义词","disposition":"独立词条","basis":"据原题和解析编释。","title":"人云亦云","related":[],"examFocus":{"国考 2023 副省级 行测#99":"判断后一个词能否概括成语的核心含义时，可以比较两者所指的行为和感情色彩。","国考 2024 行政执法 行测#36":"结合“没有思考”和前面并列的三种阅读表现，辨析末空成语的侧重点，再检查前两空的搭配。"}},"readings":[{"origin":"k-1692457566a5136d","title":"人云亦云","qs":["国考 2023 副省级 行测#99"],"definition":"别人怎么说，自己也跟着怎么说，形容没有主见、随声附和，含贬义。","explanation":"A项的“重复”是中性词，可以指再次说出自己的话，也可以指同一事物再次出现。“人云亦云”特指在言论或观点上随声附和他人，二者的核心含义有差别，因此A项与题干的近义关系不同。","evidence":"指没有主见，随声附和别人，是贬义词","doubt":"","references":[]},{"origin":"k-c6189ed4865f1589","title":"人云亦云","qs":["国考 2024 行政执法 行测#36"],"definition":"人云亦云指别人怎么说，自己也跟着怎么说，形容缺乏独立判断和主见。","explanation":"第三空紧接“没有思考”，“人云亦云”写出读书时只被动接受书中的说法，缺乏自己的判断。“走马观花”侧重粗略观察，主要对应前文的匆匆浏览。","evidence":"机械地阅读、被动地接受","doubt":"","references":[]}]},"k-f6cb8407976122e9":{"review":{"title":"流行性乙型脑炎","type":"概念与词义","definition":"流行性乙型脑炎简称乙脑，又称日本脑炎，是由乙型脑炎病毒感染引起的疾病。","explanation":"多数感染者无症状或症状轻微。出现脑炎时可有发热等表现，发热本身不足以判定病因。","basis":"据关联原题及所列出处编释。","references":[{"source":"je","location":"症状和体征"}],"domain":"科技","examFocus":{"国考 2023 副省级 行测#101":"区分病因和临床表现，并比较它们在各组三个词中与疾病名称的先后位置。"}},"aspects":[{"title":"病因与临床表现","uses":[{"unit":"Q1","role":"解题依据","use":"B项中乙型脑炎病毒是病因，发热是可能出现的症状，分别对应题干中花粉和喷嚏与春季过敏的关系。","evidence":"乙型脑炎：病毒：发热","qids":["国考 2023 副省级 行测#101","国考 2023 行政执法 行测#96"]}]}]},"k-56e2b26bff931e6c":{"review":{"definition":"片剂是片状固体制剂，散剂是干燥粉末状制剂，气雾剂在使用时借助抛射剂压力将药物喷出。三者都属于药物剂型。","explanation":"题干列出同一分类标准下互不相属的三种剂型，且药物还有其他剂型，因此三者属于并列中的反对关系。D项同样按理疗部位列出头部、腰部和腿部三类。C项的“天然水”是上位概念，可包含泉水。","references":[],"evidence":"三者是根据药物的剂型划分的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8e0402a7cfc92ab9":{"review":{"definition":"标清、高清和超清是视频清晰度的常用等级名称。在本题的分级语境中，三者按清晰度从低到高排列。","explanation":"A项同样按一个指标递增，亚音速低于音速，超音速高于音速。D项的“幽静”“寂静”“安静”各有不同侧重，无法按本题要求形成固定的递增次序。","references":[],"evidence":"三者均对清晰度进行分类，构成并列关系，且清晰度依次递增。","disposition":"独立词条","basis":"据原题和解析编释。","title":"标清、高清与超清","related":[],"examFocus":{"国考 2023 副省级 行测#103":"类比三个等级词时，先找共同的分级指标，再比较排列方向。"}},"readings":[{"origin":"k-8e0402a7cfc92ab9","title":"标清、高清与超清","qs":["国考 2023 副省级 行测#103"],"definition":"标清、高清和超清是视频清晰度的常用等级名称。在本题的分级语境中，三者按清晰度从低到高排列。","explanation":"A项同样按一个指标递增，亚音速低于音速，超音速高于音速。D项的“幽静”“寂静”“安静”各有不同侧重，无法按本题要求形成固定的递增次序。","evidence":"三者均对清晰度进行分类，构成并列关系，且清晰度依次递增。","doubt":"","references":[]},{"origin":"k-fae081bb5293133b","title":"标清、高清与超清","qs":["国考 2023 行政执法 行测#98"],"definition":"标清、高清和超清都是描述视频画面清晰度的名称，在本题中依次表示由低到高的清晰度。","explanation":"三个词沿同一指标递增。A项也按同一指标排列，亚音速低于音速，超音速高于音速。D项的三个词都描述安静状态，但“幽静、寂静、安静”没有形成程度依次提高的序列。","evidence":"三者均对清晰度进行分类，构成并列关系，且清晰度依次递增。","doubt":"","references":[]}]},"k-d68c1cda63db6ac4":{"review":{"title":"亚音速与超音速","type":"概念与词义","definition":"物体相对于周围介质的运动速度低于当地声速时称为亚音速，等于当地声速时称为音速，高于当地声速时称为超音速。","explanation":"马赫数是物体相对于介质的运动速度与当地声速之比。空气中的声速随温度变化，同一运动速度在不同温度的空气中可对应不同马赫数。","basis":"据关联原题及所列出处编释。","references":[{"source":"mach","location":"速度与马赫数"}],"domain":"科技","examFocus":{"国考 2023 副省级 行测#103":"找出清晰度分级的比较尺度和顺序，再看各组三个词能否按一个明确尺度同向排列。"}},"aspects":[{"title":"以声速为界的速度顺序","uses":[{"unit":"Q1","role":"解题依据","use":"以同一当地声速为参照，A项从低于声速排到等于声速，再排到高于声速，对应题干从标清到高清再到超清的递增顺序。","evidence":"亚音速：音速：超音速","qids":["国考 2023 副省级 行测#103","国考 2023 地市级 行测#97","国考 2023 行政执法 行测#98"]}]}]},"k-30bd62648ac76091":{"review":{"definition":"刑事警察是从事刑事案件侦查等工作的警察，打击犯罪是其工作内容。","explanation":"C项的“打击犯罪”说明刑事警察做什么，与后一组“外交人员—对外交涉”的职业与工作内容关系一致。B项的“刑事案件”只指明刑事警察处理的对象，填入“侦查刑事案件”才会表达具体工作内容。","references":[],"evidence":"刑事警察的工作内容是打击犯罪","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-18f0a18f4acfc01e":{"review":{"definition":"对外交涉是就涉外事务向外方表达立场、提出要求或进行磋商的活动，属于外交人员的工作内容。","explanation":"C项把“外交人员”填入后一空，形成“职业—工作内容”关系，与前一组“刑事警察—打击犯罪”一致。A项的“维护主权”可作为对外交涉的目的，填入后形成的是目的与方式的关系。","references":[],"evidence":"外交人员的工作内容是对外交涉","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0747778c6878ab20":{"review":{"definition":"闭着嘴不说话，常指心有顾虑而不愿或不敢开口。","explanation":"本题以言语表现为比较角度，D项的“口若悬河”表示说话滔滔不绝，与闭口不言相反。A项的“三缄其口”侧重开口谨慎，C项的“守口如瓶”侧重严守秘密，解析均将它们与“缄口不言”视为近义。","references":[],"evidence":"缄口不言意思是封住嘴巴，不开口说话","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2ff2d74cd27bd006":{"review":{"definition":"形容人能说善辩，说起话来滔滔不绝。","explanation":"D项用“口若悬河”的话语不断与“缄口不言”的闭口形成对照。B项的“畅所欲言”也能与“缄口不言”形成反义，但它强调毫无拘束地说出想说的话。B项后半组的“放荡不羁”与“虚怀若谷”并不相反，因此只有D项两组关系一致。","references":[],"evidence":"口若悬河意为说话滔滔不绝","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7d843c5dd4210c64":{"review":{"definition":"形容人十分谦虚，胸襟开阔，能容纳别人的意见。","explanation":"D项以“矜功伐善”的自夸与“虚怀若谷”的谦虚相对。A项的“大智若愚”侧重有才智而不露锋芒，C项的“礼贤下士”侧重尊重贤才，两者与“虚怀若谷”各有不同的着眼点，不能让各自选项的前后两组都构成近义关系。","references":[],"evidence":"虚怀若谷指胸怀像山谷一样深广，形容十分谦虚","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-aa859cef0afbadc8":{"review":{"definition":"夸耀自己的功劳和才能，形容人很不虚心。","explanation":"D项的“矜功伐善”侧重自夸，与“虚怀若谷”的谦虚形成反义，和前半组“缄口不言”与“口若悬河”的关系一致。B项的“放荡不羁”侧重不受约束，无法与“虚怀若谷”形成同样的反义关系。","references":[],"evidence":"夸耀自己的功劳和才能，形容极不虚心。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1618e297e971dc67":{"review":{"definition":"如果某个结果成立时某项条件必须满足，该条件就是这个结果的必要条件。缺少必要条件，结果便不能成立。","explanation":"“只有P，才Q”表示Q成立必有P。题干把围绕市场主体需求实施更大力度减税降费列为帮助其渡过资金难关所必需的举措，A项保留了这个方向。按题干的逻辑，B项仅凭稳住市场主体就断定经济能够稳中求进，C项仅凭深化“放管服”改革就断定可以改善营商环境，都把所需条件当成了结果成立的保证。D项则把内生动力有助于进一步增强经济吸引力、创造力和竞争力，说成缺少内生动力时这些能力完全不存在，超出了题干表述。","references":[],"evidence":"只有围绕市场主体需求实施更大力度减税降费，才能帮助其渡过资金难关。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4f1da827daf01526":{"review":{"title":"全过程人民民主","type":"概念与词义","definition":"全过程人民民主是人民依法参与民主选举、民主协商、民主决策、民主管理和民主监督各环节的人民民主。党的二十大报告（2022年）将其定位为社会主义民主政治的本质属性，指出它是最广泛、最真实、最管用的民主。","explanation":"党的二十大报告指出，协商民主是实践全过程人民民主的重要形式，涵盖政党协商、人大协商、基层协商等渠道。基层民主是全过程人民民主的重要体现，报告提出健全基层党组织领导的基层群众自治机制。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"发展全过程人民民主"}],"related":["k-c74a86ea848cf0a2","k-53a4c7ef856b2d94","k-60f2a76759a4b86f"],"examFocus":{"国考 2023 副省级 行测#3":"对照党的二十大报告，分别核对人民民主的地位、全过程人民民主的属性与特点，以及相关民主形式的定位。"}},"readings":[{"origin":"k-4f1da827daf01526","title":"全过程人民民主","qs":["国考 2023 地市级 行测#2","国考 2023 行政执法 行测#2"],"definition":"全过程人民民主是人民依法参与民主选举、民主协商、民主决策、民主管理和民主监督各环节的人民民主。党的二十大报告（2022年）将其定位为社会主义民主政治的本质属性，指出它是最广泛、最真实、最管用的民主。","explanation":"党的二十大报告指出，协商民主是实践全过程人民民主的重要形式，涵盖政党协商、人大协商、基层协商等渠道。基层民主是全过程人民民主的重要体现，报告提出健全基层党组织领导的基层群众自治机制。","evidence":"","doubt":"","references":[{"source":"twenty","location":"发展全过程人民民主"}]},{"origin":"k-b8fa3788f5e58250","title":"全过程人民民主","qs":["国考 2023 副省级 行测#3"],"definition":"全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主。","explanation":"党的二十大报告以国家一切权力属于人民为制度前提。第①项以“人民民主”为主语，说明其在社会主义和全面建设社会主义现代化国家中的地位。第②项以“全过程人民民主”为主语，说明其性质和特点。两项均与报告表述一致。","evidence":"全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主","doubt":"","references":[]}],"aspects":[{"title":"二十大报告中的属性、特征与实践形式","uses":[{"unit":"Q1","role":"直接考查","use":"按党的二十大报告，①关于人民民主地位、②关于全过程人民民主的属性和特征、③关于协商民主的表述均正确，选C。④把报告所说的“基层民主”替换成了“党内民主”。","evidence":"②全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主③协商民主是实践全过程人民民主的重要形式④党内民主是全过程人民民主的重要体现","qids":["国考 2023 地市级 行测#2","国考 2023 行政执法 行测#2"]}]}]},"k-53a4c7ef856b2d94":{"review":{"title":"协商民主","type":"概念与词义","definition":"协商民主是各方面通过制度化渠道围绕公共事务交流意见、寻求共识的民主形式。党的二十大报告将其定位为实践全过程人民民主的重要形式。","explanation":"协商可以贯穿决策前和决策实施过程。党的二十大报告提出，统筹推进政党协商、人大协商、政府协商、政协协商、人民团体协商、基层协商和社会组织协商，健全各种制度化协商平台。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"全面发展协商民主"}],"related":["k-c74a86ea848cf0a2","k-4f1da827daf01526","k-60f2a76759a4b86f"],"examFocus":{"国考 2023 副省级 行测#3":"对照党的二十大报告，辨析协商民主、基层民主和党内民主各自的定位及其与全过程人民民主的关系。"}},"readings":[{"origin":"k-53a4c7ef856b2d94","title":"协商民主","qs":["国考 2023 地市级 行测#2","国考 2023 行政执法 行测#2"],"definition":"协商民主是各方面通过制度化渠道围绕公共事务交流意见、寻求共识的民主形式。党的二十大报告将其定位为实践全过程人民民主的重要形式。","explanation":"协商可以贯穿决策前和决策实施过程。党的二十大报告提出，统筹推进政党协商、人大协商、政府协商、政协协商、人民团体协商、基层协商和社会组织协商，健全各种制度化协商平台。","evidence":"","doubt":"","references":[{"source":"twenty","location":"全面发展协商民主"}]},{"origin":"k-81679359595641d5","title":"协商民主","qs":["国考 2023 副省级 行测#3"],"definition":"党的二十大报告将协商民主定位为实践全过程人民民主的重要形式，并提出健全各种制度化协商平台。","explanation":"报告列举了政党协商、人大协商、政府协商、政协协商、基层协商等，说明协商民主可以在多个层面通过制度化渠道开展。第③项准确复述了报告对协商民主的定位。","evidence":"协商民主是实践全过程人民民主的重要形式","doubt":"","references":[]}],"aspects":[{"title":"全过程人民民主中的定位","uses":[{"unit":"Q1","role":"直接考查","use":"题目要求按党的二十大报告判断四项表述。③符合报告对协商民主的定位，与①②一同入选，答案为C。（国考 2023 地市级 行测第2题、国考 2023 行政执法 行测第2题）","evidence":"协商民主是实践全过程人民民主的重要形式","qids":["国考 2023 地市级 行测#2","国考 2023 行政执法 行测#2"]}]}]},"k-60f2a76759a4b86f":{"review":{"title":"基层民主","type":"概念与词义","definition":"基层民主是人民群众在基层依法参与公共事务和公益事业管理的民主实践。党的二十大报告将其定位为全过程人民民主的重要体现。","explanation":"党的二十大报告提出，健全基层党组织领导的基层群众自治机制，完善基层直接民主制度体系和工作体系，增强城乡社区群众自我管理、自我服务、自我教育、自我监督的实效。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"积极发展基层民主"}],"related":["k-c74a86ea848cf0a2","k-4f1da827daf01526","k-53a4c7ef856b2d94"],"examFocus":{"国考 2023 副省级 行测#3":"对照党的二十大报告，辨析协商民主、基层民主和党内民主各自的定位。"}},"readings":[{"origin":"k-60f2a76759a4b86f","title":"基层民主","qs":["国考 2023 地市级 行测#2","国考 2023 行政执法 行测#2"],"definition":"基层民主是人民群众在基层依法参与公共事务和公益事业管理的民主实践。党的二十大报告将其定位为全过程人民民主的重要体现。","explanation":"党的二十大报告提出，健全基层党组织领导的基层群众自治机制，完善基层直接民主制度体系和工作体系，增强城乡社区群众自我管理、自我服务、自我教育、自我监督的实效。","evidence":"","doubt":"","references":[{"source":"twenty","location":"积极发展基层民主"}]},{"origin":"k-72d1d436498db93b","title":"基层民主","qs":["国考 2023 副省级 行测#3"],"definition":"党的二十大报告将基层民主定位为全过程人民民主的重要体现，并提出完善基层直接民主制度体系和工作体系。","explanation":"报告将健全基层党组织领导的基层群众自治机制、增强城乡社区群众自我管理和自我监督的实效列为发展基层民主的措施。第④项把报告中与“重要体现”对应的主体从“基层民主”换成“党内民主”，因此错误。","evidence":"民主是全过程人民民主的重要体现。健全基层党组织领导的基层群众自治机制","doubt":"","references":[]}],"aspects":[{"title":"全过程人民民主中的定位","uses":[{"unit":"Q1","role":"解题依据","use":"题中④将报告对基层民主的定位套用于党内民主，因此排除④，选择①②③，答案为C。（国考 2023 地市级 行测第2题、国考 2023 行政执法 行测第2题）","evidence":"基层\n民主是全过程人民民主的重要体现。","qids":["国考 2023 地市级 行测#2","国考 2023 行政执法 行测#2"]}]}]},"k-fdb33b9733777e9e":{"review":{"definition":"高质量发展是体现创新、协调、绿色、开放、共享的新发展理念，能够更好满足人民日益增长的美好生活需要的发展。《习近平经济思想学习纲要》把推动高质量发展概括为我国经济发展的鲜明主题。","explanation":"②判断的是推动高质量发展在我国经济发展中的定位，其与《习近平经济思想学习纲要》中的“鲜明主题”对应，因此成立。③所说的“指导原则”对应坚持新发展理念。","references":[],"evidence":"推动高质量发展是我国经济发展的鲜明主题","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"b1849da23e5bae07","label":"高质量发展","topic":"发展与治理","category":"非时政","text":"1.高质量发展\n高质量发展是能够满足人民日益增长的美好生活需要的发展，是体现新发展理念的发\n展，是创新成为第一动力、协调成为内生特点、绿色成为普遍形态、开放成为必由之路、\n共享成为根本目的的发展。\n习近平总书记在党的二十大报告中强调，“高质量发展是全面建设社会主义现代化国家\n的首要任务。发展是党执政兴国的第一要务。没有坚实的物质技术基础，就不可能全面建成\n社会主义现代化强国。”","source":{"doc":"6cbfb01fe723bba64b75","first":27,"last":27,"page":27,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-78d50a8035b03890":{"review":{"definition":"新发展理念包括创新、协调、绿色、开放、共享。《习近平经济思想学习纲要》把坚持新发展理念概括为我国经济发展的指导原则。","explanation":"③把坚持新发展理念定位为指导原则，与《习近平经济思想学习纲要》的表述一致。开放属于新发展理念的五个方面之一，但在题目所问的定位中，“第一动力”对应坚持创新驱动发展，④将这一定位误配给了对外开放。","references":[],"evidence":"坚持新发展理念是我国经济发展的指导原则","disposition":"独立词条","basis":"据原题和解析编释。","title":"新发展理念","related":[],"examFocus":{"国考 2023 副省级 行测#5":"依据《习近平经济思想学习纲要》，逐项辨析有关理念和举措是否与题中所称的历史方位、主题、指导原则、动力和着力点相符。"}},"readings":[{"origin":"k-78d50a8035b03890","title":"新发展理念","qs":["国考 2023 地市级 行测#4"],"definition":"新发展理念包括创新、协调、绿色、开放、共享。《习近平经济思想学习纲要》把坚持新发展理念概括为我国经济发展的指导原则。","explanation":"③把坚持新发展理念定位为指导原则，与《习近平经济思想学习纲要》的表述一致。开放属于新发展理念的五个方面之一，但在题目所问的定位中，“第一动力”对应坚持创新驱动发展，④将这一定位误配给了对外开放。","evidence":"坚持新发展理念是我国经济发展的指导原则","doubt":"","references":[]},{"origin":"k-9691e274ddf68397","title":"新发展理念","qs":["国考 2023 副省级 行测#5"],"definition":"新发展理念包括创新、协调、绿色、开放、共享。《习近平经济思想学习纲要》将坚持新发展理念定位为我国经济发展的指导原则。","explanation":"五项理念共同指导经济发展，③对其总体定位的表述正确。开放是新发展理念的一项内容，而题中④所称“第一动力”在《纲要》中对应创新驱动发展。","evidence":"坚持新发展理念是我国经济发展的指导原则","doubt":"","references":[]}],"sources":[{"id":"ffebdd7a058652ba","label":"新发展理念","topic":"发展与治理","category":"非时政","text":"1.新发展理念\n党的十八届五中全会提出了创新、协调、绿色、开放、共享的新发展理念。\n创新是引领发展的第一动力，协调是持续健康发展的内在要求，绿色是永续发展的必要\n条件和人民对美好生活追求的重要体现，开放是国家繁荣发展的必由之路，共享是中国特色\n社会主义的本质要求。\n创新发展注重的是解决发展动力问题，协调发展注重的是解决发展不平衡问题，绿色发\n展注重的是解决人与自然和谐问题，开放发展注重的是解决发展内外联动问题，共享发展注\n重的是解决社会公平正义问题。","source":{"doc":"6cbfb01fe723bba64b75","first":21,"last":21,"page":21,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"},{"id":"a96efe606f622af6","label":"新发展理念","topic":"党政制度与理论","category":"非时政","text":"1.新发展理念\n党的十八届五中全会提出，必须牢固树立创新、协调、绿色、开放、共享的发展\n理念。\n创新是引领发展的第一动力，协调是持续健康发展的内在要求，绿色是永续发展\n的必要条件和人民对美好生活追求的重要体现，开放是国家繁荣发展的必由之路，共\n享是中国特色社会主义的本质要求。\n创新发展注重的是解决发展动力问题，协调发展注重的是解决发展不平衡问题，\n绿色发展注重的是解决人与自然和谐问题，开放发展注重的是解决发展内外联动问\n题，共享发展注重的是解决社会公平正义问题。\n——《新华网》","source":{"doc":"41195a191a57c1c36332","first":3,"last":4,"page":3,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-4e745fb604a3c668":{"review":{"definition":"创新驱动发展强调以创新带动经济发展。《习近平经济思想学习纲要》把坚持创新驱动发展概括为我国经济发展的第一动力。","explanation":"《习近平经济思想学习纲要》将“第一动力”对应坚持创新驱动发展，将“重要法宝”对应坚定不移全面扩大开放。④把第一动力归给对外开放，因而错误。本题正确的有①②③⑤，共四项。","references":[],"evidence":"坚持创新驱动发展","disposition":"独立词条","basis":"据原题和解析编释。","title":"创新驱动发展","related":[],"examFocus":{"国考 2023 副省级 行测#5":"依据《习近平经济思想学习纲要》，辨析历史方位、鲜明主题、指导原则、第一动力和主要着力点各自对应的表述。"}},"readings":[{"origin":"k-4e745fb604a3c668","title":"创新驱动发展","qs":["国考 2023 地市级 行测#4"],"definition":"创新驱动发展强调以创新带动经济发展。《习近平经济思想学习纲要》把坚持创新驱动发展概括为我国经济发展的第一动力。","explanation":"《习近平经济思想学习纲要》将“第一动力”对应坚持创新驱动发展，将“重要法宝”对应坚定不移全面扩大开放。④把第一动力归给对外开放，因而错误。本题正确的有①②③⑤，共四项。","evidence":"坚持创新驱动发展","doubt":"","references":[]},{"origin":"k-4fccd7d36caedb1c","title":"创新驱动发展","qs":["国考 2023 副省级 行测#5"],"definition":"创新驱动发展强调依靠创新形成发展动力。《习近平经济思想学习纲要》将坚持创新驱动发展定位为我国经济发展的第一动力。","explanation":"④把“第一动力”错配给对外开放。《纲要》将坚定不移全面扩大开放定位为我国经济发展的“重要法宝”。排除④后，①②③⑤共四项正确，选C。","evidence":"坚持创新驱动发展是我国经济发\n展的第一动力","doubt":"","references":[]}]},"k-ba21811591ff4d33":{"review":{"definition":"实体经济涵盖物质产品生产以及提供实际服务的经济活动，制造业是其中的重要组成部分。《习近平经济思想学习纲要》把大力发展制造业和实体经济概括为我国经济发展的主要着力点。","explanation":"⑤沿用《习近平经济思想学习纲要》的表述，并提制造业和实体经济，突出制造业在实体经济中的地位。这里对应的定位是“主要着力点”，所以⑤计入正确项。","references":[],"evidence":"大力发展制造业和实体经济是我国经济发展的主要着力点","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"d28abd67bac9d0d3","label":"实体经济","topic":"产业、科技与对外开放","category":"非时政","text":"2.实体经济\n实体经济指物质的、精神的产品和服务的生产、流通等经济活动，包括农业、工业、交\n通运输业、商业、建筑业等物质生产和服务部门，是国民经济的根基，区别于金融、房地产\n等虚拟经济领域，实体经济是一国经济的立身之本，是财富创造的根本源泉，是国家强盛的\n重要支柱。习近平总书记强调，经济发展任何时候都不能脱实向虚。要处理好实体经济与虚\n拟经济的关系，推动虚拟经济服务于实体经济，促进两者协同发展。","source":{"doc":"6cbfb01fe723bba64b75","first":16,"last":16,"page":16,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-ba33b5486fe871ee":{"review":{"definition":"畅通无阻指通行或通过时没有阻碍，也可形容经济循环等过程运转顺畅。","explanation":"文段以调理任督二脉作比，落脚于生产要素在生产、分配、流通、消费各环节之间顺利流转，因此选C。“环环相扣”强调环节衔接紧密，贴合“有机衔接”，但“畅通无阻”更能概括衔接所要实现的循环流转。","references":[],"evidence":"“畅通无阻”指毫无阻碍地通行或通过","disposition":"独立词条","basis":"据原题和解析编释。","title":"畅通无阻","related":[],"examFocus":{"国考 2023 副省级 行测#21":"结合任督二脉的比喻，区分描述各环节如何衔接的成语和概括经济循环状态的成语。"}},"readings":[{"origin":"k-ba33b5486fe871ee","title":"畅通无阻","qs":["国考 2023 地市级 行测#21"],"definition":"畅通无阻指通行或通过时没有阻碍，也可形容经济循环等过程运转顺畅。","explanation":"文段以调理任督二脉作比，落脚于生产要素在生产、分配、流通、消费各环节之间顺利流转，因此选C。“环环相扣”强调环节衔接紧密，贴合“有机衔接”，但“畅通无阻”更能概括衔接所要实现的循环流转。","evidence":"“畅通无阻”指毫无阻碍地通行或通过","doubt":"","references":[]},{"origin":"k-d36ba0998e57b8ff","title":"畅通无阻","qs":["国考 2023 副省级 行测#21"],"definition":"畅通无阻指通行或流转顺利，没有阻碍。","explanation":"文段以调理任督二脉作比，强调生产要素要在生产、分配、流通、消费各环节顺利流转，因此选“畅通无阻”。“环环相扣”也能形容环节之间的联系，侧重衔接紧密，空缺处则要突出循环的通畅程度。","evidence":"在生产、分配、流通、消费各环节有机衔接，从而实现循环流转","doubt":"","references":[]}]},"k-bc355a724e1a49bf":{"review":{"definition":"比喻说话或做事目标明确，有针对性。","explanation":"题干用“报得准”强调预报的准确性。准确的预报为有关部门提供决策依据，使防灾减灾措施能够针对预报提示的风险，因此选B。“有条不紊”侧重办事有条理，“万无一失”则表示有绝对把握，程度过强。","references":[],"evidence":"天气预报准确率高，防灾减灾才能","disposition":"独立词条","basis":"据原题和解析编释。","title":"有的放矢","related":[],"examFocus":{"国考 2023 地市级 行测#22":"结合后文的决策和应急处置，判断横线处要概括准确预报对防灾减灾的什么作用。","国考 2023 行政执法 行测#30":"首空结合调研、找准问题与补齐短板的关系辨析，次空留意“不会”和下文对系统性问题的说明。"}},"readings":[{"origin":"k-bc355a724e1a49bf","title":"有的放矢","qs":["国考 2023 地市级 行测#22"],"definition":"比喻说话或做事目标明确，有针对性。","explanation":"题干用“报得准”强调预报的准确性。准确的预报为有关部门提供决策依据，使防灾减灾措施能够针对预报提示的风险，因此选B。“有条不紊”侧重办事有条理，“万无一失”则表示有绝对把握，程度过强。","evidence":"天气预报准确率高，防灾减灾才能","doubt":"","references":[]},{"origin":"k-dea44674b0a9928d","title":"有的放矢","qs":["国考 2023 行政执法 行测#30"],"definition":"“有的放矢”比喻说话或做事有明确的对象和针对性。","explanation":"题干要求先调研并弄清问题的本质和关键，再据此采取补齐公共服务短板的措施。“有的放矢”着眼于找准问题后针对性地行动，“一针见血”侧重说话或分析直截了当地切中要害。","evidence":"深入调研、综合分析、精准掌握，弄清问题的本质和关键","doubt":"","references":[]}]},"k-90785fda85f68e8b":{"review":{"definition":"增加收入来源，节省开支。也可借指增加某种资源的流入，同时减少其流失。","explanation":"题中用引号标明借用义。固定并沉积河流、潮汐带来的外源性碳是“开源”，厌氧环境减慢根系和凋落物的分解是“节流”。两种作用共同增强红树林的碳汇功能，因此选C。“一举两得”强调一项举措带来两种好处，题干写的是两种作用共同促成一个结果。","references":[],"evidence":"外源性碳，被它们固定并快速沉积下来","disposition":"独立词条","basis":"据原题和解析编释。","title":"开源节流","related":[],"examFocus":{"国考 2023 地市级 行测#23":"结合根系和凋落物的分解过程与外源性碳的沉积过程，判断哪个成语能同时概括红树林的两种作用。"}},"readings":[{"origin":"k-90785fda85f68e8b","title":"开源节流","qs":["国考 2023 地市级 行测#23"],"definition":"增加收入来源，节省开支。也可借指增加某种资源的流入，同时减少其流失。","explanation":"题中用引号标明借用义。固定并沉积河流、潮汐带来的外源性碳是“开源”，厌氧环境减慢根系和凋落物的分解是“节流”。两种作用共同增强红树林的碳汇功能，因此选C。“一举两得”强调一项举措带来两种好处，题干写的是两种作用共同促成一个结果。","evidence":"外源性碳，被它们固定并快速沉积下来","doubt":"","references":[]},{"origin":"k-b7da6866cdc92206","title":"开源节流","qs":["国考 2023 行政执法 行测#22"],"definition":"指增加收入来源并节省开支，也可比喻一边扩大来源，一边减少损耗。","explanation":"题干中，红树林固定随河流和潮汐而来的外源性碳，对应“开源”。地下厌氧环境减缓根系和凋落物分解，使更多碳得以埋藏，对应“节流”。两条途径共同增强碳汇作用，C项比侧重一个举措带来两种收益的“一举两得”更贴合这两个方向。","evidence":"被它们固定并快速沉积下来","doubt":"","references":[]}]},"k-3afc67d7d76282fe":{"review":{"definition":"指等待或做事时能沉住气，不急躁、不厌烦。","explanation":"题中的“历史耐心”指推进现代化时尊重发展进程，按步骤持续推进。“稳中求进、循序渐进、持续推进”具体体现了这种心态，第二空据此选“耐心”。“清醒”侧重认识清楚，“自信”侧重相信自己。","references":[],"evidence":"坚持稳中求进、循序渐进、持续推进","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e101eb3ad29ac9e5":{"review":{"definition":"指某种事物、情形或程度以前从未出现过。","explanation":"题干以十四亿多人口整体迈向现代化、规模超过现有发达国家人口总和为依据，强调这一进程的艰巨性和复杂性在以往无先例，因此第一空选“前所未有”。“异乎寻常”只强调超出平常水平。","references":[],"evidence":"规模超过现有发达国家人口的总和","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3f87a082ec3083ea":{"review":{"definition":"指靠近，也可指表达方式或内容与特定对象的实际情况相契合。","explanation":"题干提出全球化表达、区域化表达和分众化表达，要求传播方式适应不同区域、国家和群体的受众。“贴近”直接说明传播方式与受众的关系，并与后文“亲和力”呼应。“细分”侧重把受众划为更具体的群体。","references":[],"evidence":"推进中国故事和中国声音的全球化表达、区域化表达、分众化表达","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-221e4b4327bac07f":{"review":{"definition":"指让人感到亲近、愿意接触的特质或力量。","explanation":"题中根据不同区域、国家和群体的受众调整表达方式，能使中国故事和中国声音更易为受众接触和接受。“亲和力”体现这种效果，与第一空的“贴近”呼应，因此选B。“说服力”侧重使受众信服某个判断或主张。","references":[],"evidence":"愿意接触的力量","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ee4ea8e8d0c29e89":{"review":{"definition":"「评估」指依据有关情况加以评价和估量。「评估社会危害性」指综合相关情节，对行为的社会危害作出评价。","explanation":"第30题第二空承接对主观认知、动机目的等情节的全面考察。文段要求以综合评价为依据，审慎决定是否启动惩罚机制。「辨别」侧重区分真伪、好坏等，难以表达这里综合多项情节衡量危害的意思。","references":[],"evidence":"“评估社会危害性”为常见搭配","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-68cfff6392294960":{"review":{"definition":"对同一问题的看法、判断等存在差异。","explanation":"第31题第二空的「分歧」指科学家对未来变暖速度及相关变量变化的预测判断存在差异。题中以极端降水将如何变化为例说明预测仍有不确定性。「短板」「瑕疵」「漏洞」均指某种不足或缺陷，无法表达判断之间的差异。","references":[],"evidence":"类似极端降水这样的关键变量将如何变化，仍有很大的不确定性","disposition":"独立词条","basis":"据原题和解析编释。","title":"分歧","related":[],"examFocus":{"国考 2023 副省级 行测#27":"首空比较实际升温与物理预期的关系，第二空结合极端降水的例子，辨析词语指向的是预测过程还是预测判断。"}},"readings":[{"origin":"k-68cfff6392294960","title":"分歧","qs":["国考 2023 地市级 行测#31"],"definition":"对同一问题的看法、判断等存在差异。","explanation":"第31题第二空的「分歧」指科学家对未来变暖速度及相关变量变化的预测判断存在差异。题中以极端降水将如何变化为例说明预测仍有不确定性。「短板」「瑕疵」「漏洞」均指某种不足或缺陷，无法表达判断之间的差异。","evidence":"类似极端降水这样的关键变量将如何变化，仍有很大的不确定性","doubt":"","references":[]},{"origin":"k-8ea31b782d52e088","title":"分歧","qs":["国考 2023 副省级 行测#27"],"definition":"指不同的看法、判断或意见之间存在差异。","explanation":"第27题第二空承接的问题是未来变暖有多快，后文又举出极端降水如何变化仍有很大不确定性。按题目解析，这里填“分歧”，侧重科学家的预测判断可能有差异。“短板”“瑕疵”“漏洞”分别侧重不足、细小缺点和破绽，仅凭预测存在不确定性，无法判定模型有这些缺陷。","evidence":"类似极端降水这样的关键变量将如何变化，仍有很大的不确定性","doubt":"","references":[]}]},"k-75c99e386a66aaa8":{"review":{"definition":"各个方面都照顾到了，没有遗漏。","explanation":"第32题第二空指城管执法能否覆盖各类事项和对象。超大城市执法事项多、市场主体庞杂，加上执法力量有限，平均用力也很难做到全面覆盖。「百无一失」侧重有把握、不出差错，对应的是差错风险。","references":[],"evidence":"城管执法事项繁多，涉及市场主体庞杂，而城管执法力量是有限的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9b52ade8a4859e40":{"review":{"definition":"没有人来探问、尝试或购买，也可形容某处或某事无人过问。","explanation":"第33题第二空指偏远、人口稀少的区域生态恶化时缺少人过问。文段以明确产权归属、建立管理机制来解决这一问题。「听之任之」侧重任由事情发展，「鞭长莫及」侧重力量所不能及。","references":[],"evidence":"避免出现生态环境恶化却","disposition":"独立词条","basis":"据原题和解析编释。","title":"无人问津","related":[],"examFocus":{"国考 2023 地市级 行测#33":"首空考查动词与“管理效能”的搭配，末空要结合偏远地区的产权归属和管理机制，辨析成语描述的是哪类治理困境。","江苏 2024 A类 行测#39":"用“变成网红”判断首空所需的反差，再结合花形描写和“并非……而是……”的结构核对后两空。"}},"readings":[{"origin":"k-9b52ade8a4859e40","title":"无人问津","qs":["国考 2023 地市级 行测#33"],"definition":"没有人来探问、尝试或购买，也可形容某处或某事无人过问。","explanation":"第33题第二空指偏远、人口稀少的区域生态恶化时缺少人过问。文段以明确产权归属、建立管理机制来解决这一问题。「听之任之」侧重任由事情发展，「鞭长莫及」侧重力量所不能及。","evidence":"避免出现生态环境恶化却","doubt":"","references":[]},{"origin":"k-e5c52c0b4b947bd8","title":"无人问津","qs":["江苏 2024 A类 行测#39"],"definition":"比喻没有人来打听、过问、尝试或购买，侧重缺少外界关注或参与。","explanation":"第39题写禾雀花从少有人关注的乡土植物变成“网红”。“无人问津”与走红形成关注度上的反差。“鲜为人知”侧重知道的人少，第一空也能说通，整题还要结合第三空判断。","evidence":"“无人问津”比喻没有人来探问、尝试或购买","doubt":"","references":[]}]},"k-a5e5218196226f6e":{"review":{"definition":"「警戒」在警示义上指告诫人注意风险或约束行为。「提醒」侧重引起注意。","explanation":"第34题第二空写柔性执法对群众的作用。前文说人们随时可能触及法律红线，「警戒」更能体现柔性执法让人意识到越界风险、注意约束行为的作用。","references":[],"evidence":"“警戒”表示警示告诫，使人注意","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-68485632d6f896b9":{"review":{"definition":"自己认识到某事应该做，并主动去做。","explanation":"第35题第一空指市场主体在注册制改革更包容的背景下，仍应主动、诚实地把自身信息说完整、说清楚。「自强」侧重努力使自身强大，和文段强调的主动履行信息披露责任不对应。","references":[],"evidence":"将自身相关信息说完整、说清楚","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-260631b636304546":{"review":{"definition":"心里想做某件事，但能力或力量达不到要求。","explanation":"第37题要求环境整治“不留死角、不存盲点”，首空说的是仅靠人工监管恐怕覆盖不过来。“收效甚微”着眼于实际成效很小，比这里的能力不足判断更重。“捉襟见肘”和“顾此失彼”也能表达监管吃紧，首空仍需与后两空合看。","references":[],"evidence":"“力不从心”指心里想做，可是能力或力量够不上","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8a61abea221f8e4e":{"review":{"definition":"比喻轻微的动荡或变故，侧重变化虽小却可被察觉。","explanation":"第37题用“天罗地网”比喻数字监测的覆盖能力，第二空指连轻微变动也能暴露在监测数据中。“小打小闹”说的是做事规模小，“一举一动”通常指人的每个动作。结合末空需要体现与“具象”相呼应的细致程度，选“风吹草动、精细”的B项。","references":[],"evidence":"“风吹草动”比喻轻微的动荡或变故","disposition":"独立词条","basis":"据原题和解析编释。","title":"风吹草动","related":[],"examFocus":{"国考 2023 地市级 行测#37":"结合“天罗地网”的比喻辨析第二空词语的适用对象，再看末空与“具象”的并列关系。"}},"readings":[{"origin":"k-8a61abea221f8e4e","title":"风吹草动","qs":["国考 2023 地市级 行测#37"],"definition":"比喻轻微的动荡或变故，侧重变化虽小却可被察觉。","explanation":"第37题用“天罗地网”比喻数字监测的覆盖能力，第二空指连轻微变动也能暴露在监测数据中。“小打小闹”说的是做事规模小，“一举一动”通常指人的每个动作。结合末空需要体现与“具象”相呼应的细致程度，选“风吹草动、精细”的B项。","evidence":"“风吹草动”比喻轻微的动荡或变故","doubt":"","references":[]},{"origin":"k-f134206454a873c7","title":"风吹草动","qs":["国考 2023 行政执法 行测#39"],"definition":"“风吹草动”比喻轻微的动荡或变故，也可指细微的动静。","explanation":"第二空承接前文的“天罗地网”。“任何‘风吹草动’”指生态环境监测范围内的细微动静，说明数字监测网能让这些变化显现在数据中。“小打小闹”侧重做事规模小，与监测网捕捉细微变化的意思不合。最终由第三空的“精细”与“具象”并列，确定B项。","evidence":"“风吹草动”比喻轻微的动荡或变故","doubt":"","references":[]}]},"k-f6b1953419789c80":{"review":{"title":"精细与有效","type":"概念与词义","definition":"精细指细致、精密。有效指能产生所期望的效果。","explanation":"评价环境监测时，“精细”着眼于观测和记录能细化到什么程度，“有效”着眼于监测能否实现识别污染等预定目标。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典精細","location":"“精細”词目"},{"source":"词典有效","location":"“有效”词目"}],"examFocus":{"国考 2023 地市级 行测#37":"结合数字监测的描写，比较第三空的词与“更加具象”并列时是否贴合语境。"}},"aspects":[{"title":"监测的细致程度","uses":[{"unit":"Q1","role":"直接考查","use":"第三空与“更加具象”并列。前文写数字监测能让细微变化显现在数据中，突出监测和防治的细致程度，因此选B项的“精细”。A项的“有效”侧重目标能否实现。两卷答案均为B（国考 2023 地市级 行测第37题、国考 2023 行政执法 行测第39题）。","evidence":"B项“精细”指精密细致，符合文意，当选。A项“有效”指能实现预期目的，有效果","qids":["国考 2023 地市级 行测#37","国考 2023 行政执法 行测#39"]}]}]},"k-ead9a7f74aca339f":{"review":{"definition":"经过长期而充分的积累，到时机成熟时才将积累转化为成果。","explanation":"第38题以“十年磨一剑”和“持续投入”交代积累过程，以“迈上发展新台阶”交代后续成果，第二空用“厚积薄发”衔接这两个阶段。“卧薪尝胆”侧重刻苦自励，“筚路蓝缕”侧重创业艰辛。","references":[],"evidence":"持续投入，迎难而上，才能在","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-196a76c16bd67925":{"review":{"definition":"“自强不息”指努力上进、永不懈怠。“稳扎稳打”比喻有步骤、有把握地推进工作。","explanation":"第38题末空与“勇毅前行”并列，前文又写中小企业克服融资难、原料贵、订单少等困难，持续投入自主创新。“自强不息”突出持续奋进的劲头，与这些语句相呼应。“稳扎稳打”突出推进的方式和节奏。","references":[],"evidence":"“自强不息”指努力上进，永不懈怠","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b66f5908fe5557d4":{"review":{"title":"息息相关与相辅相成","type":"概念与词义","definition":"息息相关形容两个或多个事物之间的关系十分密切。相辅相成指事物彼此配合、相互补充，从而共同发挥作用。","explanation":"共同变化或一方影响另一方，都可以体现事物联系密切。能说明各方怎样彼此补足时，用“相辅相成”可以进一步写出配合关系。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典息息相關","location":"“息息相關”词目"},{"source":"词典相輔相成","location":"“相輔相成”词目"}],"examFocus":{"国考 2023 地市级 行测#40":"结合下文辨别首空强调联系密切还是彼此配合，再核对后两空的词语搭配。"}},"aspects":[{"title":"竞争与创新的联系","uses":[{"unit":"Q1","role":"直接考查","use":"首空概括竞争与创新的关系。后文提出平台反垄断要在抑制垄断和鼓励创新之间取得平衡，支持用“息息相关”概括两者的联系。“相辅相成”则强调竞争与创新怎样彼此补充。结合后两空，两卷均选D（国考 2023 地市级 行测第40题、国考 2023 行政执法 行测第40题）。","evidence":"平台反垄断最终要在抑制垄断与鼓励创新之间达到平衡。","qids":["国考 2023 地市级 行测#40","国考 2023 行政执法 行测#40"]}]}]},"k-d1af7383f2618d43":{"review":{"title":"制止与约束","type":"概念与词义","definition":"制止指阻止某种行为发生或继续。约束指通过规则、纪律等对行为加以限制或管束。","explanation":"“制止违规交易”指叫停具体的违规行为。“约束交易行为”指给行为划定界限，界限内的交易仍可进行。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典制止","location":"“制止”词目"},{"source":"词典約束","location":"“約束”词目"}],"examFocus":{"国考 2023 地市级 行测#40":"第二空与“预防”并列，结合动词所支配的对象及行为所处阶段，辨别词义和搭配。"}},"aspects":[{"title":"阻止滥用行政权力限制竞争","uses":[{"unit":"Q1","role":"直接考查","use":"第二空与“预防”并列，对象是滥用行政权力限制竞争的行为。“预防”着眼于事前防范，“制止”着眼于阻止这类行为发生或继续。“约束”更适合表示对权力行使划定界限。两卷均选D（国考 2023 地市级 行测第40题、国考 2023 行政执法 行测第40题）。","evidence":"“制止”指强迫使停止，不允许继续","qids":["国考 2023 地市级 行测#40","国考 2023 行政执法 行测#40"]}]}]},"k-e7b0b7249dce7e00":{"review":{"title":"释放动能","type":"概念与词义","definition":"“释放动能”在经济语境中指让已经具备或尚未充分发挥的推动力量起作用。","explanation":"这里的“动能”取比喻义，可以指市场竞争、技术创新等带来的推动力。“充分释放”强调让这种力量尽可能发挥出来。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"国考 2023 地市级 行测#40":"用前文的准入和审查措施判断第三空要表达的作用，再核对动词与“动能”的搭配。"}},"aspects":[{"title":"发挥市场竞争机制的作用","uses":[{"unit":"Q1","role":"直接考查","use":"第三空的宾语是“市场竞争机制的强大动能”。前文提出健全市场准入制度和公平竞争审查机制，落脚于让竞争机制的推动作用充分发挥，对应“充分释放”。两卷均选D（国考 2023 地市级 行测第40题、国考 2023 行政执法 行测第40题）。","evidence":"“释放”符合文意，且与“动能”为常见搭配","qids":["国考 2023 地市级 行测#40","国考 2023 行政执法 行测#40"]}]}]},"k-d7e6ccc2e416504e":{"review":{"definition":"万物可以共同生长而互不妨害，各种道理或道路可以并行而互不冲突。用来说明不同事物可以相容共存。","explanation":"第41题用这句古语承接“构建人类命运共同体”，并引出各国“和睦相处、合作共赢”以及后文的“交流互鉴”。“并育”“并行”贴合各国相容共处的意思。“大道之行也，天下为公”侧重天下为公，与后文和睦相处的呼应较弱。","references":[],"evidence":"万物并育而不相害，道并行而不相悖","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-82678b9cd4c22c94":{"review":{"definition":"以保持内心宁静来修养身心。","explanation":"“静”是方式，“修身”是目的。C项的下一句“俭以养德”也按方式与目的组成，两句分别对应题干中用猛药去疴、用重典治乱的结构。","references":[],"evidence":"通过内心安静精力集中来修养身心","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-168b95368790472f":{"review":{"definition":"以践行俭朴来培养品德。","explanation":"“俭”是方式，“养德”是目的，内部关系与题干的“重典治乱”一致。C项前句“静以修身”也具有同样的结构，因此两句都符合题干。","references":[],"evidence":"通过俭朴的作风来培养品德","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5db0f370d743d9ec":{"review":{"definition":"两个概念所指的对象有一部分重合，且双方各有一部分对象在对方的范围之外。","explanation":"铜镜按材质命名，化妆镜按用途命名，两者有重合且各有独有对象。B项的木碗与汤碗也按“材质、用途”的顺序命名，外延同样交叉。D项也有交叉，但“古瓶”按年代界定。","references":[],"evidence":"有的木碗是汤碗，有的木碗不是汤碗，有的汤碗是木碗，有的汤碗不是木碗","disposition":"独立词条","basis":"据原题和解析编释。","title":"概念外延的交叉关系","related":[],"examFocus":{"国考 2023 地市级 行测#94":"比较每组两个名称的分类依据，并判断两类对象的范围是交叉、包含还是互斥。","江苏 2024 A类 行测#73":"分别比较首尾两个概念的外延，以及中间概念与两端各自的外延关系。"}},"readings":[{"origin":"k-5db0f370d743d9ec","title":"概念外延的交叉关系","qs":["国考 2023 地市级 行测#94"],"definition":"两个概念所指的对象有一部分重合，且双方各有一部分对象在对方的范围之外。","explanation":"铜镜按材质命名，化妆镜按用途命名，两者有重合且各有独有对象。B项的木碗与汤碗也按“材质、用途”的顺序命名，外延同样交叉。D项也有交叉，但“古瓶”按年代界定。","evidence":"有的木碗是汤碗，有的木碗不是汤碗，有的汤碗是木碗，有的汤碗不是木碗","doubt":"","references":[]},{"origin":"k-7cc137dd7ecb09c2","title":"概念外延的交叉关系","qs":["江苏 2024 A类 行测#73"],"definition":"两个概念的外延有一部分重合，并且各自都有对方未涵盖的对象，二者即构成交叉关系。","explanation":"题干按阶段界定「阶段成果」，它可以分别涵盖一部分实践成果和一部分理论成果。D项按时代界定「现代文明」，现代和前现代都可以有物质文明、精神文明，因此中间项也与两端分别交叉。B项在解析中则把阅读辅导和写作辅导视为读写辅导的组成部分。","evidence":"“现代文明”与“物质文明”和“精神文明”分别构成交叉关系。","doubt":"","references":[]}]},"k-59bf95524d8ac95d":{"review":{"definition":"同一上位概念下，几个概念的外延彼此不相交，合起来也未覆盖上位概念的全部外延。","explanation":"片剂、散剂、气雾剂按剂型并列，药物还有其他剂型。D项的头部、腰部和腿部理疗按单个施治部位并列，还有其他部位可施治理疗。B项的“君子协定”着眼于双方的信任，与按形式区分的口头契约、书面协议采用了不同的分类标准。","references":[],"evidence":"三者是根据药物的剂型划分的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2826045170745a5c":{"review":{"title":"火星探测","type":"概念与词义","definition":"火星探测是以火星及其环境为对象的航天探测活动，属于深空探测。","explanation":"火星探测按探测对象划分，可以采用环绕、着陆和巡视等形式。我国天问一号任务涵盖这三种形式。","basis":"据关联原题及所列出处编释。","references":[{"source":"rover","location":"天问一号环绕、着陆与巡视探测"}],"domain":"科技","examFocus":{"国考 2023 地市级 行测#99":"辨明两空补入的词各自表示什么，再比较两组词的关系与顺序。"}},"aspects":[{"title":"火星探测的上位类别","uses":[{"unit":"Q1","role":"解题依据","use":"D项中，深空探测包含火星探测，社会组织包含公益组织，两组词均按上位概念到下位概念排列。","evidence":"火星探测是一种深空探测，二者为种属关系","qids":["国考 2023 地市级 行测#99","国考 2023 行政执法 行测#99"]}]}]},"k-4e09782e054e8cc0":{"review":{"title":"公益组织与社会组织","type":"概念与词义","definition":"公益组织通常指以开展社会公益活动为宗旨的组织。在按活动宗旨划分社会组织的语境中，公益组织是社会组织的一类。","explanation":"慈善组织是《中华人民共和国慈善法》规定的法律概念。该法第八条规定了慈善组织的成立条件和活动宗旨，并列举基金会、社会团体、社会服务机构等组织形式。","basis":"据关联原题及所列出处编释。","references":[{"source":"charity","location":"第八条；原题分类另见题据"}],"domain":"法律","examFocus":{"国考 2023 地市级 行测#99":"辨明两空补入的词各自表示什么，再比较两组词的关系与顺序。"}},"aspects":[{"title":"公益组织的上位类别","uses":[{"unit":"Q1","role":"解题依据","use":"按原题的分类口径，D项将社会组织填在公益组织之前，与左侧深空探测、火星探测的上下位顺序一致。","evidence":"公益组织是一种社会组织，二者为种属关系","qids":["国考 2023 地市级 行测#99","国考 2023 行政执法 行测#99"]}]}]},"k-72a705667e55a451":{"review":{"definition":"缄口不言指闭口不说，常含谨慎、不愿或不敢开口之意。口若悬河形容能说善辩、话语滔滔不绝。","explanation":"D项把闭口不说与滔滔不绝相对，在开口说话的表现上构成反义关系，与后半组的反义关系一致。A项的三缄其口和C项的守口如瓶都与缄口不言有闭口少言的共同点。B项的畅所欲言虽也可与缄口不言相对，但其后半组的放荡不羁与虚怀若谷谈的是不同方面。","references":[],"evidence":"口若悬河意为说话滔滔不绝","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d6e6aca0d5edb600":{"review":{"definition":"矜功伐善指夸耀自己的功劳和才能。虚怀若谷形容十分谦虚，能容纳他人的意见。","explanation":"D项前者突出自夸，后者突出谦虚，二者在待人处事的态度上相对，与前半组的反义关系一致。大智若愚侧重有才智而不露锋芒，礼贤下士侧重尊重并礼遇贤才，虚怀若谷侧重谦虚纳意见，三者各有侧重。","references":[],"evidence":"夸耀自己的功劳和才能，形容极不虚心。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5db4b46712552e56":{"review":{"title":"平均单价","type":"概念与词义","definition":"同一统计范围内，总金额除以对应总数量所得的单位价格。","explanation":"汇总多批货物时，先合计金额和数量。直接平均各批单价，只有在权数适当时才会得到总体单价。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"单位价格与平均量","related":["k-6893dd42defd2106"]}},"k-507a654c368a98ee":{"review":{"definition":"党的二十大报告指出，中国式现代化是中国共产党领导的社会主义现代化，既有各国现代化的共同特征，也有基于中国国情的中国特色。","explanation":"各国现代化可以具有某些相同特征，具体发展途径和推进方式则取决于本国国情。报告以我国十四亿多人口整体迈进现代化社会为例，说明人口规模带来的复杂性要求中国采取适合自身条件的推进方式。第④项把“共同特征”说成各国遵循的“共同模式”，因此判错。","references":[],"evidence":"既有各国现代化的共同特征，更有基于自己国情的中国特色","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a976247acd3a4de2":{"review":{"definition":"分红型商业保险是保单持有人可按约定分享保险公司实际经营成果优于定价假设所产生的可分配盈余的人寿保险产品。","explanation":"C项所说的收益，在本题中对应保单红利。经营成果影响可分配盈余，进而影响红利，所以C项关于收益与经营状况有关的说法成立。具体年度是否有红利以及红利多少，要看当期可分配盈余和分配安排。","references":[],"evidence":"分红型商业保险的收益与保险公司的经营状况有关","disposition":"独立词条","basis":"据原题和解析编释。","title":"分红型商业保险","related":[],"examFocus":{"国考 2023 地市级 行测#7":"核对分红型商业保险中保单红利的分配依据，以及它与保险公司经营状况的关系。"}},"readings":[{"origin":"k-a976247acd3a4de2","title":"分红型商业保险","qs":["国考 2023 行政执法 行测#6"],"definition":"分红型商业保险是保单持有人可按约定分享保险公司实际经营成果优于定价假设所产生的可分配盈余的人寿保险产品。","explanation":"C项所说的收益，在本题中对应保单红利。经营成果影响可分配盈余，进而影响红利，所以C项关于收益与经营状况有关的说法成立。具体年度是否有红利以及红利多少，要看当期可分配盈余和分配安排。","evidence":"分红型商业保险的收益与保险公司的经营状况有关","doubt":"","references":[]},{"origin":"k-e41680440b4a9182","title":"分红型商业保险","qs":["国考 2023 地市级 行测#7"],"definition":"分红型商业保险是保单持有人可以分享保险公司相关经营成果的人寿保险。实际经营成果优于定价假设所产生的可分配盈余，可按约定向保单持有人分配。","explanation":"第7题C项所说的收益与经营状况有关，具体体现在保单红利上。可分配盈余随实际经营结果变化，因此红利多少也会变化。","evidence":"按一定比例向保单持有人进行分配","doubt":"","references":[]}]},"k-cccb0163c10417d3":{"review":{"definition":"启明和长庚都是金星的别称。金星在日出前见于东方时称启明，在日落后见于西方时称长庚。","explanation":"金星的轨道位于地球轨道以内，从地球上看，金星总在太阳附近，因而可在清晨或傍晚见到。《大东》中的“东有启明，西有长庚”写的是金星在不同时段的两个名称，C项将它们说成不同天体，因此本题选C。","references":[],"evidence":"“启明”和“长庚”都是指金星。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9d7717e21b493188":{"review":{"definition":"堠在“开远门前万里堠”中指古代沿道路设置的土堆或石堆，可用来辨认道路和计量路程。","explanation":"沿途的堠可以标示道路走向，按一定间隔设置也便于估算行程。A项所说的“导航和计程”分别对应这两种用途。","references":[],"evidence":"既可指明道路走向，又可计程。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-74ed722041f6db68":{"review":{"definition":"《淮南子》“见斗极则寤矣”中的“斗”指北斗星，“极”指北极星。","explanation":"引文写乘舟者迷失方向后，借观察北斗星和北极星恢复辨向。北极星在天空中靠近北天极，在北半球可用来辨认大致的北方，因此B项对“极”的解释成立。","references":[],"evidence":"乘舟而惑者，不知东西，见斗极则寤矣","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8989ab9741584098":{"review":{"definition":"比喻颠倒主要与次要的关系，把原本居于从属地位的事物当成首要目标。","explanation":"题干把育人设为布置作业的根本目的，把作业和分数放在服务这一目的的位置。传统管理却只关注作业和分数，忽视学生成长，符合B项“本末倒置”。“揠苗助长”侧重急于求成，“缘木求鱼”侧重方法与目标不匹配，“徒有其表”侧重只有外表而缺少实质。","references":[],"evidence":"眼中有作业、有分数，但唯独没有人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-85496216fa815b8c":{"review":{"definition":"指事物在一定使用条件下免受或避免造成危险、伤害的程度。","explanation":"题干把标准化生产写成手段，用后文的输血相关传染病风险降低来说明产品的“安全性”，所以选A。“规范性”更贴近生产流程是否符合标准，“可靠性”侧重是否可信赖，“稳定性”侧重特性能否保持。此处的安全性具体指材料所谈的感染风险。","references":[],"evidence":"可最大程度降低输血相关传染病的风险","disposition":"独立词条","basis":"据原题和解析编释。","title":"安全性","related":[],"examFocus":{"国考 2023 副省级 行测#22":"辨清“其”指代的对象，再借助空后对输血风险的说明判断所填词语应描述哪种属性。"}},"readings":[{"origin":"k-85496216fa815b8c","title":"安全性","qs":["国考 2023 行政执法 行测#23"],"definition":"指事物在一定使用条件下免受或避免造成危险、伤害的程度。","explanation":"题干把标准化生产写成手段，用后文的输血相关传染病风险降低来说明产品的“安全性”，所以选A。“规范性”更贴近生产流程是否符合标准，“可靠性”侧重是否可信赖，“稳定性”侧重特性能否保持。此处的安全性具体指材料所谈的感染风险。","evidence":"可最大程度降低输血相关传染病的风险","doubt":"","references":[]},{"origin":"k-b8a487110aa8802d","title":"安全性","qs":["国考 2023 副省级 行测#22"],"definition":"安全性指事物在一定条件下避免或降低危害的程度。","explanation":"题干用降低艾滋病、肝炎等输血相关传染病的感染风险来说明空缺所指，因此选“安全性”。“规范性”对应按标准生产，“稳定性”侧重性质保持一致，“可靠性”侧重值得信赖。本题的感染风险表述用于确定词义，适用范围是材料所述情形。","evidence":"可最大程度降低输血相关传染病的风险","doubt":"","references":[]}]},"k-1f774c28aaab12e5":{"review":{"definition":"指主动舍弃或排除，常用于观念、习惯、成见等。","explanation":"题干的“打破常规辟蹊径”提示第一空需要表达主动放下既有定式。“摒弃”符合这个意思，“忽略”表示没注意到或未加重视。“突破”和“摆脱”在第一空也说得通，最终由第二空“校正”确定B项。","references":[],"evidence":"打破常规辟蹊径","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-67e3d34d4154d3e2":{"review":{"definition":"指纠正已有事物的偏差，使其符合实际情况或既定标准。","explanation":"第二空的宾语是“行动部署”。“复杂多变”与“及时”提示语句说的是修正已经作出的安排，因此B项“校正”契合。“扭转”常指改变局面或趋势，“规划”侧重拟定安排。","references":[],"evidence":"与“行动部署”搭配不当","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0ad45e2432cd765b":{"review":{"definition":"“游离”的比喻义是脱离原来所属的集体或所依附的事物而存在。","explanation":"第一空转述部分教师的错误认识。“游离于传统教学之外”把课程思政描述成脱离教学主体的附加行为。“隔绝”把分离说得更彻底，与“附加行为”仍依附于教学的意味不合。“独立”也能表达分离，整组选项须由第二空进一步区分。","references":[],"evidence":"于传统教学之外的附加行为，这种认识是错误的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fe18da9c00b46376":{"review":{"definition":"“喧宾夺主”比喻次要的或外来的事物占据了主要事物的地位。","explanation":"题干说课程思政“不是喧宾夺主”，后文以“为提升教学质量服务”说明它在教学中的作用。“敷衍了事”说的是办事马虎、只求应付，填入后只能说明应认真开展课程思政，无法说明它与教学的关系。","references":[],"evidence":"它首先是为提升教学质量服务的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-069f3d23e20bf93d":{"review":{"definition":"“完整”指具备或保有应有的各个部分，没有缺漏。","explanation":"题干列出施肥的时间、地点、肥料种类和施用方法，并交代这些安排贯穿年度农业生产的各个时节。“完整”概括的是体系各环节齐备。“固定”侧重不变，题干交代的分时节安排不足以说明做法恒定。","references":[],"evidence":"何时、何地施肥，施何种肥，怎样施肥","disposition":"独立词条","basis":"据原题和解析编释。","title":"完整","related":[],"examFocus":{"国考 2023 副省级 行测#24":"留意农书对施肥时间、地点、肥料和方法的列举，辨析第二空应从哪个角度描述施肥体系。"}},"readings":[{"origin":"k-069f3d23e20bf93d","title":"完整","qs":["国考 2023 行政执法 行测#27"],"definition":"“完整”指具备或保有应有的各个部分，没有缺漏。","explanation":"题干列出施肥的时间、地点、肥料种类和施用方法，并交代这些安排贯穿年度农业生产的各个时节。“完整”概括的是体系各环节齐备。“固定”侧重不变，题干交代的分时节安排不足以说明做法恒定。","evidence":"何时、何地施肥，施何种肥，怎样施肥","doubt":"","references":[]},{"origin":"k-77833174dcd05b5d","title":"完整","qs":["国考 2023 地市级 行测#27"],"definition":"指具备或保有应有的各个部分，没有缺漏。","explanation":"题干列举施肥的时间、地点、肥料种类和方法，又说明各项措施按农时安排，体现出体系组成齐备，因此第二空选“完整”。“固定”强调保持不变，“复杂”强调头绪多、关系繁复。","evidence":"何时、何地施肥，施何种肥，怎样施肥","doubt":"","references":[]},{"origin":"k-9d918e13f4995a0f","title":"完整","qs":["国考 2023 副省级 行测#24"],"definition":"完整指应有的部分齐全，没有缺失。","explanation":"题干列出施肥时间、地点、肥料种类和施用方法，并说古人把施肥安排在各个时节。这些细节共同说明施肥体系要素齐备，第二空选“完整”。“固定”强调保持不变，“复杂”强调构成或头绪繁多。","evidence":"何时、何地施肥，施何种肥，怎样施肥","doubt":"","references":[]}]},"k-f3436617a41c6bc4":{"review":{"definition":"“忽视”指疏忽或不重视。“淡化”在涉及重视程度时，侧重使某事受到的重视减弱，或其重要性变得不那么突出。","explanation":"第一空对照两种关注对象。指尖上的形式主义把注意力放在形式是否美观上，对作为根本政绩的群众满意度关注不足，因此用“忽视”。题干给出的是当前的关注偏向，未交代群众满意度受到的重视如何减弱。","references":[],"evidence":"关注点在于形式美观，而    了根本政绩——人民群众的满意度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-22936b02075896e4":{"review":{"definition":"“华而不实”比喻外表好看，实际内容空虚或缺乏实效。","explanation":"第二空修饰“虚功”。题干把“以痕迹论政绩”下的形式美观与工作是否落实、群众是否满意相对照，正好对应“华而不实”的两层意思。“花拳绣腿”也可形容表面好看但没有实效的工作，最终由第一空选“忽视”确定D项。","references":[],"evidence":"的“虚功”中解救出来，务求实效、扎根基层","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bdf3e59e14d67d30":{"review":{"definition":"“一劳永逸”指辛苦一次把事情办好，以后就不必再为此费力。","explanation":"第二空受“不会”否定。有些公共服务短板会随时代发展而凸显，局部打补丁无法一次解决系统性问题。“水到渠成”强调条件成熟后事情自然办成，无法体现题干对一次处理即可长期奏效的否定。","references":[],"evidence":"有一些短板和弱项是随着时代发展而凸显的系统性问题","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-042c8a1ee55bb9bf":{"review":{"definition":"“一视同仁”指对不同对象同样看待，不分亲疏厚薄。","explanation":"第二空问当地政府能否在就业创业、项目立项推广中同等对待本地和非本地的人才及企业项目。“甚至”把语意从平等对待推进到主动降低门槛、清除障碍以留人留项目。“开诚布公”侧重坦诚，无法表达对两类对象的同等对待。","references":[],"evidence":"甚至千方百计降门槛、清路障以留人留项目","disposition":"独立词条","basis":"据原题和解析编释。","title":"一视同仁","related":[],"examFocus":{"国考 2023 地市级 行测#29":"结合第一空与“包容审慎”的对照，以及第二空与“甚至”后具体做法的递进关系，辨析成语的语义。"}},"readings":[{"origin":"k-042c8a1ee55bb9bf","title":"一视同仁","qs":["国考 2023 行政执法 行测#31"],"definition":"“一视同仁”指对不同对象同样看待，不分亲疏厚薄。","explanation":"第二空问当地政府能否在就业创业、项目立项推广中同等对待本地和非本地的人才及企业项目。“甚至”把语意从平等对待推进到主动降低门槛、清除障碍以留人留项目。“开诚布公”侧重坦诚，无法表达对两类对象的同等对待。","evidence":"甚至千方百计降门槛、清路障以留人留项目","doubt":"","references":[]},{"origin":"k-dd2683236cc6d027","title":"一视同仁","qs":["国考 2023 地市级 行测#29"],"definition":"对不同的人或对象同等看待，不分亲疏厚薄。","explanation":"第29题第二空指当地政府对本地和非本地的人才、企业项目同等看待。「甚至」把语意从平等对待推进到主动降门槛、清路障。「开诚布公」侧重坦诚，「海纳百川」侧重接纳范围广，均未点出题中的同等对待。","evidence":"甚至千方百计降门槛、清路障以留人留项目","doubt":"","references":[]}]},"k-34a62fbcbedce927":{"review":{"definition":"评估是依据相关信息，对对象的价值、程度或影响等作出评价和估量。","explanation":"题干要求把客观后果与当事人的主观认知、动机目的等情节合在一起考量，估量行为的社会危害程度，再决定是否启动惩罚机制。“评估”适合这种综合衡量，“辨别”侧重区分真伪、好坏等类别。","references":[],"evidence":"“评估社会危害性”为常见搭配","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-606fe1ea66d0ea8f":{"review":{"definition":"遥不可及指距离很远，无法到达或触及，也可比喻某个目标很难实现，或某类事物让人感觉离自己很远。","explanation":"“自己一辈子都不会和法律打交道”写的是普通人主观上觉得法律离日常生活很远，后文“随时可能触及法律的红线”正好与这种距离感构成转折。“事不关己”也能表达自认与法律无关的想法，整组选项还需结合第二空的执法警示作用来确定。","references":[],"evidence":"自己一辈子都不会和法律打交道","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f02d9c5e41be840d":{"review":{"definition":"“警戒”在警示、告诫的义项上，侧重使人对风险或越界后果保持警觉。“提醒”侧重使人留意某件事或想起可能忽略的事项。","explanation":"题干先说人们“随时可能触及法律的红线”，又说许多人平时法律意识不强，因此“起到警戒作用”能突出柔性执法使人对违法风险保持警觉的作用。“提醒”也能引起注意，警示、告诫的意味较弱。","references":[],"evidence":"人们随时可能触及法律的红线","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f81002b6d27945bb":{"review":{"definition":"“面面俱全”指各方面都能照顾到，侧重覆盖全面。“百无一失”形容很有把握，侧重不会出差错。","explanation":"超大城市的城管执法事项繁多、涉及的市场主体庞杂，有限的人力很难照顾到各方面，所以第二空填“面面俱全”。“百无一失”说的是办事的把握和差错，无法准确概括题干的覆盖难题。","references":[],"evidence":"由于城管执法事项繁多，涉及市场主体庞杂，而城管执法力量是有限的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-23b1fb81256b60f3":{"review":{"definition":"刻不容缓形容事情非常紧迫，片刻也不能拖延。","explanation":"题干说有害信息可能潜移默化地影响已经普遍接触网络的未成年人。“势在必行”强调整治有必要，“刻不容缓”进一步强调应尽快行动。“迫在眉睫”也能表达这种紧迫性，整题还需借助第三空的“凝聚合力”确定答案。","references":[],"evidence":"“刻不容缓”形容形势非常紧迫，片刻也不能拖延","disposition":"独立词条","basis":"据原题和解析编释。","title":"刻不容缓","related":[],"examFocus":{"国考 2023 地市级 行测#39":"结合后文判断首空应在“势在必行”之外补充哪层含义，再辨析后两空与“网络空间”和“合力”的搭配。"}},"readings":[{"origin":"k-23b1fb81256b60f3","title":"刻不容缓","qs":["国考 2023 行政执法 行测#35"],"definition":"刻不容缓形容事情非常紧迫，片刻也不能拖延。","explanation":"题干说有害信息可能潜移默化地影响已经普遍接触网络的未成年人。“势在必行”强调整治有必要，“刻不容缓”进一步强调应尽快行动。“迫在眉睫”也能表达这种紧迫性，整题还需借助第三空的“凝聚合力”确定答案。","evidence":"“刻不容缓”形容形势非常紧迫，片刻也不能拖延","doubt":"","references":[]},{"origin":"k-e28ce530262b1181","title":"刻不容缓","qs":["国考 2023 地市级 行测#39"],"definition":"形容事情十分紧迫，片刻也不能拖延。","explanation":"第39题首空承接“势在必行”，把整治未成年人网络环境的必要性推进到行动的紧迫性，后文有害信息的潜移默化影响给出了理由。“迫在眉睫”也能表达紧急，首空可保留B、C两项，最后由“凝聚合力”确定B项。","evidence":"“刻不容缓”形容形势非常紧迫，片刻也不能拖延","doubt":"","references":[]}]},"k-992e344097c435a7":{"review":{"definition":"凝聚合力指把多方力量聚集起来，形成共同推进同一目标的力量。","explanation":"“发挥多主体多领域联动优势”说明治理未成年人网络环境需要各方协同，“凝聚合力”直接承接这种共同发力的过程。“集成”偏向把分散的要素组合成一个整体，在这里与“合力”的搭配不及“凝聚”贴切。","references":[],"evidence":"需要发挥多主体多领域联动优势","disposition":"独立词条","basis":"据原题和解析编释。","title":"凝聚合力","related":[],"examFocus":{"国考 2023 地市级 行测#39":"根据有害信息对未成年人的影响判断首空所需的紧迫程度，再结合多方联动的语境检查动词与“网络空间”“合力”的搭配。"}},"readings":[{"origin":"k-992e344097c435a7","title":"凝聚合力","qs":["国考 2023 行政执法 行测#35"],"definition":"凝聚合力指把多方力量聚集起来，形成共同推进同一目标的力量。","explanation":"“发挥多主体多领域联动优势”说明治理未成年人网络环境需要各方协同，“凝聚合力”直接承接这种共同发力的过程。“集成”偏向把分散的要素组合成一个整体，在这里与“合力”的搭配不及“凝聚”贴切。","evidence":"需要发挥多主体多领域联动优势","doubt":"","references":[]},{"origin":"k-eab10fe5e1577fb8","title":"凝聚合力","qs":["国考 2023 地市级 行测#39"],"definition":"把不同方面的力量汇聚起来，使各方朝共同目标发力。","explanation":"第39题先提出“发挥多主体多领域联动优势”，末空用“凝聚合力”承接，写各方如何共同为未成年人营造清朗网络空间。B、C两项的前两空均可读通，B项的“凝聚合力”更贴合多方协同发力的语义和搭配。","evidence":"需要发挥多主体多领域联动优势","doubt":"","references":[]}]},"k-88b6a24894fbb9ff":{"review":{"definition":"寓教于乐指把教育内容融入有趣的活动或体验，使人在获得乐趣的同时受到教育。","explanation":"题干以沉浸式、交互式网上展览说明参观可以有趣，又提出提升实物展览的内涵，使展览兼备文化和教育功能。“寓教于乐”概括了把有趣的参观体验与学习文化知识结合起来的特点。","references":[],"evidence":"也不能忽视实物展览内涵的提升，使之兼备文化和教育功能","disposition":"独立词条","basis":"据原题和解析编释。","title":"寓教于乐","related":[],"examFocus":{"国考 2023 地市级 行测#36":"分别从数字展览的体验、智能终端普及后的参观感受和实物展览的功能三个角度辨析用词。"}},"readings":[{"origin":"k-88b6a24894fbb9ff","title":"寓教于乐","qs":["国考 2023 行政执法 行测#36"],"definition":"寓教于乐指把教育内容融入有趣的活动或体验，使人在获得乐趣的同时受到教育。","explanation":"题干以沉浸式、交互式网上展览说明参观可以有趣，又提出提升实物展览的内涵，使展览兼备文化和教育功能。“寓教于乐”概括了把有趣的参观体验与学习文化知识结合起来的特点。","evidence":"也不能忽视实物展览内涵的提升，使之兼备文化和教育功能","doubt":"","references":[]},{"origin":"k-f25cf78b155daaa5","title":"寓教于乐","qs":["国考 2023 地市级 行测#36"],"definition":"把教育融入有趣的活动或体验，使人在娱乐中受到教育。","explanation":"第36题第三空要概括博物馆展览的特点。沉浸式、交互式手段可以增加趣味，提升实物展览内涵则有助于发挥文化和教育功能。「寓教于乐」把有趣的参观体验和教育功能联系起来，「触手可及」只侧重容易接触。","evidence":"使之兼备文化和教育功能","doubt":"","references":[]}]},"k-8f2aa4d68cd9c020":{"review":{"definition":"如雷贯耳比喻名声很大，广为人知，常用来形容人的名声。","explanation":"“关于戏曲衰亡的声音”指相继出现的议论，第二空要描述这些议论怎样出现。“如雷贯耳”说的是名声响亮，用在这里无法表达议论一阵接一阵的情形。","references":[],"evidence":"关于戏曲衰亡的声音","disposition":"独立词条","basis":"据原题和解析编释。","title":"如雷贯耳","related":[],"examFocus":{"国考 2023 副省级 行测#34":"辨析第二空的成语时，留意“声音”所指的对象，并核对成语的惯用搭配。"}},"readings":[{"origin":"k-8f2aa4d68cd9c020","title":"如雷贯耳","qs":["国考 2023 行政执法 行测#37"],"definition":"如雷贯耳比喻名声很大，广为人知，常用来形容人的名声。","explanation":"“关于戏曲衰亡的声音”指相继出现的议论，第二空要描述这些议论怎样出现。“如雷贯耳”说的是名声响亮，用在这里无法表达议论一阵接一阵的情形。","evidence":"关于戏曲衰亡的声音","doubt":"","references":[]},{"origin":"k-ce15fc5f34fcde78","title":"如雷贯耳","qs":["国考 2023 副省级 行测#34"],"definition":"形容名声很大，像雷声传入耳中。","explanation":"第二空的「声音」指关于戏曲将会衰亡的议论。这里要描述的是这类议论怎样出现，「此起彼伏」能写出议论接连出现的情形。「如雷贯耳」着眼于名声的响亮程度，放在这里与句意不合。","evidence":"关于戏曲衰亡的声音","doubt":"","references":[]}]},"k-c09e671341fcad83":{"review":{"definition":"“积淀”可指文化、经验等经过长期积累而逐渐形成，也可指积累下来的成果。“渗透”本指液体慢慢透入，比喻思想、观念等逐步进入某个群体或领域，或逐渐向其他方面扩展。","explanation":"题干把制度的文化认同归于中华文化沃土的滋养，并强调这种文化源于“内在的演化”。“积淀”承接长期演化中逐渐积累的过程，“渗透”侧重观念如何进入或扩展到某处，与这里强调的内在历史积累贴合度较低。","references":[],"evidence":"必须是内在的演化和","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d041b55b0d173cf6":{"review":{"definition":"“力不从心”指想做某事却因能力或力量不足而难以做到。“收效甚微”指采取行动后取得的效果很小。","explanation":"第一空前的“不留死角、不存盲点”提出了全面覆盖的要求，“光靠人为监管恐怕会”引出的是现有监管力量可能达不到这一要求，因此“力不从心”贴切。“收效甚微”评价的是实际成效，题干并未说人为监管取得的效果很小。第一空据此可排除D项，再结合后两空确定B项。","references":[],"evidence":"环境整治关键要不留死角、不存盲点，光靠人为监管恐怕会","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2178d4d2b58bc9f2":{"review":{"definition":"轴对称图形沿某条直线翻折后与原图形重合。中心对称图形绕某一点旋转180°后与原图形重合。","explanation":"第72题分别检验外框和内部图案。D项外框是等腰直角三角形，沿直角的角平分线翻折，两条直角边重合。内部图案绕斜线段的中点旋转180°，两条短斜线互换位置，整个图案重合。A项的外框也有对称轴，但内部的单向箭头旋转180°后方向反转，无法与原图案重合。","references":[],"evidence":"题干图形外部均为轴对称图形，内部均为中心对称图形","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1b0e8773b8fa0022":{"review":{"definition":"原题引文：人类外耳道多毛症为伴Y染色体遗传病","explanation":"题目将B项的外耳道多毛症设定为伴Y遗传，并描述其在家族男性亲属中代代遗传。按题设，B项同时满足基因位于性染色体和性状仅在一种性别表现两个条件。现实研究中，常见的「hairy ears」指耳廓耳轮长毛，已有分子遗传研究对该表型的伴Y遗传解释提出反证。题文所称外耳道多毛与这一研究表型是否相同，仍有待确认。","references":[{"source":"web-7eb65827332cd060","location":"Definition","quote":"long hairs growing from the helix of the pinna"},{"source":"web-61e26e1e5b127950","location":"引言关于早期伴Y性状报告的段落及参考文献2","quote":"Molecular evidence for absence of Y-linkage of the hairy ears trait"}],"evidence":"人类外耳道多毛症为伴Y染色体遗传病","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-c150d90ab4fba53e":{"review":{"definition":"铜镜是以铜合金制成的镜子，按材质命名。化妆镜是供化妆时照看的镜子，按用途命名。","explanation":"一面铜镜可以用来化妆，化妆镜也可以用其他材质制成，两词的外延有交叉。B项的木碗和汤碗同样先按材质、再按用途命名。A项的门帘按悬挂位置命名，D项的古瓶按年代命名。","references":[],"evidence":"前者是根据材质命名，后者是根据功能命名","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-a325daf319f1a13b":{"review":{"definition":"两个概念具有交叉关系，是指它们的外延有共同成员，同时各自都有对方外延之外的成员。","explanation":"本题中，木碗有的盛汤、有的作其他用途，汤碗也可以由木材或其他材质制成，因此B项的两个概念相互交叉。C项按题意是金簪属于发簪，属于种属关系。A、D也有外延交叉，选B还须匹配题干中材质在前、用途在后的顺序。","references":[],"evidence":"有的木碗是汤碗，有的木碗不是汤碗，有的汤碗是木碗，有的汤碗不是木碗，二者为交叉关系","disposition":"独立词条","basis":"据原题和解析编释。","title":"概念的交叉关系","related":[],"examFocus":{"国考 2023 行政执法 行测#91":"先判断两个概念的外延是否交叉，再比较每组词的命名依据和先后顺序。","江苏 2025 A类 行测#78":"找出每个概念的划分依据，再逐对检验是否既有共同成员，又各有独有成员。"}},"readings":[{"origin":"k-a325daf319f1a13b","title":"概念的交叉关系","qs":["国考 2023 行政执法 行测#91"],"definition":"两个概念具有交叉关系，是指它们的外延有共同成员，同时各自都有对方外延之外的成员。","explanation":"本题中，木碗有的盛汤、有的作其他用途，汤碗也可以由木材或其他材质制成，因此B项的两个概念相互交叉。C项按题意是金簪属于发簪，属于种属关系。A、D也有外延交叉，选B还须匹配题干中材质在前、用途在后的顺序。","evidence":"有的木碗是汤碗，有的木碗不是汤碗，有的汤碗是木碗，有的汤碗不是木碗，二者为交叉关系","doubt":"","references":[]},{"origin":"k-e11cc2b983ba00b0","title":"概念的交叉关系","qs":["江苏 2025 A类 行测#78"],"definition":"两个概念的外延有一部分重合，同时各自还有另一方未涵盖的对象，这两个概念就具有交叉关系。","explanation":"判断时要同时看共有部分和各自独有的部分。本土药材、野生药材、名贵药材分别按地域来源、生长方式和珍贵程度划分，两两之间都可能有重合，且各有独有的药材。A项的沿海高铁、跨省高铁、城际高铁分别从线路地理位置、是否跨省和服务对象来划分，同一条线路可以同时符合其中几项，因此与题干关系一致。","evidence":"三者互为交叉关系","doubt":"","references":[]}]},"k-4f447e889052dc5c":{"review":{"definition":"小计是一组数值的和，总计是全部数值的和。各组完整覆盖全部数值且互不重叠时，各组小计相加得到总计。","explanation":"本题的C项沿用同一加总关系，按题意把各科分数相加即可得到总分。A项由平均值乘以相应的个数得到总值，D项是目录内容的汇整，计算或汇整方式各有不同。","references":[],"evidence":"“小计”是数字列表中一部分数字的总和，“总计”是数字列表中所有数字的总和","disposition":"独立词条","basis":"据原题和解析编释。","title":"小计与总计","related":[],"examFocus":{"国考 2023 地市级 行测#91":"先看小计和总计各自覆盖哪些数据，再比较各组词中局部量与整体量的构成关系。"}},"readings":[{"origin":"k-4f447e889052dc5c","title":"小计与总计","qs":["国考 2023 行政执法 行测#92"],"definition":"小计是一组数值的和，总计是全部数值的和。各组完整覆盖全部数值且互不重叠时，各组小计相加得到总计。","explanation":"本题的C项沿用同一加总关系，按题意把各科分数相加即可得到总分。A项由平均值乘以相应的个数得到总值，D项是目录内容的汇整，计算或汇整方式各有不同。","evidence":"“小计”是数字列表中一部分数字的总和，“总计”是数字列表中所有数字的总和","doubt":"","references":[]},{"origin":"k-c5bd1873f6671b75","title":"小计与总计","qs":["国考 2023 地市级 行测#91"],"definition":"小计是某一部分数值之和，总计是全部数值之和。各部分完整覆盖全部数据且彼此不重叠时，各小计相加即得总计。","explanation":"C项的各科分数按题意直接相加得到总分，与各小计相加得到总计的关系一致。A项由平均值求总值还要乘以数据个数，D项则是汇编目录，缺少数值求和关系。","evidence":"所有“单科分”相加可以得到“总分”","doubt":"","references":[]}]},"k-1f0f2fd766a92586":{"review":{"definition":"海棠红和南瓜橙分别是以海棠、南瓜命名的红色和橙色。","explanation":"题干的两词并列表示不同颜色，而且两个名称都取自植物。D项的橄榄绿、梅子青同时符合这两个条件。B项也列举了两种颜色，但孔雀蓝的名称取自动物。","references":[],"evidence":"“海棠红”和“南瓜橙”是两种不同的颜色，二者为并列关系，且都是根据植物命名的。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-0d900d9840c5d570":{"review":{"definition":"橄榄绿和梅子青分别是以橄榄、梅子命名的绿色和青色。","explanation":"D项的两个色名都取自植物，与题干的海棠红、南瓜橙对应。B项的柠檬黄也以植物命名，但同组的孔雀蓝取名于动物，因此只有D项完整匹配题干的命名依据。","references":[],"evidence":"“橄榄绿”和“梅子青”是两种不同的颜色，二者为并列关系，且二者都是根据植物命名的","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-9e0db36e6b43a9bb":{"review":{"definition":"在同一时期、同一贸易范围内，出口额大于进口额时，两者的差额称为贸易顺差额。","explanation":"第130题的贸易范围是中国与“一带一路”沿线国家之间的纺织品服装贸易。材料给出的2021年出口额和进口额分别为1137.9亿和131.6亿美元，两者同比均增长24.5%，因此可先求2021年的差额，再用同一增长系数还原2020年的差额，即（1137.9−131.6）÷1.245≈808.3亿美元，选C。D项的1006亿美元接近2021年的顺差额。","references":[],"evidence":"贸易顺差额=出口额-进口额","disposition":"独立词条","basis":"据原题和解析编释。","title":"贸易顺差额","related":[],"examFocus":{"国考 2023 副省级 行测#135":"用同比增速还原上年数据，计算顺差时要取同一贸易范围内的出口额与进口额之差。","国考 2023 行政执法 行测#130":"用同比增速还原上年数据，计算顺差时要取同一贸易范围内的出口额与进口额之差。"}},"readings":[{"origin":"k-9e0db36e6b43a9bb","title":"贸易顺差额","qs":["国考 2023 行政执法 行测#130"],"definition":"在同一时期、同一贸易范围内，出口额大于进口额时，两者的差额称为贸易顺差额。","explanation":"第130题的贸易范围是中国与“一带一路”沿线国家之间的纺织品服装贸易。材料给出的2021年出口额和进口额分别为1137.9亿和131.6亿美元，两者同比均增长24.5%，因此可先求2021年的差额，再用同一增长系数还原2020年的差额，即（1137.9−131.6）÷1.245≈808.3亿美元，选C。D项的1006亿美元接近2021年的顺差额。","evidence":"贸易顺差额=出口额-进口额","doubt":"","references":[]},{"origin":"k-b59c1b4c53e5af12","title":"贸易顺差额","qs":["国考 2023 副省级 行测#135"],"definition":"在同一时期、同一贸易范围内，出口额大于进口额时，出口额减去进口额所得的正差额称为贸易顺差额。","explanation":"第135题求2020年中国对“一带一路”沿线国家的纺织品服装贸易顺差额。材料给出2021年出口额1137.9亿美元、进口额131.6亿美元，两者同比均增长24.5%，因此可以先求2021年的顺差额，再除以共同的增长倍数1.245，得到（1137.9－131.6）÷1.245≈808.3亿美元，对应C项。","evidence":"贸易顺差额=出口额-进口额","doubt":"","references":[]}]},"k-3e95b77eeabd0099":{"review":{"title":"高标准农田","type":"概念与词义","definition":"高标准农田是通过田块整治、灌排设施建设和耕地质量提升等措施建成的集中连片、旱涝保收、高产稳产的农田。","explanation":"田块整治便于连片耕作，灌排设施提高农田抗旱排涝能力，建后管护有助于维持设施和耕地的生产能力。2023年12月中央农村工作会议提出，加大高标准农田建设投入和管护力度，确保耕地数量有保障、质量有提升。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"国考 2024 副省级 申论#4":"从资料4提取高标准农田建设的实际成效，按项目管理环节归纳问题并使改进建议与问题一一对应。","国考 2025 副省级 行测#6":"对照粮食安全部署，区分高标准农田建设与建成后的管护，核对它们各自涉及的耕地保障要求。"}},"aspects":[{"title":"建设成效与项目管理","uses":[{"unit":"Q1","role":"直接考查","use":"本题 要求汇报C市调研结果并提出改进建议。材料以灌排改善、土地整合和特色产业发展说明成效，并以规划地块与实地不符、验收不严、田间道不合规和有机肥以发代施说明项目管理问题。","evidence":"通过高标准农田改造，亩均效益增加了200多元。","qids":["国考 2024 副省级 申论#4"]}]},{"title":"粮食安全中的建设投入与管护","uses":[{"unit":"Q2","role":"直接考查","use":"本题 均要求清点正确的粮食安全举措。③符合2023年12月中央农村工作会议关于高标准农田建设投入、管护和耕地数量质量保障的部署。①②③⑤共四项正确，三卷均选C。","evidence":"加大高标准农田建设投入和管护力度，确保耕地数量有保障、质量有提升","qids":["国考 2025 副省级 行测#6","国考 2025 地市级 行测#6","国考 2025 行政执法 行测#6"]}]}],"sources":[{"id":"18b15dd81bc52dab","label":"高标准农田建设","topic":"农业与城乡治理","category":"非时政","text":"5.高标准农田建设\n高标准农田是指通过土地整治、设施完善和生态优化形成的旱涝保收、高产稳产耕地，\n具有集中连片、土壤肥沃、抗灾能力强等特点，是国家粮食安全的核心保障。《逐步把永久\n基本农田建成高标准农田实施方案》提出到 2030 年，力争累计建成高标准农田 13.5 亿亩，\n累计改造提升 2.8 亿亩，统筹规划、同步实施高效节水灌溉，新增高效节水灌溉面积 8000\n万亩；到 2035 年，力争将具备条件的永久基本农田全部建成高标准农田，累计改造提升 4.55\n亿亩，新增高效节水灌溉面积 1.3 亿亩。","source":{"doc":"6cbfb01fe723bba64b75","first":34,"last":34,"page":34,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-abf275cf7d287f0a":{"review":{"definition":"按材料4引用的《高标准农田建设通则》，田间道是连接田块与村庄或连接不同田块，供农田耕作及农用物资、农产品运输通行的道路。","explanation":"调研组对照规划图实地查看，发现福树村用高标准农田建设资金修建的道路没有连接任何田块，未满足田间道的连接要求。汇报可据此指出配套设施建设不合规，并建议核查规划图、按规定使用项目资金。","references":[],"evidence":"田间道是指连接田块与村庄、田块之间","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6a9c45c166838357":{"review":{"definition":"古典戏曲双璧指王实甫的《西厢记》和汤显祖的《牡丹亭》。","explanation":"C项列对了两部作品，却把《西厢记》的作者写成白朴。白朴的代表作包括《梧桐雨》。《西厢记》的作者归属错误，因此这道选非题选C。","references":[],"evidence":"《西厢记》的作者为王实甫","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fc853829120caccb":{"review":{"definition":"乐府双璧是汉乐府诗《孔雀东南飞》和北朝民歌《木兰诗》的合称。《木兰诗》又名《木兰辞》。","explanation":"A项同时列对了两部作品及其所属的文学传统，《孔雀东南飞》属汉乐府，《木兰诗》是北朝民歌。A项表述正确，应在选非题中排除。","references":[],"evidence":"《孔雀东南飞》和《木兰诗》合称为“乐府双璧”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6fb9549fd27bd6ab":{"review":{"definition":"史学双璧是司马迁的《史记》和司马光的《资治通鉴》的合称。","explanation":"《史记》是纪传体通史，《资治通鉴》是编年体通史。两部史书的体例不同，B项中的作者、书名和合称均对应正确，应在选非题中排除。","references":[],"evidence":"司马迁的《史记》和司马光的《资治通鉴》并称为“史学双璧”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6c8751f23d78473d":{"review":{"definition":"清代戏曲双璧指洪昇的《长生殿》和孔尚任的《桃花扇》。两部作品都把爱情故事与政治历史相结合。","explanation":"D项把《长生殿》配给洪昇、把《桃花扇》配给孔尚任，作者与作品均对应正确，应在选非题中排除。","references":[],"evidence":"“清代戏曲双璧”是指洪昇的《长生殿》和孔尚任的《桃花扇》","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b3b5f13097f2a009":{"review":{"definition":"波尔多液是以硫酸铜、石灰和水为原料制成的无机铜素杀菌剂，常用于防治果树和葡萄等作物的病害。","explanation":"题中解析所列原料包括硫酸铜、生石灰和水。C项说硫酸铜溶液可用于配制波尔多液，描述的是硫酸铜作为原料的用途，与解析一致。","references":[],"evidence":"波尔多液是一种无机铜素杀菌剂，由硫酸铜、生石灰和水按不同比例配制成","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-236c82eaae7bcda3":{"review":{"definition":"殊途同归指采取不同的途径而达到同一目的或得到同样的结果。","explanation":"题干先把空间碎片清除分为接触式和非接触式，随后说明两类方案都以让碎片离开当前轨道、进入大气层烧毁为目标，因此选B。“如出一辙”强调做法或表现相似，“双管齐下”强调两种手段同时使用，“各有千秋”强调各有所长。","references":[],"evidence":"都是要让碎片离开当前轨道，进入大气层烧毁","disposition":"独立词条","basis":"据原题和解析编释。","title":"殊途同归","related":[],"examFocus":{"国考 2024 副省级 行测#22":"对照空前列举的两类清除手段和空后交代的目标，判断成语应概括哪一层关系。"}},"readings":[{"origin":"k-236c82eaae7bcda3","title":"殊途同归","qs":["国考 2024 副省级 行测#22"],"definition":"殊途同归指采取不同的途径而达到同一目的或得到同样的结果。","explanation":"题干先把空间碎片清除分为接触式和非接触式，随后说明两类方案都以让碎片离开当前轨道、进入大气层烧毁为目标，因此选B。“如出一辙”强调做法或表现相似，“双管齐下”强调两种手段同时使用，“各有千秋”强调各有所长。","evidence":"都是要让碎片离开当前轨道，进入大气层烧毁","doubt":"","references":[]},{"origin":"k-a7ff28b009343e97","title":"殊途同归","qs":["国考 2024 行政执法 行测#23"],"definition":"通过不同途径达到同一目标或得到相同结果。","explanation":"第23题先区分接触式与非接触式两类空间碎片清除方式，再交代文中两类方案都要让碎片离开当前轨道、进入大气层烧毁。方法有别、目标一致，因此选B项。“如出一辙”强调相似，“双管齐下”强调两种手段同时使用。","evidence":"都是要让碎片离开当前轨道，进入大气层烧毁","doubt":"","references":[]}]},"k-7f1943ba8f4226a6":{"review":{"definition":"没有做出有成效的事情或取得什么成绩。形容工作状态时，常指缺少主动担当和实际作为。","explanation":"本题用“一潭死水”形容人们因瞻前顾后、畏首畏尾而不敢担当的局面。“无所作为”与前文的“鼓励担当作为”直接呼应。“无所事事”侧重闲着没做事，本题结合第二空“立规矩”确定选D。","references":[],"evidence":"使人瞻前顾后、畏首畏尾","disposition":"独立词条","basis":"据原题和解析编释。","title":"无所作为","related":[],"examFocus":{"国考 2024 副省级 行测#23":"首空结合文段对担当作为的讨论辨析所描述的状态，第二空看词语能否与前后的治理举措并列。"}},"readings":[{"origin":"k-7f1943ba8f4226a6","title":"无所作为","qs":["国考 2024 副省级 行测#23"],"definition":"没有做出有成效的事情或取得什么成绩。形容工作状态时，常指缺少主动担当和实际作为。","explanation":"本题用“一潭死水”形容人们因瞻前顾后、畏首畏尾而不敢担当的局面。“无所作为”与前文的“鼓励担当作为”直接呼应。“无所事事”侧重闲着没做事，本题结合第二空“立规矩”确定选D。","evidence":"使人瞻前顾后、畏首畏尾","doubt":"","references":[]},{"origin":"k-fffd8fa8a834c8d9","title":"无所作为","qs":["国考 2024 行政执法 行测#24"],"definition":"指没有采取有成效的行动，或没有做出实际成绩。","explanation":"第24题首空与“暮气沉沉”并列描述“一潭死水”，并与前文“鼓励担当作为”呼应，突出畏首畏尾导致缺少担当和行动。“无所事事”侧重闲着、没有做事，在首空也可暂留。结合第二空“立规矩”与其余治理举措的并列关系，确定D项。","evidence":"全面从严治党和鼓励担当作为是内在统一的","doubt":"","references":[]}]},"k-d8c25654e10c30e5":{"review":{"definition":"“立规矩”指确立应当遵循的行为规范。“守底线”指守住不可逾越的最低界限。","explanation":"第二空与“明方向、正风气、强免疫”并列，列举从严治党中主动采取的举措。“立规矩”写的是确立规范这一举措，“守底线”侧重行为主体遵守最低要求，因此D项与该处列举的内容更贴合。","references":[],"evidence":"D项“立规矩”意为确立规矩","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7dbadcbffbe41ffd":{"review":{"definition":"集中众人的智慧，广泛吸收有益的意见。","explanation":"第一空紧接“广开言路”，后文又提出促进不同思想观点充分表达和深入交流。“广开言路”强调让意见有机会表达，“集思广益”进一步强调汇集和吸收有益意见。“兼收并蓄”侧重容纳不同内容，与征集意见的联系较弱。","references":[],"evidence":"促进不同思想观点的充分表达和深入交流","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-116083777a8e9969":{"review":{"definition":"各自发表自己的意见或见解。","explanation":"第二空与“畅所欲言”并列，前者强调每个人都能表达自己的看法，后者强调充分表达。两者共同写出协商中的表达空间，后接的“又理性有度、合法依章”写出表达和交流所遵循的要求。","references":[],"evidence":"“各抒己见”指各自发表自己的意见或见解","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d4c791221af9bf2b":{"review":{"definition":"“偏离”指与原有方向、标准或实际情况产生偏差。“虚构”指编造实际没有的人物、情节或事实。","explanation":"题干并列列举“随意取舍、记忆有误或者心存故意”，同时涵盖无意失实和有意失实。“偏离历史真实”概括了记载与实际有出入的结果，“虚构”强调编造，与单纯因记忆错误造成的偏差不符。","references":[],"evidence":"随意取舍、记忆有误或者心存故意","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c1a89c725f71a185":{"review":{"definition":"“降低”指使程度、水平或可能性下降。“化解”指消除或缓和矛盾、危机等，“规避”指设法避开风险或不利情况。","explanation":"题干说可以通过重复操作核验研究结论，第二空要表达的是人为造假的可能性减小。“降低”可直接与“可能”搭配，表达程度变化。“化解”偏重处理矛盾、危机等问题，“规避”偏重采取措施避开不利情况。","references":[],"evidence":"可以用重复操作检验此前的研究成果是否准确、正确","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d98cd4b54a68a7bb":{"review":{"definition":"根据各地的具体条件，制定或采用适合当地的办法。","explanation":"第二空修饰“实施振兴政策”，前文要求尊重农村发展实际和市场规律，并指出统一套用一种发展方式的问题。“因地制宜”说明措施要适应各地实际。“脚踏实地”强调做事踏实认真，对应的是做事态度。","references":[],"evidence":"尊重农村发展实际和市场规律","disposition":"独立词条","basis":"据原题和解析编释。","title":"因地制宜","related":[],"examFocus":{"国考 2024 副省级 行测#27":"第一空结合“平均用力”及其后的解释，第二空看成语如何修饰“实施振兴政策”。"}},"readings":[{"origin":"k-d98cd4b54a68a7bb","title":"因地制宜","qs":["国考 2024 副省级 行测#27"],"definition":"根据各地的具体条件，制定或采用适合当地的办法。","explanation":"第二空修饰“实施振兴政策”，前文要求尊重农村发展实际和市场规律，并指出统一套用一种发展方式的问题。“因地制宜”说明措施要适应各地实际。“脚踏实地”强调做事踏实认真，对应的是做事态度。","evidence":"尊重农村发展实际和市场规律","doubt":"","references":[]},{"origin":"k-e4242df3f22ffb21","title":"因地制宜","qs":["国考 2024 地市级 行测#24"],"definition":"根据不同地区的具体情况，采取适合当地的办法。","explanation":"“尊重农村发展实际和市场规律”要求振兴政策适应各地条件，也呼应前文对统一套用发展方式的批评。“脚踏实地”强调做事踏实，“步步为营”强调行动谨慎，只有“因地制宜”直接体现按当地实际选取办法。","evidence":"只有尊重农村发展实际和市场规律","doubt":"","references":[]},{"origin":"k-ea9d037e006a47e6","title":"因地制宜","qs":["国考 2024 行政执法 行测#31"],"definition":"根据各地的具体情况采取适宜的办法。","explanation":"第31题要求尊重农村发展实际和市场规律，据此调整振兴政策的实施办法，以免把单一发展方式套到所有农村。“脚踏实地”侧重做事踏实，“坚定不移”侧重立场或意志稳定，“步步为营”侧重行动谨慎，只有“因地制宜”直接体现办法要随地方实际而调整。","evidence":"只有尊重农村发展实际和市场规律","doubt":"","references":[]}]},"k-0bbf4ceb332fe60c":{"review":{"definition":"公平指处理事情合乎情理，对有关各方一视同仁。分配是否公平，要看依据和规则能否合理对待各方。","explanation":"哈尼族的木刻分水以沟渠所能灌溉的梯田面积为依据，经集体协商确定每份梯田应得的水量。“公平”强调应得份额的确定合乎情理，“精确”则侧重量水分水的准确程度。“科学”在首空也能表达合理之意，但其配对的“量入为出”侧重按收入确定开支，第二空的“精打细算”更贴合“取之有度，用之有节”。","references":[],"evidence":"根据沟渠所能灌溉的梯田面积，经过集体协商，确定每份梯田应得水量","disposition":"独立词条","basis":"据原题和解析编释。","title":"公平","related":[],"examFocus":{"国考 2024 副省级 行测#29":"首空结合按梯田面积协商定水量的过程，辨析各词评价分水规则的侧重点，第二空结合取水和用水的描述，辨析各成语适用的语境。"}},"readings":[{"origin":"k-0bbf4ceb332fe60c","title":"公平","qs":["国考 2024 副省级 行测#29"],"definition":"公平指处理事情合乎情理，对有关各方一视同仁。分配是否公平，要看依据和规则能否合理对待各方。","explanation":"哈尼族的木刻分水以沟渠所能灌溉的梯田面积为依据，经集体协商确定每份梯田应得的水量。“公平”强调应得份额的确定合乎情理，“精确”则侧重量水分水的准确程度。“科学”在首空也能表达合理之意，但其配对的“量入为出”侧重按收入确定开支，第二空的“精打细算”更贴合“取之有度，用之有节”。","evidence":"根据沟渠所能灌溉的梯田面积，经过集体协商，确定每份梯田应得水量","doubt":"","references":[]},{"origin":"k-43c983df6d65f7b9","title":"公平","qs":["国考 2024 地市级 行测#31"],"definition":"公平指处理事务合情合理，对相关各方一视同仁。分配资源时，公平可以体现为按共同认可的标准确定各方应得份额。","explanation":"第31题的木刻分水制度根据沟渠所能灌溉的梯田面积，经集体协商确定每份梯田应得的水量，并用横木刻度作为分水依据。“公平”概括的是这一分配原则，“精确”侧重计量的准确程度。第一空也可用“科学”表达做法合理，第二空的“精打细算”使A项更贴切。","evidence":"经过集体协商，确定每份梯田应得水量","doubt":"","references":[]}]},"k-86d7c3bc528617f5":{"review":{"title":"精打细算与量入为出","type":"概念与词义","definition":"精打细算指在使用人力、物力、财力等资源时周密计算、细致安排。量入为出指根据收入多少确定支出的限度。","explanation":"精打细算可用于描述对水等资源的细致分配和节制使用。量入为出侧重支出受收入约束，引申到资源管理时也强调先确定可用总量，再据此安排用量。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典精打細算","location":"“精打細算”词目"},{"source":"词典量入為出","location":"“量入為出”词目"}],"related":[],"examFocus":{"国考 2024 副省级 行测#29":"第一空看协商定水量和刻度分水体现了怎样的分配原则，第二空看“取之有度，用之有节”描述了怎样的用水方式。"}},"readings":[{"origin":"k-86d7c3bc528617f5","title":"精打细算与量入为出","qs":["国考 2024 副省级 行测#29","国考 2024 行政执法 行测#28"],"definition":"精打细算指在使用人力、物力、财力等资源时周密计算、细致安排。量入为出指根据收入多少确定支出的限度。","explanation":"精打细算可用于描述对水等资源的细致分配和节制使用。量入为出侧重支出受收入约束，引申到资源管理时也强调先确定可用总量，再据此安排用量。","evidence":"","doubt":"","references":[{"source":"词典精打細算","location":"“精打細算”词目"},{"source":"词典量入為出","location":"“量入為出”词目"}]},{"origin":"k-963cb658114dfef7","title":"精打细算与量入为出","qs":["国考 2024 地市级 行测#31"],"definition":"精打细算指在使用钱财、人力或物力时细致计算、周密安排。量入为出指根据收入多少确定支出限度。","explanation":"第31题用“量水、分水，取之有度，用之有节”说明哈尼人细致分配、节制使用灌溉用水，因此第二空用“精打细算”。“量入为出”侧重用收入约束支出，材料着重描述的是应得水量的分配及用水节制。","evidence":"量水、分水，取之有度，用之有节","doubt":"","references":[]}],"aspects":[{"title":"节制使用与按收入安排支出","uses":[{"unit":"Q1","role":"直接考查","use":"哈尼族通过集体协商确定各份梯田应得的水量，再以刻度量水、分水。第二空承接细致安排、节制用水，填“精打细算”，与第一空的“公平”组成A项。","evidence":"哈尼人用其量水、分水，取之有度，用之有节","qids":["国考 2024 副省级 行测#29","国考 2024 行政执法 行测#28"]}]}]},"k-308053abdeaa1f83":{"review":{"definition":"异想天开形容想法离奇，完全不切实际。","explanation":"第二空受“脱离国情的”限定，与“闭门造车的主观想象”并列，都指脱离实际的想法。后文提出“一切从实际出发”，进一步明确了这里批评的是设想缺乏现实基础。","references":[],"evidence":"“异想天开”比喻想法离奇而完全不切实际","disposition":"独立词条","basis":"据原题和解析编释。","title":"异想天开","related":[],"examFocus":{"国考 2024 副省级 行测#30":"重点看第二空与“闭门造车的主观想象”构成怎样的并列关系，再比较候选成语各自侧重什么。"}},"readings":[{"origin":"k-308053abdeaa1f83","title":"异想天开","qs":["国考 2024 副省级 行测#30"],"definition":"异想天开形容想法离奇，完全不切实际。","explanation":"第二空受“脱离国情的”限定，与“闭门造车的主观想象”并列，都指脱离实际的想法。后文提出“一切从实际出发”，进一步明确了这里批评的是设想缺乏现实基础。","evidence":"“异想天开”比喻想法离奇而完全不切实际","doubt":"","references":[]},{"origin":"k-6645f66d7ec43690","title":"异想天开","qs":["国考 2024 地市级 行测#30"],"definition":"异想天开形容想法离奇、难以实现，常用于批评脱离实际的设想。","explanation":"第30题第二空受“脱离国情”限定，与“闭门造车的主观想象”并列，又与“一切从实际出发”相对。“异想天开”在这里强调想法缺乏现实依据，贴合文段对解放思想的要求。","evidence":"而是要求我们一切从实际出发","doubt":"","references":[]},{"origin":"k-b0c320482ce29e23","title":"异想天开","qs":["国考 2024 行政执法 行测#32"],"definition":"形容想法离奇，很不切实际。","explanation":"第32题用“脱离国情的异想天开”与“闭门造车的主观想象”并列，说明解放思想须从实际出发。这里的“异想天开”强调想法缺乏国情和现实依据。","evidence":"而是要求我们一切从实际出发","doubt":"","references":[]}]},"k-7edd2c2a2ea1635e":{"review":{"title":"剥离与甄别","type":"概念与词义","definition":"剥离是把原本附着在一起或处于同一整体中的部分分开。甄别是经过审查或考察，辨别对象的真伪、优劣或类别。","explanation":"用于信息处理时，甄别着眼于判定信息属于哪一类，剥离着眼于把特定信息从原有数据集合中分出。甄别结果可以作为后续剥离的依据。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典剝離","location":"“剝離”词目"},{"source":"词典甄別","location":"“甄別”词目"}],"examFocus":{"国考 2024 副省级 行测#31":"结合下文对可用信息的处理，辨析第二空的动词侧重辨认、分开还是去除，再核对第一空的搭配。"}},"aspects":[{"title":"敏感信息的辨识与分离","uses":[{"unit":"Q1","role":"直接考查","use":"本题均选D。第二空与“利用好其他可用信息”并列，语境要求先从海量个人信息中分出敏感信息，因此选“剥离”。“甄别”只表达识别哪些信息属于敏感信息。","evidence":"敏感信息、利用好其他可用信息","qids":["国考 2024 副省级 行测#31","国考 2024 地市级 行测#27","国考 2024 行政执法 行测#27"]}]}]},"k-0d9bfe3556bda9c0":{"review":{"definition":"真抓实干指以务实的作风采取实际行动，把工作落到实处。","explanation":"第一空与“以上率下”并列。后文的带领大家定盘子、理路子体现带头作用，亲自部署重要任务、把关关键环节、督查落实情况则具体体现“真抓实干”。“一马当先”偏重带头，与前面的“以上率下”意思接近。","references":[],"evidence":"重要任务亲自部署、关键环节亲自把关、落实情况亲自督查","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9982caad8db44605":{"review":{"definition":"原题引文：“凌空蹈虚”指无史实根据的虚构","explanation":"新华社报道原文把“凌空蹈虚”与“高高在上”并列，前面列出亲自部署、把关和督查三项要求，后面接“不能只挂帅不出征”。第二空因此是在批评脱离实际的工作作风，对应B项。题附解析提到的“无史实根据的虚构”指向虚构是否有史实依据，讲话中的用法则指向工作是否落到实处。","references":[{"source":"web-3eb1ec77748fd067","location":"2020年10月10日新华社通稿，“年轻干部要提高抓落实能力”段","quote":"不能高高在上、凌空蹈虚，不能只挂帅不出征"}],"evidence":"“凌空蹈虚”指无史实根据的虚构","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-bf4ce7169fc550fb":{"review":{"definition":"稳扎稳打比喻有把握、有步骤地推进工作。","explanation":"第三空修饰“向前走”。后文写登过一山再登一峰、跨过一沟再越一壑，把持续推进具体写成逐步克服困难，贴合“稳扎稳打”。“披荆斩棘”更侧重扫除障碍，“久久为功”更侧重长期坚持。","references":[],"evidence":"过了一山再登一峰，跨过一沟再越一壑","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e5f7b01b3816208c":{"review":{"definition":"精致指精巧细致，可用于形容作品在整体安排和细部处理上呈现出的品质。","explanation":"第二空需要同时描述AI绘画成品的构图、配色和细节。“精致”能概括三者表现出的精巧细致，与后文所说的符合人类审美经验相呼应。“丰富”主要说明种类多或数量大，侧重的是另一个方面。","references":[],"evidence":"“精致”指精巧细致","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-66986411f23a588f":{"review":{"definition":"贡献者为某项事业或共同资源提供有价值的投入。维护者负责维持已有系统的正常运行，推广者着力扩大事物的知晓度或使用范围。","explanation":"研究人员从数据库取用数据，是使用者，把自己发现的数据存入数据库，又是贡献者。题干没有描述系统维护或宣传推广。“建设者”也能体现参与数据库建设，需再凭第二空的搭配选定C项。","references":[],"evidence":"将自己研究发现的基因序列或蛋白质结构数据存入数据库","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9d11e4e744278daa":{"review":{"definition":"可靠指可以信赖或依靠。坚定指意志、信念、立场等稳定而不动摇。","explanation":"第二空修饰“纪录载体”，强调数据库作为记录凭据值得信赖，因此用“可靠”。“坚定”通常修饰立场、信念等，与“纪录载体”搭配不当，可据此排除D项。","references":[],"evidence":"“坚定”指意志坚强，不动\n摇，与“纪录载体”搭配不当","disposition":"独立词条","basis":"据原题和解析编释。","title":"可靠与坚定","related":[],"examFocus":{"国考 2024 副省级 行测#34":"第二空修饰“纪录载体”，可结合候选词通常修饰的对象来辨析搭配。"}},"readings":[{"origin":"k-9d11e4e744278daa","title":"可靠与坚定","qs":["国考 2024 副省级 行测#34"],"definition":"可靠指可以信赖或依靠。坚定指意志、信念、立场等稳定而不动摇。","explanation":"第二空修饰“纪录载体”，强调数据库作为记录凭据值得信赖，因此用“可靠”。“坚定”通常修饰立场、信念等，与“纪录载体”搭配不当，可据此排除D项。","evidence":"“坚定”指意志坚强，不动\n摇，与“纪录载体”搭配不当","doubt":"","references":[]},{"origin":"k-b8cdc11f89a14499","title":"可靠与坚定","qs":["国考 2024 地市级 行测#39"],"definition":"可靠指值得信赖或可以依靠。坚定指意志、立场、态度等稳固而不动摇。","explanation":"第二空修饰“纪录载体”。数据库保存研究人员提交的数据，也作为研究人员使用的数据分析平台，“可靠”能说明这种记录载体值得信赖，并与末句“为整个生命科学研究所依赖”呼应。“坚定”通常评价意志或立场，无法表达载体的可信程度，因此选C。","evidence":"“可靠”指可以信赖依靠，与“纪录载体”搭配得当","doubt":"","references":[]}]},"k-d9a7a75361fe01cf":{"review":{"definition":"包罗万象形容所包含的内容丰富，涉及的范围广。","explanation":"首空用“包罗万象”概括基层工作涉及事项多，与调研时的“千头万绪”呼应，也解释了为什么需要从一件具体的民生实事切入。“盘根错节”和“错综复杂”也能呼应头绪多，最终由后两空确定C项。","references":[],"evidence":"“包罗万象”形容内容丰富，应有尽有","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-675016a3fe0a1abd":{"review":{"definition":"抽丝剥茧比喻从复杂现象中逐层梳理线索，细致地分析问题。","explanation":"第二空写调研怎样直面“真问题”。从民生实事的小切口入手，再坚持“一根竿子插到底”，对应“抽丝剥茧”的逐层深入。“追根溯源”偏重追查起因，也符合深入调查的方向，最终由第三空“破解症结”确定C项。","references":[],"evidence":"调研要坚持“一根竿子插到底”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0a8fc48508a25001":{"review":{"title":"为政之要，以顺民心为本","type":"概念与词义","definition":"这句话意为治理政事应以顺应民心为根本。","explanation":"“顺”指顺应，“本”指根本。在中央人大工作会议讲话的题选段中，顺应民心体现为听取人民意见、接受人民监督，并通过人大代表联系群众、回应社会关切。","basis":"据关联原题及所列出处编释。","references":[{"source":"quote42","location":"程颐《代吕晦叔应诏疏》与后世引述"}],"related":[],"examFocus":{"国考 2024 副省级 行测#43":"辨析各句古语的侧重点，看哪一句能同时统领后文对国家机关及其工作人员和人大代表的要求。"}},"readings":[{"origin":"k-0a8fc48508a25001","title":"为政之要，以顺民心为本","qs":["国考 2024 副省级 行测#43","国考 2024 地市级 行测#50"],"definition":"这句话意为治理政事应以顺应民心为根本。","explanation":"“顺”指顺应，“本”指根本。在中央人大工作会议讲话的题选段中，顺应民心体现为听取人民意见、接受人民监督，并通过人大代表联系群众、回应社会关切。","evidence":"","doubt":"","references":[{"source":"quote42","location":"程颐《代吕晦叔应诏疏》与后世引述"}]},{"origin":"k-f5eedced27ec9b1f","title":"为政之要，以顺民心为本","qs":["国考 2024 行政执法 行测#53"],"definition":"这句话指治理国家的要务，是把顺应民心作为根本。","explanation":"“为本”指出治理应以什么为根本，与后文所说人民代表大会制度“深深植根于人民之中”相呼应。后文要求国家机关和国家工作人员倾听人民意见、接受人民监督，也要求拓宽人大代表联系群众的渠道，具体说明了这一原则。A项侧重从民众的状况判断治理成效，D项侧重因利民而变革旧制，B项的主旨与后文最贴合。","evidence":"为政之要，以顺民心为本","doubt":"","references":[]}],"aspects":[{"title":"顺应民心与人大联系群众","uses":[{"unit":"Q1","role":"解题依据","use":"本题均选B。文段将人民代表大会制度的生命力归于其植根人民，并提出国家机关及其工作人员听取意见、人大代表联系群众等要求。这句古语概括了以人民为根本的主旨。","evidence":"人民代表大会制度之所以具有强大生命力和显著优越性，关键在于深深植根于人民之中。","qids":["国考 2024 副省级 行测#43","国考 2024 地市级 行测#50"]}]}]},"k-ee0c52fd110c2085":{"review":{"definition":"同比降幅是本期比上年同期减少的比例，以上年同期数值为基数。减少额等于上年同期数值乘以降幅。","explanation":"设去年上、下半年支出分别为x、y万元，两个降幅各乘对应的同期支出，因此有0.20x＋0.15y＝172，再与x＋y＝960联立。算得今年上半年支出为448万元，下半年为340万元，上半年多108万元。","references":[],"evidence":"企业支出比去年同期分别减少20%和15%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-79b409629f0860e1":{"review":{"title":"2型糖尿病","type":"概念与词义","definition":"2型糖尿病是一种慢性非传染性疾病，主要表现为机体不能有效利用胰岛素，导致血糖持续升高。","explanation":"机体对胰岛素的反应减弱称为胰岛素抵抗。当胰岛素分泌不足以弥补这种反应减弱时，血糖就会升高。","basis":"据关联原题和解析编释。","references":[],"related":[],"examFocus":{"国考 2024 副省级 行测#86":"判断慢病自我管理时，先核对当事人是否已患慢病，再看监测和管理是否由本人主动开展。"}},"readings":[{"origin":"k-79b409629f0860e1","title":"2型糖尿病","qs":["国考 2024 副省级 行测#86","国考 2024 地市级 行测#83"],"definition":"2型糖尿病是一种慢性非传染性疾病，主要表现为机体不能有效利用胰岛素，导致血糖持续升高。","explanation":"机体对胰岛素的反应减弱称为胰岛素抵抗。当胰岛素分泌不足以弥补这种反应减弱时，血糖就会升高。","evidence":"","doubt":"","references":[]},{"origin":"k-667ed7f9afa4286e","title":"2型糖尿病","qs":["国考 2024 行政执法 行测#86"],"definition":"2型糖尿病是一种以血糖升高为主要特征的慢性非传染性疾病。","explanation":"D项中，老李患有2型糖尿病，符合题干要求的慢病患者这一主体条件。他按时服药、定期监测血糖，符合主动管理自身病情的要求。B项的老王也是慢病患者，但选项写的是医院追踪指标。","evidence":"II型糖尿病属于慢性非传染性疾病","doubt":"","references":[]}],"aspects":[{"title":"慢病自我管理的主体","uses":[{"unit":"Q1","role":"解题依据","use":"老李所患的2型糖尿病属于慢病，他本人按时服药并定期监测血糖，符合题干对慢病自我管理的定义，故选D。","evidence":"II型糖尿病属于慢性非传染性疾病","qids":["国考 2024 副省级 行测#86","国考 2024 地市级 行测#83"]}]}]},"k-586ad23e4f3a00e0":{"review":{"definition":"按题干定义，郁闭度是乔木树冠在阳光直射下的地面总投影面积与所在林地总面积之比。取值为1表示树冠层完全郁闭。","explanation":"B项给出树冠投影面积3万公顷和郁闭度0.3，林地总面积为3÷0.3＝10万公顷。题干还给出郁闭度与气温日变化负相关、与相对湿度正相关，因此C项虽写对了相对湿度的变化方向，却把气温日变化写成了增加。","references":[],"evidence":"乔木树冠在阳光直射下地面总投影面积与此林地总面积的比","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2d31952883d39c1d":{"review":{"definition":"续约指当事人在已有约定的基础上，达成继续维持原合同关系的约定。","explanation":"C项按原合约期满后继续签约来理解。签约可以是首次订立合同，续约则以已有合约为前提，对应题干中已有冠军称号、随后再次夺冠的关系。","references":[],"evidence":"续约指合同、合约期满后继续签约","disposition":"独立词条","basis":"据原题和解析编释。","title":"续约","related":[],"examFocus":{"国考 2024 副省级 行测#96":"比较“卫冕”和“夺冠”的含义，留意两词对先前是否已取得冠军的要求。"}},"readings":[{"origin":"k-2d31952883d39c1d","title":"续约","qs":["国考 2024 副省级 行测#96"],"definition":"续约指当事人在已有约定的基础上，达成继续维持原合同关系的约定。","explanation":"C项按原合约期满后继续签约来理解。签约可以是首次订立合同，续约则以已有合约为前提，对应题干中已有冠军称号、随后再次夺冠的关系。","evidence":"续约指合同、合约期满后继续签约","doubt":"","references":[]},{"origin":"k-a0fdcbb31f84ba21","title":"续约","qs":["国考 2024 地市级 行测#91"],"definition":"续约指已有合同或合约，经续订使约定在原约定期限届满后继续。","explanation":"“签约”可以是首次订立合约。“续约”以先前已有合约为前提，强调接续原有的合约关系。正如题干中的“卫冕”以此前已经夺冠为前提，C项符合这一关系。","evidence":"续约指合同、合约期满后继续签约","doubt":"","references":[]}]},"k-da52f2a9c6ee4246":{"review":{"definition":"花生壳是包住花生种子的外壳，核桃仁是去掉核桃硬壳后可食用的部分。","explanation":"题干两词分别指各自原物已有的部位，一个在外，一个在内。比对的共同点是两词都与各自原物构成部分和整体的关系。B项的丝瓜络和石榴籽也符合，C项中的杏仁露则是以杏仁制成的饮料。","references":[],"evidence":"“花生壳”是花生的组成部分；“核桃仁”是核桃的组成部分","disposition":"题内说明","basis":"据原题和解析编释。","title":"花生壳与核桃仁","related":[],"examFocus":{"国考 2024 副省级 行测#97":"比对每个词与其原物的关系，留意它指的是原物的组成部分还是加工后的产物。"}},"readings":[{"origin":"k-da52f2a9c6ee4246","title":"花生壳与核桃仁","qs":["国考 2024 副省级 行测#97"],"definition":"花生壳是包住花生种子的外壳，核桃仁是去掉核桃硬壳后可食用的部分。","explanation":"题干两词分别指各自原物已有的部位，一个在外，一个在内。比对的共同点是两词都与各自原物构成部分和整体的关系。B项的丝瓜络和石榴籽也符合，C项中的杏仁露则是以杏仁制成的饮料。","evidence":"“花生壳”是花生的组成部分；“核桃仁”是核桃的组成部分","doubt":"","references":[]},{"origin":"k-f0a4212771577719","title":"花生壳与核桃仁","qs":["国考 2024 地市级 行测#92"],"definition":"花生壳是花生的外壳，核桃仁是核桃壳内的种仁。两者分别是各自植物果实的一部分。","explanation":"B项中，丝瓜络是成熟丝瓜的网状纤维，石榴籽是石榴的种子，两者也分别属于各自的果实。C项虽有同样属于果实一部分的葡萄皮，但杏仁露是用杏仁制成的饮料，所以两词合在一起与题干关系不同。","evidence":"“花生壳”是花生的组成部分；“核桃仁”是核桃的组成部分","doubt":"","references":[]}]},"k-21f5da72d95c351c":{"review":{"definition":"丝瓜络是成熟丝瓜干燥后留下的网状纤维。石榴籽是石榴果实中的种子。","explanation":"丝瓜络的网状纤维原本就存在于丝瓜中，石榴籽也原本就存在于石榴中。B项两词各指原物的一个组成部分，与题干的花生壳、核桃仁一致。D项的葛根茶和芡实粉则分别以葛根和芡实为原料制成。","references":[],"evidence":"“丝瓜络”是干燥成熟丝瓜的网状纤维","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b1a85f10484e0cb1":{"review":{"definition":"尊和爵是中国古代两种不同的酒器。","explanation":"第100题的首词“酒器”是总类，“尊”和“爵”分别归入这个总类，二者彼此并列。D项的木柱、石柱、砖柱也彼此并列，但总类“柱子”未出现在词组中。","references":[],"evidence":"尊和爵是古代两种不同的酒器","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7dcdab89bd164064":{"review":{"definition":"原题引文：礼服和常服是两种不同穿着场合的服装","explanation":"尊和爵分别是酒器的下位类别。B项的礼服和常服也分别是服装的下位类别，三词都指实物类别，与题干对应最直接。转载题本的C项确为“人居：巢居：穴居”。巢居、穴居指居住方式。若把“人居”宽泛理解为人类居住活动，C项也可作总类与下位类的解读，单凭题附解析所称的“交叉关系”难以排除这个读法。","references":[{"source":"web-7a152da599b3ca7c","location":"判断推理，酒器、尊、爵类比题C项","quote":"人居：巢居：穴居"}],"evidence":"礼服和常服是两种不同穿着场合的服装","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-e4af987a86189cc5":{"review":{"definition":"“领头雁”比喻有号召力、能发挥带头和示范作用的人。","explanation":"A项的“领导者”对应“领头雁”比喻所指的人，和“拓荒牛”对应“先驱”的方向一致。B项的“鸟类”对应的是“领头雁”的字面义，属于种属关系。","references":[],"evidence":"领头雁比喻在众人眼里有一定的号召力和领导能力，具有榜样力量的人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d4362ca742afb2a4":{"review":{"definition":"“拓荒牛”比喻率先开拓、勇于创新的人。","explanation":"A项的“先驱”指走在前面开路的人，正是“拓荒牛”这一形象所比喻的人。D项的“先行者”和“先驱”意思相近，两词之间属于近义关系。","references":[],"evidence":"比喻开拓创新的先行者，先驱指前行开路的人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-51ba02848364c3a1":{"review":{"title":"粮食单位面积产量","type":"概念与词义","definition":"一定范围内粮食总产量与相应播种面积的比值，也称单产。","explanation":"总产量＝播种面积×单产。总产量增长时，如播种面积增长更快，单产仍可能下降。","basis":"据所列文献编释。","references":[{"source":"farmyield","location":"粮食总产量、播种面积和单位面积产量"}],"basisGroup":"单位价格与平均量","related":["k-d53156aa5705fe00","k-bc653d5f836f1adb"]}},"k-d53156aa5705fe00":{"review":{"title":"单位平均量","type":"概念与词义","definition":"同一范围的总量除以承担该总量的单位个数所得的平均值。","explanation":"原题求单站能量，分母须用相应类别的电站数。两类电站数量不同时，类平均值的简单平均通常不同于总体平均值。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"单位价格与平均量","related":["k-bc653d5f836f1adb","k-51ba02848364c3a1"]}},"k-0653efd3e9d668f6":{"review":{"definition":"两数之差的绝对值表示两数相差的大小，等于较大数减去较小数。交换相减顺序，所得绝对值相同。","explanation":"第134题中，京、津、冀三地的农村居民人均可支配收入年均增速均高于各自的城镇增速。按农村增速减城镇增速，北京为8.2%−7.3%=0.9个百分点，天津为7.3%−6.9%=0.4个百分点，河北为8.6%−7.1%=1.5个百分点。差值的绝对值从大到小为冀、京、津，对应B项。","references":[],"evidence":"年均增速的城乡差值的绝对值","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-19b1f957c3d77505":{"review":{"definition":"自变量是回归模型中用于解释或预测因变量的变量。根据研究设计，自变量的取值可以预先设定，也可以按随机变量处理。","explanation":"自变量指变量在模型中的角色，随机变量指变量取值的统计性质。例如研究温度与某项测量结果的关系时，可以预先设定若干温度值作为自变量。这个情形足以反驳题中③将自变量一概视为随机变量的说法。","references":[],"evidence":"回归分析中自变量可以是固定变量。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b5982a0f7ff989b6":{"review":{"definition":"众数是一组数据中出现次数最多的数值。多个数值并列达到最高频数时，可以有多个众数。","explanation":"样本为1、1、1、2、3时，众数为1。把3改为100，最高频数仍由1取得，众数也仍为1。这说明题中④所说的情形确实可能发生。","references":[],"evidence":"众数的大小可能与样本数据中的部分数据无关","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b9e7138b92b5b785":{"review":{"definition":"有机肥原料是用于生产有机肥的物料，常见来源包括农业废弃物、畜禽粪便和餐厨垃圾等。","explanation":"秸秆来自农业生产，餐厨垃圾来自餐饮或家庭生活，二者都可作为有机肥生产的原料。B项判断的是原料来源，所述正确。","references":[],"evidence":"秸秆、餐厨垃圾都是有机肥料的原料","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ae6729beeeda923f":{"review":{"definition":"见微知著指从细微的迹象察知事物较深层的情况或发展趋势。","explanation":"“当杜其萌”把防范的时点放在风险萌发时。“见微知著”强调从小迹象看出潜在的大风险，为后面的“抓早抓小”提供判断依据。“对症下药”强调措施有针对性，“审时度势”强调研判形势，“当机立断”强调及时决断，因此选C。","references":[],"evidence":"祸几始作，当杜其萌","disposition":"独立词条","basis":"据原题和解析编释。","title":"见微知著","related":[],"examFocus":{"国考 2024 副省级 行测#21":"结合古语和“抓早抓小”，判断空格应突出风险防范的哪个环节。"}},"readings":[{"origin":"k-ae6729beeeda923f","title":"见微知著","qs":["国考 2024 地市级 行测#22"],"definition":"见微知著指从细微的迹象察知事物较深层的情况或发展趋势。","explanation":"“当杜其萌”把防范的时点放在风险萌发时。“见微知著”强调从小迹象看出潜在的大风险，为后面的“抓早抓小”提供判断依据。“对症下药”强调措施有针对性，“审时度势”强调研判形势，“当机立断”强调及时决断，因此选C。","evidence":"祸几始作，当杜其萌","doubt":"","references":[]},{"origin":"k-d3f172b17158a5b4","title":"见微知著","qs":["国考 2024 副省级 行测#21"],"definition":"见微知著指从细微的迹象中看出事物的实质或发展趋势。","explanation":"题干引文中的“祸几始作”和“疾证方形”都指隐患初露苗头，后文“抓早抓小”要求在风险扩大前识别并处置。C项“见微知著”对应由苗头识别潜在风险这一步。“对症下药”侧重措施有针对性，“审时度势”侧重研判总体形势，“当机立断”侧重迅速作出决定。","evidence":"祸几始作，当杜其萌；疾证方形，当绝其根。","doubt":"","references":[]}]},"k-e0aeca9b0007e8dc":{"review":{"definition":"形容对事物观察得透彻，看得十分清楚。","explanation":"题中“对敌方的军事行动”与“对敌方的结构体系”构成并列，后半句的“心知肚明”提示前一空也应表达了解得很清楚。“洞若观火”强调看得透彻，“胸有成竹”强调事前已有打算，“未卜先知”强调事先知道。","references":[],"evidence":"形容观察事物透彻分明","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a9d451e85ac691a3":{"review":{"definition":"指使数值、水平或程度下降。“降低某事发生的可能性”指使这件事发生的可能性变小。","explanation":"题中重复操作是为了检验先前的研究成果，提高发现问题的机会。文段据此表达造假的可能性减小，用“降低……的可能”搭配自然，也比表示彻底阻止的“杜绝”更符合这里的程度。","references":[],"evidence":"可以用重复操作检验此前的研究成果是否准确、正确","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e8fc75dbb214e22d":{"review":{"definition":"比喻出了问题或受到损失后及时补救，以防类似损失再次发生。","explanation":"“前者”指治标，所面对的是已经产生的谣言。“亡羊补牢”突出问题发生后着手补救，和“针对既成事实”对应。“补偏救弊”也能表达纠正已出现的问题，整组答案由第二空的事前预防含义确定。","references":[],"evidence":"前者针对既成事实","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b9007d503d7fa567":{"review":{"definition":"比喻在祸患发生之前采取预防措施。","explanation":"“后者”指治本，“治未病”在这段话中比喻从源头防范谣言产生。“曲突徙薪”强调事先预防，与第一空“亡羊补牢”的事后补救形成时间上的对应。“先发制人”侧重抢先取得主动并制住对方，与这里的预防含义不同。","references":[],"evidence":"后者侧重于“治未病”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-10e94123159c4305":{"review":{"definition":"指阻隔、分隔，使彼此之间的联系断开。","explanation":"“隔绝”在第一空表示切断信息数据与互联网经济的联系。它受前面的“并不是”否定，文段主张在必要、合理、合规的基础上兼顾保护与利用。“分离”也能表达分开，第二空的“剥离”强调将敏感信息分出，和下文利用其他可用信息相接，因此确定选D。","references":[],"evidence":"阻隔，分隔断绝","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-974bbb429dec87d3":{"review":{"definition":"差异性指事物之间存在区别的性质。","explanation":"第29题说，不同文化背景下的音乐有所区别，这种区别会激发听众的探索兴趣。第一空的“差异性”直接指向这种区别，“多元化”侧重多种形态并存，放在第一空也能说通。最终由第二空的“共鸣”确定选B。","references":[],"evidence":"“差异性”强调存在区别、不同","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e2b40878473c8902":{"review":{"definition":"共鸣在思想感情上指受到他人或作品触动，产生相通的思想或感情。互动指双方或多方彼此联系、相互影响。","explanation":"第29题第二空说的是电影借助音乐，让全球观众对中国故事及其传达的精神和文化产生情感回应。“共鸣”能概括作品触动观众的效果，“互动”需要文段体现双方相互影响。","references":[],"evidence":"“互动”指彼此联系，相互影响的过程","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-52ecfe7add059fc6":{"review":{"definition":"落地生根比喻在某地扎下根来、稳定融入，也可形容理论或理念在当地实践中获得持久的基础。","explanation":"第30题用“必须中国化才能……、本土化才能深入人心”的并列句式，说明马克思主义理论要结合中国实际，在中国扎根。“薪火相传”突出代际传承，“枝繁叶茂”和“生生不息”突出发展或延续，第一空需要突出的是理论在中国的扎根。","references":[],"evidence":"马克思主义理论深度融入中国","disposition":"独立词条","basis":"据原题和解析编释。","title":"落地生根","related":[],"examFocus":{"国考 2024 副省级 行测#30":"第一空结合与“本土化才能深入人心”并列的句式，判断成语能否描述理论中国化后的状态；第二空结合“从实际出发”辨析被否定的做法。"}},"readings":[{"origin":"k-52ecfe7add059fc6","title":"落地生根","qs":["国考 2024 地市级 行测#30"],"definition":"落地生根比喻在某地扎下根来、稳定融入，也可形容理论或理念在当地实践中获得持久的基础。","explanation":"第30题用“必须中国化才能……、本土化才能深入人心”的并列句式，说明马克思主义理论要结合中国实际，在中国扎根。“薪火相传”突出代际传承，“枝繁叶茂”和“生生不息”突出发展或延续，第一空需要突出的是理论在中国的扎根。","evidence":"马克思主义理论深度融入中国","doubt":"","references":[]},{"origin":"k-8be730a3e1e01831","title":"落地生根","qs":["国考 2024 行政执法 行测#32"],"definition":"比喻在一个地方扎下根来。用于理论、政策等时，可以指它们在当地实践中扎根。","explanation":"第32题把“中国化才能落地生根”与“本土化才能深入人心”并列，说明马克思主义理论要同中国实际相结合，才能在中国实践中扎根。“薪火相传”侧重代际传承，“枝繁叶茂”侧重发展兴盛，“生生不息”侧重持续发展。","evidence":"本土化才能深入人心","doubt":"","references":[]},{"origin":"k-9913a201976a3b1c","title":"落地生根","qs":["国考 2024 副省级 行测#30"],"definition":"落地生根可比喻长期安家落户。用于理论时，比喻理论融入当地实际并在实践中扎下根基。","explanation":"首空承接“必须中国化才能”，把马克思主义同中国实际相结合写成理论在当地扎根，并与“本土化才能深入人心”形成并列。“薪火相传”侧重代际传承，“枝繁叶茂”侧重发展兴盛，“生生不息”侧重持续生长，都缺少扎根当地的指向。","evidence":"马克思主义理论必须随着实践发展而发展","doubt":"","references":[]}]},"k-710b007baf08faec":{"review":{"definition":"司空见惯指某事经常见到，因而不足为奇。习以为常指习惯了某种情形，因而把它视作平常。","explanation":"第32题把年轻人熟悉的数字服务操作与老年人遇到的困难作对照。第一空用“司空见惯”可突出年轻人经常见到这类操作，用“习以为常”也可突出年轻人已经习惯。最终由第二空与“站在老年人的角度”的呼应确定选A。","references":[],"evidence":"某事常常见到，不足为奇","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3552abc0a870cc6f":{"review":{"definition":"设身处地指把自己放在他人的处境中考虑问题。感同身受指对他人的遭遇体会很深，仿佛自己亲身经历一样。","explanation":"第32题第二空紧接“站在老年人的角度”，要求全社会成员主动换位，进而体会老年人使用数字服务时可能遭遇的困境。“设身处地”可修饰这一换位行动，“感同身受”侧重描述体会他人处境时的感受。","references":[],"evidence":"把自己放在别人所处的地位上考虑，替别人着想","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d5a77d2fbd4be1eb":{"review":{"definition":"望而却步指看到危险或自觉难以应付的情形便退缩。裹足不前指因有所顾虑而停步，迟迟不敢行动。","explanation":"第33题以少数船只“敢于一试身手”反衬绝大部分战舰面对巨大海冰时不敢贸然前进。“望而却步”突出面对眼前障碍而退缩，“裹足不前”突出因顾虑而止步，两者都能承接第一空的对照。最终由第二空的“轻而易举”确定选A。","references":[],"evidence":"唯有破冰船和冰面下的潜艇敢于一试身手","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2bac8bb698eae1c8":{"review":{"definition":"轻而易举形容一件事很容易办成，几乎不费力。长驱直入形容迅速而顺利地向纵深推进，常用于描述进军。","explanation":"第33题第二空修饰“破开”，结合题干给出的“近3米厚的坚冰”，用“轻而易举”说明这艘破冰船完成该动作并不费力。“长驱直入”适合写船只或队伍顺利向前推进，用在这里无法直接表达破冰动作的难易。","references":[],"evidence":"“轻而易举”形容事情容易做，不费力，省事","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f24e9d130fb0bc58":{"review":{"definition":"以偏概全指用局部情况概括整体，侧重推断方式。一孔之见指狭隘片面的见解，侧重所得看法。","explanation":"题中调研者只看到孤立的“盆景”。若把这些局部情况当成全貌，就是以偏概全，所得的片面看法也可称为一孔之见。两词均可呼应“盲人摸象”，A、C两项在第一空都可保留，由第二空判定选A。","references":[],"evidence":"眼中只有一个个孤立的“盆景”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-00fb39d166a586fa":{"review":{"definition":"针对性指措施与具体对象、问题相适应的程度。时效性侧重信息、措施等是否及时，或能否在一定时间内发挥作用。","explanation":"题中调研者对新情况多凭主观判断下结论，由此制定的政策容易对不准眼下的实际问题，所以填“针对性”。“新情况”交代的是调研需要掌握的实际变化，题干未提供政策出台太晚或已经过时的线索。","references":[],"evidence":"对新情况多凭主观判断下结论","disposition":"独立词条","basis":"据原题和解析编释。","title":"针对性与时效性","related":[],"examFocus":{"国考 2024 副省级 行测#26":"辨析第二空的“针对性”和“时效性”时，留意题干描述的是政策与实际问题的匹配程度，还是政策出台的时间。"}},"readings":[{"origin":"k-00fb39d166a586fa","title":"针对性与时效性","qs":["国考 2024 地市级 行测#34"],"definition":"针对性指措施与具体对象、问题相适应的程度。时效性侧重信息、措施等是否及时，或能否在一定时间内发挥作用。","explanation":"题中调研者对新情况多凭主观判断下结论，由此制定的政策容易对不准眼下的实际问题，所以填“针对性”。“新情况”交代的是调研需要掌握的实际变化，题干未提供政策出台太晚或已经过时的线索。","evidence":"对新情况多凭主观判断下结论","doubt":"","references":[]},{"origin":"k-122eab437eaa1286","title":"针对性与时效性","qs":["国考 2024 副省级 行测#26"],"definition":"政策的针对性指措施切合特定对象及其具体问题的程度。时效性强调作用或效力与时间条件的关系。","explanation":"题干的因果链是调研人员对新情况凭主观判断下结论，出台的政策因而难以切合眼下的具体问题，应填“针对性”。“新情况”在这里是调研需要弄清的现实情况，题干也未涉及政策生效的时间或出台是否及时。","evidence":"对新情况多凭主观判断下结论","doubt":"","references":[]}]},"k-74fdaa43dd5ef243":{"review":{"definition":"完美指完备而无缺陷，合理指合乎道理，直观指可以直接感知或容易直接理解，简便指简单方便。","explanation":"量子理论和广义相对论在各自领域都运作得很好，后文用“因此”引出寻找能统一两者的理论。第二空着眼于两种理论能否协调统一，“完美”和“合理”在这一空都能呼应语意。“直观”侧重是否易于直接理解，“简便”侧重结合方式是否简单方便，题干未涉及这两个方面。第三空的“目标”进一步确定选A。","references":[],"evidence":"寻找能将这两种理论统一起来的量子引力理论","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8c49839aeb6d39cf":{"review":{"definition":"人云亦云指没有主见，跟着别人说。走马观花现多指粗略地观察一下。","explanation":"第三空紧接“没有思考”，又呼应前文的“被动地接受”。“人云亦云”具体表现了缺少独立判断便附和他人的情形，符合C项。“走马观花”可以形容前面的粗略浏览，侧重观察的深浅。","references":[],"evidence":"只能对应前文中的“浏览”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cdd3ad24d0c1a0ff":{"review":{"definition":"涵盖指包括、覆盖，强调范围。集中指使分散的人、事物或力量聚在一起。兼顾指同时照顾多个方面。","explanation":"第二空的宾语是“众多科学领域”，下文又列举载人航天工程涉及的多种工程技术，并称其为科技成果的“集大成者”。“涵盖”能直接说明该工程包含哪些学科领域。“集中”突出聚集过程，“兼顾”突出同时照顾各方，题干表达的是工程所涉范围，因此选B。","references":[],"evidence":"载人航天系统所包含的科学领域非常多样","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-022103928e4e5bb8":{"review":{"definition":"破解指解开难题、找到解决办法。洞见用作动词时指清楚、深入地看出事物的实质或关键。","explanation":"题干先写从“小切口”入题、深入调研、直面真问题，再以“方能”引出这些做法要达到的结果。第三空填“破解”，表明调研着眼于解决基层“最后一公里”的症结，对应C项。“洞见症结”表达的是看清问题所在。","references":[],"evidence":"“破解”意为解开，解决，与“症结”搭配恰当","disposition":"独立词条","basis":"据原题和解析编释。","title":"破解与洞见","related":[],"examFocus":{"国考 2024 副省级 行测#35":"结合“方能”前后的语意判断第三空侧重发现问题还是处理问题，并检验动词与“症结”的搭配。"}},"readings":[{"origin":"k-022103928e4e5bb8","title":"破解与洞见","qs":["国考 2024 地市级 行测#38"],"definition":"破解指解开难题、找到解决办法。洞见用作动词时指清楚、深入地看出事物的实质或关键。","explanation":"题干先写从“小切口”入题、深入调研、直面真问题，再以“方能”引出这些做法要达到的结果。第三空填“破解”，表明调研着眼于解决基层“最后一公里”的症结，对应C项。“洞见症结”表达的是看清问题所在。","evidence":"“破解”意为解开，解决，与“症结”搭配恰当","doubt":"","references":[]},{"origin":"k-92406c242dbd6f7a","title":"破解与洞见","qs":["国考 2024 副省级 行测#35"],"definition":"破解指解开难题或解决障碍。洞见作动词时指透彻地看清事物或问题。","explanation":"“方能”引出深入调研、克服认知盲区后要达到的结果，即解决基层“最后一公里”的症结。“破解”表达解决，“洞见”表达看清，所以末空选“破解”。","evidence":"“洞\n见”指清楚地看到，不能体现解决问题的意思","doubt":"","references":[]},{"origin":"k-a226668f06fc6d4d","title":"破解与洞见","qs":["国考 2024 行政执法 行测#40"],"definition":"“破解”指解开难题或解决问题。“洞见”在本题中作动词，指透彻地看清事物。","explanation":"题干先写调研要“直面‘真问题’”，再用“方能”引出调研所要达到的结果。末空的宾语是基层“最后一公里”的“症结”，也就是阻碍工作落实的关键问题。C项“破解”指解决这一问题，B项“洞见”只说明看清了这一问题。","evidence":"“洞见”指清楚地看到，不能体现解决问题的意思","doubt":"","references":[]}]},"k-946757ae3c5d7ca3":{"review":{"definition":"贡献者为某项工作提供数据、成果等有益资源，建设者参与建成或发展某项工程或事业。维护者负责维持既有事物的正常运转，推广者着力扩大其知晓度或应用范围。","explanation":"研究人员一面使用数据库，一面上传自己的研究数据，上传这一行为直接体现其数据贡献，也可视为参与数据库建设，所以第一空可保留“贡献者”和“建设者”。题干写的是提供数据，未提到系统维护或宣传推广。第二空的“可靠”适合修饰“纪录载体”，据此选C。","references":[],"evidence":"将自己研究发现的基因序列或蛋白质结构数据存入数据库","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9568529cd9bae658":{"review":{"definition":"“固本强基”指巩固根本、强化基础。“返璞归真”指去除外在修饰，恢复原有的质朴状态。","explanation":"第三空承接前文“守住本和源、根和魂”，需要说明守正对根基的作用，因此用“固本强基”与“恪守正道”并列。“返璞归真”侧重恢复质朴，语义重心在“恢复”。","references":[],"evidence":"守住本和源、根和魂","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0ef566e9908edceb":{"review":{"definition":"期刊扩散因子表示某期刊在统计当年每被引100次所涉及的期刊种数。在当年总被引频次大于零时，用涉及的期刊种数除以总被引频次，再乘以100。","explanation":"总被引频次统计的是该刊自创刊以来发表的论文在统计当年被引用的次数。按2022年的数据计算，甲刊为40，乙刊约为33.33，丙刊为30，由大到小为甲、乙、丙，对应D项。创刊年份用于理解统计范围，无需按创刊年数折算。","references":[],"evidence":"期刊当年每被引100次所涉及的期刊数","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-31f2a5d877f77b62":{"review":{"definition":"文献流通率是文献流通数占馆藏中提供流通的文献数的比率。文献利用率是文献流通数占馆藏文献总数的比率。","explanation":"同一图书馆的两项指标都以实际被借阅、利用的文献数为分子。提供流通的文献数至多等于馆藏文献总数，因此在两率均可计算时，文献流通率至少等于文献利用率，A项正确。D项只给出了流通数与提供流通的文献数的变化，缺少馆藏文献总数的变化，无法判断利用率是否上升。","references":[],"evidence":"文献流通率的分母一定小于或等于文献利用率的分母","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5f7639e3588a1c39":{"review":{"definition":"卫冕指在竞赛中保住上一次获得的冠军称号。","explanation":"“夺冠”可以是首次获得冠军。“卫冕”则以上一次已经夺冠为前提，强调这一次保住冠军称号。C项“续约”也以此前已经签约为前提，强调继续原有的合约关系。","references":[],"evidence":"卫冕指竞赛中保住上次获得的冠军称号","disposition":"独立词条","basis":"据原题和解析编释。","title":"卫冕","related":[],"examFocus":{"国考 2024 副省级 行测#96":"比较“卫冕”和“夺冠”所指的动作，留意其中一个动作是否以先前的结果为前提。"}},"readings":[{"origin":"k-5f7639e3588a1c39","title":"卫冕","qs":["国考 2024 地市级 行测#91"],"definition":"卫冕指在竞赛中保住上一次获得的冠军称号。","explanation":"“夺冠”可以是首次获得冠军。“卫冕”则以上一次已经夺冠为前提，强调这一次保住冠军称号。C项“续约”也以此前已经签约为前提，强调继续原有的合约关系。","evidence":"卫冕指竞赛中保住上次获得的冠军称号","doubt":"","references":[]},{"origin":"k-ca05edbb42c3c4e1","title":"卫冕","qs":["国考 2024 副省级 行测#96"],"definition":"卫冕指在竞赛中保住上一次获得的冠军称号。卫冕成功意味着上届冠军在本届再次夺冠。","explanation":"“夺冠”只说明获得冠军，“卫冕”还要求此前已获得同一赛事的冠军。题干中前词是在已有冠军称号的基础上再次夺冠，与C项在已有合约的基础上再次签约相对应。","evidence":"卫冕指竞赛中保住上次获得的冠军称号","doubt":"","references":[]}]},"k-3d81b1bf44806fa9":{"review":{"title":"丝瓜络","type":"概念与词义","definition":"丝瓜络是成熟丝瓜果实中呈网状的维管束，通常指果实干燥、去除外皮和种子后留下的纤维网络。","explanation":"干燥后保留下来的网状纤维原本就是果实的组成部分。","basis":"据关联原题及所列出处编释。","references":[{"source":"luffa","location":"来源及性状"}],"domain":"科技","examFocus":{"国考 2024 地市级 行测#92":"辨明词语所指事物的来源、构成和形成方式，再比较各组与题干的关系。"}},"aspects":[{"title":"果实的组成部分","uses":[{"unit":"Q1","role":"解题依据","use":"B项的丝瓜络和石榴籽分别是丝瓜和石榴的组成部分，与题干中花生壳和核桃仁各自所属的整体关系一致。","evidence":"“丝瓜络”是干燥成熟丝瓜的网状纤维，“丝瓜络”是丝瓜的组成部分；“石榴籽”是石榴的组成部分","qids":["国考 2024 地市级 行测#92","国考 2024 行政执法 行测#92"]}]}]},"k-1dea2adc2aae8fa5":{"review":{"definition":"这句话说的是，施加惩罚失当，施罚者反而会因此受到祸害。","explanation":"“诛禁不当”点明原因，“反受其央”写出反过来由施罚者承受的后果。C项也从在上位者自身的过失说到由此产生的后果。D项的“小”与“五脏俱全”构成让步关系，规模小并非器官齐全的原因。","references":[],"evidence":"惩罚得不恰当，反而受其祸害","disposition":"独立词条","basis":"据原题和解析编释。","title":"诛禁不当，反受其央","related":[],"examFocus":{"国考 2024 副省级 行测#99":"先读懂每组古语的前后两句，再辨析它们是因果、并列还是让步关系。"}},"readings":[{"origin":"k-1dea2adc2aae8fa5","title":"诛禁不当，反受其央","qs":["国考 2024 地市级 行测#93"],"definition":"这句话说的是，施加惩罚失当，施罚者反而会因此受到祸害。","explanation":"“诛禁不当”点明原因，“反受其央”写出反过来由施罚者承受的后果。C项也从在上位者自身的过失说到由此产生的后果。D项的“小”与“五脏俱全”构成让步关系，规模小并非器官齐全的原因。","evidence":"惩罚得不恰当，反而受其祸害","doubt":"","references":[]},{"origin":"k-4e72d060e676eba7","title":"诛禁不当，反受其央","qs":["国考 2024 行政执法 行测#93"],"definition":"这句话指惩罚失当，施罚者反而因此遭受祸害。","explanation":"前句交代原因，后句说明后果。“反”强调后果落在施罚者自身。C项同样由前句指出管理者自身的问题，再由后句交代这一问题导致的结果。","evidence":"意思是惩罚得不恰当，反而受其祸害","doubt":"","references":[]},{"origin":"k-69a215a52c669e4d","title":"诛禁不当，反受其央","qs":["国考 2024 副省级 行测#99"],"definition":"施行惩罚或禁令失当，施行者反而会受到祸害。","explanation":"第99题前半句交代惩罚失当这一原因，后半句写施行者反遭祸害的结果。C项同样先交代管理者自身的问题，再写发令后难以使人服从的结果。","evidence":"意思是惩罚得不恰当，反而受其祸害","doubt":"","references":[]}]},"k-18ae8b3ad6d45659":{"review":{"definition":"“是非”在“明辨是非”中指对与错，“成败”在“静待成败”中指成功与失败。","explanation":"两个短语的第三、第四字各自组成一对反义字，即“是—非”和“成—败”。比对选项时，两个短语都须在这两个字位上满足同样的关系。C项的“高—低”符合，但“强—食”不构成反义。","references":[],"evidence":"（即“是”和“非”、“成”和“败”）均是反义关系","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-e354464fb567d3c1":{"review":{"definition":"“古今”在“洞鉴古今”中指古代和当今，“始终”在“博观始终”中指事物的开始和结束。","explanation":"B项两个短语的第三、第四字分别是“古—今”和“始—终”，两组都构成反义，分别对应题干相同位置的“是—非”和“成—败”。A项的“云—泥”虽用来比喻差距很大，但这两个字本身并非反义。","references":[],"evidence":"（即“古”和“今”、“始”和“终”）均是反义关系","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-444c3085352ace39":{"review":{"definition":"感想是接触外界事物后产生的想法或感受。体会在这里指从亲身体验中得到的认识或感受。","explanation":"感想侧重接触事物后的思想反应，体会侧重经历之后有所领会。题干取两词都可指个人所得的义项，因此首尾近义，中间的“主观性”是二者的共有属性。","references":[],"evidence":"二者为近义关系；感想和体会均具有主观性","disposition":"独立词条","basis":"据原题和解析编释。","title":"感想与体会","related":[],"examFocus":{"国考 2024 副省级 行测#102":"先判断首尾两词在题中的义项是否近义，再看中间词是否表示两者都必然具有的属性。"}},"readings":[{"origin":"k-444c3085352ace39","title":"感想与体会","qs":["国考 2024 地市级 行测#96"],"definition":"感想是接触外界事物后产生的想法或感受。体会在这里指从亲身体验中得到的认识或感受。","explanation":"感想侧重接触事物后的思想反应，体会侧重经历之后有所领会。题干取两词都可指个人所得的义项，因此首尾近义，中间的“主观性”是二者的共有属性。","evidence":"二者为近义关系；感想和体会均具有主观性","doubt":"","references":[]},{"origin":"k-7e467a4c1676eb5e","title":"感想与体会","qs":["国考 2024 行政执法 行测#97"],"definition":"感想指接触外界事物后产生的想法或感受。体会在本题中指通过体验得到的感受或认识。","explanation":"感想侧重接触事物后的思想反应，体会侧重从体验中有所领会。第97题把两词作为近义词，两者都体现个人的感受或认识，因而都具有题干中间项所说的主观性。","evidence":"感想和体会均具有主观性","doubt":"","references":[]},{"origin":"k-9e88138a97997cfc","title":"感想与体会","qs":["国考 2024 副省级 行测#102"],"definition":"感想指接触外界事物后产生的感受和想法。体会在本题中指从亲身体验中获得的感受或认识。","explanation":"第102题把“感想”和名词义的“体会”作为近义词处理。前者侧重接触事物后的思想反应，后者侧重体验后的领会。两者都带有个人体验和认识的色彩，因此题干将“主观性”列为共同属性。","evidence":"感想和体会均具有主观性","doubt":"","references":[]}]},"k-9a4095a11c0fec1b":{"review":{"definition":"典范指可以作为学习和仿效标准的人或事物。表率指能给他人作榜样的人。","explanation":"“典范”可用于人或事物，“表率”常用于人。两词在指可供仿效的人时近义，并且都有示范性，所以A项同时满足题干的首尾近义和共有属性两个条件。C项的“泥土”是“材料”的一种，而且材料未必具有可塑性。","references":[],"evidence":"典范是指可以作为学习、仿效标准的人或事物，表率是指好的榜样","disposition":"独立词条","basis":"据原题和解析编释。","title":"典范与表率","related":[],"examFocus":{"国考 2024 副省级 行测#102":"先判断首尾两个词的语义关系，再检验中间词所指的属性是否为二者共有。"}},"readings":[{"origin":"k-9a4095a11c0fec1b","title":"典范与表率","qs":["国考 2024 地市级 行测#96"],"definition":"典范指可以作为学习和仿效标准的人或事物。表率指能给他人作榜样的人。","explanation":"“典范”可用于人或事物，“表率”常用于人。两词在指可供仿效的人时近义，并且都有示范性，所以A项同时满足题干的首尾近义和共有属性两个条件。C项的“泥土”是“材料”的一种，而且材料未必具有可塑性。","evidence":"典范是指可以作为学习、仿效标准的人或事物，表率是指好的榜样","doubt":"","references":[]},{"origin":"k-bc6ad3892815537a","title":"典范与表率","qs":["国考 2024 副省级 行测#102"],"definition":"典范指可作为学习、仿效标准的人或事物。表率指值得效法的好榜样。","explanation":"第102题A项中，“典范”和“表率”在可供效法这一点上词义相近，并都具有示范性。它与题干同样由两端的近义词和中间的共同属性组成。","evidence":"典范是指可以作为学习、仿效标准的人或事物，表率是指好的榜样","doubt":"","references":[]},{"origin":"k-fa5be1d65335b7ba","title":"典范与表率","qs":["国考 2024 行政执法 行测#97"],"definition":"典范指可作为学习、仿效标准的人或事物。表率指可供效法的好榜样。","explanation":"典范侧重可作为标准的范例，表率侧重榜样作用。第97题A项两端的词义相近，而且都具有中间项所说的示范性，与题干中感想和体会都具有主观性的结构一致。","evidence":"表率是指好的榜样，二者为近义关系","doubt":"","references":[]}]},"k-c98628c84fd05ad2":{"review":{"definition":"核裂变是重原子核分裂成较轻原子核的过程。按是否由外部作用引发，可分为自发裂变和诱发裂变。","explanation":"自发裂变在没有外部激发的情况下发生，诱发裂变由外部作用引发。按照这一标准，题干首尾两类互斥，合起来覆盖中间的“核裂变”。B项的铁路交通和公路交通虽同属现代交通，但现代交通还包括其他类型。","references":[],"evidence":"“核裂变”分为“自发裂变”和“诱发裂\n变”两种。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-432d033f3148f118":{"review":{"definition":"负实数是小于零的实数。能写成两个整数之比且分母非零的负实数是负有理数，其余负实数是负无理数。","explanation":"每个负实数恰好属于这两类中的一类。D项把上位概念“负实数”放在中间，首尾两类互斥且覆盖全部负实数，与题干的分类关系和词序一致。","references":[],"evidence":"“负实数”分为“负有理数”和“负无理数”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-99ea11c2e2772def":{"review":{"definition":"“领头雁”比喻在群体中有号召力、能带领他人并起带头作用的人。","explanation":"A项的“领导者”直接说出了“领头雁”比喻所指的角色，与另一组“拓荒牛”比喻“先驱”的方向一致。D项的“出头鸟”也是比喻说法，可侧重表现突出或惹人注目，与“领头雁”无法构成同样的比喻对应。","references":[],"evidence":"领头雁比喻在众人眼里有一定的号召力和领导能力，具有榜样力量的人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8a9fa8964f01bf0f":{"review":{"definition":"“拓荒牛”比喻率先开拓新领域、开创新局面的人。","explanation":"“先驱”指走在前面开路的人。A项由形象说法“拓荒牛”指向它所比喻的角色“先驱”，与“领头雁”指向“领导者”一致。D项的“先行者”和“先驱”都是对人的直接称谓，二者在题中是近义关系。","references":[],"evidence":"比喻开拓创新的先行者，先驱指前行开路的人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-24ec4b161ca4722e":{"review":{"definition":"载弹量是衡量战机能够携带多少弹药的性能指标。","explanation":"D项中，重型战机对应其性能指标载弹量，显示器对应其性能指标分辨率，两组都是“设备→性能指标”。B项中，重型战机属于战斗机，分辨率属于性能指标，代入后两组种属关系的方向相反。","references":[],"evidence":"载弹量是重型战机的一个性能指标","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8612fa1c06fd3a9d":{"review":{"title":"显示器分辨率","type":"概念与词义","definition":"显示器分辨率是显示画面在水平方向和垂直方向上各包含多少像素的规格，通常写作横向像素数乘纵向像素数。","explanation":"同为1920×1080的屏幕，尺寸越大，像素密度越低。刷新率则表示画面每秒更新的次数。","basis":"据关联原题和解析编释。","references":[],"domain":"科技","examFocus":{"国考 2024 地市级 行测#100":"比较两组词的词义关系和方向，分清设备类别、性能指标和业务数据在词对中各起什么作用。"}},"aspects":[{"title":"设备与性能指标的对应","uses":[{"unit":"Q1","role":"解题依据","use":"D项填入后，右侧的“显示器—分辨率”与左侧的“重型战机—载弹量”均按“设备—性能指标”的顺序排列。","evidence":"分辨率是显示器的一个性能指标","qids":["国考 2024 地市级 行测#100","国考 2024 行政执法 行测#100"]}]}]},"k-9627ee2b2d8dde59":{"review":{"definition":"两个数的差值的绝对值等于较大数减去较小数，表示两数在数轴上的距离。交换相减顺序，结果相同。","explanation":"题目比较2013—2022年各地城镇与农村居民人均可支配收入年均增速的差距。三地农村增速均较高，用农村增速减去城镇增速，北京为8.2%−7.3%=0.9个百分点，天津为7.3%−6.9%=0.4个百分点，河北为8.6%−7.1%=1.5个百分点。从大到小为冀、京、津，对应B项。","references":[],"evidence":"城乡差值的绝对值从大到小排列","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-af3f082622183350":{"review":{"definition":"1万亿元等于10000亿元。将以亿元为单位的数值换算成以万亿元为单位的数值时，除以10000。","explanation":"图1以亿元列出各年收入，选项以万亿元划分范围。将2017—2022年移动数据流量业务收入相加，得到36590亿元，折合3.659万亿元，超过3.6万亿元，因此选B。解析中的3.66万亿元是保留两位小数的结果。","references":[],"evidence":"亿元=3.66万亿元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b7e2ea515f503791":{"review":{"definition":"非物质文化遗产是各族人民世代相传并视为其文化遗产组成部分的各种传统文化表现形式，以及与这些表现形式相关的实物和场所。","explanation":"“世代相传”直接说明了材料所举的误认问题。地方把刚创造出来的“现产”当成祖先留下的遗产，混淆了新创内容与世代传承的传统文化表现形式，报告据此概括为部分地方混淆非遗概念。相关实物和场所纳入定义的依据是它们与传统文化表现形式的联系。","references":[],"evidence":"各族人民世代相传并视为其文化遗产组成部分的各种","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-143c6f04f3dcbfc0":{"review":{"definition":"中国革命的三大法宝是统一战线、武装斗争和党的建设。毛泽东在1939年的《〈共产党人〉发刊词》中将三者概括为中国共产党在中国革命中战胜敌人的三个主要法宝。","explanation":"第8题题干强调党中央把调查研究作为主题教育的重要内容，A项却把调查研究列入「三大法宝」，超出了毛泽东所概括的固定范围。本题要求选出不准确的说法，因此选A。","references":[],"evidence":"是中国共产党在中国革命中战胜敌人的三个法宝","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5de9c14f77f8b61b":{"review":{"definition":"顾到了这一方面，却顾不到另一方面，形容难以兼顾。","explanation":"第21题要求共享公交专用车道时，在维持公交通行效率的前提下便利社会车辆通行。“而并非”后需要表达只顾及一方而失掉另一方，所以选C项。“厚此薄彼”强调对两方待遇有别，“此消彼长”强调一方减弱、另一方增强。","references":[],"evidence":"“顾此失彼”指顾了这个，顾不了那个","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-63ec9480b88b4962":{"review":{"definition":"“安全阀”可比喻防范风险、保障安全的措施或机制。","explanation":"第22题写环境影响评价会分析和预测影响，还会提出预防或减轻不良影响的措施，并进行跟踪监测。“安全阀”能概括这种风险防控作用，也与后文的“第一道防线”呼应，因此选B项。“预警机”侧重提前提醒，“缓冲器”侧重减轻冲击。","references":[],"evidence":"“安全阀”比喻保障安全的措施","disposition":"独立词条","basis":"据原题和解析编释。","title":"安全阀（比喻义）","related":[],"examFocus":{"国考 2024 地市级 行测#21":"结合环评的措施和后文的“第一道防线”，辨析不同喻体在风险防控中各侧重哪个环节。"}},"readings":[{"origin":"k-63ec9480b88b4962","title":"安全阀（比喻义）","qs":["国考 2024 行政执法 行测#22"],"definition":"“安全阀”可比喻防范风险、保障安全的措施或机制。","explanation":"第22题写环境影响评价会分析和预测影响，还会提出预防或减轻不良影响的措施，并进行跟踪监测。“安全阀”能概括这种风险防控作用，也与后文的“第一道防线”呼应，因此选B项。“预警机”侧重提前提醒，“缓冲器”侧重减轻冲击。","evidence":"“安全阀”比喻保障安全的措施","doubt":"","references":[]},{"origin":"k-861687b9c39544b1","title":"安全阀（比喻义）","qs":["国考 2024 地市级 行测#21"],"definition":"“安全阀”比喻用于控制风险、保障安全的措施或机制。","explanation":"文中的环评既预测环境影响，又提出预防或减轻不良影响的措施，与后文“第一道防线”的保护作用呼应。“预警机”侧重提醒，“试金石”侧重检验，“缓冲器”侧重缓和冲击，因此B项“安全阀”最能概括这里的风险防护作用。","evidence":"提出预防或减轻不良环境影响的对策和措施","doubt":"","references":[]}]},"k-3ea2330915cd517f":{"review":{"definition":"指确立相关人员应当遵循的行为规范。","explanation":"第24题第二空与“明方向、正风气、强免疫”并列，列举全面从严治党中的治理举措。“立规矩”侧重确立行为规范，符合这一组举措的语义。“守底线”侧重行为主体遵守最低要求，因此第二空支持D项。","references":[],"evidence":"“立规矩”意为确立规矩","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a7bf7acceeec302a":{"review":{"definition":"在纠纷解决语境中，司法的终局性指司法能够对依法进入审理的纠纷作出具有最终效力的裁判。","explanation":"第25题以“最后一道防线”强调司法在纠纷解决中的最终裁断作用，因此第一空选“终局性”。这一用法描述的是司法在纠纷解决中的地位，具体裁判何时生效、能否依法救济取决于相应程序。“强制性”侧重约束力，与题干强调的最终裁断作用有别。","references":[],"evidence":"公正司法是维护社会公平正义的最后一道防线","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4df15248a6eff2ad":{"review":{"definition":"看见危险或觉得困难超出自身能力，便退缩而不敢尝试。","explanation":"第26题用“绝大部分战舰只能”与“唯有破冰船和冰面下的潜艇敢于一试身手”形成对照。“望而却步”贴合多数战舰面对巨大海冰时的退缩。“裹足不前”也能写有所顾忌而不前进，最终由第二空“轻而易举”与“破开”的搭配确定A项。","references":[],"evidence":"唯有破冰船和冰面下的潜艇敢于一试身手","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-775489fb35b98698":{"review":{"definition":"形容事情很容易完成，几乎不费力。","explanation":"第26题第二空修饰“破开”，文段借最强破冰船能破开近3米厚坚冰来表现它的破冰能力。“轻而易举”直接描述完成这个动作的难易，支持A项。“长驱直入”描写迅速顺畅地深入，侧重行进态势。","references":[],"evidence":"“轻而易举”形容事情容易做，不费力，省事","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7668ea748deb47da":{"review":{"definition":"比喻显露自己的才能或表现自己，也可借指事物的成效显现出来。","explanation":"第29题借“并不显山露水”形容基础工作要稳步推进，短期内往往看不出明显成效，呼应开头的“潜”与“显”。“声势浩大”“惊天动地”“轰轰烈烈”都侧重声势或气魄，与文段强调的成效能否显现有别。","references":[],"evidence":"“潜”是“显”的基础，“显”是“潜”的结果。","disposition":"独立词条","basis":"据原题和解析编释。","title":"显山露水","related":[],"examFocus":{"国考 2024 副省级 行测#28":"结合开头“潜”与“显”的关系和后文“但”字引出的转折，判断两空分别从什么角度描述工作和政绩。"}},"readings":[{"origin":"k-7668ea748deb47da","title":"显山露水","qs":["国考 2024 行政执法 行测#29"],"definition":"比喻显露自己的才能或表现自己，也可借指事物的成效显现出来。","explanation":"第29题借“并不显山露水”形容基础工作要稳步推进，短期内往往看不出明显成效，呼应开头的“潜”与“显”。“声势浩大”“惊天动地”“轰轰烈烈”都侧重声势或气魄，与文段强调的成效能否显现有别。","evidence":"“潜”是“显”的基础，“显”是“潜”的结果。","doubt":"","references":[]},{"origin":"k-7ae0e627093bfe4e","title":"显山露水","qs":["国考 2024 地市级 行测#28"],"definition":"比喻显露才能、表现自己，也可引申为使某些情况或成果显露出来。","explanation":"本题把“显山露水”用于形容工作。“并不显山露水”表示事关长远的基础工作在推进时往往不显眼，呼应开头“潜”与“显”的关系。“声势浩大”“惊天动地”“轰轰烈烈”主要强调声势或气魄的大小。","evidence":"“潜”是“显”的基础，“显”是“潜”的结果","doubt":"","references":[]},{"origin":"k-bb854580f7bde5d1","title":"显山露水","qs":["国考 2024 副省级 行测#28"],"definition":"显山露水比喻显露才能、表现自己。文中用它形容工作的表现容易被人察觉。","explanation":"第一空由“并不”引出基础工作不容易显现的特点，呼应开头的“潜”与“显”。“声势浩大”“惊天动地”“轰轰烈烈”主要强调声势或影响之大，“显山露水”更贴合题中是否显现的区别。","evidence":"“潜”是“显”的基础，“显”是“潜”的结果。","doubt":"","references":[]}]},"k-2ecdd6fa351de906":{"review":{"definition":"一眼就能看得清楚明白，强调容易看清或弄懂。","explanation":"第29题用“政绩也并非一目了然”说明，事关长远的基础工作要稳步推进，成效往往难以立刻看清。“家喻户晓”强调知晓范围广，“引人注目”强调吸引注意。","references":[],"evidence":"“一目了然”指一眼就看得很清楚","disposition":"独立词条","basis":"据原题和解析编释。","title":"一目了然","related":[],"examFocus":{"国考 2024 副省级 行测#28":"结合文段对“潜”与“显”的讨论，分别判断两空如何描述基础工作和政绩，并区分成语在声势、受关注程度和可见程度上的侧重。"}},"readings":[{"origin":"k-2ecdd6fa351de906","title":"一目了然","qs":["国考 2024 行政执法 行测#29"],"definition":"一眼就能看得清楚明白，强调容易看清或弄懂。","explanation":"第29题用“政绩也并非一目了然”说明，事关长远的基础工作要稳步推进，成效往往难以立刻看清。“家喻户晓”强调知晓范围广，“引人注目”强调吸引注意。","evidence":"“一目了然”指一眼就看得很清楚","doubt":"","references":[]},{"origin":"k-e65baa3fbd4a7cdc","title":"一目了然","qs":["国考 2024 地市级 行测#28"],"definition":"指一眼就能看得清楚明白。","explanation":"“政绩也并非一目了然”表示稳步推进的长期基础工作，其成效难以当即看清。后文“但有助于各项事业全面发展、长足进步”指出这些工作的长远作用。“有目共睹”侧重大家都能看到，“一目了然”侧重一眼即能看清。","evidence":"“一目了然”指一眼就看得很清楚","doubt":"","references":[]},{"origin":"k-f363c20d1966ad61","title":"一目了然","qs":["国考 2024 副省级 行测#28"],"definition":"一目了然指一眼就能看得清楚明白。","explanation":"第二空的“并非一目了然”表示基础工作带来的政绩难以立刻看清，与后文所说的长远成效相呼应。“有目共睹”侧重大家都能看到，“一目了然”侧重看一眼就能明白。","evidence":"“一目了然”指一眼就看得很清楚","doubt":"","references":[]}]},"k-2c87981400612684":{"review":{"definition":"指离开原定的轨道、方向，也指与作为参照的事实或标准出现偏差。","explanation":"第30题的“偏离历史真实”说明史书记载与历史事实有出入，既涵盖记忆有误造成的无意偏差，也涵盖有意取舍造成的偏差。“掩盖”侧重遮蔽或隐瞒，“虚构”侧重凭空捏造，都难以概括单纯的记忆错误。","references":[],"evidence":"随意取舍、记忆有误或者心存故意","disposition":"独立词条","basis":"据原题和解析编释。","title":"偏离","related":[],"examFocus":{"国考 2024 地市级 行测#25":"第一空看动词与“历史真实”的搭配及其能否涵盖文中列举的不同原因，第二空比较动词对造假可能性变化程度的表达。"}},"readings":[{"origin":"k-2c87981400612684","title":"偏离","qs":["国考 2024 行政执法 行测#30"],"definition":"指离开原定的轨道、方向，也指与作为参照的事实或标准出现偏差。","explanation":"第30题的“偏离历史真实”说明史书记载与历史事实有出入，既涵盖记忆有误造成的无意偏差，也涵盖有意取舍造成的偏差。“掩盖”侧重遮蔽或隐瞒，“虚构”侧重凭空捏造，都难以概括单纯的记忆错误。","evidence":"随意取舍、记忆有误或者心存故意","doubt":"","references":[]},{"origin":"k-d97c516639e124b2","title":"偏离","qs":["国考 2024 地市级 行测#25"],"definition":"指离开原有的轨道、方向，也可指与预定目标、标准或事实出现偏差。","explanation":"“偏离历史真实”表示记载与史实有出入，既可涵盖“心存故意”导致的失实，也可涵盖“记忆有误”造成的偏差。“虚构”强调凭空编造，用来统摄记错的情形不合适。本题还须凭第二空“降低……的可能”确定整组选项。","evidence":"随意取舍、记忆有误或者心存故意","doubt":"","references":[]}]},"k-2fc3c9766303660d":{"review":{"definition":"表示使某事发生的可能性减小，程度上仍容许该事发生。","explanation":"第30题说重复操作可以检验此前的研究成果，因此用“降低了人为造假的可能”表述可重复检验对造假的约束作用。“杜绝”指彻底防止发生，程度超出了题干给出的条件。","references":[],"evidence":"可以用重复操作检验此前的研究成果是否准确、正确","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1144f2ef7c370bad":{"review":{"definition":"把有差别的事物同等看待。","explanation":"第31题中，“等量齐观”与“平均用力”并列，批评把情况不同的农村按同一套办法对待。题干列举了把单一发展方式套用到所有农村、简单分解资源两种表现。","references":[],"evidence":"将单一发展方式套用到所有农村，或将资源进行简单分解","disposition":"独立词条","basis":"据原题和解析编释。","title":"等量齐观","related":[],"examFocus":{"国考 2024 副省级 行测#27":"辨析第一空与“平均用力”的并列关系，结合文中列举的两种做法判断成语是否贴合语境。"}},"readings":[{"origin":"k-1144f2ef7c370bad","title":"等量齐观","qs":["国考 2024 行政执法 行测#31"],"definition":"把有差别的事物同等看待。","explanation":"第31题中，“等量齐观”与“平均用力”并列，批评把情况不同的农村按同一套办法对待。题干列举了把单一发展方式套用到所有农村、简单分解资源两种表现。","evidence":"将单一发展方式套用到所有农村，或将资源进行简单分解","doubt":"","references":[]},{"origin":"k-8d6e339c7c4a1e71","title":"等量齐观","qs":["国考 2024 副省级 行测#27"],"definition":"把有差别的事物放在同等地位看待。","explanation":"第一空与“平均用力”并列。题干给出的具体表现是把同一发展方式套用到所有农村，或简单分配资源，“等量齐观”点出了这种做法忽略各村差异的思路。结合第二空“因地制宜”，全题选B。","evidence":"将单一发展方式套用到所有农村，或将资源进行简单分解","doubt":"","references":[]},{"origin":"k-d7359044f99b8472","title":"等量齐观","qs":["国考 2024 地市级 行测#24"],"definition":"指把有差别的事物同等看待。","explanation":"第一空和“平均用力”并列。把同一种发展方式套用到所有农村，体现了忽略各地差异而作同样处理。“一视同仁”侧重对待各方一律平等，题中批评的则是忽略条件差异。整组答案由第二空的“因地制宜”锁定。","evidence":"将单一发展方式套用到所有农村，或将资源进行简单分解","doubt":"","references":[]}]},"k-ae7440f293a38755":{"review":{"definition":"形容只有一个，没有相同的，强调唯一性。","explanation":"第33题用“独一无二”修饰进口商品的“身份证”，强调每件商品都有区别于其他商品的身份标识。“与众不同”只表示有别于一般对象，对唯一性的表达较弱。","references":[],"evidence":"“独一无二”指没有相同的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9b7ba3dd0364a13d":{"review":{"definition":"指用作伪的手段改动原有内容，或歪曲其原意。","explanation":"第33题用“不可篡改”说明题述溯源场景中，消费者查到的生产、物流信息受到防止作伪性改动的保护，从而为海淘多提供一分保障。“变更”泛指改变，“撤销”指取消，都缺少这里强调的作伪含义。","references":[],"evidence":"“篡改”指用作伪的手段改动或曲解","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8df6e20a6c3a04c6":{"review":{"definition":"以偏概全指拿局部或片面的情况推断整体，把部分情况当作全貌。","explanation":"题干以“盲人摸象”形容调研者只看到一个个孤立的“盆景”，却据此对整体下结论。“以偏概全”点明了从局部推断整体的过程，“一孔之见”侧重见解本身狭隘片面。两者都能呼应第一空的片面性，整题再由第二空的“针对性”确定选A。","references":[],"evidence":"眼中只有一个个孤立的“盆景”","disposition":"独立词条","basis":"据原题和解析编释。","title":"以偏概全","related":[],"examFocus":{"国考 2024 副省级 行测#26":"从“盲人摸象”和“刻舟求剑”入手，分别判断两种调研方式会给结论和政策带来什么问题。"}},"readings":[{"origin":"k-8df6e20a6c3a04c6","title":"以偏概全","qs":["国考 2024 行政执法 行测#34"],"definition":"以偏概全指拿局部或片面的情况推断整体，把部分情况当作全貌。","explanation":"题干以“盲人摸象”形容调研者只看到一个个孤立的“盆景”，却据此对整体下结论。“以偏概全”点明了从局部推断整体的过程，“一孔之见”侧重见解本身狭隘片面。两者都能呼应第一空的片面性，整题再由第二空的“针对性”确定选A。","evidence":"眼中只有一个个孤立的“盆景”","doubt":"","references":[]},{"origin":"k-c60263ba39e55e57","title":"以偏概全","qs":["国考 2024 副省级 行测#26"],"definition":"把局部的、片面的情况当成整体情况，或仅凭片面材料对整体下结论。","explanation":"题干用“盲人摸象”和孤立的“盆景”表现调研材料只覆盖局部，“以偏概全”点明了从局部推论整体的错误。“一孔之见”也可形容见解片面，侧重见解本身的局限。全题还需结合第二空“针对性”确定选A。","evidence":"眼中只有一个个孤立的“盆景”","doubt":"","references":[]}]},"k-2183c0ceb53ea564":{"review":{"definition":"政策措施的针对性指措施与特定对象、实际问题及其具体情况的契合程度。","explanation":"题干说调研者面对新情况仍凭主观判断下结论，政策因此难以切中实际问题，第二空用“针对性不强”。“时效性”侧重措施在一定时间内是否适用，题干强调的是政策与眼下实际问题的匹配程度。","references":[],"evidence":"对新情况多凭主观判断下结论","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7168fedc5fffe415":{"review":{"definition":"墨守成规指固守已有的规矩或办法，不肯改变。","explanation":"第一空与“循规蹈矩”并列，用“墨守成规”突出拘泥于既有规矩。后文用“守住本和源、根和魂”阐明本段所说的守正，说明守住根本仍有变通的空间。","references":[],"evidence":"“墨守成规”指思想保守，守着老规矩不肯改变","disposition":"独立词条","basis":"据原题和解析编释。","title":"墨守成规","related":[],"examFocus":{"国考 2024 地市级 行测#40":"辨析第一空时，既要看它与“循规蹈矩”的并列关系，也要看它与后文对“守正”的正面阐释如何对照。"}},"readings":[{"origin":"k-7168fedc5fffe415","title":"墨守成规","qs":["国考 2024 行政执法 行测#35"],"definition":"墨守成规指固守已有的规矩或办法，不肯改变。","explanation":"第一空与“循规蹈矩”并列，用“墨守成规”突出拘泥于既有规矩。后文用“守住本和源、根和魂”阐明本段所说的守正，说明守住根本仍有变通的空间。","evidence":"“墨守成规”指思想保守，守着老规矩不肯改变","doubt":"","references":[]},{"origin":"k-a9b7e01eb72fa033","title":"墨守成规","qs":["国考 2024 地市级 行测#40"],"definition":"形容思想保守，固守旧规矩，不肯变通。","explanation":"第一空与“循规蹈矩”并列。在“守正不是……”的句式中，“墨守成规”突出拘泥旧规的一面，与后文“守住本和源、根和魂”形成对照。","evidence":"“墨守成规”指思想保守，守着老规矩不肯改变","doubt":"","references":[]}]},"k-1fbf93030e4d6471":{"review":{"definition":"恣意妄为指随心所欲地胡乱行事，含贬义。","explanation":"第二空与“凭空幻想”并列，分别写想法脱离实际和行动任意而为。后文要求“在把握事物发展规律的基础上”发挥主观能动性，“恣意妄为”正好写出行动缺少这种约束。各空合看，第三空的“固本强基”进一步确定选D。","references":[],"evidence":"“恣意妄为”意思是随心所欲，胡作非为","disposition":"独立词条","basis":"据原题和解析编释。","title":"恣意妄为","related":[],"examFocus":{"国考 2024 地市级 行测#40":"辨析第二空成语与“凭空幻想”的并列关系，并结合后文对创新的正面阐释判断词义是否贴合。"}},"readings":[{"origin":"k-1fbf93030e4d6471","title":"恣意妄为","qs":["国考 2024 行政执法 行测#35"],"definition":"恣意妄为指随心所欲地胡乱行事，含贬义。","explanation":"第二空与“凭空幻想”并列，分别写想法脱离实际和行动任意而为。后文要求“在把握事物发展规律的基础上”发挥主观能动性，“恣意妄为”正好写出行动缺少这种约束。各空合看，第三空的“固本强基”进一步确定选D。","evidence":"“恣意妄为”意思是随心所欲，胡作非为","doubt":"","references":[]},{"origin":"k-db2c7a36ec14c3b0","title":"恣意妄为","qs":["国考 2024 地市级 行测#40"],"definition":"指随心所欲地胡作非为，含贬义。","explanation":"第二空与“凭空幻想”并列，“恣意妄为”着重写行动上的任意妄为，与后文要求“在把握事物发展规律的基础上”发挥主观能动性相对。“纸上谈兵”侧重空谈理论，“向壁虚造”侧重无据捏造。","evidence":"“恣意妄为”意思是随\n心所欲，胡作非为","doubt":"","references":[]}]},"k-31bd0e47767b4e13":{"review":{"definition":"固本强基指巩固根本、夯实基础。","explanation":"第三空与“恪守正道”并列，说明守正的作用。“固本强基”呼应前文的“本和源、根和魂”，强调巩固根本和基础。“返璞归真”侧重去掉外在修饰、恢复原有的质朴，所表达的结果与此处不同。","references":[],"evidence":"“固本强基”指加固本体、强化基础","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4f0b6efc56ffdd38":{"review":{"definition":"目标指希望达到的结果或努力追求的方向。困惑指遇到问题时疑惑不解的状态，也可指使人疑惑的问题。","explanation":"末空的主语是“寻找能将这两种理论统一起来的量子引力理论”，指物理学家正在努力做的事，其目标是找到能统一量子理论和广义相对论的理论。若要表达困惑，通常会把“如何统一这两种理论”作为令人疑惑的问题。","references":[],"evidence":"寻找能将这两种理论统一起来的量子引力理论","disposition":"独立词条","basis":"据原题和解析编释。","title":"目标与困惑","related":[],"examFocus":{"国考 2024 地市级 行测#35":"辨析末空时，把备选名词放回句中，检查它与主语“寻找能将这两种理论统一起来的量子引力理论”是否搭配。"}},"readings":[{"origin":"k-4f0b6efc56ffdd38","title":"目标与困惑","qs":["国考 2024 行政执法 行测#37"],"definition":"目标指希望达到的结果或努力追求的方向。困惑指遇到问题时疑惑不解的状态，也可指使人疑惑的问题。","explanation":"末空的主语是“寻找能将这两种理论统一起来的量子引力理论”，指物理学家正在努力做的事，其目标是找到能统一量子理论和广义相对论的理论。若要表达困惑，通常会把“如何统一这两种理论”作为令人疑惑的问题。","evidence":"寻找能将这两种理论统一起来的量子引力理论","doubt":"","references":[]},{"origin":"k-dc8594ef81ede47a","title":"目标与困惑","qs":["国考 2024 地市级 行测#35"],"definition":"目标指希望达到的结果或努力的方向。困惑指疑惑不解的状态，也可指令人疑惑的问题。","explanation":"第三空评价的是“寻找能将这两种理论统一起来的量子引力理论”这项研究追求，填“目标”能说明物理学家努力的方向。若用“困惑”，与之自然对应的是“怎样统一两种理论”这一尚待解答的问题。这个区别可用来排除D项。","evidence":"是物理学家努力的方向和目标","doubt":"","references":[]}]},"k-41790fd5def1cd47":{"review":{"definition":"虚与委蛇指对人虚情假意、敷衍应付。口是心非指嘴上说的和心里想的不一致。","explanation":"末空由“而非”引出，与“诚心正意”对举。题干讨论运营商如何落实未成年人保护责任，“虚与委蛇”写出在履责上敷衍应付的态度。“口是心非”着重于言语与内心的落差，题中未给出运营商的具体表态。","references":[],"evidence":"对于落实未成年人保护责任，运营商唯有诚心正意而非","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d80e224218e3347d":{"review":{"definition":"精致形容事物精巧细致。妥帖形容安排、处理或表达恰当合适。","explanation":"第二空同时描述AI绘画成品的构图、配色和细节。“精致”能概括三者共同呈现的精巧细腻，也与下文所说的成品符合人类审美经验相呼应。“妥帖”更适合评价某项安排或处理是否得当。","references":[],"evidence":"这些完成品的构图、配色和细节可能极其","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2214465ee7460a79":{"review":{"definition":"大相径庭形容两者相差很远。水火不容形容两者彼此对立、无法相容。","explanation":"题干先写AI绘画成品在审美上可能与人类经验高度一致，再用“但”转向创作过程，指出其难以体现人类艺术创作中的情感追求。“大相径庭”描述的是材料所说的创作理念差异，“水火不容”会把这种差异说成对立到无法共存。","references":[],"evidence":"并不能体现人类在艺术创作里的情感追求","disposition":"独立词条","basis":"据原题和解析编释。","title":"大相径庭与水火不容","related":[],"examFocus":{"国考 2024 副省级 行测#33":"抓住“但”之后对创作过程的讨论，辨析末空成语所表达的关系及程度。"}},"readings":[{"origin":"k-2214465ee7460a79","title":"大相径庭与水火不容","qs":["国考 2024 行政执法 行测#39"],"definition":"大相径庭形容两者相差很远。水火不容形容两者彼此对立、无法相容。","explanation":"题干先写AI绘画成品在审美上可能与人类经验高度一致，再用“但”转向创作过程，指出其难以体现人类艺术创作中的情感追求。“大相径庭”描述的是材料所说的创作理念差异，“水火不容”会把这种差异说成对立到无法共存。","evidence":"并不能体现人类在艺术创作里的情感追求","doubt":"","references":[]},{"origin":"k-7ba96e9d751119a7","title":"大相径庭与水火不容","qs":["国考 2024 副省级 行测#33"],"definition":"大相径庭形容彼此相差很远。水火不容形容双方彼此对立、无法相容。","explanation":"第三空比较的是创作理念。材料先说AI绘画成品在审美上可能符合人类经验，再转到创作过程，指出算法模仿难以体现人类创作中的情感追求。“大相径庭”足以表达这种理念差异，“水火不容”还要求相互排斥，超出了文段的判断。","evidence":"并不能体现人类在艺术创作里的情感追求","doubt":"","references":[]}]},"k-b46c5789171775d6":{"review":{"definition":"质证是诉讼中围绕证据的真实性、合法性、关联性及其证明力进行质疑、说明和辩驳的活动。","explanation":"解析以对证人证言提出问题为例，将质证与法庭配成“活动—特定场所”。C项的考场也是为监考所对应的考试活动设置的特定场所。A项的窗口只是缴费渠道之一，D项的现场泛指事情发生或活动进行的地方。","references":[],"evidence":"在法庭上对证人证言进一步提出问题","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-31dbc4bc682208b6":{"review":{"definition":"这句话指居于上位的人自身言行不端正，即使发出命令，下属也不会服从。","explanation":"C项的“虽”表示即使发令，“其身不正”仍是命令得不到服从的原因，因果方向与题干一致。D项的“虽小”则与“五脏俱全”构成让步关系，体形小并非器官齐全的原因。","references":[],"evidence":"在上位的管理者本身言行不正，即使发出命令，大家也不会服从遵守","disposition":"独立词条","basis":"据原题和解析编释。","title":"其身不正，虽令不从","related":[],"examFocus":{"国考 2024 副省级 行测#99":"结合古语的句意，辨析前后两句是因果关系还是让步关系。"}},"readings":[{"origin":"k-31dbc4bc682208b6","title":"其身不正，虽令不从","qs":["国考 2024 行政执法 行测#93"],"definition":"这句话指居于上位的人自身言行不端正，即使发出命令，下属也不会服从。","explanation":"C项的“虽”表示即使发令，“其身不正”仍是命令得不到服从的原因，因果方向与题干一致。D项的“虽小”则与“五脏俱全”构成让步关系，体形小并非器官齐全的原因。","evidence":"在上位的管理者本身言行不正，即使发出命令，大家也不会服从遵守","doubt":"","references":[]},{"origin":"k-c1451aecc62f2490","title":"其身不正，虽令不从","qs":["国考 2024 副省级 行测#99"],"definition":"居于上位者自身言行不端正，即使发出命令，也难以使人服从。","explanation":"第99题C项的因果关系贯穿前后两句，管理者自身言行不正，使发出的命令难以得到服从。“虽令不从”内部包含让步，但整组仍与题干一样，先说过失，再说由此产生的后果。","evidence":"即使发出命令，大家也不会服从遵守","doubt":"","references":[]},{"origin":"k-cdfe1d58490df68c","title":"其身不正，虽令不从","qs":["国考 2024 地市级 行测#93"],"definition":"这句话说的是，在上位者自身言行不端正，即使发号施令，也难以让人服从。","explanation":"“其身不正”交代命令得不到服从的原因。“虽”在后半句表示即使下令，也改变不了这个结果。C项因此与题干中惩罚失当导致施罚者反受其害的因果方向一致。","evidence":"在上位的管理者本身言行不正，即使发出命令，大家也不会服从遵守","doubt":"","references":[]}]},"k-a4dbc51031451b07":{"review":{"definition":"嬗变指蜕变、演变，侧重事物发生变化的过程。","explanation":"第99题用“演变”对应“嬗变”的这一义项，使B项左侧形成与右侧“属相—生肖”相应的同义关系。“改变”的含义更宽，“剧变”强调变化急剧，“巨变”强调变化幅度大。","references":[],"evidence":"嬗变指蜕变、演变","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e09a439ca9a6c5d2":{"review":{"definition":"生肖又称属相，是用与十二地支相配的十二种动物来标记出生年份的传统称谓。具体到个人，指其出生年份对应的动物。","explanation":"第99题中，“属相”和“生肖”是同一概念的两个称谓，与B项左侧“嬗变”和“演变”在本题义项上的同义关系相配。“动物”只提供更宽泛的类别，无法与“生肖”互换。","references":[],"evidence":"属相也叫生肖","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f319ef66d4c272ef":{"review":{"definition":"载弹量表示战机可携带的弹药载荷，是描述重型战机性能的一项指标。","explanation":"第100题D项左侧为重型战机到载弹量，右侧为显示器到分辨率，两边都先给出对象，再给出该对象的性能指标。B项左侧从“重型战机”到上位类别“战斗机”，右侧从上位类别“性能指标”到“分辨率”，种属方向相反。","references":[],"evidence":"载弹量是重型战机的一个性能指标","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-93b4f5d407ed91ed":{"review":{"definition":"两个量的比值是前项除以后项所得的商，后项不能为零。","explanation":"第118题按题干顺序，用各省的改善灌溉面积除以本省的新增恢复灌溉面积。2022年，河南为53.2÷11.5≈4.63，山西为25.2÷6.3＝4.00，湖北为70.1÷26.2≈2.68，江西为40.5÷15.0＝2.70。表中其余两个中部省份安徽和湖南的比值也低于4.63，因此河南最大，选C。","references":[],"evidence":"改善灌溉面积与新增恢复灌溉面积比值最大的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-03aa482b6a61fec7":{"review":{"definition":"增长贡献率是某一部分对总体增量的贡献所占的比重。总体增量不为零时，用该部分贡献的增量除以总体增量，通常以百分比表示。","explanation":"第119题按新增粮食生产能力得到充分利用的假设，将中部六省中型灌区的新增粮食生产能力合计作为分子。六省合计36921.7万公斤，折合36.9217万吨。以全国粮食同比增产量368万吨为分母，算得约10.03%，对应B项“超过9%”。","references":[],"evidence":"如全国中型灌区新增粮食生产能力均得到充分利用","disposition":"独立词条","basis":"据原题和解析编释。","title":"增长贡献率","related":[],"examFocus":{"国考 2024 副省级 行测#119":"用增长贡献率比较中部六省中型灌区的新增粮食生产能力合计与全国粮食同比增产量，注意统一质量单位。","国考 2024 行政执法 行测#119":"在新增产能充分利用的假设下，统一单位后比较中部六省中型灌区新增粮食生产能力合计与全国粮食同比增产量。","江苏 2025 B类 行测#122":"根据现期量和同比增速求增长量，再比较东北片区与全市同期接待过夜游客人次的增量。","江苏 2025 C类 行测#117":"计算增长贡献率时，比较东北片区与全市接待过夜游客人次的同比增量。"}},"readings":[{"origin":"k-03aa482b6a61fec7","title":"增长贡献率","qs":["国考 2024 行政执法 行测#119"],"definition":"增长贡献率是某一部分对总体增量的贡献所占的比重。总体增量不为零时，用该部分贡献的增量除以总体增量，通常以百分比表示。","explanation":"第119题按新增粮食生产能力得到充分利用的假设，将中部六省中型灌区的新增粮食生产能力合计作为分子。六省合计36921.7万公斤，折合36.9217万吨。以全国粮食同比增产量368万吨为分母，算得约10.03%，对应B项“超过9%”。","evidence":"如全国中型灌区新增粮食生产能力均得到充分利用","doubt":"","references":[]},{"origin":"k-121a4ddb2e873bf3","title":"增长贡献率","qs":["江苏 2025 B类 行测#122"],"definition":"增长贡献率表示某一部分的增长量占整体增长量的百分比。整体增长量非零时，用同一比较期内的部分增长量除以整体增长量，再乘以100%。","explanation":"第122题以东北片区2023年比上年增加的过夜游客人次为分子，以全市同期增加的过夜游客人次为分母。按“增长量＝现期量×增长率÷（1＋增长率）”，用东北片区的1125万人次和38.2%求得增量为1125×0.382÷1.382，用全市的10190万人次和88.1%求得增量为10190×0.881÷1.881。两项增量相除约为6.52%，对应选项A。","evidence":"对全市接待过夜游客增长的贡献率","doubt":"","references":[]},{"origin":"k-5670e891c3562e27","title":"增长贡献率","qs":["江苏 2025 C类 行测#117"],"definition":"增长贡献率表示某一部分的增长量占同期整体增长量的百分比。整体增长量非零时，增长贡献率＝部分增长量÷整体增长量×100%。","explanation":"本题的分子是东北片区过夜游客人次的同比增长量，分母是全市过夜游客人次的同比增长量。用“现期量×同比增长率÷（1＋同比增长率）”分别求得两者为1125×0.382÷1.382和10190×0.881÷1.881，单位均为万人次。两者相除后化为百分数，约为6.5%，对应A项。","evidence":"增长对全市接待过夜游客增长的贡献率","doubt":"","references":[]},{"origin":"k-a9cdb3a2b85d2d02","title":"增长贡献率","qs":["国考 2024 副省级 行测#119"],"definition":"增长贡献率表示某一组成部分的增量占同期总体增量的比重。总体增量为正时，用部分增量除以总体增量，并以百分比表示。","explanation":"在题设新增粮食生产能力均得到充分利用的条件下，将中部六省中型灌区的新增粮食生产能力计作对全国粮食增产的贡献。六省合计为36921.7万公斤，折合36.9217万吨。以全国粮食产量同比增加的368万吨为分母，算得贡献占比约为10.03%，超过9%，对应B项。","evidence":"中部六省中型灌区新增粮食生产能力对全国粮食增产的贡献占比","doubt":"","references":[]}]},"k-127c6eb2fdb5ce50":{"review":{"definition":"同一时期、同一统计口径下，进口额超过出口额时形成贸易逆差。逆差额等于进口额减去出口额。","explanation":"本题2023年一季度机器人设备进口额为6.9亿美元，出口额为1.9亿美元，逆差为5亿美元。将两项金额分别除以1＋55.1%和1＋62.1%，还原上年同期的进口额和出口额，再相减得到上年同期逆差约3.28亿美元。以这笔逆差为基数计算，逆差同比上升约52.6%，对应D项。","references":[],"evidence":"贸易逆差=进口额-出口额","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a8d26f78ce5c8c54":{"review":{"definition":"月均产量是某一统计期内平均每月的产量，等于该统计期的累计产量除以所含月数。","explanation":"第128题比较2022年12月产量与同年1～11月的月均产量。先用全年累计产量减去12月产量，再除以11。工业机器人的月均产量为（44.3－4）÷11≈3.66万套，低于12月的4万套。服务机器人的月均产量为（645.8－49.1）÷11≈54.25万套，高于12月的49.1万套。因此仅工业机器人12月产量高于前11个月的月均水平，选C。","references":[],"evidence":"1~11月的月均水平","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5d5ddc6eab42ab83":{"review":{"title":"进出口总额","type":"概念与词义","definition":"在同一范围、同一期间和同一计价单位下，进口额与出口额之和。","explanation":"进出口总额描述贸易规模。出口额减进口额得到贸易差额，衡量的是另一件事。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"进出口合计"}},"k-ce6e5741dbc3711e":{"review":{"definition":"数字孪生黄河是以实体黄河为原型构建的计算机仿真系统。它利用原型黄河的动态数据，实现同步仿真运行、虚实交互和迭代优化。","explanation":"监测感知网络获取原型黄河的动态数据，防汛会商预演系统据此推演洪水演进和滩区灾情，工作人员再用推演结果研判调度方案、指导现场防范或处置。这说明了题中第二条“黄河”如何为实体黄河治理提供预报、预警、预演、预案支持。","references":[],"evidence":"实现与原型黄河的同步仿真运行、虚实交互、迭代优化。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e56d4f9b5d46ab99":{"review":{"definition":"模型黄河是以实体黄河为原型，在实验室通过实体模型再现河流、流域或水利工程的相关过程并开展试验的科研体系。","explanation":"材料中的洪水预演实体模型试验为防汛指挥和防洪部署提供技术支撑，小浪底水库淤积形态试验为水库优化运行寻找方案。作答时可用这些例子说明第三条“黄河”的实验室用途，并与数字孪生黄河的计算机仿真区分开。","references":[],"evidence":"利用“模型黄河”开展洪水预演实体模型试验","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-612b12d50dd774cd":{"review":{"definition":"劳动密集型产业是指生产经营中对劳动力投入依赖程度较高的产业。","explanation":"材料4中，标注员需要逐件处理文本、图片、语音和视频等数据，许多AI公司出于成本考虑将业务外包。这解释了青溪县发展数据标注产业为何能吸纳当地劳动力。面对技术要求更高的标注业务，现有队伍还需要补足专业技能，对应本题的培训和引才建议。","references":[],"evidence":"数据标注是劳动密集型产业","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"c6d2b60d41683a60","label":"劳动密集型行业企业","topic":"就业、社保与公共服务","category":"非时政","text":"4.劳动密集型行业企业\n密集型产业主要包括劳动密集型、资本密集型、技术/知识密集型、资源密集型等四种\n核心类型，这种产业分类方法体现了各产业对不同生产要素的依赖程度。\n（1）劳动密集型：指生产过程中对劳动力数量的依赖度远高于资本、技术等其他生产\n要素的产业。\n（2）资本密集型：指在生产经营中需要投入大量资本用于购置固定资产（如大型生产\n设备、厂房、生产线等）的产业。\n（3）技术/知识密集型：指以先进科学技术为核心生产要素，研发投入占比高、对专业\n技术人才依赖度强的产业。\n（4）资源密集型：指直接依托自然资源进行开采或初级加工的产业，生产过程高度依\n赖土地、矿产、森林、水等天然资源的禀赋。","source":{"doc":"6cbfb01fe723bba64b75","first":40,"last":40,"page":40,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-6129abc029f16867":{"review":{"title":"多元化食物供给体系","type":"概念与词义","definition":"多元化食物供给体系是在保障粮食供给的基础上，统筹利用农业、林业、牧业和渔业等资源，从多种途径提供食物的体系。","explanation":"2024年《国务院办公厅关于践行大食物观构建多元化食物供给体系的意见》提出树立大农业观、大食物观，推动农林牧渔并举，将肉蛋奶、水产品、森林食品等纳入食物供给的统筹范围，以保障粮食和重要农产品稳定安全供给。","basis":"据关联原题及所列出处编释。","references":[{"source":"food","location":"总体要求"}],"related":["k-fbc703040a1d4d3a","k-10875ff0d8a54918","k-82a4f4b98ff57ecb"],"examFocus":{"国考 2025 副省级 行测#6":"对照粮食安全部署，核对各项举措涉及的食物供给、耕地建设、种业、进口和科技攻关要求。"}},"aspects":[{"title":"农林牧渔并举","uses":[{"unit":"Q1","role":"直接考查","use":"第②项将践行大食物观、推动农林牧渔并举列为保障粮食安全的举措，表述正确。本题①②③⑤正确，共4项，选C。","evidence":"树立大农业观、大食物观，农林牧渔并举，构建多元化食物供给体系","qids":["国考 2025 副省级 行测#6","国考 2025 地市级 行测#6","国考 2025 行政执法 行测#6"]}]}],"sources":[{"id":"9784754828cadfa9","label":"多元化食物供给体系","topic":"农业与城乡治理","category":"非时政","text":"3.元化食物供给\n《国务院办公厅关于践行大食物观构建多元化食物供给体系的意见》指出，树立大农业\n观、大食物观，农林牧渔并举，构建多元化食物供给体系，是党中央提出的明确要求，是\n保障粮食和重要农产品稳定安全供给的客观要求和重要举措。\n构建多元化食物供给体系，全方位、多途径开发食物资源，有利于更好满足人民群众日\n益多元化的食物消费需求，实现从“吃得饱”向“吃得好”升级。\n构建多元化食物供给体系有两层含义。一是拓宽食物供给渠道，提高食物来源结构的多\n元化水平。除了向耕地和植物动物要食物，还要进一步开发草原森林海洋资源，挖掘微生物\n和生物工程技术潜力，加强对非常规农业生产空间的开发和利用。二是增加食物供给种类，\n提高食物产品构成的多元化水平。除了粮食，还要增加肉类、蔬菜、水果、水产品等各类食\n物供给，既保障传统的以口粮为主的粮食安全，也保障肉蛋奶蔬果油糖等非口粮重要农产品\n的供给安全。","source":{"doc":"6cbfb01fe723bba64b75","first":34,"last":34,"page":34,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-c9e54faa00997e23":{"review":{"title":"高质量充分就业","type":"概念与词义","definition":"高质量充分就业是使就业机会更加充分、就业质量持续提高的就业目标。它既关注整体就业状况，也关注劳动者的工作条件和劳动保障。","explanation":"习近平《促进高质量充分就业》（2024年《求是》第21期）从两个层面阐述这一目标。宏观层面包括就业机会充分、就业环境公平、就业结构优化、人岗匹配高效和劳动关系和谐。微观层面关注劳动者有活干、工作稳定、收入合理、保障可靠、职业安全。实现这一目标需要循序渐进、尽力而为、量力而行。","basis":"据关联原题及所列出处编释。","references":[{"source":"jobs","location":"就业容量与就业质量"}],"related":["k-1ee6f0c02f41907a","k-5dfa658086207b9d","k-95491b6a9bb3eff5"],"domain":"公共管理","examFocus":{"国考 2025 副省级 行测#7":"核对就业方针中各主体的作用、创业与就业的带动方向，以及就业扩容提质和劳动者权益保障的政策表述。","江苏 2025 A类 行测#8":"区分高质量充分就业的宏观指标和微观适用对象，并核对实现过程与政策部署的表述。"}},"readings":[{"origin":"k-c9e54faa00997e23","title":"高质量充分就业","qs":["国考 2025 副省级 行测#7","国考 2025 地市级 行测#7","国考 2025 行政执法 行测#7","江苏 2025 A类 行测#8","江苏 2025 B类 行测#8","江苏 2025 C类 行测#8"],"definition":"高质量充分就业是使就业机会更加充分、就业质量持续提高的就业目标。它既关注整体就业状况，也关注劳动者的工作条件和劳动保障。","explanation":"习近平《促进高质量充分就业》（2024年《求是》第21期）从两个层面阐述这一目标。宏观层面包括就业机会充分、就业环境公平、就业结构优化、人岗匹配高效和劳动关系和谐。微观层面关注劳动者有活干、工作稳定、收入合理、保障可靠、职业安全。实现这一目标需要循序渐进、尽力而为、量力而行。","evidence":"","doubt":"","references":[{"source":"jobs","location":"就业容量与就业质量"}]},{"origin":"k-cbc1513844349b26","title":"高质量充分就业","qs":["江苏 2025 C类 行测#8"],"definition":"高质量充分就业在宏观层面表现为就业机会充分、就业环境公平、就业结构优化、人岗匹配高效、劳动关系和谐等。在微观层面，表现为劳动者有活干、工作稳定、收入合理、保障可靠、职业安全等。","explanation":"①准确列举了宏观层面的主要表现。②所列工作稳定、收入合理等内容属于微观层面，但把《促进高质量充分就业》中的主体“劳动者”扩大成“每个公民”，因此②错误。","evidence":"为劳动者不仅有活干，而且工作稳定、收入合理、保障可靠、职业安全等","doubt":"","references":[]}],"aspects":[{"title":"扩大就业容量与保障劳动者权益","uses":[{"unit":"Q1","role":"直接考查","use":"第②项扩大就业容量与提升就业质量相结合、第④项保障灵活就业和新就业形态劳动者权益并扩大职业伤害保障试点，均符合文章要求。第①项错置市场和政府的作用并漏列鼓励创业，第③项颠倒创业带动就业的方向，选C。","evidence":"②坚持扩大就业容量和提升就业质量相结合③坚持就业带动创业④加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点","qids":["国考 2025 副省级 行测#7","国考 2025 地市级 行测#7","国考 2025 行政执法 行测#7"]}]},{"title":"宏观和微观内涵及政策部署","uses":[{"unit":"Q2","role":"直接考查","use":"第②项将文章微观层面的适用对象由“劳动者”扩大为“每个公民”，判错。第①项的宏观内涵、第③项的循序渐进要求以及第④项的五项工作部署均符合文章表述，选C。","evidence":"在微观层面，高质量充分就业主要表现为每个公民不仅有活干，而且工作稳定、收入合理、保障可靠、职业安全等","qids":["江苏 2025 A类 行测#8","江苏 2025 B类 行测#8","江苏 2025 C类 行测#8"]}]}],"sources":[{"id":"89c071eacc7a83cb","label":"促进高质量充分就业","topic":"就业、社保与公共服务","category":"非时政","text":"2.促进高质量充分就业\n促进高质量充分就业，是新时代新征程就业工作的新定位、新使命。要坚持以人民为中\n心的发展思想，全面贯彻劳动者自主就业、市场调节就业、政府促进就业和鼓励创业的方针，\n持续促进就业质的有效提升和量的合理增长，不断增强广大劳动者的获得感幸福感安全感，\n为以中国式现代化全面推进强国建设、民族复兴伟业提供有力支撑。\n——《求是》杂志文章《促进高质量充分就业》","source":{"doc":"6cbfb01fe723bba64b75","first":40,"last":40,"page":40,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-125a7cc54a3fcd30":{"review":{"definition":"胡焕庸线是胡焕庸于1935年提出的人口地理分界线，今称黑河—腾冲线。线的东南侧人口多、密度高，西北侧人口少、密度低。","explanation":"C项题名中的“中国的‘东与西’”概括的是这条线东南侧和西北侧的人口分布差异。按人口地理的含义，题名与胡焕庸线所揭示的格局相符。","references":[],"evidence":"呈现出极不均衡的特征，东南多、西北少","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d1c0a940f9a426fa":{"review":{"definition":"五岳是中国传统文化中按东、西、南、北、中五个方位命名的五座名山，分别为泰山、华山、衡山、恒山和嵩山。","explanation":"传统山岳崇拜和祭祀赋予五岳神圣地位，五方定位又使它们具有文化地理上的象征意义。D项的“高山神圣性”概括的是这种传统地位，作为展览题名恰当。","references":[],"evidence":"具有方位代表性的神圣高山","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d8c904fafe4ea405":{"review":{"definition":"植物补光灯用于在自然光不足时为作物补充光合作用所需的光照。温室栽培中常见的类型有LED植物灯和高压钠灯。","explanation":"本题中的紫外线灯主要用于杀菌消毒。C项把它说成温室中经常使用且效果较好的植物补光灯，混淆了设备的常见用途，因此是选非题的答案。","references":[],"evidence":"补光灯包含LED灯和高压钠灯","disposition":"独立词条","basis":"据原题和解析编释。","title":"温室植物补光灯","related":[],"examFocus":{"国考 2025 副省级 行测#33":"辨析温室常见灯具的光谱特点与实际用途，判断它们是否适合给作物补光。"}},"readings":[{"origin":"k-d8c904fafe4ea405","title":"温室植物补光灯","qs":["国考 2025 副省级 行测#33"],"definition":"植物补光灯用于在自然光不足时为作物补充光合作用所需的光照。温室栽培中常见的类型有LED植物灯和高压钠灯。","explanation":"本题中的紫外线灯主要用于杀菌消毒。C项把它说成温室中经常使用且效果较好的植物补光灯，混淆了设备的常见用途，因此是选非题的答案。","evidence":"补光灯包含LED灯和高压钠灯","doubt":"","references":[]},{"origin":"k-f1d38d8e4ff83a9c","title":"温室植物补光灯","qs":["国考 2025 行政执法 行测#35"],"definition":"温室植物补光灯用于在自然光照不足时补充作物光合作用所需的光照。常见灯型包括LED植物灯和高压钠灯。","explanation":"本题比较的是温室日常栽培中的常规补光用途。解析所说的紫外线灯主要用于杀菌消毒，C项把它描述为常用且效果较好的植物补光灯，因此应选C。","evidence":"补光灯包含LED灯和高压钠灯。","doubt":"","references":[]}]},"k-204f0fe8b15ca303":{"review":{"definition":"加速度是速度对时间的变化率，描述速度大小或方向变化的快慢。","explanation":"在④中，汽车可以以非零速度沿直线匀速行驶，此时加速度为零。汽车也可以在达到同一速度时继续加速，此时加速度非零。因此单凭车速无法确定加速度，两者没有固定的正比例关系。","references":[],"evidence":"汽车行驶时的加速度与速度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2808897dc82c9bc7":{"review":{"definition":"指脱离实际，追求过高、难以实现的目标。","explanation":"题干要求把人口基数和城乡区域发展差异纳入决策，并保持历史耐心、循序渐进。“好高骛远”点明所追求的目标超出现实条件，与另一端的“因循守旧”相对。“一厢情愿”侧重单方面的主观意愿，对目标定得过高这一偏差的指向较弱。","references":[],"evidence":"脱离实际去追求过高的、难以实现的目标","disposition":"独立词条","basis":"据原题和解析编释。","title":"好高骛远","related":[],"examFocus":{"国考 2025 副省级 行测#36":"结合人口基数、城乡区域发展差异和“循序渐进”的要求，辨析空处应与“因循守旧”形成怎样的对照。"}},"readings":[{"origin":"k-2808897dc82c9bc7","title":"好高骛远","qs":["国考 2025 副省级 行测#36"],"definition":"指脱离实际，追求过高、难以实现的目标。","explanation":"题干要求把人口基数和城乡区域发展差异纳入决策，并保持历史耐心、循序渐进。“好高骛远”点明所追求的目标超出现实条件，与另一端的“因循守旧”相对。“一厢情愿”侧重单方面的主观意愿，对目标定得过高这一偏差的指向较弱。","evidence":"脱离实际去追求过高的、难以实现的目标","doubt":"","references":[]},{"origin":"k-66eaed82e2a69ef8","title":"好高骛远","qs":["国考 2025 地市级 行测#36"],"definition":"好高骛远指脱离实际，追求过高、难以实现的目标。","explanation":"题干要求制定决策时考虑人口基数和城乡区域发展水平差异，并且稳中求进、循序渐进。“好高骛远”点出脱离这些条件、把目标定得过高的问题，与另一端的“因循守旧”相呼应。“一厢情愿”侧重单凭主观意愿，缺少对目标过高的指向。","evidence":"“好高骛远”指脱离实际去追求过高的、难以实现的目标","doubt":"","references":[]}]},"k-378d286db8050b47":{"review":{"definition":"用柔软的事物克制刚强的事物，比喻用柔和、灵活的方式应对强硬的力量。","explanation":"文中用引号标出比喻。“柔”对应火箭随风向主动调整姿态的灵活性，“刚”对应高空风的干扰。火箭通过转动让较稳定的一面迎风，贴合“以柔克刚”。“以守为攻”还要求借防守取得进攻效果，材料只描述了火箭如何减轻风的影响。","references":[],"evidence":"使火箭用更稳定的优势面来应对高空风","disposition":"独立词条","basis":"据原题和解析编释。","title":"以柔克刚","related":[],"examFocus":{"国考 2025 副省级 行测#37":"结合火箭主动滚转应对高空风的过程，辨析各成语所描述的应对方式。"}},"readings":[{"origin":"k-378d286db8050b47","title":"以柔克刚","qs":["国考 2025 副省级 行测#37"],"definition":"用柔软的事物克制刚强的事物，比喻用柔和、灵活的方式应对强硬的力量。","explanation":"文中用引号标出比喻。“柔”对应火箭随风向主动调整姿态的灵活性，“刚”对应高空风的干扰。火箭通过转动让较稳定的一面迎风，贴合“以柔克刚”。“以守为攻”还要求借防守取得进攻效果，材料只描述了火箭如何减轻风的影响。","evidence":"使火箭用更稳定的优势面来应对高空风","doubt":"","references":[]},{"origin":"k-4a83050197be354c","title":"以柔克刚","qs":["国考 2025 行政执法 行测#36"],"definition":"以柔克刚指用柔和、灵活的方式克制刚强的力量或强硬的对手。","explanation":"文段用引号提示比喻。“柔”对应火箭主动调整姿态的灵活性，“刚”对应高空风的干扰。“以退为进”强调以退让换取进展，题中的动作重点是主动调整，因此A项更贴切。","evidence":"用柔软的去克制刚强的","doubt":"","references":[]}]},"k-207aa0e34de494bd":{"review":{"definition":"原指拿起棋子却迟迟决定不了下在哪里，比喻犹豫不决、拿不定主意。","explanation":"第一空与“等待观望”“议而不决”并列，写反复权衡后仍迟迟拿不定主意。“举棋不定”和“犹豫不决”都贴合第一空，整组选C还取决于第二空的“刚愎自用”能与“我行我素”呼应。","references":[],"evidence":"比喻犹豫不决，拿不定主意","disposition":"独立词条","basis":"据原题和解析编释。","title":"举棋不定","related":[],"examFocus":{"国考 2025 副省级 行测#38":"结合第一空前后的“等待观望”“议而不决”和第二空后的“我行我素”，分别判断两空成语的语义。"}},"readings":[{"origin":"k-207aa0e34de494bd","title":"举棋不定","qs":["国考 2025 副省级 行测#38"],"definition":"原指拿起棋子却迟迟决定不了下在哪里，比喻犹豫不决、拿不定主意。","explanation":"第一空与“等待观望”“议而不决”并列，写反复权衡后仍迟迟拿不定主意。“举棋不定”和“犹豫不决”都贴合第一空，整组选C还取决于第二空的“刚愎自用”能与“我行我素”呼应。","evidence":"比喻犹豫不决，拿不定主意","doubt":"","references":[]},{"origin":"k-6e82a4b20fd194f0","title":"举棋不定","qs":["国考 2025 行政执法 行测#43"],"definition":"比喻犹豫不决，拿不定主意。","explanation":"第43题首空与“等待观望”“议而不决”并列，强调权衡之后仍拿不定主意，和前文的“当机立断”形成对照。“犹豫不决”也能填入首空，整组答案还须看第二空。","evidence":"比喻犹豫不决，拿不定主意","doubt":"","references":[]}]},"k-1dcee5793ce121e7":{"review":{"definition":"形容许多人未经认真准备和组织，便一下子涌上去做同一件事。","explanation":"开头说各地纷纷布局，第一空紧接“盲目跟风”，指出各地可能在缺乏准备时竞相上马。“拾人牙慧”侧重把他人的言论或观点据为己用，难以表现各地仓促集体行动的情形。","references":[],"evidence":"没有经过认真准备和严密组织，一下子行动起来","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-64e255a376fb595b":{"review":{"definition":"指先把事情谋划妥当，再付诸行动。","explanation":"第二空承接“从新质生产力的形成条件入手，考虑周全”，将分析实际条件、做好谋划放在行动之前，具体回应了前文的“急于求成”。“有备无患”侧重提前准备以避免祸患，文段强调的则是各地在充分谋划后再推进。","references":[],"evidence":"谋划完毕才开始行动","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6ea725314b985ea4":{"review":{"definition":"形容道理、理论等经得起检验，无法被驳倒或推翻。","explanation":"第41题用它修饰“自然规律”，强调植物能否适生受当地自然条件约束，照应下文不顾本地条件复制网红景观的做法。“显而易见”侧重容易看出，“众所周知”侧重广为人知。A项还须由第二空“得不偿失”与景观收益和生态代价的关系共同确定。","references":[],"evidence":"比喻理论、学说等完全正确，不会被驳倒推翻","disposition":"独立词条","basis":"据原题和解析编释。","title":"颠扑不破","related":[],"examFocus":{"国考 2025 副省级 行测#41":"首空辨析成语修饰“自然规律”时的侧重点，第二空结合复制景观的目的和可能造成的生态后果判断。"}},"readings":[{"origin":"k-6ea725314b985ea4","title":"颠扑不破","qs":["国考 2025 副省级 行测#41"],"definition":"形容道理、理论等经得起检验，无法被驳倒或推翻。","explanation":"第41题用它修饰“自然规律”，强调植物能否适生受当地自然条件约束，照应下文不顾本地条件复制网红景观的做法。“显而易见”侧重容易看出，“众所周知”侧重广为人知。A项还须由第二空“得不偿失”与景观收益和生态代价的关系共同确定。","evidence":"比喻理论、学说等完全正确，不会被驳倒推翻","doubt":"","references":[]},{"origin":"k-8b1055096b7c54f0","title":"颠扑不破","qs":["国考 2025 行政执法 行测#45"],"definition":"比喻道理、理论或学说经得起检验，无法被驳倒或推翻。","explanation":"第45题用“南橘北枳”引出一些植物的生长受当地自然条件制约。首空以“颠扑不破”修饰“自然规律”，强调这条规律经得起检验。“显而易见”侧重容易看出，“众所周知”侧重知道的人多。","evidence":"比喻理论、学说等完全正确，不会被驳倒推翻","doubt":"","references":[]}]},"k-2955564fdaa21a21":{"review":{"definition":"所得的好处抵不上付出的代价或遭受的损失。","explanation":"第41题中，“得”是复制网红景观所求的效果，“失”是可能付出的生态代价。“得不偿失”体现对这两者的权衡。“后患无穷”把未来祸患说得更重，“一无所有”把结果说成毫无所得，“贻笑大方”则把重点转到了被内行人笑话。","references":[],"evidence":"得到的抵不上失去的","disposition":"独立词条","basis":"据原题和解析编释。","title":"得不偿失","related":[],"examFocus":{"国考 2025 副省级 行测#41":"第一空辨析成语能否修饰“自然规律”，第二空结合“到头来”判断成语的侧重点和语气是否符合复制景观的后果。"}},"readings":[{"origin":"k-2955564fdaa21a21","title":"得不偿失","qs":["国考 2025 副省级 行测#41"],"definition":"所得的好处抵不上付出的代价或遭受的损失。","explanation":"第41题中，“得”是复制网红景观所求的效果，“失”是可能付出的生态代价。“得不偿失”体现对这两者的权衡。“后患无穷”把未来祸患说得更重，“一无所有”把结果说成毫无所得，“贻笑大方”则把重点转到了被内行人笑话。","evidence":"得到的抵不上失去的","doubt":"","references":[]},{"origin":"k-ca0547c130829dc7","title":"得不偿失","qs":["国考 2025 行政执法 行测#45"],"definition":"指得到的好处抵不上付出的代价或遭受的损失。","explanation":"第45题中，复制网红景观可能带来景观收益，也可能因不顾本地条件而破坏生态平衡。“得不偿失”点明景观收益可能抵不过生态损失。“后患无穷”把后果说得更重，“贻笑大方”则把重点转到被内行人笑话。","evidence":"指得到的抵不上失去的","doubt":"","references":[]}]},"k-19674ec5dad0f4ed":{"review":{"definition":"密封性是部件或系统在一定条件下阻止内部介质外泄或外部物质侵入的能力。","explanation":"第43题后文提到氢分子容易从管路缝隙逸出，因此第一空要点明储存系统防止外泄的能力。“安全性”涵盖的范围更广，“密封性”直接对应题中给出的缝隙和外泄问题。","references":[],"evidence":"故液氢对储存系统防外泄的功能有更高的要求","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4f5d652e00c030e0":{"review":{"definition":"描述分子运动时，“逃逸”可指分子脱离原有的束缚或限制，逸出原来所在的范围。","explanation":"第43题用“氢分子”作主语，用“从管路缝隙中”指出逸出的路径，“逃逸”正好描述这个动作。“泄漏”也能描述氢气外泄，整组选项还要结合第一空的“密封性”和第三空的“恒温”确定。","references":[],"evidence":"氢分子更容易从管路缝隙中跑出去","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-69d2ad17250866a8":{"review":{"definition":"恒温指温度保持不变或相对稳定的状态。","explanation":"第43题第三空后用“否则”引出升温气化及压强骤增的风险，所填词应体现保持温度稳定。“热量”虽与温度有关，但表示因温差而传递的能量，无法表达题中要求的温度状态。","references":[],"evidence":"“恒温”意为相对稳定的温度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0e4d07f460cabe46":{"review":{"definition":"指用浅显易懂的语言讲清深刻的道理或复杂的内容。","explanation":"第44题第三空后紧接“用朴实的语言阐述深刻的理论”。“朴实的语言”对应“浅出”，“深刻的理论”对应“深入”。前两空均可初步保留B、C两项，第三空据此选B，“举一反三”侧重从已知事例类推出其他事例。","references":[],"evidence":"用朴实的语言阐述深刻的理论","disposition":"独立词条","basis":"据原题和解析编释。","title":"深入浅出","related":[],"examFocus":{"国考 2025 副省级 行测#44":"前两空看正反对照，第三空结合紧随其后的阐释，判断成语应概括哪一种表达特点。"}},"readings":[{"origin":"k-0e4d07f460cabe46","title":"深入浅出","qs":["国考 2025 副省级 行测#44"],"definition":"指用浅显易懂的语言讲清深刻的道理或复杂的内容。","explanation":"第44题第三空后紧接“用朴实的语言阐述深刻的理论”。“朴实的语言”对应“浅出”，“深刻的理论”对应“深入”。前两空均可初步保留B、C两项，第三空据此选B，“举一反三”侧重从已知事例类推出其他事例。","evidence":"用朴实的语言阐述深刻的理论","doubt":"","references":[]},{"origin":"k-717a06a8fe03894e","title":"深入浅出","qs":["国考 2025 地市级 行测#50"],"definition":"指用浅显易懂的语言表达深刻的内容，使读者或听众容易理解。","explanation":"题末的“朴实的语言”对应表达浅显，“深刻的理论”对应内容深刻，两者共同指向第三空的“深入浅出”。“举一反三”侧重由一个例子类推其他同类情况。","evidence":"用朴实的语言阐述深刻的理论","doubt":"","references":[]}]},"k-728a09fe8b200e76":{"review":{"definition":"菱形是四条边都相等的平行四边形，平行四边形是两组对边分别平行的四边形。因此，菱形、平行四边形、四边形的范围依次扩大。","explanation":"本题选A。A项先分别说明平行四边形和菱形都属于四边形，再给出菱形属于平行四边形的结论，与题干中乔木、水杉、植物的示例句式一致。菱形属于平行四边形有几何定义作依据，仅凭两者同属四边形无法推出这一结论。B项则直接利用已给出的两级包含关系推出蝴蝶属于动物，采用的是包含关系的传递。","references":[],"evidence":"所有的平行四边形都是四边形，所有的菱形都是四边形，所以，所有的菱形都是平行四边形","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-61b6af80a08b58f7":{"review":{"definition":"逐客令原指驱逐客卿的命令，后来也指以明示或暗示的方式催促客人离开。","explanation":"“逐客”说明这道命令的用途，与“挡箭牌”用“挡箭”说明盾牌用途的构词方式一致。第101题据此匹配C项中同样以作用命名的“敲门砖”和“绊脚石”。","references":[],"evidence":"“逐客令”本为驱逐客卿的命令","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-53549d93a5eb1bfd":{"review":{"definition":"挡箭牌本指抵挡刀箭的盾牌，比喻可以用来掩护自己或推托事情的人、事物或借口。","explanation":"第101题用本义判断命名依据。“挡箭”说明盾牌的防护用途，与“逐客令”用“逐客”说明命令用途的构词方式一致。","references":[],"evidence":"可以抵挡刀箭的盾牌，比喻推掉事情的借口或可以掩护的东西","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a7b23a40af50c2e5":{"review":{"definition":"敲门砖本指用来敲门的砖石，比喻借以取得入门机会或谋取名利的手段。","explanation":"“敲门”直接说明砖石的用途。第101题C项的另一词“绊脚石”也以石块造成的作用命名，因此整组与“逐客令、挡箭牌”的命名关系一致。","references":[],"evidence":"“敲门砖”是指敲门的砖石，比喻借以谋取名利的工具","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c19ab2e3934c4642":{"review":{"definition":"绊脚石本指使人绊倒的石块，比喻阻碍事情进展或阻碍人前进的事物。","explanation":"第101题把“绊脚”视为石块造成的作用，把“敲门”视为砖石的用途。C项的两个词都把物件的作用写进名称，与题干的命名关系一致。","references":[],"evidence":"喻指前进道路上的障碍物","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-339cd39948f3af9d":{"review":{"definition":"这句话说鸟儿嘤嘤鸣叫，意在寻求同伴的应声，常借来表达寻求知音的愿望。","explanation":"前句的鸣叫是方式，后句的求取友声是目的。第102题A项用“以求”明确标出目的，和题干的关系一致。B项“经旬必得”表达满足前句条件后的预期结果。","references":[],"evidence":"指小鸟那嘤嘤的叫声，是为了寻求知音","disposition":"独立词条","basis":"据原题和解析编释。","title":"嘤其鸣矣，求其友声","related":[],"examFocus":{"国考 2025 副省级 行测#102":"辨析后一句是在说明前一句行动的目的，还是在描述结果或另一项行动。"}},"readings":[{"origin":"k-339cd39948f3af9d","title":"嘤其鸣矣，求其友声","qs":["国考 2025 副省级 行测#102"],"definition":"这句话说鸟儿嘤嘤鸣叫，意在寻求同伴的应声，常借来表达寻求知音的愿望。","explanation":"前句的鸣叫是方式，后句的求取友声是目的。第102题A项用“以求”明确标出目的，和题干的关系一致。B项“经旬必得”表达满足前句条件后的预期结果。","evidence":"指小鸟那嘤嘤的叫声，是为了寻求知音","doubt":"","references":[]},{"origin":"k-b9ef678168ea7012","title":"嘤其鸣矣，求其友声","qs":["国考 2025 行政执法 行测#96"],"definition":"这句话写鸟儿嘤嘤鸣叫，寻求同伴的应声。","explanation":"“嘤其鸣矣”写鸟儿采取的行动，“求其友声”交代鸣叫的目的。A项“遏其生气，以求重价”也先写行动，再写目的，顺序一致。","evidence":"指小鸟那嘤嘤的叫声，是为了寻求知音","doubt":"","references":[]}]},"k-7c431108a3d34a85":{"review":{"definition":"这句话说压制梅花的生机，以求把梅花卖出高价。","explanation":"在这里，“生气”指生机，“重价”指高价。“以求”把前句的做法和后句的目的连在一起，与第102题题干中鸟儿通过鸣叫寻求同伴应声的关系一致，因此选A。","references":[],"evidence":"指阻抑它（梅花）的生机，这样做是为了谋求高价","disposition":"独立词条","basis":"据原题和解析编释。","title":"遏其生气，以求重价","related":[],"examFocus":{"国考 2025 副省级 行测#102":"比较各组古语前后两句的关系，辨别后句是在交代前一做法的目的、结果，还是接下来的行动。"}},"readings":[{"origin":"k-7c431108a3d34a85","title":"遏其生气，以求重价","qs":["国考 2025 副省级 行测#102"],"definition":"这句话说压制梅花的生机，以求把梅花卖出高价。","explanation":"在这里，“生气”指生机，“重价”指高价。“以求”把前句的做法和后句的目的连在一起，与第102题题干中鸟儿通过鸣叫寻求同伴应声的关系一致，因此选A。","evidence":"指阻抑它（梅花）的生机，这样做是为了谋求高价","doubt":"","references":[]},{"origin":"k-cc943a8bea7cd198","title":"遏其生气，以求重价","qs":["国考 2025 行政执法 行测#96"],"definition":"这句话指抑制梅花的生机，以求卖得高价。句中的“生气”指生机。","explanation":"“遏其生气”写采取的手段，“以求重价”明示目的。A项的两部分依次对应题干中的鸟儿鸣叫和寻求同伴的应声。","evidence":"指阻抑它（梅花）的生机，这样做是为了谋求高价","doubt":"","references":[]}]},"k-982ce6847c75488d":{"review":{"title":"网络直播的即时性与直观性","type":"概念与词义","definition":"网络直播的即时性是指观众可以在事件发生或主播活动进行时接收内容。直观性是指观众可以通过直播的声音或画面直接感知现场情形。","explanation":"即时性指内容随现场进程发布，实际传输和播放可以有短暂延迟。直播呈现的现场情形受镜头取景和收音范围影响。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"国考 2025 副省级 行测#103":"以第三个词为对象，分别核对前两项性质能否同时用来描述这个对象。"}},"aspects":[{"title":"同一对象的两项属性","uses":[{"unit":"Q1","role":"解题依据","use":"题干中的直观性和即时性都属于网络直播，据此选择同样由两项属性对应一个对象的 B 项。","evidence":"网络直播具有直观性和即时性，前两词与第三词构成属性对应关系。","qids":["国考 2025 副省级 行测#103","国考 2025 地市级 行测#98"]}]}]},"k-24aba5d00e7b6ac1":{"review":{"title":"行政法律的公开性与权威性","type":"概念与词义","definition":"在本题语境中，行政法律的公开性指规范内容可为公众知悉，权威性指规范具有法律约束力。","explanation":"这里的公开性指规范文本的公布与查阅。权威性体现在行政机关依法行使职权、履行职责时须遵守适用的法律规范。","basis":"据关联原题和解析编释。","references":[],"domain":"法律","examFocus":{"国考 2025 副省级 行测#103":"逐组检查前两个词能否分别作为第三个对象本身的属性，并与题干的排列顺序对照。"}},"aspects":[{"title":"行政法律的两项属性","uses":[{"unit":"Q1","role":"解题依据","use":"B 项将公开性和权威性都归于行政法律，与题干中直观性和即时性都归于网络直播的关系一致。","evidence":"公开性：权威性：行政法律","qids":["国考 2025 副省级 行测#103","国考 2025 地市级 行测#98"]}]}]},"k-afded82c85ab316e":{"review":{"definition":"光伏电站是利用光伏电池板将太阳光能转化为电能的发电设施，光伏电池板是其组成部分。","explanation":"第104题中，“光伏电站—电池板”是整体与部件的关系，“光伏电站—发电”是设施与功能的关系。B项中的电磁波是射电望远镜接收的对象，在第一个关系上就与题干不同。","references":[],"evidence":"电池板是光伏电站的组成部分","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-15cba5c60af818af":{"review":{"definition":"跨海大桥是跨越海域、供交通通行的桥梁。题中的桥墩支架指桥梁的支承构件。","explanation":"第104题A项以跨海大桥为整体、桥墩支架为部件、交通为功能，两组关系都与题干一致。C项的“钻井”指开发海底气田的一项工程，处在开发环节这一层面。","references":[],"evidence":"跨海大桥：桥墩支架：交通","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-48c9f9055256dcfa":{"review":{"definition":"稀树草原是以草本植物为主、散生树木的植被类型，常见于炎热且有明显干季的地区。","explanation":"第105题D项中，稀树草原是“植被类型”下的一个具体类型，关系方向由种到属。B项的落叶阔叶林也是一种具体植被类型，它与稀树草原是并列关系。","references":[],"evidence":"稀树草原是炎热、季节性干旱气候条件下长成的植被类型","disposition":"独立词条","basis":"据原题和解析编释。","title":"稀树草原","related":[],"examFocus":{"国考 2025 副省级 行测#105":"把备选词分别代入两空，辨析稀树草原与前一空、后一空与国际公约之间的关系，尤其留意并列与种属的区别及种属方向。"}},"readings":[{"origin":"k-48c9f9055256dcfa","title":"稀树草原","qs":["国考 2025 副省级 行测#105"],"definition":"稀树草原是以草本植物为主、散生树木的植被类型，常见于炎热且有明显干季的地区。","explanation":"第105题D项中，稀树草原是“植被类型”下的一个具体类型，关系方向由种到属。B项的落叶阔叶林也是一种具体植被类型，它与稀树草原是并列关系。","evidence":"稀树草原是炎热、季节性干旱气候条件下长成的植被类型","doubt":"","references":[]},{"origin":"k-c937690dc87d8fdf","title":"稀树草原","qs":["国考 2025 地市级 行测#100"],"definition":"稀树草原是一种以草本植物为主、散生乔木或灌木的植被类型，常见于炎热且干湿季分明的地区。","explanation":"D项中的「植被类型」是「稀树草原」的上位概念，前半组按具体类型到所属类别排列。B项的「落叶阔叶林」和「稀树草原」同属植被类型，构成并列关系。","evidence":"稀树草原是炎热、季节性干旱气候条件下长成的植被类型","doubt":"","references":[]}]},"k-9d95a91b22b88a7a":{"review":{"definition":"在长青市试点中，林票是国有林场与村集体共同出资造林或合作经营现有森林时，按投资份额制发的股权凭证，具有质押、交易和兑现功能。","explanation":"新坡村发行的林票实行实名登记，票面标明面值，背面载明对应山场的亩数、林木等信息。林票把合作份额落实到可流转的凭证上，持有人可通过流转提前实现部分林权价值，也可凭票申请贷款。这是本题归纳“盘活林权价值”的依据。","references":[],"evidence":"双方按投资份额制发林票。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4332d00dc4b55e2d":{"review":{"definition":"元科普是由某一科研领域一线的领军人物或团队开展的科普，内容包括阐释科学前沿、梳理知识由来、展望领域发展，以及分享科研亲历中的感悟。","explanation":"材料用《深海浅说》说明，一线科学家既能介绍基础知识、开发利用和最新进展，也能讲清科学发现的过程。提案据此建议科学家优先把有限的可支配时间和精力用于这类难以由他人替代的科普。","references":[],"evidence":"“元科普”是由工作在某个科研领域\n第一线的领军人物（或团队）进行的科普","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-43fbc0d9fd6aabe3":{"review":{"title":"国内生产总值（GDP）","type":"概念与词义","definition":"国内生产总值是一个国家或地区所有常住单位在一定时期内生产活动的最终成果。按生产法核算，等于各行业增加值之和。","explanation":"符合常住单位条件的在华外资企业在境内生产形成的增加值计入中国GDP。增加值等于总产出减去中间投入，企业对GDP增长的贡献取决于同一核算口径下增加值的变动。","basis":"据关联原题及所列出处编释。","references":[{"source":"gdp","location":"定义和三种核算方法"},{"source":"web-2caa41b85888f544","location":"二、国内生产总值的三种核算方法（一）生产法","quote":"增加值＝总产出－中间投入"}],"examFocus":{"国考 2025 地市级 行测#28":"辨清GDP核算中生产地、企业所有权和产出指标各自的作用。"}},"aspects":[{"title":"在华外资企业的增加值归属","uses":[{"unit":"Q1","role":"直接考查","use":"本题，所给答案均为B。两卷解析以在华外资企业的生产成果纳入中国GDP说明核算归属。B项只给出企业产值持续增长，缺少判断其增加值是否增长的条件。","evidence":"外资企业CEO：我公司的产值持续增长，为中国GDP提升做出了贡献","qids":["国考 2025 地市级 行测#28","国考 2025 行政执法 行测#28"]}]}],"sources":[{"id":"0daa793a65a0589f","label":"国内生产总值（GDP）","topic":"经济指标与宏观调控","category":"非时政","text":"1.国内生产总值（GDP）\n国内（地区）生产总值是一个国家或地区的所有常住单位在一定时期内生产活动的全部\n最终产品的价值总和，是反映经济总体状况最重要的指标。\n——国家统计局","source":{"doc":"6cbfb01fe723bba64b75","first":3,"last":3,"page":3,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-cdbbbc6622e2047b":{"review":{"definition":"按第28题采用的中国货币供应量统计口径，居民定期储蓄存款属于广义货币M2中超出狭义货币M1的部分。","explanation":"A项中决定归类的是“定期储蓄存款”。解析将这类个人存款计入M2，A项将其归入M1，因此错误。","references":[],"evidence":"社区居民的定期储蓄存款属于个人存款，通常被计入M2。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f87ac15ace2e47a1":{"review":{"definition":"乳酸菌是一类能发酵糖类并产生大量乳酸的细菌。","explanation":"第29题A项用乳酸菌酿果酒来举例说明人类利用真菌发酵。乳酸菌属于细菌，典型发酵产物是乳酸。果酒中的乙醇主要来自酵母菌的酒精发酵，因此该例与所述真菌及其发酵作用都不对应。","references":[],"evidence":"产生大量乳酸的细菌的统称","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d49b09fec2be5e22":{"review":{"definition":"岩溶盆地是水对石灰岩等可溶性岩石长期溶蚀形成的大型洼地。","explanation":"识别岩溶盆地主要看洼地是否由溶蚀作用形成。D项所指的渤海湾盆地由断层活动造成地块沉降，按成因应归为断陷盆地。","references":[],"evidence":"岩溶盆地是大型溶蚀洼地","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3621dad2b8564195":{"review":{"definition":"断陷盆地是断层活动导致部分地块相对下沉而形成的盆地。","explanation":"断层活动控制沉降的位置和盆地的形态，盆地边界可受断层走向控制。本题据断块沉降这一成因将渤海湾盆地归为断陷盆地，由此判定D项所用的岩溶分类有误。","references":[],"evidence":"断陷盆地指断块构造中的沉降地块","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f13f01ac650b3375":{"review":{"definition":"把握规律指理解并掌握事物发展变化中较为稳定的关系或特点。","explanation":"第一空位于“认识”和“尊重”之间，共同搭配“人才成长规律”。“把握”强调在认识的基础上掌握规律，使培养者能够依其特点开展工作。“归纳”侧重从材料中概括出规律，在这组并列成分中，“把握”更贴合由认识到尊重的语意。","references":[],"evidence":"“认识、把握、尊重人才成长规律”","disposition":"独立词条","basis":"据原题和解析编释。","title":"把握规律","related":[],"examFocus":{"国考 2025 副省级 行测#40":"把第一空的动词与“认识”“尊重”放在一起，比较它们与“人才成长规律”的搭配，以及三个动词在语意上能否衔接。"}},"readings":[{"origin":"k-f13f01ac650b3375","title":"把握规律","qs":["国考 2025 地市级 行测#39"],"definition":"把握规律指理解并掌握事物发展变化中较为稳定的关系或特点。","explanation":"第一空位于“认识”和“尊重”之间，共同搭配“人才成长规律”。“把握”强调在认识的基础上掌握规律，使培养者能够依其特点开展工作。“归纳”侧重从材料中概括出规律，在这组并列成分中，“把握”更贴合由认识到尊重的语意。","evidence":"“认识、把握、尊重人才成长规律”","doubt":"","references":[]},{"origin":"k-f29946080a3bd910","title":"把握规律","qs":["国考 2025 副省级 行测#40"],"definition":"把握规律，是指理解并掌握事物发展的内在关系和基本趋势。","explanation":"第40题第一空承接“认识”，后接“尊重”，三者共用宾语“人才成长规律”。“把握”体现从初步认识到进一步掌握，再在培养中尊重规律的层次。“归纳”侧重从事例中概括，这里更需要表达对人才成长规律的掌握。","evidence":"认识、把握、尊重人才成长规律","doubt":"","references":[]}]},"k-198741262bdda74e":{"review":{"definition":"因噎废食比喻因为担心遇到问题或出了小问题，就放弃本来该做的事。","explanation":"第二空承接“因为害怕犯错而顾虑重重”。“因噎废食”进一步指出培养者可能因为怕出错而放弃放手让人才干事，这与下文提出为人才“松绑”、健全容错纠错机制相呼应。“瞻前顾后”也符合顾虑重重的语境，侧重犹豫不决。全题结合第一空“把握规律”选A。","references":[],"evidence":"“因噎废食”比喻因为怕出问题，索性不干","disposition":"独立词条","basis":"据原题和解析编释。","title":"因噎废食","related":[],"examFocus":{"国考 2025 副省级 行测#40":"第一空看动词与“人才成长规律”的搭配，第二空结合“顾虑重重”和下文的“松绑”，辨析成语所描写的行为及其程度。"}},"readings":[{"origin":"k-198741262bdda74e","title":"因噎废食","qs":["国考 2025 地市级 行测#39"],"definition":"因噎废食比喻因为担心遇到问题或出了小问题，就放弃本来该做的事。","explanation":"第二空承接“因为害怕犯错而顾虑重重”。“因噎废食”进一步指出培养者可能因为怕出错而放弃放手让人才干事，这与下文提出为人才“松绑”、健全容错纠错机制相呼应。“瞻前顾后”也符合顾虑重重的语境，侧重犹豫不决。全题结合第一空“把握规律”选A。","evidence":"“因噎废食”比喻因为怕出问题，索性不干","doubt":"","references":[]},{"origin":"k-c81a5a5e525cceb7","title":"因噎废食","qs":["国考 2025 副省级 行测#40"],"definition":"比喻因为遇到问题或担心出问题，就索性放弃本来该做的事。","explanation":"第40题中，人才干事创业难免有失误，培养者若因害怕犯错就束缚人才干事创业，便违背了培养初衷。“瞻前顾后”也能照应“顾虑重重”，侧重犹豫不决。A项最终还靠第一空“把握规律”的搭配胜出。","evidence":"因为怕出问题，索性不干","doubt":"","references":[]}]},"k-08e73b92922188a7":{"review":{"definition":"众志成城比喻众人同心协力，能够克服困难。同仇敌忾指众人一致痛恨、共同对付敌人。","explanation":"第40题第二空与“凝心聚力”并列，前有“心往一处想、劲往一处使”，后有“步调一致向前进”，强调全党团结一致应对重大问题和严峻形势，因此填“众志成城”。“同仇敌忾”需要有共同敌人这一语义条件。","references":[],"evidence":"心往一处想、劲往一处使","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1a68a8346ca40803":{"review":{"definition":"波动性侧重某一事物的状态或数值随时间起伏。差异性侧重不同对象或不同情形之间存在区别。","explanation":"第41题用“时多时少”说明同一用电需求在不同时段有高有低，第二空应概括这种随时间起伏的特征，因此填“波动性”。“差异性”可以描述不同时段的需求有别，但“时多时少”更具体地指向需求量的起伏。","references":[],"evidence":"时多时少","disposition":"独立词条","basis":"据原题和解析编释。","title":"波动性与差异性","related":[],"examFocus":{"国考 2025 地市级 行测#41":"第一空关注发电与用电在时间上的关系，第二空结合“时多时少”辨析各词描述用电需求的角度。"}},"readings":[{"origin":"k-1a68a8346ca40803","title":"波动性与差异性","qs":["国考 2025 地市级 行测#41"],"definition":"波动性侧重某一事物的状态或数值随时间起伏。差异性侧重不同对象或不同情形之间存在区别。","explanation":"第41题用“时多时少”说明同一用电需求在不同时段有高有低，第二空应概括这种随时间起伏的特征，因此填“波动性”。“差异性”可以描述不同时段的需求有别，但“时多时少”更具体地指向需求量的起伏。","evidence":"时多时少","doubt":"","references":[]},{"origin":"k-e30eb4f650ef9724","title":"波动性与差异性","qs":["国考 2025 行政执法 行测#44"],"definition":"波动性指某个量随时间或条件变化而起伏的特性。差异性指对象、情形或时段之间存在差别。","explanation":"第44题用“时多时少”描述用电需求随时间起伏，第二空用“波动性”最贴切。如果要突出“差异性”，通常会交代所比较的对象或情形，例如不同地区的用电需求有何不同。","evidence":"时多时少","doubt":"","references":[]}]},"k-ca3e67f6a6101d74":{"review":{"definition":"比喻孤立无助，单凭一方的力量难以把事情办成。","explanation":"第42题第一空用“孤掌难鸣”概括题中单个单位独自应对复杂情形的困境，与后文“攥指成拳”的协同意象呼应。“捉襟见肘”也可形容难以应付，但侧重顾此失彼，“孤掌难鸣”更突出题中的孤立无助。","references":[],"evidence":"“孤掌难鸣”指孤立无助，难以成事","disposition":"独立词条","basis":"据原题和解析编释。","title":"孤掌难鸣","related":[],"examFocus":{"国考 2025 地市级 行测#42":"结合前文判断第一空要描写哪种困境，再看第二空与“攥指成拳”构成怎样的转折。"}},"readings":[{"origin":"k-ca3e67f6a6101d74","title":"孤掌难鸣","qs":["国考 2025 地市级 行测#42"],"definition":"比喻孤立无助，单凭一方的力量难以把事情办成。","explanation":"第42题第一空用“孤掌难鸣”概括题中单个单位独自应对复杂情形的困境，与后文“攥指成拳”的协同意象呼应。“捉襟见肘”也可形容难以应付，但侧重顾此失彼，“孤掌难鸣”更突出题中的孤立无助。","evidence":"“孤掌难鸣”指孤立无助，难以成事","doubt":"","references":[]},{"origin":"k-edecbb5dba467c7b","title":"孤掌难鸣","qs":["国考 2025 行政执法 行测#46"],"definition":"比喻单凭一方的力量或缺少配合，事情难以办成。","explanation":"第46题首空把题文所述单一力量难以独立应对复杂局面的处境比作“孤掌难鸣”。“捉襟见肘”也能形容能力不足、穷于应付，但“孤掌难鸣”突出缺少配合，呼应后文的“攥指成拳”。","evidence":"指孤立无助，难以成事","doubt":"","references":[]}]},"k-471105f275ef1a4a":{"review":{"definition":"比喻拘泥于旧办法或成例，遇到情况变化也不知变通。","explanation":"第43题要求在中国式现代化的未知领域通过实践探索和改革创新推动发展。第一空与“守株待兔”并列，其中“刻舟求剑”突出沿用旧办法处理新情况，“守株待兔”突出消极等待，两者都是题干以“决不能”否定的做法。","references":[],"evidence":"“刻舟求剑”比喻办事刻板，拘泥成例而不知变通","disposition":"独立词条","basis":"据原题和解析编释。","title":"刻舟求剑","related":[],"examFocus":{"国考 2025 副省级 行测#42":"结合“决不能”和“鼓励”确定两空的语义方向，再看所填成语能否分别与“守株待兔”和“大胆探索”并列。"}},"readings":[{"origin":"k-471105f275ef1a4a","title":"刻舟求剑","qs":["国考 2025 地市级 行测#43"],"definition":"比喻拘泥于旧办法或成例，遇到情况变化也不知变通。","explanation":"第43题要求在中国式现代化的未知领域通过实践探索和改革创新推动发展。第一空与“守株待兔”并列，其中“刻舟求剑”突出沿用旧办法处理新情况，“守株待兔”突出消极等待，两者都是题干以“决不能”否定的做法。","evidence":"“刻舟求剑”比喻办事刻板，拘泥成例而不知变通","doubt":"","references":[]},{"origin":"k-c77f68cc1b1baf80","title":"刻舟求剑","qs":["国考 2025 副省级 行测#42"],"definition":"比喻情况已经变化，处理事情仍拘泥于原来的做法，不知变通。","explanation":"第42题把它与“守株待兔”并列放在“决不能”之后，具体指面对未知领域和新问题，仍照搬旧办法。这与前文要求大胆探索、通过改革创新推动发展相对照。“画地为牢”也能表达自我设限，最终还要靠第二空的“敢为人先”确定A项。","evidence":"办事刻板，拘泥成例而不知变通","doubt":"","references":[]}]},"k-833d3299afad1d5e":{"review":{"definition":"指敢于走在别人前面，率先尝试前人或他人未做过的事。","explanation":"第43题第二空与“大胆探索”并列，具体指各地区各部门在前沿实践和未知领域先行尝试，形成解决新问题的新办法和可推广的经验。“大展拳脚”侧重充分施展本领，缺少率先尝试这层意思。","references":[],"evidence":"努力创造可复制、可推广的新鲜经验","disposition":"独立词条","basis":"据原题和解析编释。","title":"敢为人先","related":[],"examFocus":{"国考 2025 副省级 行测#42":"首空结合“决不能”和“守株待兔”辨析成语，第二空看词义与“大胆探索”及前沿实践语境是否相合。"}},"readings":[{"origin":"k-833d3299afad1d5e","title":"敢为人先","qs":["国考 2025 地市级 行测#43"],"definition":"指敢于走在别人前面，率先尝试前人或他人未做过的事。","explanation":"第43题第二空与“大胆探索”并列，具体指各地区各部门在前沿实践和未知领域先行尝试，形成解决新问题的新办法和可推广的经验。“大展拳脚”侧重充分施展本领，缺少率先尝试这层意思。","evidence":"努力创造可复制、可推广的新鲜经验","doubt":"","references":[]},{"origin":"k-a6d99ed6315ea758","title":"敢为人先","qs":["国考 2025 副省级 行测#42"],"definition":"敢于走在别人前面，率先尝试此前少有人做或无人做过的事。","explanation":"第42题第二空紧接“大胆探索”，后文要求在前沿实践和未知领域寻找解决新问题的办法，创造可复制、可推广的新鲜经验。“敢为人先”的重点在“率先尝试”，“大展拳脚”的重点在“充分施展本领”，前者更贴合开拓新做法的要求。","evidence":"敢于做别人没有做过的事情","doubt":"","references":[]}]},"k-39c3db152faf2d50":{"review":{"definition":"指喜欢听、乐意看，常用来形容某种事物或情形受到欢迎。","explanation":"第44题第一空评价的是雨量增多、变率减弱的降水变化型。雨水丰盈又能温和滋养大地，因而这种变化受到欢迎。“望眼欲穿”和“翘首以盼”侧重盼望，“津津乐道”侧重有兴致地谈论。","references":[],"evidence":"未来的雨水不仅丰盈，还会以“润物细无声”的方式滋养大地","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4905477d535c4dc7":{"review":{"definition":"在第44题材料中，降水的极端性指降水量出现明显偏离通常水平的情形。","explanation":"材料把我国大部分地区的降水变化概括为“更湿润且波动更大”，并用“须引起广泛重视”提示降水出现显著偏离常态的风险，因此第二空选“极端性”。这一表述概括的是文段给出的风险判断，具体极端降水指标取决于采用的定义和统计口径。","references":[],"evidence":"更湿润且波动更大","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-64f12b8d4e6dffd3":{"review":{"definition":"形容力量不足，应付了这一方面，另一方面又出了问题。","explanation":"题中用“十个指头弹钢琴”比喻统筹多项工作。一味加压会影响部分工作的力量分配，造成顾此失彼，所以第二空填“左支右绌”。“进退维谷”侧重进退两难，“拖泥带水”侧重办事拖沓或表达不简明。","references":[],"evidence":"势必使某个或多个指头的力量受到影响","disposition":"独立词条","basis":"据原题和解析编释。","title":"左支右绌","related":[],"examFocus":{"国考 2023 副省级 行测#26":"首空看“则”连接的短期波动与长期调整的对照，第二空结合下文对跨周期调节的说明辨析成语。","国考 2025 地市级 行测#45":"首空留意“赢得”的搭配，第二空根据“十个指头弹钢琴”的比喻，辨析成语各自描述的是哪种工作局面。"}},"readings":[{"origin":"k-64f12b8d4e6dffd3","title":"左支右绌","qs":["国考 2025 地市级 行测#45"],"definition":"形容力量不足，应付了这一方面，另一方面又出了问题。","explanation":"题中用“十个指头弹钢琴”比喻统筹多项工作。一味加压会影响部分工作的力量分配，造成顾此失彼，所以第二空填“左支右绌”。“进退维谷”侧重进退两难，“拖泥带水”侧重办事拖沓或表达不简明。","evidence":"势必使某个或多个指头的力量受到影响","doubt":"","references":[]},{"origin":"k-e64260eecfce7ac4","title":"左支右绌","qs":["国考 2023 副省级 行测#26"],"definition":"形容力量不足，顾得了一方面，另一面又应付不过来。","explanation":"第26题首空承接“则”，用来说明传统逆周期调节虽能较好地应对短期波动，面对长期结构性调整却容易顾此失彼。“捉襟见肘”也能表达穷于应付，B项由第二空的“另辟蹊径”进一步确定，呼应下文引出的跨周期调节。","evidence":"“左支右绌”指力量不足，应付了这一方面，那一方面又有了问题","doubt":"","references":[]}]},"k-c8f9c64f84c283a7":{"review":{"definition":"指帮助别人排除忧虑、解决困难。","explanation":"题中民营企业仍有不少困难和问题，干部应主动为企业解决实际困难，因此第一空填“排忧解难”。“雪中送炭”突出在对方急需时给予帮助，“嘘寒问暖”侧重表达对他人生活的关切。","references":[],"evidence":"民营企业所遇到的困难和问题仍不少","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f754640e56db123a":{"review":{"definition":"指把听到的话或得知的事搁在一边，像没听见一样，形容不予理会。","explanation":"题中“把握分寸”仍要求干部积极服务企业，第二空描述的是对企业家正当要求不予理会的态度。“退避三舍”侧重退让回避，“充耳不闻”和“熟视无睹”也能表达忽视，最终由第一空“排忧解难”确定D项。","references":[],"evidence":"对企业家的正当要求","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bf56acfe0eb992e2":{"review":{"definition":"指一个过程反复回到起点，一轮接一轮地重现。","explanation":"题中刺沙蓬随风翻滚时散落种子，种子长成新的刺沙蓬，新植株又会散落种子。“如此”承接的是这个反复重现的过程，所以第二空填“循环往复”。“环环相扣”侧重各环节紧密相连。","references":[],"evidence":"时机成熟就会长成新的刺沙蓬","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1817dc5f6d6ae5d8":{"review":{"definition":"本指人到了异地后难以适应当地的气候、饮食等条件，也可比喻外来的做法与当地实际情况不相适应。","explanation":"题中平原的耕地恢复方法未必适合山区，有些耕保经验还依赖当地经济基础和民风社情。第三空用“水土不服”说明照搬外地经验可能因条件不同而失效。“功亏一篑”侧重临近完成时因欠缺最后一点努力而失败。","references":[],"evidence":"有些经验做法依托的是当地经济基础和民风社情","disposition":"独立词条","basis":"据原题和解析编释。","title":"水土不服","related":[],"examFocus":{"国考 2025 地市级 行测#48":"先梳理文段从借鉴经验到地区差异再到推广后果的脉络，再比较第三空各成语所强调的受挫原因。"}},"readings":[{"origin":"k-1817dc5f6d6ae5d8","title":"水土不服","qs":["国考 2025 地市级 行测#48"],"definition":"本指人到了异地后难以适应当地的气候、饮食等条件，也可比喻外来的做法与当地实际情况不相适应。","explanation":"题中平原的耕地恢复方法未必适合山区，有些耕保经验还依赖当地经济基础和民风社情。第三空用“水土不服”说明照搬外地经验可能因条件不同而失效。“功亏一篑”侧重临近完成时因欠缺最后一点努力而失败。","evidence":"有些经验做法依托的是当地经济基础和民风社情","doubt":"","references":[]},{"origin":"k-bb5111683edfbecd","title":"水土不服","qs":["国考 2025 行政执法 行测#48"],"definition":"原指到了异地，不能适应当地的气候、饮食等环境条件。也比喻外来的做法等不适应当地实际。","explanation":"第48题第三空用的是比喻义。耕保经验可能依赖原地的经济基础和民风社情，盲目推广到外地就可能难以落实，还会劳民伤财。“功亏一篑”需要有接近完成却未能成功的情节，文段没有交代这样的进度。","evidence":"有些经验做法依托的是当地经济基础和民风社情","doubt":"","references":[]}]},"k-0f4bd795df8c49a6":{"review":{"definition":"指事物顺应时机或在相应条件成熟时产生。","explanation":"题文先交代弹药技术发生变化，再写弹匣手枪问世，最后写它显露优势。第二空承担交代问世的作用，因此填“应运而生”。“初露锋芒”侧重已经出现的对象开始显示本领或实力。","references":[],"evidence":"应先交代弹匣手枪的问世，随后再分析其优势","disposition":"独立词条","basis":"据原题和解析编释。","title":"应运而生","related":[],"examFocus":{"国考 2025 地市级 行测#49":"按叙述顺序判断第二空和第三空分别处于哪个发展阶段，留意成语对事物所处阶段的要求。","江苏 2025 B类 行测#39":"首空结合前文时间框架的建立和后文每年更新的叙述，判断国际年代地层表在该处所处的阶段。"}},"readings":[{"origin":"k-0f4bd795df8c49a6","title":"应运而生","qs":["国考 2025 地市级 行测#49"],"definition":"指事物顺应时机或在相应条件成熟时产生。","explanation":"题文先交代弹药技术发生变化，再写弹匣手枪问世，最后写它显露优势。第二空承担交代问世的作用，因此填“应运而生”。“初露锋芒”侧重已经出现的对象开始显示本领或实力。","evidence":"应先交代弹匣手枪的问世，随后再分析其优势","doubt":"","references":[]},{"origin":"k-5ce3287b6271fb48","title":"应运而生","qs":["江苏 2025 B类 行测#39"],"definition":"应运而生指事物顺应一定的形势或条件而产生。","explanation":"首空承接“地球演化史的时间框架已经建立”，写国际年代地层表在这一基础上随之产生。“应运而生”既交代地层表已经出现，也把它的产生与前文所述条件联系起来。“呼之欲出”用于此处只表示将要出现，与后文每年更新该表不合。","evidence":"地球演化史的时间框架已经建立","doubt":"","references":[]},{"origin":"k-a3ac2f0c513fcf09","title":"应运而生","qs":["江苏 2025 C类 行测#39"],"definition":"应运而生指顺应某种形势或时势而产生。","explanation":"题中，全球地质学家和古生物学家建立了地球演化史的时间框架，国际年代地层表随之产生。“应运而生”把前文交代的背景和地层表的形成接在一起。“呼之欲出”在这里侧重将要出现，与下文地层表已在逐年更新的状态有别。","evidence":"“应运而生”指随着某种形势而产生","doubt":"","references":[]}]},"k-9916fdd38e8fa715":{"review":{"definition":"侃侃而谈形容说话从容不迫，常带正面色彩。喋喋不休形容说话啰嗦、没完没了，带贬义。","explanation":"辞书释义和用例分别突出说话的从容与啰嗦，两词的共同点是都描述说话，词义侧重点有别。按本题采用的感情色彩比较，C项与“殚精竭虑：费尽心机”同为先褒后贬，而A项两词均带贬义。题解所说的近义关系，在C项只宜理解为处于同一语义领域。","references":[{"source":"web-db34a8eaf7717798","location":"释义及例句","quote":"說話從容不迫的樣子"},{"source":"web-502cafc45a3828e9","location":"释义及例句","quote":"言語囉嗦，不能停止的樣子"}],"evidence":"“侃侃而谈”是褒义词，“喋喋不休”是贬义词","disposition":"独立词条","basis":"据原题与所列资料编释。","title":"侃侃而谈与喋喋不休","related":[],"examFocus":{"国考 2025 地市级 行测#96":"先看每组词的语义联系，再按前后顺序比较两个词的褒贬色彩。"}},"readings":[{"origin":"k-9916fdd38e8fa715","title":"侃侃而谈与喋喋不休","qs":["国考 2025 地市级 行测#96"],"definition":"侃侃而谈形容说话从容不迫，常带正面色彩。喋喋不休形容说话啰嗦、没完没了，带贬义。","explanation":"辞书释义和用例分别突出说话的从容与啰嗦，两词的共同点是都描述说话，词义侧重点有别。按本题采用的感情色彩比较，C项与“殚精竭虑：费尽心机”同为先褒后贬，而A项两词均带贬义。题解所说的近义关系，在C项只宜理解为处于同一语义领域。","evidence":"“侃侃而谈”是褒义词，“喋喋不休”是贬义词","doubt":"","references":[{"source":"web-db34a8eaf7717798","location":"释义及例句","quote":"說話從容不迫的樣子"},{"source":"web-502cafc45a3828e9","location":"释义及例句","quote":"言語囉嗦，不能停止的樣子"}]},{"origin":"k-ed364c976a71bcbe","title":"侃侃而谈与喋喋不休","qs":["国考 2025 行政执法 行测#97"],"definition":"“侃侃而谈”形容说话从容、理直气壮。“喋喋不休”形容说话唠叨个没完，含贬义。","explanation":"前者着重说话的态度和风度，后者着重话多且不停。本题以二者同写说话状态作为联系，C项由褒到贬的顺序与“殚精竭虑、费尽心机”一致。","evidence":"“侃侃而谈”是褒义词，“喋喋不休”是贬义词","doubt":"","references":[]}]},"k-77b2a4d4e5dfa53b":{"review":{"definition":"「逐客令」本指驱逐客卿的命令，后来也指明示或暗示客人离开的做法。「挡箭牌」本指抵挡刀箭的盾牌，常比喻用来掩护自己的人或事物，也可指推托的借口。","explanation":"「逐客」说明命令要做什么，「挡箭」说明盾牌用来做什么。题干据此建立两个名称各自体现用途的关系，C项的「敲门砖」和「绊脚石」也各自体现所指事物的用途或作用。","references":[],"evidence":"“逐客令”本为驱逐客卿的命令","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-83574758193f2b4d":{"review":{"definition":"「敲门砖」字面指用来敲门的砖石，比喻为取得机会或谋取名利而使用的手段。「绊脚石」字面指会把人绊倒的石块，比喻前进中的障碍。","explanation":"「敲门」说的是砖的用途，「绊脚」说的是石块造成的阻碍。C项的两个名称都能从字面看出所指事物的用途或作用，分别对应题干中「逐客令」的逐客用途和「挡箭牌」的挡箭作用。","references":[],"evidence":"“敲门砖”与“绊脚石”均根据功能进行命名","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d067819fc066e876":{"review":{"definition":"《联合国宪章》是规定联合国宗旨、原则和组织架构的多边国际条约。","explanation":"本题把「国际公约」用作国际条约的宽泛类称，《联合国宪章》是其中一份具体文件。D项后半组由具体文件指向所属类别，与前半组「稀树草原」指向「植被类型」的方向一致。","references":[],"evidence":"法，是国际公约，二者为种属关系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bc653d5f836f1adb":{"review":{"title":"场均观众人次","type":"概念与词义","definition":"观众总人次除以对应的放映场次，表示每场平均有多少观影人次。","explanation":"分子、分母应属于同一地区和时期。同一人观影两次计为两人次，因此场均人次不能说明有多少不同观众。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"单位价格与平均量","related":["k-d53156aa5705fe00","k-51ba02848364c3a1"]}},"k-b3ba9534e0541226":{"review":{"definition":"电影上座率是一定时期内的观众总人次占同期各场放映座位总数的百分比。放映座位总数等于总放映场次乘以平均每场座位数。","explanation":"题设中北京的总放映场次和平均每场座位数都与2023年12月相同，因此两个月的放映座位总数相同，观众总人次随上座率同比例变化。图2显示，北京2023年12月的上座率为10.75%，观众总人次为410.74万。上座率增加5个百分点后为15.75%，因此该月观众总人次为410.74×（15.75%÷10.75%）≈601.78万，最接近A项的602万人次。","references":[],"evidence":"总观众人次=总放映场次×平均每场座位数×上座率","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6511376d3008b0bb":{"review":{"definition":"价值尺度是货币以自身价值为尺度衡量其他商品价值的职能。商品的价值用货币表现出来就是价格。","explanation":"给商品标价时，使用观念上的货币即可衡量商品价值。第3题B项把实际的物质交换说成发挥价值尺度职能的条件，因而错误。","references":[],"evidence":"只需要观念上的货币，不需要通过实际的物质交换来实现。","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"db4a7e019f79c6eb","label":"商品经济理论 · 货币的含义和职能","topic":"马克思主义政治经济学","category":"非时政","text":"五、货币的含义和职能\n1.含义：货币是在长期交换过程中形成的固定地充当一般等价物的特殊商品。\n2.职能：价值尺度（不需要现实的货币，只需要观念上的货币，常见形式为标价）、流\n通手段（币充当商品交换的媒介）、支付手段（赊购赊销）、贮藏手段（必须是足值的金属货\n币或金属条块）、世界货币。其中价值尺度和流通手段是货币的两种最基本职能。\n（粉笔敲黑板：区分并记忆货币的五大职能，考试中给相关案例需要区分出体现的是货\n币的哪个职能）","source":{"doc":"3ccc56f4000d1642c2d1","first":9,"last":9,"page":9,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-92fb1283efb514a3":{"review":{"definition":"启明星是金星在日出前出现在东方天空时的称呼。金星在日落后出现在西方天空时称为长庚星。","explanation":"“启明星在树梢头”中的“启明星”指金星。由此可用金星的轨道核对C项，金星的公转轨道半径小于地球的公转轨道半径，C项的比较方向有误。","references":[],"evidence":"清晨在东方天空出现则被称为“启明星”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3a908307b4d1979e":{"review":{"definition":"指用同一个原则、思想或做法贯穿始终。","explanation":"《营造法式》刊行后，题干所述抬梁式承重方案成为此后中国官式建筑沿用的技术路径。“一以贯之”强调同一方案在后续发展中的延续，“源远流长”则侧重历史悠久、根底深厚。","references":[],"evidence":"置于此处可体现发展路径一直延续之意","disposition":"独立词条","basis":"据原题和解析编释。","title":"一以贯之","related":[],"examFocus":{"国考 2025 地市级 行测#37":"填空时留意“此后”的时间线索，判断前文的承重方案与后文“发展路径”之间的关系。"}},"readings":[{"origin":"k-3a908307b4d1979e","title":"一以贯之","qs":["国考 2025 行政执法 行测#37"],"definition":"指用同一个原则、思想或做法贯穿始终。","explanation":"《营造法式》刊行后，题干所述抬梁式承重方案成为此后中国官式建筑沿用的技术路径。“一以贯之”强调同一方案在后续发展中的延续，“源远流长”则侧重历史悠久、根底深厚。","evidence":"置于此处可体现发展路径一直延续之意","doubt":"","references":[]},{"origin":"k-43953921c21216e5","title":"一以贯之","qs":["国考 2025 地市级 行测#37"],"definition":"一以贯之指用同一思想或原则贯穿始终，也可形容始终沿用同一种做法或路径。","explanation":"题干说《营造法式》刊行后，抬梁式及其屋面承重方案成为此后官式建筑的发展路径。“此后”指向同一路径的延续，适合用“一以贯之”。“源远流长”侧重历史悠久、根底深厚。","evidence":"置于此处可体现发展路径一直延续之意","doubt":"","references":[]}]},"k-6f200f2547555b47":{"review":{"definition":"指掩饰自己的过失和错误。","explanation":"第一空与“不讳疾忌医”并列，两个“不”共同说明修正错误时应正视自身问题，以便及时发现和解决。“文过饰非”侧重掩饰过错，“避重就轻”侧重回避主要问题，“矫枉过正”侧重纠正偏差时超过限度。","references":[],"evidence":"“文过饰非”指掩饰自己的过失和错误","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-61e044fa0770c7fe":{"review":{"definition":"指随着时代的发展而不断发展、前进。","explanation":"第二空后的“不断深化”规律性认识和句末的“革故鼎新、守正创新”，共同指向党的自我革命在认识和举措上的持续发展。“与时俱进”体现这种动态变化，“学以致用”侧重把所学用于实践。","references":[],"evidence":"“与时俱进”指随着时代的发展而不断发展、前进","disposition":"独立词条","basis":"据原题和解析编释。","title":"与时俱进","related":[],"examFocus":{"国考 2025 行政执法 行测#39":"第一空看它与“讳疾忌医”的并列关系，第二空看它如何衔接后文对规律性认识和思路举措的描述。","江苏 2023 B类 行测#39":"第一空看动词与“网络语言中的优质部分”的搭配，第二空看“从而”引出的报道效果。"}},"readings":[{"origin":"k-61e044fa0770c7fe","title":"与时俱进","qs":["国考 2025 行政执法 行测#39"],"definition":"指随着时代的发展而不断发展、前进。","explanation":"第二空后的“不断深化”规律性认识和句末的“革故鼎新、守正创新”，共同指向党的自我革命在认识和举措上的持续发展。“与时俱进”体现这种动态变化，“学以致用”侧重把所学用于实践。","evidence":"“与时俱进”指随着时代的发展而不断发展、前进","doubt":"","references":[]},{"origin":"k-b4fde944d00782d6","title":"与时俱进","qs":["江苏 2023 B类 行测#39"],"definition":"与时俱进指顺应时代的变化而不断前进或发展。","explanation":"第39题用「从而」引出吸收优质网络语言的效果。网络语言能表达民众当下的心情，融入报道后，报道用语便能更贴近当下的社会现实，这对应「与时俱进」。「博采众长」着重从多方吸收长处，「推陈出新」着重革除陈旧成分、推出新内容，两者的侧重点均与这里的结果不同。","evidence":"能够反映社会现实，生动表达民众当下心情","doubt":"","references":[]}]},"k-b7c9c9a2e5322afd":{"review":{"definition":"指事物在发生、响应或推进的时间和进度上落后于相关变化或实际需要的特性。","explanation":"题干用“应救即救”强调及时性，第一空因此对应人工摸排发现救助线索可能出现的延迟。并列的“被动性”侧重线索发现方式，后文用大数据“主动发现”与之呼应。","references":[],"evidence":"表达靠人工摸排获取救助线索在时间上有一些延迟","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-df0df6c1de22cd66":{"review":{"definition":"指覆盖有关的各个方面。","explanation":"题干以“衔接社会救助力量，构建多元帮扶机制”说明救助可以回应困难群体多方面的需求，第二空强调帮扶的覆盖范围。“一站式”侧重集中办理，“全天候”侧重服务时间。","references":[],"evidence":"同时衔接社会救助力量，构建多元帮扶机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6edd3164a6840098":{"review":{"definition":"指道理或事实显而易见，自然无须再作说明。","explanation":"题干先说明政府机关依法履行公共职责，再用“自不待言”承接其承担广告监管职责这一点，随后以“但”引出网络平台也应参与治理。“当仁不让”强调遇到应该做的事主动担当，侧重行动态度。","references":[],"evidence":"“自不待言”指大家心里明白，不必再用言语解释","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f82a66ae7cd7c2fd":{"review":{"definition":"比喻对进入或流通的内容起筛选作用、能拦截不合要求内容的主体或机制。","explanation":"题干用“过滤网”比喻网络平台在提供信息服务时防范、制止违法广告的作用，与“协同监管者”呼应。“责任田”比喻需要负责的范围，“防火墙”也能表达防范和阻隔，因此还需用第一空的“自不待言”确定D项。","references":[],"evidence":"应当采取措施防范、制止违法广告","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-29fd45aea13b8de7":{"review":{"definition":"比喻下属势力过大，难以驾驭，也形容组织庞大、涣散，指挥不灵。","explanation":"题干由“党的规模大了”引出搞小山头、小圈子、小团伙的问题。“尾大不掉”与“自行其是”并列，突出团结统一和统一指挥可能受到影响。“分崩离析”表示分裂瓦解，程度更重。","references":[],"evidence":"机构下强上弱，或组织庞大、涣散，指挥不灵","disposition":"独立词条","basis":"据原题和解析编释。","title":"尾大不掉","related":[],"examFocus":{"国考 2025 地市级 行测#40":"结合组织规模扩大后的现象辨析第一空的词义，再看第二空的成语能否呼应“凝心聚力”和“步调一致”。"}},"readings":[{"origin":"k-29fd45aea13b8de7","title":"尾大不掉","qs":["国考 2025 行政执法 行测#42"],"definition":"比喻下属势力过大，难以驾驭，也形容组织庞大、涣散，指挥不灵。","explanation":"题干由“党的规模大了”引出搞小山头、小圈子、小团伙的问题。“尾大不掉”与“自行其是”并列，突出团结统一和统一指挥可能受到影响。“分崩离析”表示分裂瓦解，程度更重。","evidence":"机构下强上弱，或组织庞大、涣散，指挥不灵","doubt":"","references":[]},{"origin":"k-62a363b4472f05ea","title":"尾大不掉","qs":["国考 2025 地市级 行测#40"],"definition":"比喻下属势力过强，或组织庞大而涣散，以致上级难以指挥调度。","explanation":"第40题先说党的规模扩大后容易出现小山头、小圈子、小团伙，再把第一空与“自行其是”并列，指向各行其是给统一领导带来的困难。“分崩离析”已经到了分裂瓦解的程度，重于题干所述的问题。","evidence":"搞小山头、小圈子、小团伙现象","doubt":"","references":[]}]},"k-5889dfd588b003ab":{"review":{"definition":"比喻众人团结一致，形成能够克服困难的强大力量。","explanation":"第二空与“凝心聚力”并列，承接重大问题和严峻形势面前“心往一处想、劲往一处使”的要求，并照应全党团结、步调一致。“同仇敌忾”特指大家共同痛恨敌人，题干强调的是团结应对困难。","references":[],"evidence":"大家团结一致，就能克服困难","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-325c809d655e6d36":{"review":{"definition":"形容人固执己见，听不进别人的意见。","explanation":"第43题第二空与“我行我素”并列，后文要求“聚民意、集众智”，突出作决断时要听取他人意见。“刚愎自用”切中固执己见这一点。“泥古不化”侧重拘泥旧规，“听之任之”侧重放任不管。","references":[],"evidence":"“刚愎自用”指十分倔强固执，不考虑别人的意见","disposition":"独立词条","basis":"据原题和解析编释。","title":"刚愎自用","related":[],"examFocus":{"国考 2025 副省级 行测#38":"辨析第二空时，结合并列的“我行我素”和后文“聚民意、集众智”所形成的对照。"}},"readings":[{"origin":"k-325c809d655e6d36","title":"刚愎自用","qs":["国考 2025 行政执法 行测#43"],"definition":"形容人固执己见，听不进别人的意见。","explanation":"第43题第二空与“我行我素”并列，后文要求“聚民意、集众智”，突出作决断时要听取他人意见。“刚愎自用”切中固执己见这一点。“泥古不化”侧重拘泥旧规，“听之任之”侧重放任不管。","evidence":"“刚愎自用”指十分倔强固执，不考虑别人的意见","doubt":"","references":[]},{"origin":"k-6994906f0e1f6fc2","title":"刚愎自用","qs":["国考 2025 副省级 行测#38"],"definition":"指十分固执，坚持按自己的主意行事，听不进别人的意见。","explanation":"第二空与“我行我素”并列，下文又要求“聚民意、集众智”。“刚愎自用”同时写出了固执己见和拒绝听取他人意见，与两处语句呼应。“泥古不化”侧重拘守旧规，“听之任之”侧重放任不管。","evidence":"十分倔强固执，不考虑别人的意见","doubt":"","references":[]}]},"k-14732ea9142d41d2":{"review":{"definition":"指两个或多个相互关联的过程在时间上同时发生，或按一致的步调推进。","explanation":"第44题说风电、光伏发电有间歇性，用电需求又时多时少。“不一定同步”表示有电可供的时段与需要用电的时段未必重合，储能可以把一部分电留到需要时使用。“匹配”也能描述供需是否相适应，“同步”更明确地指出这里的时间关系。","references":[],"evidence":"应体现能量的产生和使用在时间上存在不一致性。","disposition":"独立词条","basis":"据原题和解析编释。","title":"同步","related":[],"examFocus":{"国考 2025 地市级 行测#41":"结合发电的间歇性判断第一空要描述的产用关系，再用“时多时少”检验第二空能否概括用电需求的变化。"}},"readings":[{"origin":"k-14732ea9142d41d2","title":"同步","qs":["国考 2025 行政执法 行测#44"],"definition":"指两个或多个相互关联的过程在时间上同时发生，或按一致的步调推进。","explanation":"第44题说风电、光伏发电有间歇性，用电需求又时多时少。“不一定同步”表示有电可供的时段与需要用电的时段未必重合，储能可以把一部分电留到需要时使用。“匹配”也能描述供需是否相适应，“同步”更明确地指出这里的时间关系。","evidence":"应体现能量的产生和使用在时间上存在不一致性。","doubt":"","references":[]},{"origin":"k-75abee92005a4e3d","title":"同步","qs":["国考 2025 地市级 行测#41"],"definition":"指相互关联的事物在时间上同时发生，或在进行的节奏、进度上保持一致。","explanation":"第41题中，风电和光伏发电具有间歇性，用电需求也时多时少，所以发电较多的时段可能与用电需求较高的时段错开。“同步”直接点明这种时序关系，“匹配”则泛指在某一方面相适应。","evidence":"存在不同时间尺度的间歇性","doubt":"","references":[]}]},"k-e00dbc5ed6270f33":{"review":{"definition":"指独自行动，常用来形容缺少他人配合而独力做事。","explanation":"第46题的“不再……而是……”要求第二空与“攥指成拳”形成对照。“单打独斗”说的是独自行动，“攥指成拳”说的是把力量集中起来协同行动。“故步自封”侧重守旧、安于现状，无法形成这一对照。","references":[],"evidence":"指独自一个人去打斗、做事","disposition":"独立词条","basis":"据原题和解析编释。","title":"单打独斗","related":[],"examFocus":{"国考 2025 地市级 行测#42":"第一空结合饱和袭击与单一目标拦截的冲突，第二空看所填成语能否与“攥指成拳”形成对照。"}},"readings":[{"origin":"k-e00dbc5ed6270f33","title":"单打独斗","qs":["国考 2025 行政执法 行测#46"],"definition":"指独自行动，常用来形容缺少他人配合而独力做事。","explanation":"第46题的“不再……而是……”要求第二空与“攥指成拳”形成对照。“单打独斗”说的是独自行动，“攥指成拳”说的是把力量集中起来协同行动。“故步自封”侧重守旧、安于现状，无法形成这一对照。","evidence":"指独自一个人去打斗、做事","doubt":"","references":[]},{"origin":"k-f6c870d92de9c5ea","title":"单打独斗","qs":["国考 2025 地市级 行测#42"],"definition":"指独自行动或做事，缺少与他人的配合。","explanation":"第42题“不再……而是……”把第二空与“攥指成拳”相对照。后者比喻把分散力量集中起来，前者就应写各自行动的状态。“故步自封”强调因循守旧，偏离了这里由单独行动转向协同的变化。","evidence":"“单打独斗”指独自一个人去打斗、做事","doubt":"","references":[]}]},"k-64dd9a0492f421f6":{"review":{"definition":"指写在纸上却没有兑现或落实、因而没有实际效力的文件、规定等。","explanation":"第47题首空以纪律为对象。“不执行、不遵守、不维护”说明再严明的纪律也可能只停留在纸面上，与下文“可有可无的空摆设”呼应。“徒劳无功”侧重付出了努力却没有成效，“事与愿违”侧重实际结果与愿望相反。","references":[],"evidence":"不执行、不遵守、不维护","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-22f6a0714d792958":{"review":{"definition":"明明知道某种行为不被允许，却故意去做。","explanation":"第47题第二空的“更”把两种违纪情形连成递进关系，从因不认真学习而违纪，推进到明知纪律要求仍故意违反。“有恃无恐”还需要有所倚仗，题中没有交代这类条件。","references":[],"evidence":"有不认真学习造成的情况，更有","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7539b96223354a09":{"review":{"definition":"比喻把某事物搁置起来，不去使用、处理或理会。","explanation":"第47题第三空的对象是“党的纪律要求”。前面的“把政治规矩置于脑后”和后面的“毫无自我约束”共同表明，这些人把本应落实的要求搁在一旁。“束之高阁”贴合这种搁置不理的做法。","references":[],"evidence":"指弃置不用或置之不理","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-434703dd967e9de2":{"review":{"definition":"把现成的经验、做法等原样搬用。","explanation":"第48题首空用“照搬”指出借鉴的限度。平原地区的耕地恢复方法到了山区可能不适用，说明借鉴需要根据本地条件调整。“效仿”只表示仿照，语义上未必包含原样采用。","references":[],"evidence":"平原地区的耕地恢复方法不一定适合山区","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3bf408e10338d2e1":{"review":{"definition":"形容两者相差很远。","explanation":"第48题第二空承接平原与山区的例子，指出粮食主产区与主销区在耕保相关条件上可能差异很大。“背道而驰”强调方向相反，题中只需说明地区差异足以影响经验的适用性。整组答案还需由第三空的“水土不服”确定。","references":[],"evidence":"粮食主产区与主销区可能差别很大","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7f4d754bc3f8776a":{"review":{"definition":"比喻在极大的范围内寻找极少或极小的目标，极难找到。","explanation":"第49题写循环肿瘤细胞在大量正常血细胞中极为稀少，因此首空强调找出目标的难度。“雾里看花”侧重看不清事物的真相，“无从下手”侧重缺少着手点。","references":[],"evidence":"在海量血细胞里寻觅数量极其稀少的循环肿瘤细胞","disposition":"独立词条","basis":"据原题和解析编释。","title":"大海捞针","related":[],"examFocus":{"国考 2025 副省级 行测#45":"结合循环肿瘤细胞的数量、仿生膜的捕获过程和细胞被带回时的状态，分别判断三处空缺应突出什么。"}},"readings":[{"origin":"k-7f4d754bc3f8776a","title":"大海捞针","qs":["国考 2025 行政执法 行测#49"],"definition":"比喻在极大的范围内寻找极少或极小的目标，极难找到。","explanation":"第49题写循环肿瘤细胞在大量正常血细胞中极为稀少，因此首空强调找出目标的难度。“雾里看花”侧重看不清事物的真相，“无从下手”侧重缺少着手点。","evidence":"在海量血细胞里寻觅数量极其稀少的循环肿瘤细胞","doubt":"","references":[]},{"origin":"k-88632be30459b75f","title":"大海捞针","qs":["国考 2025 副省级 行测#45"],"definition":"比喻在极大的范围内寻找极为稀少的事物，很难找到。","explanation":"题干用“十亿分之一”突出目标在海量血细胞中极为稀少，因此首空用“大海捞针”。“雾里看花”着重看不清，“异想天开”着重想法离奇，“无从下手”着重找不到着手的办法。","evidence":"在大海里捞一根针，比喻极难找到","doubt":"","references":[]}]},"k-506e1edabba06a60":{"review":{"definition":"形容一点损伤也没有。","explanation":"第49题第三空修饰“带回”，写的是循环肿瘤细胞在捕获并带回的过程中没有受损，与前文“媲美人体环境的仿生机制”相呼应。“轻而易举”描述操作的难易程度，“严丝合缝”描述接合紧密，都缺少这里需要的未受损之义。","references":[],"evidence":"连毫毛、头发这样细微的部位都没有损伤","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-628d9fec812499d8":{"review":{"definition":"形容流动、运行或表达通畅，少有阻碍。","explanation":"第50题末空的“顺畅”与前文“打通……堵点卡点”呼应，说明改革要减少先进优质生产要素流向新质生产力发展领域的障碍。“竞相”表示多个主体争相行动，文段强调的是流动条件的改善。","references":[],"evidence":"“顺畅”指通畅，没有阻碍","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a21869f503dc6c56":{"review":{"definition":"指法律上认定某种行为、事实或法律关系成立所需具备的条件。","explanation":"第55题A项用“构成要件”概括文段末尾对什么情形构成声音侵权的说明。文段先借AI模仿人声引出风险，再转向声音的法律保护，末尾以未经许可擅自使用录音制品中的声音或许可他人使用为例说明侵权情形。A项概括了这部分法律论述，B项只概括了前文引出话题时所说的风险。这里的侵权情形按文段表述理解。","references":[],"evidence":"指一定法律效果发生的前提条件","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d6c94fda4c1d006f":{"review":{"definition":"“邑”指城镇。“都”本指大城邑，后引申为具有重要政治地位的大城邑。“鄙”指边邑，即边远的小城。","explanation":"按题干给出的义项，“都”和“鄙”都属于“邑”，分别指大城邑和边远小城。D项用“邑”的大圈包住“都”和“鄙”两个互不相交的小圈，符合这一关系。A项把“邑”画在“都”里面，颠倒了包含关系。B项以“国”为外圈，但“国”可指诸侯封地或天子、诸侯的都城，题干未给出它涵盖所有“都”和“鄙”的依据。C项将三者画成彼此分离的圆，遗漏了“邑”对“都”和“鄙”的包含关系。","references":[],"evidence":"“都”指具有重要政治地位的大城邑，“邑”指城镇，“鄙”指边远的小城","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-129fa9d3fa8e0c34":{"review":{"definition":"按题设，凌汛指我国北方春季河冰解冻引起的涨水，伏汛指夏季三伏前后发生的汛水。","explanation":"依题设，凌汛属于春汛，伏汛属于夏汛。春季先于夏季，因此伏汛在凌汛之后。本题要求选出错误判断，故选C项“伏汛在凌汛前”。","references":[],"evidence":"伏汛是发生在夏季三伏前后的汛水，凌汛是春季河冰解冻引起的涨水现象","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-019d489e27fc9717":{"review":{"definition":"“殚精竭虑”指用尽精力、费尽心思，通常含褒义。“费尽心机”指挖空心思、想尽办法，通常含贬义。","explanation":"两词都涉及为达目的而费心，评价方向依次为褒、贬。C项“侃侃而谈、喋喋不休”在本题中同为先褒后贬，A项“狐假虎威、虚张声势”则同含贬义。","references":[],"evidence":"“殚精竭虑”是褒义词，“费尽心机”是贬义词","disposition":"独立词条","basis":"据原题和解析编释。","title":"殚精竭虑与费尽心机","related":[],"examFocus":{"国考 2025 地市级 行测#96":"类比词对时，既要比较两个词的语义是否相近，也要看褒贬色彩及其先后顺序。"}},"readings":[{"origin":"k-019d489e27fc9717","title":"殚精竭虑与费尽心机","qs":["国考 2025 行政执法 行测#97"],"definition":"“殚精竭虑”指用尽精力、费尽心思，通常含褒义。“费尽心机”指挖空心思、想尽办法，通常含贬义。","explanation":"两词都涉及为达目的而费心，评价方向依次为褒、贬。C项“侃侃而谈、喋喋不休”在本题中同为先褒后贬，A项“狐假虎威、虚张声势”则同含贬义。","evidence":"“殚精竭虑”是褒义词，“费尽心机”是贬义词","doubt":"","references":[]},{"origin":"k-2120fb0718d038b3","title":"殚精竭虑与费尽心机","qs":["国考 2025 地市级 行测#96"],"definition":"「殚精竭虑」指用尽精力、费尽心思，通常含褒义。「费尽心机」指挖空心思、想尽办法，通常含贬义。","explanation":"两词都涉及费尽心思。「殚精竭虑」侧重投入精力，「费尽心机」带有对谋划行为的负面评价。按本题解析的口径，题干的顺序是先褒后贬，A项「狐假虎威」「虚张声势」两词都含贬义，因而排除。","evidence":"“殚精竭虑”是褒义词，“费尽心机”是贬义词","doubt":"","references":[]}]},"k-257ed33b202f10e7":{"review":{"definition":"在本题设定中，透明胶是提取指纹所用的工具，提取指纹是收集罪证的一种方式。","explanation":"题干按“目的、行动、工具”的顺序排列。C项的“设置防护”也可服务于“道路施工”，但题中的混凝土未构成设置防护所用的工具，因此只对应上前一组关系。","references":[],"evidence":"透明胶是提取指纹的工具","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-a8407f3acc7f86fc":{"review":{"definition":"安全锤是紧急情况下用于破窗逃生的工具。","explanation":"B项中，“逃生自救”是目的，“敲碎车窗”是行动，“安全锤”是工具，三项的关系及顺序与题干“收集罪证、提取指纹、透明胶”一致。","references":[],"evidence":"安全锤是敲碎车窗的工具","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-816dea6278fc7824":{"review":{"definition":"本题所说的监管函，是监管部门发给被监管对象的书面通知，用于告知违规事实或风险，并要求补救、改正或防范。","explanation":"按本题口径，这类监管函归入行政文书。代入D项后，左侧由“行政文书”这一上位类别指向“监管函”这一下位类别，与右侧“计算机语言、汇编语言”的顺序一致。","references":[],"evidence":"监管函是一种行政文书","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-099fc02d038198d4":{"review":{"definition":"汇编语言是一类低级计算机语言，通常用助记符表示机器指令，并与特定的指令集相关。","explanation":"代入D项后，“计算机语言”是上位类别，“汇编语言”是下位类别，方向与左侧按题设归类的“行政文书、监管函”一致。","references":[],"evidence":"汇编语言是一种计算机语言","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2eb9a1e0825e1fa9":{"review":{"definition":"日均处理金额是统计期内平均每天处理的金额，等于该期处理总金额除以按统计口径计入的天数。","explanation":"第128题所求为2022年三季度的日均处理金额。根据2023年同期处理金额为5707.35亿美元、同比下降14.63%，用5707.35÷（1－14.63%）还原2022年三季度总额，约为6685.43亿美元。再按该季度92个自然日计算，日均约为72.67亿美元，落在B项的70亿至80亿美元之间。","references":[],"evidence":"日均处理金额","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-907bfaa463aaeda3":{"review":{"definition":"微视频是可用手机、摄像头等终端制作并在网上播放和分享的短视频，形式包括纪录短片、动画等。材料描述的常见时长为短至30秒，长的一般在10分钟以内。","explanation":"材料用“一般”描述微视频的常见时长，参考启事据此把30秒至10分钟写为本次大赛的投稿要求。时长3分28秒的《棋局人生 勿忘初心》符合这一要求，可列为参考作品。","references":[],"evidence":"短则30秒，长的一般在10分钟以内","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d63adb72557f1c72":{"review":{"definition":"数字经济是以数据为关键生产要素，直接或间接利用数据引导资源配置和使用、推动生产力发展的经济形态。","explanation":"数据可以为生产经营决策提供依据，进而引导人力、资金等资源的配置。B项说的“利用数据来引导资源发挥作用”符合这一含义，因此在本题的选非设问中应排除。","references":[],"evidence":"利用数据来引导资源发挥作用","disposition":"独立词条","basis":"据原题和解析编释。","title":"数字经济","related":[],"examFocus":{"江苏 2023 A类 行测#8":"从组织结构、资源配置、实体经济发展和社会经济活动四个方面辨析数字经济的影响。"}},"readings":[{"origin":"k-d63adb72557f1c72","title":"数字经济","qs":["江苏 2023 A类 行测#8"],"definition":"数字经济是以数据为关键生产要素，直接或间接利用数据引导资源配置和使用、推动生产力发展的经济形态。","explanation":"数据可以为生产经营决策提供依据，进而引导人力、资金等资源的配置。B项说的“利用数据来引导资源发挥作用”符合这一含义，因此在本题的选非设问中应排除。","evidence":"利用数据来引导资源发挥作用","doubt":"","references":[]},{"origin":"k-e35755358ec8bac7","title":"数字经济","qs":["江苏 2023 B类 行测#9"],"definition":"数字经济是以数据为关键生产要素，借助数字技术优化资源配置、推动生产力发展的经济形态。","explanation":"数据可以帮助生产者识别需求、安排供给和调度资源。B项所说的“利用数据来引导资源发挥作用”符合这一特征，因此在本题要求选出不正确说法时排除B项。","evidence":"利用数据来引导资源发挥作用","doubt":"","references":[]}]},"k-270f4bc351657efa":{"review":{"definition":"归根到底指归结到根本上，用来指出事物的根本性质或决定因素。","explanation":"第31题用“归根到底是”把综合国力竞争归结为人才和劳动者素质的竞争。“毋容置疑”强调判断的确定性，也能接在“是”前，但表达的是另一层意思。全题还需结合第二空的“共同发力”确定C项。","references":[],"evidence":"“归根到底”意为归结到根本上","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c7ec4c89e76e681e":{"review":{"definition":"发力指使出力量，也可比喻采取行动并发挥作用。","explanation":"第31题的“中国制造、中国创造、中国建造”是三个并列主体，“共同发力”突出它们各自发挥作用，合起来推动中国面貌发生变化。“共同努力”更侧重付出，和后文所写的实际变化相比，“发力”更贴合力量发挥作用的意思。","references":[],"evidence":"“发力”指把聚集的力量集中使出来","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7c6a181fd932d4de":{"review":{"definition":"摒弃指舍弃、抛弃。扬弃在本题所涉义项中指舍去旧事物中的消极因素，同时保留和发扬其中的积极因素。","explanation":"第32题说像素风格的文字去掉繁杂的设计，仍然别具一格，能够快速吸引受众。“繁杂的设计”在句中是被舍弃的对象，文段也未交代其中有哪部分被保留或发扬，因此第二空选“摒弃”。","references":[],"evidence":"“扬弃”指发扬旧事物中的积极因素，抛弃旧事物中的消极因素","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-56984e1d5f363621":{"review":{"definition":"脱颖而出比喻才华或本领显露出来，也可形容某个对象在同类中表现突出。层见叠出指接连出现，侧重出现的频次。","explanation":"第33题用“脱颖而出”写主打中华传统文化元素的动画电影表现突出，接着写相关产业链日渐生成，呈现创作与产业的活力。“层见叠出”能写这类电影接连出现，但单凭该词无法表达作品表现突出的意思。","references":[],"evidence":"“脱颖而出”比喻本领全部显露出来","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1bb2b48d584d8ecd":{"review":{"definition":"砥砺可比喻磨炼，也有勉励之意。","explanation":"第33题先写传统文化题材的动画电影崭露头角，再写相关产业链逐步形成。“创作与产业互相砥砺”借用磨炼、勉励的意思，形容电影创作和产业发展彼此促进，与后文“呈现生机勃勃的气象”相呼应。","references":[],"evidence":"“砥砺”指磨炼，勉励","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4f6259035ff4c910":{"review":{"definition":"体验侧重亲身经历，也可指由经历形成的体会。感受侧重受到外界影响后产生的主观感觉或体会。","explanation":"第34题中的“这些用心之处”指细致的服务和别出心裁的产品设计。“情绪体验”把良好的情绪与消费者接受服务、使用产品的过程联系起来。“情绪感受”也能指消费者产生的感觉，但对亲身经历这一层着墨较少，因此本题选“体验”。","references":[],"evidence":"“体验”指在实践中认识事物、亲身经历","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-657c6e36bb234c77":{"review":{"definition":"完备指应有的内容齐全或制度健全。完整侧重整体具备应有的各部分，没有缺损。","explanation":"第35题把法制作为实行法治的基础和前提，第二空要描述法律制度健全、齐备的状态，“完备”贴合这一语境。“完善”也可以形容法制，A、B两项最终由第三空的“实现法治”分出优劣。","references":[],"evidence":"“完备”指健全、齐全","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1e75db34fea7ed52":{"review":{"definition":"实现指使目标、愿望等成为现实。体现指某种性质、原则或现象通过具体事物表现出来。","explanation":"第35题的“立足点和归宿”“发展前途”和“最终”都指向要达成的目标。按题干的表述，法制是实行法治的基础，末空用“实现法治”说的是让法治成为现实。“体现”只能表达法治的原则或要求得到具体表现，无法表达本句的目标达成之意。","references":[],"evidence":"“实现”指使成为","disposition":"独立词条","basis":"据原题和解析编释。","title":"实现与体现","related":[],"examFocus":{"江苏 2023 A类 行测#35":"结合“立足点和归宿”与“发展前途”，辨析末空动词与“法治”搭配后表达的含义。"}},"readings":[{"origin":"k-1e75db34fea7ed52","title":"实现与体现","qs":["江苏 2023 A类 行测#35"],"definition":"实现指使目标、愿望等成为现实。体现指某种性质、原则或现象通过具体事物表现出来。","explanation":"第35题的“立足点和归宿”“发展前途”和“最终”都指向要达成的目标。按题干的表述，法制是实行法治的基础，末空用“实现法治”说的是让法治成为现实。“体现”只能表达法治的原则或要求得到具体表现，无法表达本句的目标达成之意。","evidence":"“实现”指使成为","doubt":"","references":[]},{"origin":"k-b9feab8482d68880","title":"实现与体现","qs":["江苏 2023 B类 行测#28"],"definition":"“实现”指使目标、愿望或设想成为现实。“体现”指某种性质、观念或现象通过具体事物表现出来。","explanation":"题干把法治称为法制的“立足点和归宿”，第三空说的是法制发展最终要达到的目标。“实现法治”表示让这一治国原则成为现实，“体现法治”侧重表现法治的理念或特征，因此第三空选“实现”。","evidence":"法治是法制的立足点和归宿","doubt":"","references":[]}]},"k-06d8ca0f95c71c87":{"review":{"definition":"一目了然指一眼就能看清楚或明白。有的放矢比喻说话或做事有明确的针对性。","explanation":"第37题说照片能呈现物种全貌，但特征乍看不明显。植物科学画着重呈现物种特征，末空写的是读者更容易一眼辨认特征，因此选“一目了然”。“有的放矢”可以形容画师选取特征时有针对性，侧重点在作画方式。","references":[],"evidence":"“一目了然”指一眼就能看清楚","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-26f0e81fd6179e98":{"review":{"definition":"相得益彰指双方相互配合、相互补充，使各自的长处更显著。取长补短指吸收别人的长处来弥补自己的不足。","explanation":"第三空承接“水乳交融”。题中先进的高科技产业和富有创新能力的企业家在城市中集聚，相互促进并持续对外释放能量，“相得益彰”贴合这种配合效果。“取长补短”需要有借对方长处弥补自身不足的语意，题中着重写的是两者已有的优势。","references":[],"evidence":"最先进的高科技产业和最具创新能力的企业家的集聚","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-68a63243ce939724":{"review":{"definition":"桂冠可比喻光荣的称号或荣誉。“摘取桂冠”表示赢得这样的称号或荣誉。","explanation":"题中各大科技强国的中心城市竞相争取成为全球“科创策源地”。第二空用“桂冠”，既把这一地位写成竞逐的荣誉，也和前面的“摘取”构成惯用搭配。","references":[],"evidence":"力图摘取全球“科创策源地”这一","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4fbfb8ba20742f07":{"review":{"definition":"吐故纳新比喻扬弃旧的、吸收新的，侧重通过新旧更替实现更新。","explanation":"题中社会新事物不断涌现，词库也随之更新，后文所举的“融媒体”“数据信托”等是吸纳新词的例子。“弃旧图新”侧重舍弃旧有状态、谋求新的变化，“去芜存菁”侧重筛去杂质、留下精华。“吐故纳新”最贴合词库随社会变化不断更新的过程。","references":[],"evidence":"“吐故纳新”比喻扬\n弃旧的，吸收新的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-02a0f0ce22ff1390":{"review":{"definition":"阐释指阐述并解释，将某个观点、文本或现象的含义讲清楚。","explanation":"题中先用“熟悉多少经典著作”衡量阅读积累，接着要衡量学者能在多大程度上解读经典、回应当代问题。“阐释”体现主动解读，“通晓”侧重理解和掌握。第一空的“诠释”也能表达解释之意，需结合后两空选定A项。","references":[],"evidence":"本着当代人面临的问题开展与伟大经典的对话","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e03ee051700aaf63":{"review":{"definition":"可遇不可求指有机会遇到或得到，但无法凭意愿强求。可望不可即指可以望见或向往，却难以接近或实现。","explanation":"材料说有些才能杰出者“或许可以”提出创造性思想，并认为创造性成果不宜预先设为目标。第二空用“可遇不可求”，突出成果有可能出现，却难以强求。“可望不可即”侧重目标难以企及，“不可多得”则侧重成果稀少。","references":[],"evidence":"有些才能杰出者或许可以提出富有创造性的思想","disposition":"独立词条","basis":"据原题和解析编释。","title":"可遇不可求与可望不可即","related":[],"examFocus":{"江苏 2023 A类 行测#40":"结合“或许可以”和“不应该是预先设立的目标”，辨析第二空的成语分别侧重成果出现的机会、目标能否企及，还是成果是否罕见。"}},"readings":[{"origin":"k-e03ee051700aaf63","title":"可遇不可求与可望不可即","qs":["江苏 2023 A类 行测#40"],"definition":"可遇不可求指有机会遇到或得到，但无法凭意愿强求。可望不可即指可以望见或向往，却难以接近或实现。","explanation":"材料说有些才能杰出者“或许可以”提出创造性思想，并认为创造性成果不宜预先设为目标。第二空用“可遇不可求”，突出成果有可能出现，却难以强求。“可望不可即”侧重目标难以企及，“不可多得”则侧重成果稀少。","evidence":"有些才能杰出者或许可以提出富有创造性的思想","doubt":"","references":[]},{"origin":"k-f3b40ee578191ceb","title":"可遇不可求与可望不可即","qs":["江苏 2023 B类 行测#31"],"definition":"“可遇不可求”指有机会遇到或获得，却难以靠刻意追求得来。“可望不可即”指可以望见或向往，却难以接近或达到。","explanation":"材料认为，有些才能杰出的人文学者或许会提出原创思想，甚至形成自己的理论体系，但这不应当成为预先设立的目标。第二空要表达的是成果可能出现、难以强求，所以“可遇不可求”比侧重目标难以企及的“可望不可即”更贴切。","evidence":"有些才能杰出者或许可以提出富有创造性的思想","doubt":"","references":[]}]},"k-a155771c95997ffe":{"review":{"definition":"水到渠成比喻条件成熟后，事情自然成功。铁杵磨成针比喻坚持努力，终能做成艰难的事情。","explanation":"第三空描述材料作者眼中独特理论体系的形成。作者把它视为学者在传承和解读经典的“修炼”过程中条件成熟后自然形成的成果，因此A项的“水到渠成”贴合文意。“铁杵磨成针”侧重靠持续努力攻克困难，与材料强调的自然形成有别。","references":[],"evidence":"不应该是预先设立的目标","disposition":"独立词条","basis":"据原题和解析编释。","title":"水到渠成与铁杵磨成针","related":[],"examFocus":{"江苏 2023 A类 行测#40":"判断第三空时，结合后文对研究目标的说明，辨析各成语对“修炼”过程与成果之间关系的侧重。"}},"readings":[{"origin":"k-a155771c95997ffe","title":"水到渠成与铁杵磨成针","qs":["江苏 2023 A类 行测#40"],"definition":"水到渠成比喻条件成熟后，事情自然成功。铁杵磨成针比喻坚持努力，终能做成艰难的事情。","explanation":"第三空描述材料作者眼中独特理论体系的形成。作者把它视为学者在传承和解读经典的“修炼”过程中条件成熟后自然形成的成果，因此A项的“水到渠成”贴合文意。“铁杵磨成针”侧重靠持续努力攻克困难，与材料强调的自然形成有别。","evidence":"不应该是预先设立的目标","doubt":"","references":[]},{"origin":"k-f2f2195da61a3b0e","title":"水到渠成与铁杵磨成针","qs":["江苏 2023 B类 行测#31"],"definition":"“水到渠成”比喻条件成熟后，事情自然取得结果。“铁杵磨成针”比喻持之以恒、不断努力，可以完成原本很难的事。","explanation":"第三空写人文学者在理解、解释经典并与经典对话的过程中，可能随着积累形成自己的理论体系。材料强调原创成果随条件成熟自然产生，因此选“水到渠成”。“铁杵磨成针”侧重为完成一件难事而长期坚持，与文段对预设原创目标的态度不合。","evidence":"人文学者“修炼”过程中","doubt":"","references":[]}]},"k-b3b4c659b23f380e":{"review":{"definition":"涵盖指把若干对象或方面包括在一定范围内，常用于说明内容或应用的范围。","explanation":"空格的主语是地球观测组织确定的“遥感9大应用领域”。B项“涵盖”适合引出灾害、卫生、能源等领域，后文再用“更是涉及”延展到人类生活的方方面面。“覆盖”可表示范围延伸到哪里，“囊括”突出全部收罗，“包含”侧重列明范围内有哪些成员。这里主要描述应用范围，“涵盖”最贴切。","references":[],"evidence":"更是涉及了人\n类生活的方方面面","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-207b65184384ec4a":{"review":{"definition":"椭圆边界上的点到中心的最小距离等于短半轴长。边界两点间的最大距离等于长轴全长，即长半轴长的两倍。","explanation":"短轴端点离中心最近，长轴端点离中心最远。任意两个边界点的距离至多是它们各自到中心的距离之和，长轴两端恰好达到这个上限。因此本题的短半轴为20米，长半轴为80÷2＝40米。","references":[],"evidence":"边界椭圆上一点到中心距离的最小值是20米，两点间距离的最大值为80米。","disposition":"独立词条","basis":"据原题和解析编释。","title":"椭圆的短半轴与长轴","related":[],"examFocus":{"江苏 2023 A类 行测#55":"辨认题给的两种距离各对应椭圆的哪个轴长，再考虑椭圆内正方形的面积上限。"}},"readings":[{"origin":"k-207b65184384ec4a","title":"椭圆的短半轴与长轴","qs":["江苏 2023 A类 行测#55"],"definition":"椭圆边界上的点到中心的最小距离等于短半轴长。边界两点间的最大距离等于长轴全长，即长半轴长的两倍。","explanation":"短轴端点离中心最近，长轴端点离中心最远。任意两个边界点的距离至多是它们各自到中心的距离之和，长轴两端恰好达到这个上限。因此本题的短半轴为20米，长半轴为80÷2＝40米。","evidence":"边界椭圆上一点到中心距离的最小值是20米，两点间距离的最大值为80米。","doubt":"","references":[]},{"origin":"k-b9349d7e5e1999e9","title":"椭圆的短半轴与长轴","qs":["江苏 2023 B类 行测#55"],"definition":"椭圆边界到中心的最小距离是短半轴长。椭圆上两点间的最大距离是长轴长，等于长半轴长的两倍。","explanation":"椭圆边界上的点到中心的距离介于短半轴长和长半轴长之间。由三角不等式，两点距离最多是长半轴长的两倍，长轴两端正好达到该上限。因此题中的20米直接给出短半轴，80米给出长轴，长半轴为40米。","evidence":"边界椭圆上一点到中心距离的最小值是20米，两点间距离的最大值为80米","doubt":"","references":[]}]},"k-0774aabdc09a0fff":{"review":{"definition":"元宇宙指借助数字技术构建的虚拟世界。","explanation":"本题的“宇宙”指现实中的宇宙，“元宇宙”借用这一词形来命名数字虚拟世界。D项“活化石”同样借用了“化石”的词形，实际指现存生物。C项“云计算”则属于计算方式，两个词的所指构成种属关系。","references":[],"evidence":"元宇宙指人类运用数字技术构建的虚拟世界","disposition":"独立词条","basis":"据原题和解析编释。","title":"元宇宙","related":[],"examFocus":{"江苏 2023 A类 行测#66":"比较原词和新词各自指什么，辨析新词是细分原有类别，还是借用原词指称另一类事物。","江苏 2025 A类 行测#71":"逐组判断后一个词描述的属性是前一个对象所必有的，还是取决于具体情况。"}},"readings":[{"origin":"k-0774aabdc09a0fff","title":"元宇宙","qs":["江苏 2023 A类 行测#66"],"definition":"元宇宙指借助数字技术构建的虚拟世界。","explanation":"本题的“宇宙”指现实中的宇宙，“元宇宙”借用这一词形来命名数字虚拟世界。D项“活化石”同样借用了“化石”的词形，实际指现存生物。C项“云计算”则属于计算方式，两个词的所指构成种属关系。","evidence":"元宇宙指人类运用数字技术构建的虚拟世界","doubt":"","references":[]},{"origin":"k-f4abfe03f07e6788","title":"元宇宙","qs":["江苏 2025 A类 行测#71"],"definition":"元宇宙是借助数字技术构建的虚拟空间，具有共享和交互等特征。","explanation":"虚拟性来自元宇宙的空间形态，本题据此将两词判为必然属性关系。A项实验的前瞻性、B项决策的可行性和C项宣传的普遍性均取决于具体情况，D项总结的概括性才与题干同类。","evidence":"元宇宙一定具有虚拟性","doubt":"","references":[]}]},"k-07f734b3a96465ad":{"review":{"definition":"活化石通常指延续至今、起源古老且保留若干祖先形态特征的生物或类群。部分释义强调缺少现存近似种，学术用法也涵盖仍有少数现存物种的古老类群。","explanation":"D项的“活化石”借用“化石”来称呼现生生物，题干的“元宇宙”也借用“宇宙”来命名数字虚拟空间，两组复合词都指向与原词类别不同的对象。C项的“云计算”仍属于计算方式，因而D更贴合题干关系。解析中“没有其他现存的相似物种”属于较窄的释义，判断本题只需区分现生生物和古生物遗存。","references":[{"source":"web-2348e6fc2c532db2","location":"“活化石”词目，释义","quote":"沒有現存的近似種"},{"source":"web-458e1db467ff8c70","location":"Introduction，列举鲎类等典型例子的段落","quote":"all have few surviving species"}],"evidence":"活化石又称遗迹生物","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-4c2fada94d5a3550":{"review":{"definition":"布衣本指粗布衣服，借指平民百姓。","explanation":"题干由服饰借指穿着这类服饰的人。D项“巾帼：女子”也由服饰借指一类人。C项“须眉：男子”虽也借指人，但借用的是胡须和眉毛这两种身体特征，因此D项更贴合题干。","references":[],"evidence":"布衣指粗布衣服，借指平民百姓","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-317aa0fbbe75d177":{"review":{"definition":"巾帼本指古代妇女的头巾和发饰，借指女子。","explanation":"D项从女子的头饰借指女子，与题干从粗布衣服借指平民百姓一样，都由服饰引出人物称谓。A项“鸿雁”借指的是书信，C项“须眉”借用的是人的外貌特征。","references":[],"evidence":"巾帼是古代妇女戴的头巾和发饰，代指女子","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0f6aa2750205a3b3":{"review":{"definition":"交通枢纽是运输线路交会、衔接，并组织客货到发或中转的节点及其设施。","explanation":"一个站点是否属于交通枢纽，取决于它是否发挥运输衔接等功能。C项的“车站”包括只服务单条线路的小型公交站，因此车站这一大类无法整体归入交通枢纽。B项的作揖和握手则都可归入行礼方式。","references":[],"evidence":"一种或多种运输方式的交通干线相互交叉与衔接之处","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-97329b5211f0fa50":{"review":{"definition":"精装书是采用精装方式装订的实体书，通常配有较坚固的封面。","explanation":"畅销说的是销量，精装说的是装订，同一版本可以兼具两种属性。按本题以书籍版本为单位的比较，精装书是实体装订版本，电子书是数字版本，二者属于不同类别。同一作品可以同时发行这两个版本。","references":[],"evidence":"精装书指装订精致的书，和电子书为反对关系。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f3e69aa9f698c38d":{"review":{"definition":"自由诗是形式较自由的诗，音节、韵律等可以随表达需要安排，无须遵循固定格律。","explanation":"B项的“自由诗”按形式界定，“叙事诗”按主要内容和表达方式界定。自由诗可以用来叙事，叙事诗也可以采用固定格律，所以两类相交，对应题干的“畅销书：精装书”。","references":[],"evidence":"自由诗是没有规则的音节、韵律及其他正规设计的诗。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-aa410becb288f3dc":{"review":{"definition":"本题按诗歌的主要内容和表达方式区分抒情诗、叙事诗和说理诗，分别以抒发情感、叙述事件和阐说道理为主。","explanation":"在B项采用的分类口径下，叙事诗和抒情诗按作品的主要表达重心归为不同类别，对应题干中精装书与电子书的反对关系。作品可以兼有叙事和抒情成分，本题比较的是它们在这一分类口径下的主要归属。","references":[],"evidence":"诗歌按内容分为抒情诗、叙事诗、说理诗","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-60a13c6e18d32687":{"review":{"definition":"句号是句末点号，用于陈述句等句子的末尾，表示句子结束。","explanation":"C项从书写形式看，句号是相应句子的组成部分，绳索是题中秋千的组成部分，两组均按“整体→部分”排列。D项把句号和秋千分别归入标点符号和玩具，但代入后两组的种属顺序相反。","references":[],"evidence":"句号是句子的组成部分","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-46df713a1dc9efda":{"review":{"title":"实数的分类","type":"概念与词义","definition":"实数分为有理数和无理数。有理数能表示为两个整数之比，分母不为零。其余实数为无理数。","explanation":"任意整数都可写成以1为分母的分数，因此整数属于有理数。整数和无理数都属于实数，两个集合没有共同元素。","basis":"据关联原题及所列出处编释。","references":[{"source":"real","location":"3.6 · 有理数与无理数"}],"examFocus":{"江苏 2023 A类 行测#75":"分别为每组两个词寻找共同上位概念，检查候选类别能否同时涵盖两者。"}},"aspects":[{"title":"整数与无理数的共同上位概念","uses":[{"unit":"Q1","role":"解题依据","use":"无理数和整数均归入实数，哲学和历史均归入学科。两侧都要求找出能够同时涵盖所给两项的上位概念，因此选D项“实数 学科”。","evidence":"无理数和整数都是实数","qids":["江苏 2023 A类 行测#75","江苏 2023 B类 行测#75"]}]}]},"k-10a2186a077901a9":{"review":{"definition":"哲学和历史学都是学科。本题中的“历史”指历史学。","explanation":"D项中，无理数和整数分别属于实数，哲学和历史学分别属于学科，两组都是两个下位概念指向同一个上位概念。C项中，无理数和整数是数学的研究对象，典籍则可记载哲学或历史的相关内容，两侧关系不同。","references":[],"evidence":"哲学、历史都是学科门类","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-82f041a33d4e323e":{"review":{"definition":"诉诸无知是仅凭缺少证明某命题为真的证据就断定它为假，或仅凭缺少证明它为假的证据就断定它为真的论证错误。","explanation":"小李从“没有证据证明外星人存在”推出“外星人一定不存在”。B项乙仅凭自己没看到老王一家出去，便判断他们没有外出散步，采用了相同的论证结构。C项乙亲眼见过老赵不聪明的时候，这一观察直接支持“老赵有时不聪明”。","references":[],"evidence":"没有任何有关外星人存在的证据，所以外星人一定不存在","disposition":"独立词条","basis":"据原题和解析编释。","title":"诉诸无知","related":[],"examFocus":{"江苏 2023 A类 行测#101":"比较题干和选项的论证时，留意各自是缺少支持某个判断的证据，还是掌握了能直接支持其结论的观察。"}},"readings":[{"origin":"k-82f041a33d4e323e","title":"诉诸无知","qs":["江苏 2023 A类 行测#101"],"definition":"诉诸无知是仅凭缺少证明某命题为真的证据就断定它为假，或仅凭缺少证明它为假的证据就断定它为真的论证错误。","explanation":"小李从“没有证据证明外星人存在”推出“外星人一定不存在”。B项乙仅凭自己没看到老王一家出去，便判断他们没有外出散步，采用了相同的论证结构。C项乙亲眼见过老赵不聪明的时候，这一观察直接支持“老赵有时不聪明”。","evidence":"没有任何有关外星人存在的证据，所以外星人一定不存在","doubt":"","references":[]},{"origin":"k-ecc772b38188ad0f","title":"诉诸无知","qs":["江苏 2023 B类 行测#99"],"definition":"诉诸无知是一种论证谬误，指仅凭缺乏证明某命题为真的证据就断定它为假，或仅凭缺乏反证就断定它为真。","explanation":"小李仅凭没有外星人存在的证据就断定外星人一定不存在。B项的乙仅凭自己没看到老王一家出门，就推断他们都没有外出散步，两者都把缺乏观察证据当作否定命题的依据。C项的乙亲眼见过老赵不聪明的时候，这些实例直接支持“老赵有时不聪明”。","evidence":"没有任何有关外星人存在的证据，所以外星人一定不存在","doubt":"","references":[]}]},"k-5a4912f08618e0d8":{"review":{"definition":"在本题的行政执法语境中，善治指以建设和谐、有序、健康的法治环境为目标，通过执法主体与社会成员的良性互动改善治理。","explanation":"范文从治理目标和实现方式两方面解释善治。材料6中，顾警官花时间讲解交通规则，曾受处罚者中有人邀请他进社区普法，也有人主动担任交通协管员。这些细节说明题目所说的“相向而行”包含执法者主动沟通和社会成员理解、配合、参与两个方面。","references":[],"evidence":"还表现在治理主体与社会成员间的良性互动和交流。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4fd44da12cb9939b":{"review":{"definition":"光电子技术是光子技术与电子技术相结合形成的技术，涉及光显示、光存储、激光等领域。","explanation":"以光显示为例，电子电路控制显示信号，光学器件呈现画面，两类技术在同一系统中各有分工。C项把这种互补关系说成替代关系，因此是本题应选的错误说法。","references":[],"evidence":"光电子技术和电子技术应是相互补充","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0e7f3abb1ef90ab5":{"review":{"definition":"新污染物是指新近发现或受到关注、对生态环境或人体健康存在风险，且尚未纳入管理或现有管理措施不足以有效防控其风险的污染物。","explanation":"A项抓住了管理尚未覆盖或措施不足这一判别条件。B项把常受关注的持久性有机污染物和微塑料扩大成一般的有机污染物和塑料。部分风险在短期内较隐蔽，治理还要开展风险筛查与评估，因此C项的短期危害明显、D项的主要依靠达标排放均不成立。","references":[],"evidence":"尚未纳入管理或现有管理措施不足以有效防控其风险的污染物","disposition":"独立词条","basis":"据原题和解析编释。","title":"新污染物","related":[],"examFocus":{"江苏 2023 A类 行测#7":"辨析新污染物的认定条件、类别范围、危害特征和全过程治理要求。"}},"readings":[{"origin":"k-0e7f3abb1ef90ab5","title":"新污染物","qs":["江苏 2023 B类 行测#8"],"definition":"新污染物是指新近发现或受到关注、对生态环境或人体健康存在风险，且尚未纳入管理或现有管理措施不足以有效防控其风险的污染物。","explanation":"A项抓住了管理尚未覆盖或措施不足这一判别条件。B项把常受关注的持久性有机污染物和微塑料扩大成一般的有机污染物和塑料。部分风险在短期内较隐蔽，治理还要开展风险筛查与评估，因此C项的短期危害明显、D项的主要依靠达标排放均不成立。","evidence":"尚未纳入管理或现有管理措施不足以有效防控其风险的污染物","doubt":"","references":[]},{"origin":"k-6f1326a0b4d07313","title":"新污染物","qs":["江苏 2023 A类 行测#7"],"definition":"新污染物是新近发现或受到关注、对生态环境或人体健康存在风险，且尚未纳入管理或现有措施不足以有效防控其风险的污染物。","explanation":"A项抓住了有效管理的两种缺口，尚未纳管和已纳管但措施不足。B项将持久性有机污染物和微塑料分别扩大为有机污染物和塑料，超出了题中所述类别的范围。","evidence":"尚未纳入管理或现有管理措施不足以有效防控其风险","doubt":"","references":[]}]},"k-27b8f9ad0f6a70a9":{"review":{"definition":"医疗机构发布医疗广告前须申请审查，经审查取得《医疗广告审查证明》后方可发布获准的广告。行政机关经申请和审查准予申请人从事特定活动，属于行政许可。","explanation":"H市行政审批局出具证明后，整形公司才获准发布经审查的电视广告。分类取决于出具证明的法律效果。行政确认是对已有的法律事实、关系或状态作出认可，本案的证明则赋予公司发布特定广告的资格，因此C项将其归为行政确认有误。","references":[],"evidence":"出具《医疗广告审查证明》，准许某整形公司发布电视广告","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b88315f111a3dfe3":{"review":{"definition":"“完备”侧重健全齐备，“完善”侧重周全良好，也可指使事物趋于健全。“完整”侧重整体各部分无缺，“完全”常表示全部或程度达到十足。","explanation":"第二空说实行法治须具备怎样的法制，着眼于法律制度是否健全齐备，“完备的法制”贴合这一条件。“完善的法制”也搭配自然，因此第二空可保留 A、B 两项，再由第三空的“实现法治”确定 B 项。","references":[],"evidence":"“完善”指完备良好，B项“完备”指健全、齐全","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-04916cf89a33d8ba":{"review":{"definition":"形容看到的事物好到极点，令人赞叹。常用“令人叹为观止”表达对事物的赞叹。","explanation":"第一空直接修饰人工智能在音乐、绘画、棋艺等方面取得的“进步”。“令人惊叹的进步”直接写进步带给人的感受，在这个结构中比“叹为观止的进步”更自然。解析列举的是“叹为观止”的常见用法，这里的取舍限于本题搭配。","references":[],"evidence":"“令人叹为观止”或“使人叹为观止”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2ad30cd6ebbf8471":{"review":{"definition":"人人都能看见，形容事实或成就十分明显，常用来对已提到的情况作判断，如“这些进步有目共睹”。","explanation":"“有目共睹的进步”可以理解为大家都看得到的进步，“进步”在这里是被修饰的名词。题干把音乐、绘画、棋艺等方面的显著进步与文学创作的相对滞后放在一起，“令人惊叹”更直接地突出进步的程度。D 项还用“迟缓”描述文学创作，侧重进展的速度，B 项的“滞后”更贴合题中的相对差距。","references":[],"evidence":"有目共睹 迟缓 证明","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4d1cea5d9e48c769":{"review":{"definition":"“滞后”指进度或发展水平相对靠后。“落伍”本指掉队，也常指跟不上集体或时代的发展。","explanation":"题干先写人工智能在音乐、绘画、棋艺等方面进步显著，后写人类读者对书面语的句法和语义有更强的感知能力。第二空据此描述人工智能在文学创作上的相对差距，用“滞后”更贴切。“落伍”容易让人理解为跟不上时代或同行的发展。","references":[],"evidence":"人类读者对有意义的书面语中大量的句法和语义有更强的感知能力","disposition":"独立词条","basis":"据原题和解析编释。","title":"滞后与落伍","related":[],"examFocus":{"江苏 2023 A类 行测#36":"辨析第二空时，先确定人工智能文学创作表现的比较对象，再看备选词各自适用于哪种比较。"}},"readings":[{"origin":"k-4d1cea5d9e48c769","title":"滞后与落伍","qs":["江苏 2023 B类 行测#29"],"definition":"“滞后”指进度或发展水平相对靠后。“落伍”本指掉队，也常指跟不上集体或时代的发展。","explanation":"题干先写人工智能在音乐、绘画、棋艺等方面进步显著，后写人类读者对书面语的句法和语义有更强的感知能力。第二空据此描述人工智能在文学创作上的相对差距，用“滞后”更贴切。“落伍”容易让人理解为跟不上时代或同行的发展。","evidence":"人类读者对有意义的书面语中大量的句法和语义有更强的感知能力","doubt":"","references":[]},{"origin":"k-5347e4bafa3d40e3","title":"滞后与落伍","qs":["江苏 2023 A类 行测#36"],"definition":"滞后指进度、发展水平等落在参照对象之后。落伍本指掉在队伍后面，也常指跟不上时代或潮流。","explanation":"第36题先说人工智能在音乐、绘画、棋艺等领域已有显著进步，再说它在文学创作领域“比较滞后”，并以人类读者对书面语句法和语义的感知优势作说明。这里着重描述文学创作上的相对差距，“落伍”则更容易让人理解为跟不上时代。","evidence":"“滞后”意为事物落在形势发展的后面","doubt":"","references":[]}]},"k-eaf1ece772e7087a":{"review":{"definition":"指双方相互配合、相互补充，使各自的长处更加显明。","explanation":"第三空承接“水乳交融”，说明先进高科技产业和有创新能力的企业家在同一城市集聚后，彼此促进并发挥各自优势，进而向外释放创新能量。“取长补短”着眼于用对方的长处弥补自身不足，题干着眼于双方已有的优势如何在结合后得到发挥。","references":[],"evidence":"相互帮助，相互补充，更能显出各自的好处","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ef1444374d07b201":{"review":{"definition":"“孕育”比喻在一定条件下酝酿、产生新事物，侧重形成过程。“蕴含”指内部包含着某种内容、意义或潜力，侧重包含关系。","explanation":"第一空写广阔市场为需求的形成和发展提供条件。“也”将这层意思与技术进步不断积蓄升级动力并列，后文又写企业瞄准需求、升级供给，进而创造新机会。“孕育”更能表现这段话中的动态过程，“蕴含”更适合突出市场中存在需求或潜力。","references":[],"evidence":"技术的不断进步也积蓄着升级的动力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e779e19d46b15bcb":{"review":{"definition":"融合指不同事物相互结合、形成整体。集聚指事物聚集在一起，在产业语境中常指向一定区域集中。","explanation":"第36题第一空谈农村一、二、三产业的关系。农产品加工、乡村休闲旅游和农村电商分别把农业生产与加工、服务、销售联系起来，「融合」能体现产业之间相互渗透、共同发展。「集聚」描述产业的空间集中，单凭集中还看不出产业之间如何衔接。","references":[],"evidence":"推进农村一、二、三产业","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8b507e80a7d103b6":{"review":{"definition":"联动指相互关联的事物中，一方的运作或变化带动其他各方。联合指各方结合起来，共同行动或组成整体。","explanation":"第36题第二空前列出生产、加工、销售、消费等环节，并指出县城、乡镇、中心村各有分工。「城乡联动」突出这些环节跨城乡衔接、彼此带动。「城乡联合」更容易使人想到城乡各方共同采取某项行动，弱化了题干强调的分工和环节衔接。第二空由此判定选A。","references":[],"evidence":"形成县城、乡镇、中心村分工合理的产业空间结构","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c22c605025bff76c":{"review":{"definition":"应对指面对出现的情况，采取相应措施加以处理。","explanation":"第37题第一空的宾语是「眼前的现实」。「以往的设想和经验已经不能完全应对眼前的现实」说的是旧有经验不足以解决当前基层治理中遇到的问题。「适用」也能表达旧经验与当前情况的适合程度，因此第一空可以保留A、C，最终由第二空判定选A。","references":[],"evidence":"以往的设想和经验已经不能完全","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-43005d0084dad59c":{"review":{"definition":"因事施策指根据具体事情的情况，制定或采取适当的措施。","explanation":"第37题说旧有设想和经验不足以应对眼前的现实，智力支撑应帮助基层治理在探索中持续调整。「因地制宜」强调依据地方条件，「因事施策」强调依据具体问题，「久久为功」强调持续用力。C项「未雨绸缪」强调预先准备，在此处没有体现按具体问题调整措施的意思。","references":[],"evidence":"“因事施策”指根据具体事情，制定或采取适当的措施","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-06f2d2f7676ee476":{"review":{"definition":"调配在颜料等材料的语境中指调和、配合，使材料适合使用。","explanation":"第38题第一空的对象是从矿物质中提炼出的青绿颜料，空格位于「经过适当」之后，用来表示对颜料作所需的调和处理。「调配」与该对象和处理过程相合，可用于验证第二空选出的C项。","references":[],"evidence":"“调配”指调和、配合，通常搭配“颜料”“药物”等","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f85f1655d139c8ba":{"review":{"definition":"脱颖而出比喻人的才干显露出来，也可引申为事物凭自身优势在同类中显现。","explanation":"第38题把「脱颖而出」用于石青、石绿。材料先说两种颜料色彩艳丽、性能稳定，再说它们成为山水画设色的常用颜色，突出的是凭优势受到采用。「一枝独秀」会进一步强调在同类中最为突出，「历久弥新」则强调历经时间仍显新意，与这里从颜料优势推到常用的关系不同。","references":[],"evidence":"成为中国山水画设色常用的颜色","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3971b228296010d7":{"review":{"definition":"汲取指吸取、吸收，常用于经验、知识、养分等可被吸收利用的对象。","explanation":"第39题第一空的宾语是「网络语言中的优质部分」。后文说要把这些成分「巧妙融入新闻报道用语」，说明这里表达的是吸收并用于报道。「汲取」与这一过程相合，可用于验证第二空选出的C项。","references":[],"evidence":"网络语言中的优质部分，巧妙融入新闻报道用语","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bc6d5d9001c7ddea":{"review":{"definition":"足不出户指不走出家门，可用于表示人在家中即可办事或获得某种体验。","explanation":"第40题第三空接「就能获得丰富的文化体验」。「足不出户」具体写出数字化保护带来的地点便利，即人在家中也能获得文物相关的文化体验。「轻而易举」强调做事容易，「触手可得」强调取得容易，二者都缺少居家即可体验这一层意思。","references":[],"evidence":"就能获得丰富的文化体验","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2827d3ab4c9351f5":{"review":{"definition":"涵盖强调某个范围包括哪些对象。覆盖从遮盖引申为延伸到一定范围，囊括强调全部收入，包含着重整体中含有某些成分或项目。","explanation":"第41题以「遥感9大应用领域」为主语，先列举灾害、卫生、能源等，再以「更是涉及」将表述扩展到人类生活的方方面面。「涵盖」适合引出应用范围的列举。「覆盖」侧重范围所及，「囊括」容易读出收尽全部对象的意味，「包含」虽能引出列项，但更侧重整体与组成项目的关系。这里的递进来自前面列举的领域与后面生活各方面的范围差异。","references":[],"evidence":"天气、生态系统、农业、生物多样性等，更是涉及了人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5d8c63e56f9c4a5d":{"review":{"definition":"本题所称的5G城市，指将第五代移动通信技术应用于城市服务等场景的城市。","explanation":"题干由所用技术“5G”指向应用该技术的“5G城市”。C项也由所用技术指向应用方式，电子邮件利用电子技术传递信息。A项对应所在地点，B项是类别包含，D项对应涂料。","references":[],"evidence":"5G城市利用了5G技术","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ac91bdf668f9e852":{"review":{"definition":"电子邮件是利用电子手段发送和接收信息的通信方式，也可指通过这种方式传送的邮件。","explanation":"C项取通信方式这一义项，“电子”指出邮件传递所用的技术手段，和题干中“5G”指出城市应用所用的通信技术相对应。","references":[],"evidence":"电子邮件是一种利用电子手段提供信息交换的通信方式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-726293a3425f1762":{"review":{"definition":"一人发出号召，许多人响应，形容号召力强。","explanation":"“一呼”是发出号召，“百应”是号召引起的响应。题干拆分后呈现动作与结果的关系，与A项先射出一箭、继而射中两只雕相同。C项“一曝十寒”虽然也有先后顺序，但“十寒”表示接着受冻的过程，并非曝晒造成的结果。","references":[],"evidence":"先有“一呼”的动作，再有“百应”的结果","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-303dc66f0dec7d4c":{"review":{"definition":"一箭射中两只雕，比喻做一件事同时取得两方面的收获。","explanation":"本题按字面义拆分，“一箭”指射出一箭，“双雕”指射中两只雕，前者是动作，后者是动作产生的结果。这个关系对应“一呼”引起“百应”，所以选A。","references":[],"evidence":"先有“一箭”的动作，再有“双雕”的结果","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0616efac67bdb050":{"review":{"definition":"吴语是汉语的一类方言。","explanation":"题干由“吴语”到“汉语”是由下位类别到上位类别，和C项由“数学”到“理学”的方向一致。D项“壮族”到“民族”也符合这个方向，但第三项“苗族”仍属于“民族”，因此整组关系不同。","references":[],"evidence":"吴语是汉语方言之一","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-32f79e9560f1017e":{"review":{"definition":"通例指一般通行的做法或常规，在这一义项上与“惯例”近义。","explanation":"题干前两项“通例”和“惯例”是近义词。第三项“国际惯例”按适用范围限定了“惯例”，属于惯例的一种。因此，正确选项也要满足前两项近义、第三项是第二项的具体情形。","references":[],"evidence":"通例指一般的情况、常规、惯例，与惯例是近义关系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b3aa19f3f87849d1":{"review":{"definition":"预备指为将要发生的事预先做好准备，侧重“预先”，在这一义项上与“准备”近义。","explanation":"B项前两项“预备”和“准备”近义。“精心”限定了准备时用心的程度，“精心准备”仍是一种准备。两组词都是前两项近义，第三项在第二项的基础上增加限定。","references":[],"evidence":"预备指预先准备，与准备是近义关系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7ed5ac98473c5002":{"review":{"definition":"团雾可使局部路段的能见度骤降，暴雪可因强降雪造成道路积雪。按本题的分类，两者均属于恶劣天气。","explanation":"D项第一项团雾天气和第三项暴雪天气是并列的两种天气，分别从属于第二项恶劣天气。这与人口普查和经济普查分别从属于国情普查的位置和方向一致。","references":[],"evidence":"团雾天气和暴雪天气都是恶劣天气","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-008998b77f878330":{"review":{"definition":"蛛丝是蜘蛛分泌形成的丝，可用于织网。","explanation":"D项按“蜘蛛有蛛丝”和“人才有能力”的方向配对。这里的共同点是前项具有后项，蛛丝具体是蜘蛛产生的丝。B项的蛛网则是用丝织成的结构，而能力之于成功涉及条件关系。","references":[],"evidence":"蜘蛛有蛛丝","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-faca71dcd5f6589d":{"review":{"definition":"本题中的“人才”指有才能的人，才能体现为其具备的能力。","explanation":"D项把“人才”放在“能力”前，构成“人才有能力”，与“蜘蛛有蛛丝”的方向一致。A项的“才干”本身表示才能，与“能力”近义。","references":[],"evidence":"人才有能力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c86358d68d6cd0a4":{"review":{"definition":"水平尺可用于检验物体或表面是否水平，激光水平仪可提供水平测量或找平所需的激光基准。","explanation":"B项按共同用途把水平尺和激光水平仪视为并列的测量工具。A项中的“水平仪”是“激光水平仪”的上位概念，属于上位概念在前的种属关系，而另一组“抛石机—机器”的顺序相反。","references":[],"evidence":"水平尺和激光水平仪都是一种测量工具","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3ff7f6ceea906f18":{"review":{"definition":"抛石机是抛射石块的历史器械，火炮是发射弹丸的武器。本题按投射这一共同用途比较二者。","explanation":"B项将抛石机与火炮视为具有共同用途的两类器械，和水平尺、激光水平仪的并列关系相对应。C项的“石头”与抛石机构成器械与投射物的对应关系。","references":[],"evidence":"二者都可以用来投射，为并列关系","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-0a3f89aacb1f229c":{"review":{"definition":"学科是按研究对象、问题或方法等划分的知识领域。哲学和历史（历史学）都是学科。","explanation":"D项中，哲学和历史分别属于学科，正如无理数和整数分别属于实数，两侧都是种属关系。C项中的数学以无理数和整数为研究对象，典籍可以记载哲学和历史的相关内容，两侧的关系不同。","references":[],"evidence":"哲学、历史都是学科门类","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a0588a544fbce877":{"review":{"definition":"在本题中，阅读推广指以普及阅读为目的的公益活动，阅读推销指借助直播等营销手段促成图书销售的活动。","explanation":"材料5的走读、亲子阅读和社区活动主要让更多人参与阅读，适合从活动供给、触达和持续性分析。材料6的直播荐书以促成购书为直接目标，适合从市场成效、选书质量和营销方式分析。董主播讲苏轼故事后促成销售，体现了阅读分享也可以成为售书方式。","references":[],"evidence":"董主播只是“阅读推销”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-13180bbfd51c959f":{"review":{"title":"全民阅读推广与服务","type":"概念与词义","definition":"全民阅读推广通过荐书、读书会等活动吸引公众参与阅读，培养阅读兴趣和习惯。全民阅读服务通过公共阅读空间、阅读资源和无障碍设施等，为不同人群提供参与阅读的条件。","explanation":"图书馆和社区可以结合读书活动与日常服务，既吸引读者参与，也方便读者持续阅读。公益阅读推广着重分享和普及阅读，直播售书以销售图书为直接目的，讲书和荐书可以同时发挥两种作用。《“十四五”规划纲要》提出深入推进全民阅读、建设书香中国。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"江苏 2024 A类 申论#2":"对照资料5和6，按活动宗旨、服务对象和运作方式归纳阅读推广与直播售书中出现的问题。","江苏 2024 A类 申论#4":"结合首届全民阅读大会贺信和资料8，论证阅读习惯如何养成、公共阅读服务如何支持公众参与。"}},"aspects":[{"title":"公益阅读推广与直播售书","uses":[{"unit":"Q1","role":"直接考查","use":"本题依据资料5和资料6辨析两类活动。图书馆早期亲子阅读活动名额紧张，反映活动供给有限。直播讲书可以兼具阅读分享和促销作用，材料也提到直播渠道出现低价盗版书的问题。","evidence":"“给定资料5-6”中提到的“阅读推广”与“阅读推销”是现实生活中的常见现象，这两类现象涉及哪些问题？请围绕这些问题谈谈你的认识。","qids":["江苏 2024 A类 申论#2"]}]},{"title":"全民阅读倡导与公共服务","uses":[{"unit":"Q2","role":"解题依据","use":"本题以首届全民阅读大会贺信中的倡导为立意依据。党员干部带头读书、儿童养成阅读习惯、全社会共同参与，分别体现了不同群体的参与方式。资料8中的公共图书馆免费开放、农家书屋和读书节可用于论述阅读设施和推广活动如何支持公众参与。","evidence":"修身养志，增长才干；希望孩子们养成阅读习惯，快乐阅读，健康成长","qids":["江苏 2024 A类 申论#4"]}]}],"sources":[{"id":"4d94680ab5558551","label":"完善全民阅读推广服务体系","topic":"就业、社保与公共服务","category":"非时政","text":"2.完善全民阅读推广服务体系\n全民阅读促进工作坚持中国共产党的领导，坚持以习近平新时代中国特色社会主义思想\n为指导，贯彻落实习近平文化思想，坚持以人民为中心，坚定文化自信，发展社会主义先进\n文化，弘扬革命文化，传承中华优秀传统文化。\n全民阅读促进工作坚持以社会主义核心价值观为引领，传播有益于公民全面发展和社会\n文明进步的科学文化知识，激发公民阅读兴趣，培养公民阅读习惯，增强公民阅读能力，提\n升公民阅读质量，形成全社会爱读书、读好书、善读书的浓厚氛围。\n全民阅读促进工作由党委领导、政府主导、社会力量参与，按照公益性、基本性、均等\n性、便利性的要求，构建全民覆盖、普惠高效的全民阅读促进体系，涵育文明风尚，厚植家\n国情怀，增强实现中华民族伟大复兴的精神力量。\n每年 4 月第四周为全民阅读活动周。\n——《全民阅读促进条例》","source":{"doc":"6cbfb01fe723bba64b75","first":44,"last":44,"page":44,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-1ab558c29da24f2f":{"review":{"definition":"以取得利润并将利润分配给股东等出资人为目的成立的法人，是营利法人。有限责任公司属于营利法人。","explanation":"法人是否属于营利法人，要看其设立目的是否包括向出资人分配利润。D项中的有限责任公司属于营利法人。熊某作为小股东出资设立该公司，持股份额小也不改变公司性质或其参与设立公司的事实。","references":[],"evidence":"营利法人包括有限责任公司、股份有限公司和其他企业法人等。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1ef1178fc2c70e25":{"review":{"definition":"工商业联合会是以民营企业和民营经济人士为主体的人民团体和商会组织，具有统战性、经济性和民间性。","explanation":"A项中何某兼任的是市工商联主席。工商联的成员虽包括民营企业和民营经济人士，工商联本身属于人民团体和商会组织，因此该职务不在本题所问的企业或其他营利性组织兼职禁令范围内。","references":[],"evidence":"人民团体和商会组织，并非营利性组织","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-69a6c518f8f529f5":{"review":{"definition":"组织职能是指为完成既定任务，明确由谁承担各项工作，并协调各方分工与配合。","explanation":"“二牛抬杠”中，两头牛共同牵引，人员分别承担牵牛、调节入土深浅和扶犁等工作，各环节配合完成耕作，最能体现组织职能，对应D项。调节犁铧深浅是其中一项作业分工。管理上的控制职能强调对照计划检查实际执行情况并纠正偏差。","references":[],"evidence":"组织职能是指所确定的任务由谁来完成以及如何管理和协调这些任务的过程。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bb58aa38579c59c8":{"review":{"definition":"刮目相看指用新的眼光看待，常因对方有了进步或表现超出原有预期。另眼相待指以有别于一般人的态度对待某人或某类人。","explanation":"题中的“非凡业绩”使人对取得业绩者产生新的评价，因此第一空用“刮目相看”比强调区别对待的“另眼相待”更贴切。第二空的“成就”直接承接前面的“业绩”，指这些人取得的事业成绩，对应A项。","references":[],"evidence":"“刮目相看”指用新的眼光来看待","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3d49564cac313521":{"review":{"title":"成就与华章","type":"概念与词义","definition":"“成就”作名词时指取得的成绩，常用于事业、科研等领域。“华章”本指华美的诗文，也可比喻辉煌的历程或事迹。","explanation":"“取得成就”侧重已获得的成果。“谱写华章”用篇章比喻一段有成效、有意义的奋斗历程。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典成就","location":"“成就”词目"}],"examFocus":{"江苏 2024 A类 行测#31":"在“非凡业绩”和“不朽”的上下文中，比较指称事业成果和以事物作比的表达，并核对两空的搭配。"}},"aspects":[{"title":"事业成绩与篇章比喻","uses":[{"unit":"Q1","role":"解题依据","use":"文段写长期专注一件事的人取得非凡业绩。第二空与前句的“非凡业绩”呼应，“成就”直接指他们留下的事业成绩，比C项借篇章作比的“华章”更贴合此处，答案为A。","evidence":"A项“成就”指成绩、业绩","qids":["江苏 2024 A类 行测#31","江苏 2024 C类 行测#31"]}]}]},"k-4fb00e28d7fb9c5d":{"review":{"definition":"高瞻远瞩形容眼光远大，能够从长远考虑问题。","explanation":"题中一些科研单位在人工智能和机器人迅速发展的背景下，主动谋划如何应对伴随技术发展而来的伦理问题，适合用“高瞻远瞩”。“迎难而上”也能体现直面挑战，因此还要比较第二空。“整合力量”更能体现跨学科协作，最终选D项。","references":[],"evidence":"“高瞻远瞩”形容目光远大","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-70cf5d2c902da40d":{"review":{"definition":"整合指将不同组成部分通过协调、调整组合成一个整体。聚集指使人或事物集中到一起，侧重集合。","explanation":"题中科研单位要让不同学科、不同领域的力量共同探索人工智能和机器人伦理问题。两词都可以表达力量的汇合，其中D项的“整合”进一步体现了协调分工、共同发挥作用，更贴合后文的探索任务。","references":[],"evidence":"“整合”指通过调整、整顿、协调重新组合","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4005763fb41bb48b":{"review":{"definition":"人迹罕至指很少有人到达某地。与世隔绝指与外界社会隔断往来。","explanation":"题中极地寒冷干燥，“人迹罕至”写人到访得少，与“生态环境却别有洞天”形成转折，也容得下后文的企鹅和白熊等动物描写。“与世隔绝”涉及外界往来是否中断，超出了此处所描写的范围。","references":[],"evidence":"“人迹罕至”指人的足迹很少到达","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f20ea2f4802d2c51":{"review":{"definition":"置身事外指把自己放在事情之外。袖手旁观侧重在旁看着而不出手相助，作壁上观侧重站在一旁观望而不参与。","explanation":"题中“面向全民”和“全覆盖”要求国防教育覆盖所有个人、行业和领域，“没有一个……可以置身事外”直接呼应覆盖范围。“袖手旁观”和“作壁上观”更突出旁观者面对具体事情时的态度。","references":[],"evidence":"没有一个人、一个行业、一个领域可以","disposition":"独立词条","basis":"据原题和解析编释。","title":"置身事外、袖手旁观与作壁上观","related":[],"examFocus":{"江苏 2024 A类 行测#34":"结合“面向全民”和“全覆盖”，辨析第一空的成语描述的是是否参与、是否关心，还是面对具体事情时的态度。"}},"readings":[{"origin":"k-f20ea2f4802d2c51","title":"置身事外、袖手旁观与作壁上观","qs":["江苏 2024 A类 行测#34"],"definition":"置身事外指把自己放在事情之外。袖手旁观侧重在旁看着而不出手相助，作壁上观侧重站在一旁观望而不参与。","explanation":"题中“面向全民”和“全覆盖”要求国防教育覆盖所有个人、行业和领域，“没有一个……可以置身事外”直接呼应覆盖范围。“袖手旁观”和“作壁上观”更突出旁观者面对具体事情时的态度。","evidence":"没有一个人、一个行业、一个领域可以","doubt":"","references":[]},{"origin":"k-f6e8be249f1bc714","title":"置身事外、袖手旁观与作壁上观","qs":["江苏 2024 B类 行测#32"],"definition":"“置身事外”指把自己放在事情之外，侧重不参与。“袖手旁观”和“作壁上观”都侧重在一旁看着而不介入或相助。","explanation":"第一空的主语包括“一个人、一个行业、一个领域”。“面向全民”和“全覆盖”要求各类主体都纳入国防教育，因此“没有……可以置身事外”最贴合文意。“袖手旁观”和“作壁上观”强调旁观者是否介入或相助，“漠不关心”强调关心程度。","evidence":"国防教育应面向全民，没有一个人、一个行业、一个领域可以","doubt":"","references":[]}]},"k-80c93c471aaa444e":{"review":{"definition":"指光亮、色彩等相互映照，也可比喻不同事物相互映衬，各自的特点因而更加鲜明。","explanation":"本题以“现代治理精神”和“中华善治传统”为并列主体，用“交相辉映”写两者在新时代相互映衬。“一脉相承”突出源流承继，“相辅相成”突出彼此补充和促成，分别侧重不同的关系。","references":[],"evidence":"二者在新时代共同闪耀","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a0fbd67c35013bb9":{"review":{"definition":"指包含在内，常用于说明某种意义、因素或内容寓于某一事物之中。","explanation":"题干首句把社会治理现代化说成中国式现代化在社会治理领域的具体表现，“蕴含于……生成脉络中”承接这一表述，突出它内在于这一路径的形成过程。“孕育于”偏重形成过程，“发轫于”偏重起点。","references":[],"evidence":"“蕴含”指包含在内","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3a3268908ea3fe3c":{"review":{"definition":"形容寻求贤才的心情十分迫切，如同口渴时急于喝水。","explanation":"第一空与“尊重人才”并列，用“求贤若渴”可以写出社会环境中积极求才的态度。“唯才是举”“任人唯贤”也能体现重视人才，但侧重举荐或任用的标准。全题还需由后两空的“保障有力”“心无旁骛”确定选项C。","references":[],"evidence":"“求贤若渴”指寻求贤才的心情非常迫切","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-04ff837c860daafc":{"review":{"definition":"指保障措施有足够的力度，能够对所要保障的事项提供切实支持。","explanation":"题干把“待遇适当”和“保障有力”并列，前者说待遇是否合宜，后者说生活保障能否提供切实支持，共同指向让人才安心钻研业务的生活条件。“保障全面”侧重覆盖范围，在第二空也说得通，需要结合第三空确定答案。","references":[],"evidence":"“有力”指有力量，分量重","disposition":"独立词条","basis":"据原题和解析编释。","title":"保障有力","related":[],"examFocus":{"江苏 2024 A类 行测#37":"辨析第二空中修饰“保障”的词各有何侧重，再结合第三空与“钻研业务”的搭配判断。"}},"readings":[{"origin":"k-04ff837c860daafc","title":"保障有力","qs":["江苏 2024 A类 行测#37"],"definition":"指保障措施有足够的力度，能够对所要保障的事项提供切实支持。","explanation":"题干把“待遇适当”和“保障有力”并列，前者说待遇是否合宜，后者说生活保障能否提供切实支持，共同指向让人才安心钻研业务的生活条件。“保障全面”侧重覆盖范围，在第二空也说得通，需要结合第三空确定答案。","evidence":"“有力”指有力量，分量重","doubt":"","references":[]},{"origin":"k-ffd2e0f8771fe1de","title":"保障有力","qs":["江苏 2024 B类 行测#37"],"definition":"保障有力指提供的支持有力度，足以为相关活动或需求提供可靠条件。","explanation":"第37题第二空组成“待遇适当、保障有力的生活环境”。“有力”突出生活支持的力度，与后文让人才安心钻研业务的目标相衔接。“全面”也可以说明保障覆盖各方面，C组最终胜出还要看第三空能否写出人才专注于业务的状态。","evidence":"“有力”指有力量，分量重","doubt":"","references":[]}]},"k-8a0ca08567609bee":{"review":{"definition":"指从全局出发，综合考虑各方面因素并作统一筹划。","explanation":"“按人口要素统筹资源布局”是以人口因素为依据，对全民健身公共服务资源如何分布作整体安排，与下文推动城乡区域均衡发展相呼应。“统筹”强调筹划的整体性，既可用于初次布局，也可用于既有资源的重新安排。","references":[],"evidence":"“统筹”指通盘筹划","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f39eb81b75556f66":{"review":{"definition":"“弱不禁风”形容娇弱到连风吹都经受不起，侧重缺乏力量。“细若游丝”形容像游丝一样纤细微弱，侧重细小、若有若无。","explanation":"第39题用“并非……而是……”转折。直径30多厘米和“粗壮如树”写出藤茎的粗，“虬曲苍劲”还写出藤茎的劲健。“细若游丝”主要能反衬粗细，“弱不禁风”更能反衬后半句的苍劲有力，因此第三空选D项。","references":[],"evidence":"而是虬曲苍劲，粗壮如树","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-71395a513b064975":{"review":{"definition":"比喻事情中细小、次要的部分。","explanation":"第40题以“地铁会合点”这一小处着眼，与高楼大厦、车水马龙的城市图景相对。“细枝末节”在此突出日常服务安排的细小，而文章恰恰肯定这些细节对改善生活的价值。“熙熙攘攘”仍写人多热闹，与前文的繁华图景重复。","references":[],"evidence":"比喻事情或问题的细小而无关紧要的部分","disposition":"独立词条","basis":"据原题和解析编释。","title":"细枝末节","related":[],"examFocus":{"江苏 2024 A类 行测#40":"结合“地铁会合点”的例子和前后两幅生活图景辨析第一空，再看后两空分别与“科技手段”和“绣花功夫”如何呼应。"}},"readings":[{"origin":"k-71395a513b064975","title":"细枝末节","qs":["江苏 2024 A类 行测#40"],"definition":"比喻事情中细小、次要的部分。","explanation":"第40题以“地铁会合点”这一小处着眼，与高楼大厦、车水马龙的城市图景相对。“细枝末节”在此突出日常服务安排的细小，而文章恰恰肯定这些细节对改善生活的价值。“熙熙攘攘”仍写人多热闹，与前文的繁华图景重复。","evidence":"比喻事情或问题的细小而无关紧要的部分","doubt":"","references":[]},{"origin":"k-ce570daf9362223a","title":"细枝末节","qs":["江苏 2024 C类 行测#37"],"definition":"细枝末节比喻事情或问题中细小而次要的部分。","explanation":"第37题把“地铁会合点”这样规模很小的安排与高楼大厦、车水马龙的“繁华图景”相对照。A项“细枝末节”写的是日常生活中容易被忽略的细处，材料借此说明这些细处也能体现城市治理的品质。C项“熙熙攘攘”描写人来人往的热闹景象，与前面的繁华图景语义相近。","evidence":"比喻事情或问题的细小而无关紧要的部分","doubt":"","references":[]},{"origin":"k-e199c163fd4a19a5","title":"细枝末节","qs":["江苏 2024 B类 行测#40"],"definition":"细枝末节比喻事情中细小、次要的部分。","explanation":"题干以“地铁会合点”这样的小安排，说明城市善治也体现在日常生活的点滴中。“细枝末节”在第一空突出这些安排相对于高楼大厦、车水马龙的繁华图景而言尺度小，而文章恰好强调小细节对生活品质的意义。","evidence":"“地铁会合点”的选择虽然并非大手笔，但蕴含着城市善治的大道理","doubt":"","references":[]}]},"k-2d485314291cd76a":{"review":{"definition":"“莫可名状”指难以用语言形容，可用于复杂微妙的事物。“不堪言状”也有难以形容之意，常用来形容严重或恶劣的情状，带有负面色彩。","explanation":"第41题的提示词工程师既要理解AI逻辑，又涉及法律、宗教、艺术等领域，还要具备产品经理思维。作者在说明这个岗位跨界、难以按传统专业划分，用“莫可名状”贴合难以说清的意思，也契合材料的语气。","references":[],"evidence":"它非文非理、非农非工，既跨界又难以充分量化","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9ca0533b7efae951":{"review":{"title":"成本利润率","type":"概念与词义","definition":"成本利润率是利润与对应成本的比率，通常用百分数表示，等于利润除以成本再乘以100%。","explanation":"同一批商品按不同价格出售时，整批的成本利润率以各部分盈亏合计为分子，以整批成本为分母。已知总利润和非零成本利润率时，可用总利润除以该比率求总成本。","basis":"据关联原题和解析编释。","references":[],"related":["k-45392942e1591512","k-14599d5c611e3b87","k-90c98a86d3b2a861"],"examFocus":{"江苏 2024 A类 行测#53":"用整批利润和成本利润率还原总进价，再按原价和折扣价下的单件盈亏建立数量关系。"}},"aspects":[{"title":"由整批利润反推总成本","uses":[{"unit":"Q1","role":"解题依据","use":"整批盈利7410元，成本利润率为19%，可反推总进价为39000元。按每个100元计，共购进390个。原价销售每个赚30元，按原售价打7折每个亏9元，结合整批利润得打折售出110个，选D。","evidence":"共盈利7410元。若成本利润率为19%","qids":["江苏 2024 A类 行测#53","江苏 2024 B类 行测#53"]}]}]},"k-47ca586a22f86a78":{"review":{"definition":"从不同元素中选取若干个元素，只区分选中的元素时用组合，还要区分这些元素的顺序时用排列。分配到不同位置时，交换去向也会产生不同结果。","explanation":"两个二线城市各占1人，两个一线城市因此分别派2人和1人。先从5人中选2人组成一组，有10种，同一组内交换两人的顺序仍是同一组。再从剩余3人中选1人，有3种。将这两组派往两个不同的一线城市有2种，剩下两人分派到两个不同的二线城市也有2种，共10×3×2×2＝120种，选C。","references":[],"evidence":"这两组人分配到2个一线城市","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8404d4065d137ed9":{"review":{"definition":"亲身经历一件事，可以从中增长见识、积累经验。","explanation":"「经一事」是获得经验的途径，「长一智」是由此获得的结果。题目据此把D项归到方式与目的的对应关系，与通过保护知识产权来保护创新的方向一致。","references":[],"evidence":"亲身经历了某件事情，就能增长关于这方面的知识。","disposition":"独立词条","basis":"据原题和解析编释。","title":"经一事，长一智","related":[],"examFocus":{"江苏 2024 A类 行测#66":"比较各组前后两项的关系，辨别前项是后项所描述的对象、成立的条件，还是实现的途径。"}},"readings":[{"origin":"k-8404d4065d137ed9","title":"经一事，长一智","qs":["江苏 2024 A类 行测#66"],"definition":"亲身经历一件事，可以从中增长见识、积累经验。","explanation":"「经一事」是获得经验的途径，「长一智」是由此获得的结果。题目据此把D项归到方式与目的的对应关系，与通过保护知识产权来保护创新的方向一致。","evidence":"亲身经历了某件事情，就能增长关于这方面的知识。","doubt":"","references":[]},{"origin":"k-9fec8152fb6cfd41","title":"经一事，长一智","qs":["江苏 2024 C类 行测#66"],"definition":"亲身经历一件事，从中增长一分见识。","explanation":"“经一事”是增长见识的途径，“长一智”是由此获得的结果。题目把这一关系与通过保护知识产权来保护创新的方式与目的关系相类比，因此选D。","evidence":"亲身经历了某件事情，就能增长关于这方面的知识","doubt":"","references":[]}]},"k-720eeada03417ee2":{"review":{"definition":"年纪还未到衰老的时候，容貌却已经显出老态。","explanation":"「未暮」说年纪尚轻，「先秋」说容颜先衰。「尚未」与「已经」形成反差，两句可用「虽然……但是……」衔接，与C项「言者无心，听者有意」的转折关系一致。","references":[],"evidence":"未到衰老的年纪，而容颜已经老去","disposition":"独立词条","basis":"据原题和解析编释。","title":"年华未暮，容貌先秋","related":[],"examFocus":{"江苏 2024 A类 行测#67":"先读懂题干中“未暮”和“先秋”各指什么，再比较各组前后两句的衔接关系。"}},"readings":[{"origin":"k-720eeada03417ee2","title":"年华未暮，容貌先秋","qs":["江苏 2024 A类 行测#67"],"definition":"年纪还未到衰老的时候，容貌却已经显出老态。","explanation":"「未暮」说年纪尚轻，「先秋」说容颜先衰。「尚未」与「已经」形成反差，两句可用「虽然……但是……」衔接，与C项「言者无心，听者有意」的转折关系一致。","evidence":"未到衰老的年纪，而容颜已经老去","doubt":"","references":[]},{"origin":"k-84a88634303a2395","title":"年华未暮，容貌先秋","qs":["江苏 2024 B类 行测#68"],"definition":"年纪还未到衰老的时候，容颜已经显出衰老的迹象。","explanation":"“暮”比喻人生的晚年，“秋”比喻容颜衰退。“未”与“先”表明容颜比年龄先显出衰老，两个分句可以用“虽然……但是……”连接。本题C项也有这样的语意转折。","evidence":"未到衰老的年纪，而容颜已经老去","doubt":"","references":[]},{"origin":"k-d36d01b6b8f5ca90","title":"年华未暮，容貌先秋","qs":["江苏 2024 C类 行测#68"],"definition":"年纪尚未到衰老的时候，容貌却已显出老态。“秋”在句中形容容颜衰老。","explanation":"“未暮”与“先秋”写出了年龄与容貌之间的反差，可以读作“虽然年纪未老，容貌却先衰老了”。C项“言者无心，听者有意”也可以用“虽然……却……”连接。","evidence":"未到衰老的年纪，而容颜已经老去","doubt":"","references":[]}]},"k-0defbcc03869ba68":{"review":{"definition":"说话人随口一说，听话人却把这番话放在心上，或从中听出了特别的意思。","explanation":"「无心」说的是说话人没有特别用意，「有意」说的是听话人对这番话有所留意。同一句话在说者和听者那里分量不同，形成转折，对应题干中年纪未老而容颜先衰的反差。","references":[],"evidence":"说话的人不注意，而听话的人却很留神","disposition":"独立词条","basis":"据原题和解析编释。","title":"言者无心，听者有意","related":[],"examFocus":{"江苏 2024 A类 行测#67":"先理解题干前后分句的语意，再逐组比较分句之间是形成反差、构成条件关系，还是体现时间上的先后。"}},"readings":[{"origin":"k-0defbcc03869ba68","title":"言者无心，听者有意","qs":["江苏 2024 A类 行测#67"],"definition":"说话人随口一说，听话人却把这番话放在心上，或从中听出了特别的意思。","explanation":"「无心」说的是说话人没有特别用意，「有意」说的是听话人对这番话有所留意。同一句话在说者和听者那里分量不同，形成转折，对应题干中年纪未老而容颜先衰的反差。","evidence":"说话的人不注意，而听话的人却很留神","doubt":"","references":[]},{"origin":"k-a7f5f52503e50ab9","title":"言者无心，听者有意","qs":["江苏 2024 C类 行测#68"],"definition":"说话的人没有特意表达某层意思，听话的人却把这话放在心上，或从中听出了某层意思。","explanation":"“无心”和“有意”写同一句话在说者和听者那里受到不同对待，形成转折。C项因此对应题干中年纪尚未衰老而容貌已先显老态的反差。","evidence":"说话的人不注意，而听话的人却很留神","doubt":"","references":[]},{"origin":"k-acb5a17ce7ee6e78","title":"言者无心，听者有意","qs":["江苏 2024 B类 行测#68"],"definition":"说话的人无意表达某层意思，听话的人却留了心，或从话里听出了某层意思。","explanation":"本题C项中，“无心”和“有意”分别写说话者和听话者，同一句话在双方那里分量不同，形成转折。这与题干中年纪尚未老、容颜却已先衰的关系相同。","evidence":"说话的人不注意，而听话的人却很留神","doubt":"","references":[]}]},"k-7234956ff2140646":{"review":{"definition":"战火延续数月，家中的书信难以收到，一封就显得格外珍贵。「抵万金」是夸张写法。","explanation":"战乱持久使家书难得，家书因而格外珍贵。D项先写原因，再写结果，与题干「吴王好剑客，百姓多创瘢」的关系一致。","references":[],"evidence":"连绵的战火已经持续很长时间了，家书难得","disposition":"独立词条","basis":"据原题和解析编释。","title":"烽火连三月，家书抵万金","related":[],"examFocus":{"江苏 2024 A类 行测#68":"读懂各组诗句后，重点辨析一句能否解释另一句，以及两句之间的解释方向。"}},"readings":[{"origin":"k-7234956ff2140646","title":"烽火连三月，家书抵万金","qs":["江苏 2024 A类 行测#68"],"definition":"战火延续数月，家中的书信难以收到，一封就显得格外珍贵。「抵万金」是夸张写法。","explanation":"战乱持久使家书难得，家书因而格外珍贵。D项先写原因，再写结果，与题干「吴王好剑客，百姓多创瘢」的关系一致。","evidence":"连绵的战火已经持续很长时间了，家书难得","doubt":"","references":[]},{"origin":"k-b084413e27832b28","title":"烽火连三月，家书抵万金","qs":["江苏 2024 C类 行测#67"],"definition":"战火持续，家信难得，显得格外珍贵。“抵万金”用夸张写家信的分量。","explanation":"“烽火连三月”交代战事持续的背景，“家书抵万金”写战时家信难得而珍贵。D项的前后两句构成因果，对应题干中吴王喜好剑客导致百姓多有伤痕的关系。","evidence":"连绵的战火已经持续很长时间了，家书难得","doubt":"","references":[]}]},"k-5f06bad5c38c3c85":{"review":{"definition":"在本题的运动状态语境中，「停」和「止」都表示停止，「行」表示行走或移动。","explanation":"按题目采用的二分口径，同一对象在同一时刻要么停止，要么移动。因此首尾两词同义，中间一词与首尾分别互斥且穷尽，对应C项「没、有、无」的排列。","references":[],"evidence":"“停”和“止”均指“停止”","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-be49732d2f8d394f":{"review":{"definition":"在本题的有无判断中，「没」和「无」都表示没有，「有」表示存在。","explanation":"对同一对象、同一范围作有无判断，只有存在和不存在两种可能。C项的首尾两词都表示不存在，中间一词表示存在，与题干首尾同义、中间分别与两端构成矛盾的结构一致。","references":[],"evidence":"“没”和“无”均指“没有、不存在”","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-71d1d405c5cf6c7b":{"review":{"definition":"两个概念的外延在同一论域内互不重合，合起来又覆盖整个论域，二者即构成矛盾关系。","explanation":"C项的「有」和「无」在同一有无判断中只能取其一，也必取其一。B项的「盈」和「亏」在经营收支语境中互斥，但收支持平时两者都不成立，因此没有覆盖全部可能。","references":[],"evidence":"生意除了“盈”和“亏”外还有“不盈不亏”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-556bfe82778286f2":{"review":{"definition":"阶段成果是在一定时间内或某个任务阶段取得的成果。","explanation":"「阶段」说明成果在何时或哪个任务节点取得。某阶段可以形成试点成果，也可以形成理论成果，实践成果和理论成果也都可以在项目结束时取得。因此，按本题解析的分类口径，「阶段成果」与两端分别交叉。","references":[],"evidence":"一定时间或任务阶段","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3a9d5391406d6aa8":{"review":{"definition":"杞人忧天指为没有必要担忧的事情发愁。庸人自扰指本来没有问题，却自己瞎着急或自找麻烦。","explanation":"“杞人忧天”侧重担忧的事情本无必要，“庸人自扰”侧重烦恼由自己造成。A 项前一组都可指无端忧虑，构成近义关系。B 项的“局促不安”侧重举止拘束、内心不安，词义中没有无端忧虑这一层。","references":[],"evidence":"“杞人忧天”借指为不必要忧虑的事情而忧虑，“庸人自扰”指本来没有问题而自己瞎着急或自找麻烦","disposition":"独立词条","basis":"据原题和解析编释。","title":"杞人忧天与庸人自扰","related":[],"examFocus":{"江苏 2024 A类 行测#74":"辨析两组词对中成语的含义，比较前后两组的词义关系是否一致。"}},"readings":[{"origin":"k-3a9d5391406d6aa8","title":"杞人忧天与庸人自扰","qs":["江苏 2024 A类 行测#74"],"definition":"杞人忧天指为没有必要担忧的事情发愁。庸人自扰指本来没有问题，却自己瞎着急或自找麻烦。","explanation":"“杞人忧天”侧重担忧的事情本无必要，“庸人自扰”侧重烦恼由自己造成。A 项前一组都可指无端忧虑，构成近义关系。B 项的“局促不安”侧重举止拘束、内心不安，词义中没有无端忧虑这一层。","evidence":"“杞人忧天”借指为不必要忧虑的事情而忧虑，“庸人自扰”指本来没有问题而自己瞎着急或自找麻烦","doubt":"","references":[]},{"origin":"k-54175c8bb142f3d6","title":"杞人忧天与庸人自扰","qs":["江苏 2024 C类 行测#74"],"definition":"杞人忧天指为没有必要担忧的事情而担忧。庸人自扰指本来没有问题，却自己着急或自找麻烦。","explanation":"杞人忧天侧重忧虑的对象本无须担忧，庸人自扰侧重烦恼由自己引起。两者都可形容因本无须担忧的事情而烦恼，因此A项前半组构成近义关系。B项的局促不安侧重举止拘束、内心不安，词义本身并未交代担忧是否必要。","evidence":"“杞人忧天”借指为不必要忧虑的事情而忧虑，“庸人自扰”指本来没有问题而自己瞎着急或自找麻烦","doubt":"","references":[]}]},"k-0542e8cc0f0c7382":{"review":{"definition":"静息代谢指人体在静息状态下的能量消耗，活动能量代谢指日常活动或运动带来的能量消耗。题干将二者列为决定总能量代谢水平的主要因素。","explanation":"本题从M市成年人总能量代谢下降来判断静息代谢的趋势。B项的锻炼时长增加为活动能量消耗可能增加提供了线索，使静息代谢下降的解释更可信。锻炼时长只反映活动的一部分，还需结合运动强度及其他身体活动才能确定活动能量消耗的整体变化。","references":[],"evidence":"人体总能量代谢主要由静息代谢水平和活动能量代谢水平决定。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b7705745cdfbff43":{"review":{"definition":"按本题采用的口径，单选题难度是答对人数占全体参测人数的比例。若答对得该题满分、其余得零分，该比例也等于该题平均得分除以题目分值。","explanation":"全体考生在该题上的总得分等于答对人数乘以题目分值。用总得分除以参测人数得到平均得分，再除以题目分值，就得到答对人数占比，因此D成立。该等式使用的是全体考生的得分，计算无需按试卷总分划分高分组和低分组。","references":[],"evidence":"一道单选题的难度也可以表示为该题的平均得分与该题分值的比值","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ead9330aa8a795e2":{"review":{"definition":"本题花名灯谜的谜面“郎貌”指丈夫的容貌，可以用“夫容”扣合。","explanation":"谜底“芙蓉”的两个字都有草字头，分别去掉后得到“夫”和“容”。“夫”扣“郎”，“容”扣“貌”，所以第（2）则属于去掉共同部首的摘顶格，与B项的判断一致。","references":[],"evidence":"即为夫容，也就是郎貌","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-8bf3c5e505b5faf3":{"review":{"definition":"盘算指在心里琢磨、考虑，也可以有筹划的意思。本题取“思量”这一义项。","explanation":"谜底“算盘”是用来计算的器具，从后往前读成“盘算”，就与谜面“思量”扣合。第（3）则靠调换两字的顺序扣题，属于秋千格，与B项的判断一致。","references":[],"evidence":"“盘算”有思量的意思","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-17810c9f5dfc628e":{"review":{"title":"“是几倍”与“多几倍”","type":"概念与词义","definition":"以正数 B 为基准，A 是 B 的 A/B 倍；A 比 B 多的倍数为 (A－B)/B。","explanation":"若 A 为 30、B 为 10，A 是 B 的 3 倍，也可说 A 比 B 多 2 倍。两句采用同一个比较基准。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"增长率与基期换算","related":["k-a73e31fef601c55e","k-e556a045ee04f9b4"]}},"k-7422739a89662700":{"review":{"definition":"同比以上年同一时期为基期，环比以相邻上一统计期为基期。按半年统计时，下半年的同比基期是上年下半年，环比基期是本年上半年。","explanation":"第130题D项涉及2020年下半年的营业收入增速。图中有2020年上半年营业收入，可算该期环比增速，但缺少计算同比增速所需的2019年下半年数据。已有数据还显示，从2021年下半年到2022年上半年，营业收入同比增速由约0.4%降至−2.8%，环比增速则由约−2.2%升至−0.7%。两项增速在这两期的变动方向相反，D项所称趋势相同不能推出。","references":[],"evidence":"无法计算出2020年下半年同比增速","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-453349e653513111":{"review":{"definition":"新型电力系统以新能源为主体，把建设高比例新能源供给消纳体系作为主线任务。","explanation":"“以新能源为主体”指电力系统建设的供给方向，既要提高新能源供给比例，也要提升系统接纳和利用新能源电力的能力。B项把主体换成了石化能源的清洁化利用，改变了题目所问的主体定位，因此是选非题应选的一项。","references":[],"evidence":"构建以新能源为主体的新型电力系统","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d441967817900091":{"review":{"definition":"新型电力系统以坚强、智能、柔性的电网为枢纽平台，连接电源、用电负荷和储能资源，支撑各环节协调运行。","explanation":"A项描述的是电网承担的平台作用，符合题给《新型电力系统发展蓝皮书》的表述。题中B项涉及能源供给的主体定位，两项分别回答系统依托什么平台运行和以什么能源为供给主体。","references":[],"evidence":"以坚强、智能、柔性电网为枢纽平台","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f4ff2d748783ad1d":{"review":{"definition":"结构性货币政策工具是中央银行用于引导金融资源流向经济重点领域和薄弱环节的政策工具，兼顾货币政策的总量功能和定向支持功能。","explanation":"碳减排支持工具和普惠养老专项再贷款分别引导金融机构支持碳减排和普惠养老。题目把D项的小微贷款减息支持作为面向小微企业的定向信贷支持来理解。C项的地方政府专项债券属于政府举债融资工具，因其财政政策属性而入选。判断时要看政策实施主体和资金运作方式，资金有指定用途这一点不足以区分二者。","references":[],"evidence":"围绕支持普惠金融、绿色发展、科技创新等国民经济重点领域和薄弱环节","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"d38a8ce0241af167","label":"结构性货币政策工具","topic":"经济指标与宏观调控","category":"非时政","text":"8.结构性货币政策工具\n我国的结构性货币政策工具是人民银行引导金融机构信贷投向，发挥精准滴灌、杠杆撬\n动作用的工具，通过提供再贷款或资金激励的方式，支持金融机构加大对特定领域和行业的\n信贷投放，降低企业融资成本。","source":{"doc":"6cbfb01fe723bba64b75","first":24,"last":24,"page":24,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-08006e6f65704a82":{"review":{"definition":"地方政府专项债券是省级政府为有一定收益的公益性项目发行的政府债券，以项目对应的政府性基金收入或专项收入偿还本息。","explanation":"这类债券通过地方政府举债筹集项目建设资金，属于财政政策工具。即使所筹资金投向重点领域，其政策属性也由政府举债融资的方式决定。因此，C项是题中应排除的结构性货币政策工具选项。","references":[],"evidence":"以公益性项目对应的政府性基金收入或专项收入作为还本付息资金来源","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6733b99a9da82861":{"review":{"definition":"本题将以获得演出收入为目的向公众提供现场表演，认定为经营行为。观众自愿决定是否付款及付款金额，可以与表演者的营利目的并存。","explanation":"罗某在地铁口架设音响公开弹唱，并在现场摆放收款二维码。解析把表演和收款安排合在一起，判断罗某借弹唱获取收益，据此选择B项。这一判断针对罗某组织表演的目的，单凭某笔款项是自愿扫码支付，无法判断该笔款项的民事性质。","references":[],"evidence":"摆放二维码收取观众打赏","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-0c76a41ae9e947ca":{"review":{"definition":"皮都没有了，毛还能附着在哪里？比喻事物失去赖以存在的基础，就难以存续。","explanation":"文中宿主植物相当于“皮”，依赖宿主存活的菟丝草相当于“毛”。宿主枯死，菟丝草就失去了生存基础，所以选A。“覆巢之下，安有完卵”强调整体遭殃时其中的个体难以保全，“城门失火，殃及池鱼”强调灾祸牵连，这两项表达的关系与寄生依赖不同。","references":[],"evidence":"比喻事物失去了借以生存的基础，就不能存在","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c03c59706ca4d515":{"review":{"definition":"指亲身处在某个环境中，也可形容通过展示等方式产生仿佛亲历现场的感受。","explanation":"第二空承接“多媒体情景展示”，又与“重温当年情境”相呼应，描写观众仿佛进入当年的现场，因此选用D项的“身临其境”。“设身处地”侧重把自己放到别人的处境中考虑，“感同身受”侧重仿佛亲身感受到某种体验，“抚今追昔”侧重由眼前情景追想往事。","references":[],"evidence":"观众可以           ，重温当年情境","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7dba1d2dc8b6330a":{"review":{"definition":"形容某个地方很少有人到达。","explanation":"第一空写极地很少有人到访，后文用“却”转入极地丰富的生态景象，列举了企鹅疾走、白熊游泳。“人迹罕至”描述的是人的到访频率。“与世隔绝”侧重与外界社会断绝往来，“寸草不生”侧重植被状况。","references":[],"evidence":"“人迹罕至”指人的足迹很少到达","disposition":"独立词条","basis":"据原题和解析编释。","title":"人迹罕至","related":[],"examFocus":{"江苏 2024 B类 行测#33":"首空看“却”前的极地环境描写如何与后文的生态景象形成转折，次空看结尾侧重哪种观感。"}},"readings":[{"origin":"k-7dba1d2dc8b6330a","title":"人迹罕至","qs":["江苏 2024 B类 行测#33"],"definition":"形容某个地方很少有人到达。","explanation":"第一空写极地很少有人到访，后文用“却”转入极地丰富的生态景象，列举了企鹅疾走、白熊游泳。“人迹罕至”描述的是人的到访频率。“与世隔绝”侧重与外界社会断绝往来，“寸草不生”侧重植被状况。","evidence":"“人迹罕至”指人的足迹很少到达","doubt":"","references":[]},{"origin":"k-c849a7dc83f62719","title":"人迹罕至","qs":["江苏 2024 C类 行测#32"],"definition":"人迹罕至指很少有人到达某个地方，强调人的到访稀少。","explanation":"第32题先写极地冰天雪地、寒冷干燥，再用“却”引出企鹅和白熊等动物的活动。“人迹罕至”写的是人少，与后文的丰富生态形成转折。“与世隔绝”强调与外界往来隔断，比题文所需的程度更重。","evidence":"“人迹罕至”指人的足迹很少到达","doubt":"","references":[]}]},"k-2ff4a6f96a81de15":{"review":{"definition":"尝试指试着做某事，侧重付诸行动以探索做法或检验效果。","explanation":"第34题第二空用“尝试”承接持续探究，说明学生在最终形成项目成果之前，会试着用创造性的办法解决问题。“实时”和“同步”都需要联系相应的时间或步调来理解，材料只交代了探究的持续过程及其最终成果。“力求”也能表达努力解决问题，A组胜出还取决于第一空的“引导”。","references":[],"evidence":"“尝试”指试验，C项“力求”指尽最大的努力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0bae6b01d6c5e435":{"review":{"definition":"遏制指阻止事态或趋势继续发展。压制指用较强的力量加以限制，常用于对手、火力等对象。","explanation":"第35题第一空的对象是“全球生物多样性下降趋势”。“尚未得到根本遏制”说明这一下降趋势仍在持续，与下文“植物保护形势仍然十分严峻”相呼应。“压制”带有施加强力的意味，在这里和“趋势”的搭配较弱。“控制”“抑制”仍可表达限制趋势发展的意思，需要结合后两空确定答案。","references":[],"evidence":"全球生物多样性下降趋势仍然存在","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a5d9c2e4be4202fc":{"review":{"definition":"严格侧重要求严、执行认真。有效侧重措施产生了预期或实际效果。","explanation":"第35题第二空修饰“保护”。前文提出建立以国家公园为主体的自然保护地体系，后文提出建设国家植物园体系和构建迁地保护网络，重心是如何落实保护。“严格”突出保护要求和执行力度，“有效”把重心转向保护成效。“严密”也能突出保护安排周密，最终还需比较第三空。","references":[],"evidence":"让重要自然生态系统得到最","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a68bda1c4f2cde51":{"review":{"definition":"高质量侧重工作过程或成果的质量较高。高规格侧重规格、标准或层级较高。","explanation":"第35题第三空放在“建设国家植物园体系”之前。“高质量建设”强调把体系建好，与后文构建全国植物迁地保护网络的任务相衔接。“高规格”会把注意力引向植物园体系的规格或层级，材料未提出提高规格或层级的要求。","references":[],"evidence":"“高质量”侧重强调产品或工作更优","disposition":"独立词条","basis":"据原题和解析编释。","title":"高质量与高规格","related":[],"examFocus":{"江苏 2024 B类 行测#35":"第三空修饰“建设”，要结合后文的任务，辨析“高质量”和“高规格”各自评价的是建设的哪个方面。"}},"readings":[{"origin":"k-a68bda1c4f2cde51","title":"高质量与高规格","qs":["江苏 2024 B类 行测#35"],"definition":"高质量侧重工作过程或成果的质量较高。高规格侧重规格、标准或层级较高。","explanation":"第35题第三空放在“建设国家植物园体系”之前。“高质量建设”强调把体系建好，与后文构建全国植物迁地保护网络的任务相衔接。“高规格”会把注意力引向植物园体系的规格或层级，材料未提出提高规格或层级的要求。","evidence":"“高质量”侧重强调产品或工作更优","doubt":"","references":[]},{"origin":"k-df5320bfab55b91e","title":"高质量与高规格","qs":["江苏 2024 C类 行测#39"],"definition":"“高质量”强调事物的品质或工作的完成水平高，“高规格”强调规模、配置、礼仪等方面的规格高。","explanation":"第三空位于“建设国家植物园体系”之前。“高质量建设”评价的是建设工作的水平，符合通过建设植物园体系和迁地保护网络来加强植物保护的语意。若要用“高规格”描述所建体系，写成“建设高规格的国家植物园体系”更清楚，但题干没有交代该体系的规模或配置规格。因此在前两空保留的A、C两项中，第三空支持C项。","evidence":"“高质量”侧重强调产品或工作更优","doubt":"","references":[]}]},"k-44e8415e4881736e":{"review":{"definition":"统筹指从全局出发，兼顾各方面并统一筹划。调整侧重改变现有安排，优化侧重改进安排以取得更好的效果。","explanation":"第36题首句提出健身公共服务体系的“系统性建构”，第一空写“按人口要素”安排资源布局。“统筹”能体现把人口要素和布局需要放进同一套安排中。后文所举城乡区域发展和多层级设施网络的例子也延续了整体谋划的思路。“调整”和“优化”分别突出改动和改善，第一空的语境中“规划”同样可用，需结合后文选项搭配判断。","references":[],"evidence":"“统筹”指通盘筹划","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-741cdf5eb0c4a202":{"review":{"definition":"不可或缺指某个组成部分必不可少。举足轻重形容地位或作用极为重要，足以影响全局。","explanation":"第36题第三空填入“体育是……的内容”。“不可或缺”说明体育是满足人民高品质生活需求所必需的一部分，与“内容”的搭配贴切。“举足轻重”更适合描述体育在某个体系中所处的地位或发挥的作用，在这里与“内容”的搭配较弱。","references":[],"evidence":"通常形容必不可少的因素或部分","disposition":"独立词条","basis":"据原题和解析编释。","title":"不可或缺与举足轻重","related":[],"examFocus":{"江苏 2024 A类 行测#38":"辨析第三空的近义词时，结合前文的全民健身服务举措，比较各词的侧重点及其与“内容”的搭配。"}},"readings":[{"origin":"k-741cdf5eb0c4a202","title":"不可或缺与举足轻重","qs":["江苏 2024 B类 行测#36"],"definition":"不可或缺指某个组成部分必不可少。举足轻重形容地位或作用极为重要，足以影响全局。","explanation":"第36题第三空填入“体育是……的内容”。“不可或缺”说明体育是满足人民高品质生活需求所必需的一部分，与“内容”的搭配贴切。“举足轻重”更适合描述体育在某个体系中所处的地位或发挥的作用，在这里与“内容”的搭配较弱。","evidence":"通常形容必不可少的因素或部分","doubt":"","references":[]},{"origin":"k-a79a728f7a594e5c","title":"不可或缺与举足轻重","qs":["江苏 2024 A类 行测#38"],"definition":"“不可或缺”指必不可少，强调某个部分的必要性。“举足轻重”形容地位重要或作用很大，足以影响全局。","explanation":"题干列出城镇社区15分钟健身圈、青少年体育赛事体系等服务安排，最后从人民对高品质生活的需求落到“体育是……的内容”。“不可或缺”说明体育是其中必不可少的一部分，贴合“内容”。“举足轻重”侧重对全局的影响，通常用来形容地位或作用。","evidence":"通常形容必不可少的因素或部分","doubt":"","references":[]},{"origin":"k-fb9808a724cfdd00","title":"不可或缺与举足轻重","qs":["江苏 2024 C类 行测#40"],"definition":"“不可或缺”表示某个组成部分必不可少。“举足轻重”形容地位、作用等十分重要，足以影响全局。","explanation":"题干列举15分钟健身圈和青少年体育赛事体系，落脚于人民对高品质生活的需求，将体育视为其中必不可少的内容。“不可或缺的内容”恰好表达这一组成关系，“举足轻重”通常用来说明地位或作用对全局的影响。B项“必不可少”也能修饰“内容”，但其第一空“调整”在解析中已被排除。","evidence":"人民对高品质生活的需求，决定了体育是           的内容","doubt":"","references":[]}]},"k-17f90fd303709db3":{"review":{"definition":"求贤若渴形容寻求贤才的心情非常迫切。量才录用指根据人的才能决定如何录用或任用。","explanation":"第37题第一空与“尊重人才”并列，共同修饰“社会环境”。“求贤若渴”写主动求才的态度，能和尊重人才相呼应。“量才录用”写选任人才的依据，更接近下文“竞争择优”所描述的制度安排。","references":[],"evidence":"“求贤若渴”指寻求贤才的心情非常迫切","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1977bbceb213bc0b":{"review":{"definition":"心无旁骛形容专心致志，心思集中在正在做的事情上。","explanation":"第37题第三空修饰“钻研业务”，写人才在公正平等的制度环境和有保障的生活环境中能安心专研。“凝神聚力”可强调集中精神、汇聚力量，此处更需要写出人才专注钻研、少受其他事务牵扰的状态。","references":[],"evidence":"形容心思集中，专心致志","disposition":"独立词条","basis":"据原题和解析编释。","title":"心无旁骛","related":[],"examFocus":{"江苏 2024 A类 行测#37":"留意第二空与“保障”的搭配，再比较第三空各词用于修饰“钻研业务”时各自强调什么。"}},"readings":[{"origin":"k-1977bbceb213bc0b","title":"心无旁骛","qs":["江苏 2024 B类 行测#37"],"definition":"心无旁骛形容专心致志，心思集中在正在做的事情上。","explanation":"第37题第三空修饰“钻研业务”，写人才在公正平等的制度环境和有保障的生活环境中能安心专研。“凝神聚力”可强调集中精神、汇聚力量，此处更需要写出人才专注钻研、少受其他事务牵扰的状态。","evidence":"形容心思集中，专心致志","doubt":"","references":[]},{"origin":"k-63089c298cf92340","title":"心无旁骛","qs":["江苏 2024 A类 行测#37"],"definition":"指心思集中在当前所做的事上，专心致志。","explanation":"题干先提出营造公正平等、竞争择优的制度环境，并给予人才适当待遇和生活保障，而后落到“钻研业务”。“心无旁骛”写出了这些条件让人才少受外界事务和生活顾虑牵扯，能够专注于业务的效果。","evidence":"形容心思集中，专心致志","doubt":"","references":[]}]},"k-33882f5ba374d7e3":{"review":{"definition":"“凝结”用于抽象事物时，可以表示把长期积累的成果集中体现出来。“凝结经验”强调把实践所得集中体现在某一成果中。","explanation":"第二空与“新理念”并列，句子说的是社会治理现代化集中体现了改革开放以来特别是新时代以来的治理实践积累。“新经验”突出实践所得，“新方法”偏重做法，“新举措”偏重行动，“新视野”偏重认识范围，因此本题选“新经验”。","references":[],"evidence":"凝结了改革开放以来特别是新时代以来我国社会治理的新理念","disposition":"独立词条","basis":"据原题和解析编释。","title":"凝结经验","related":[],"examFocus":{"江苏 2024 A类 行测#36":"判断第二空时，留意它既要能与“凝结”搭配，又要能与“新理念”并列。"}},"readings":[{"origin":"k-33882f5ba374d7e3","title":"凝结经验","qs":["江苏 2024 B类 行测#38"],"definition":"“凝结”用于抽象事物时，可以表示把长期积累的成果集中体现出来。“凝结经验”强调把实践所得集中体现在某一成果中。","explanation":"第二空与“新理念”并列，句子说的是社会治理现代化集中体现了改革开放以来特别是新时代以来的治理实践积累。“新经验”突出实践所得，“新方法”偏重做法，“新举措”偏重行动，“新视野”偏重认识范围，因此本题选“新经验”。","evidence":"凝结了改革开放以来特别是新时代以来我国社会治理的新理念","doubt":"","references":[]},{"origin":"k-5206f5199b993fe0","title":"凝结经验","qs":["江苏 2024 A类 行测#36"],"definition":"经验是在实践中获得的知识、技能或认识。“凝结经验”表示将实践所得积累并集中体现出来。","explanation":"题干中的“改革开放以来特别是新时代以来”交代了社会治理实践的时间跨度。“新理念、新经验”作“凝结了”的并列宾语，分别指治理观念和实践所得。“新方法”“新举措”侧重怎样做或采取了什么行动，“新视野”侧重看问题的范围，均较难贴合此处汇聚历年治理成果的语意。","evidence":"“经验”指从多次实践中得到的知识或技能，与“凝结”搭配恰当","doubt":"","references":[]}]},"k-74d931d2abcd8a5e":{"review":{"definition":"系统是由相互联系、相互作用的部分组成并具有一定功能的整体。方式侧重采取的做法，形态侧重存在或表现的样貌，机制侧重各部分怎样运作和相互作用。","explanation":"题干把农业文化遗产描述为至今仍发挥生产作用的活态整体，后文又以精耕细作和生态循环说明农耕体系的特征。第一空用“生产系统”，既能涵盖体系中的生产做法和相互关系，也能体现整体的生产功能。","references":[],"evidence":"“系统”指若干部分相互联系、相互作用，形成的具有某些功能的整体","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f676a008e94786ae":{"review":{"definition":"莫可名状指难以用言语形容或描述。“名状”在这里指说出事物的情状。","explanation":"材料里的提示词工程师既要理解AI逻辑，又要具备法律、艺术等领域的专业知识，还需要产品经理思维。作者初看这个跨界职业时，难以用惯常的专业分类说清它的性质，因此选“莫可名状”。“不知所以”侧重不明白原因，与这里的描述困难不同。","references":[],"evidence":"它非文非理、非农非工，既跨界又难以充分量化","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b4e0862e1375933c":{"review":{"definition":"不堪言状指难以用言语形容，常用来形容糟糕、难堪等达到很深程度的情状，带有负面色彩。","explanation":"第三段列举提示词工程师兼具AI技术、行业知识和产品思维，说明其职业属性跨界，难以用“专业对口”的思路概括。用“不堪言状”会给这种分类上的困难添上材料没有表达的负面评价，所以排除该项。","references":[],"evidence":"形容某种情况极其严重或恶劣，常用于贬义","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1197f626c4e931b9":{"review":{"definition":"按进价加价时，加价额等于进价乘以加价率。打折时，折后价等于折前售价乘以折扣比例，7折对应70%。","explanation":"路由器以100元进价为基数加价30%，得到折前售价130元，再以130元为基数打7折，得到折后售价91元。两阶段每件分别盈利30元和亏损9元。由7410元总利润和19%的成本利润率可得总成本39000元，共390件。若打折售出x件，则30×(390−x)−9x＝7410，解得110件。","references":[],"evidence":"加价30%出售，半年后将剩下的打7折全部售出","disposition":"独立词条","basis":"据原题和解析编释。","title":"加价率与折扣的计算基数","related":[],"examFocus":{"江苏 2024 A类 行测#53":"分清加价率、折扣和成本利润率各自的计算基数，再用折前、折后两批路由器的利润关系列式。"}},"readings":[{"origin":"k-1197f626c4e931b9","title":"加价率与折扣的计算基数","qs":["江苏 2024 B类 行测#53"],"definition":"按进价加价时，加价额等于进价乘以加价率。打折时，折后价等于折前售价乘以折扣比例，7折对应70%。","explanation":"路由器以100元进价为基数加价30%，得到折前售价130元，再以130元为基数打7折，得到折后售价91元。两阶段每件分别盈利30元和亏损9元。由7410元总利润和19%的成本利润率可得总成本39000元，共390件。若打折售出x件，则30×(390−x)−9x＝7410，解得110件。","evidence":"加价30%出售，半年后将剩下的打7折全部售出","doubt":"","references":[]},{"origin":"k-70fcd62e270bd742","title":"加价率与折扣的计算基数","qs":["江苏 2024 A类 行测#53"],"definition":"按进价加价销售时，加价率以进价为基数。打折时，折扣以折前售价为基数，打7折即按折前售价的70%出售。","explanation":"第53题中，进价100元加价30%后售价为130元，每个盈利30元。剩余商品以130元为基数打7折，售价为91元，每个亏损9元。总盈利7410元除以成本利润率19%，得总成本39000元，共390个。设打折售出x个，则30×(390−x)−9x=7410，解得110个。","evidence":"进价100元/个，加价30%出售，半年后将剩下的打7折全部售出","doubt":"","references":[]}]},"k-3ced35d22efa8532":{"review":{"definition":"质数是大于 1 且恰有两个正因数的整数，这两个正因数是 1 和它本身。","explanation":"题中用日号判断妻子是否游泳。12 月 1 日是周五，丈夫当天游泳，但 1 只有一个正因数。按每周一、三、五筛出的日号中，只有 11、13、29 是质数，所以两人同日游泳 3 天。","references":[],"evidence":"当天的日期为质数就游泳","disposition":"独立词条","basis":"据原题和解析编释。","title":"质数","related":[],"examFocus":{"江苏 2024 A类 行测#60":"用星期的七天周期确定丈夫的游泳日，再用质数定义判断其中哪些日号符合妻子的计划。"}},"readings":[{"origin":"k-3ced35d22efa8532","title":"质数","qs":["江苏 2024 B类 行测#60"],"definition":"质数是大于 1 且恰有两个正因数的整数，这两个正因数是 1 和它本身。","explanation":"题中用日号判断妻子是否游泳。12 月 1 日是周五，丈夫当天游泳，但 1 只有一个正因数。按每周一、三、五筛出的日号中，只有 11、13、29 是质数，所以两人同日游泳 3 天。","evidence":"当天的日期为质数就游泳","doubt":"","references":[]},{"origin":"k-54c6c8fe8663fd5d","title":"质数","qs":["江苏 2024 C类 行测#60"],"definition":"质数是大于1且恰有两个正因数的整数，这两个正因数是1和它本身。","explanation":"12月1日是周五，丈夫在每周一、三、五游泳，因此他的游泳日期可由4日、6日和1日分别每隔7天推得。筛选这些日期时，1日对应的整数1只有一个正因数，应排除。符合质数条件的只有11日、13日和29日，所以两人同日游泳3天，选C。","evidence":"当天的日期为质数就游泳","doubt":"","references":[]},{"origin":"k-c56997d4aed11129","title":"质数","qs":["江苏 2024 A类 行测#60"],"definition":"质数是大于1且恰有两个正因数的整数，这两个正因数是1和它本身。","explanation":"12月1日虽是周五，丈夫当天游泳，但1只有一个正因数，妻子当天按计划不游泳。在丈夫每周一、三、五游泳的日期中，只有11日、13日和29日的日期数是质数，因此两人同日游泳3天，选C。","evidence":"当天的日期为质数就游泳","doubt":"","references":[]}]},"k-f7a679076bc3fb51":{"review":{"definition":"实心方阵是排数与列数相等、每个位置都有人或物的正方形排列。有 n 排时，每排有 n 个成员。","explanation":"本题按排划分研究生和本科生。设本科生有 x 排，研究生有 3 排，则方阵每排有 x + 3 人。本科生人数满足 x(x + 3) = 270，由 15 × 18 = 270 得每排 18 人，因此研究生有 3 × 18 = 54 人。","references":[],"evidence":"方阵为（x+3）排、（x+3）列","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-11cc7efc1a5633a0":{"review":{"definition":"海沟是海底狭长的凹地，其中的“海”指海洋。海量可指极大的数量、很大的酒量或宽宏的度量，借海的广阔或容量大表示程度。","explanation":"“海沟”的“海”交代凹地所在的环境，“海量”的“海”用来形容量或度量之大。题干因此要求前一个合成词中的共同字用本义，后一个借其特征形成引申义，对应C项“火焰、火气”的顺序。","references":[],"evidence":"“海量”指极大的数量、很大的酒量或","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2e6adeba8e852c4e":{"review":{"definition":"火焰是可燃气体燃烧时形成的可见部分。火气在本题取怒气、暴躁脾气的义项，以火比喻强烈的情绪。","explanation":"C项“火焰”的“火”直接指燃烧现象，“火气”的“火”在怒气这一义项里是比喻用法，和“海沟、海量”同为先本义、后引申。B项“碑座”和“碑林”的“碑”都指石碑。","references":[],"evidence":"“火气”多指怒气、暴躁的脾","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-752cf7727bd97c28":{"review":{"title":"手术机器人","type":"概念与词义","definition":"手术机器人是用于辅助实施外科手术的机器人系统。","explanation":"按用途可将手术机器人归入医疗设备。江苏2024年行测题同时按技术属性将其归入高新装备。在该题的分类中，医疗设备和高新装备的范围有交集，各自也有交集之外的对象。","basis":"据关联原题和解析编释。","references":[],"domain":"科技","examFocus":{"江苏 2024 B类 行测#72":"从用途和技术属性两条线判断同一设备的类别，再比较两类装备的外延关系。"}},"aspects":[{"title":"按用途和技术属性归类","uses":[{"unit":"Q1","role":"解题依据","use":"题干中的手术机器人同时属于后两类，后两类为交叉关系。A项中公办中学、事业单位与教育机构的关系与之对应。","evidence":"手术机器人既是医疗设备，又是高新装备，第一词与后两词均是种属关系","qids":["江苏 2024 B类 行测#72","江苏 2024 C类 行测#73"]}]}]},"k-6d9fe766b5fb6153":{"review":{"title":"公办中学","type":"概念与词义","definition":"公办中学是由政府或其他公共机构举办、实施中等教育的学校。","explanation":"“教育机构”描述学校的职能，“事业单位”描述组织属性。江苏2024年行测题将公办中学同时归入这两个类别。","basis":"据关联原题和解析编释。","references":[],"domain":"公共管理","examFocus":{"江苏 2024 B类 行测#72":"先核对第一个对象能否分别按不同标准归入后两类，再区分后两类是交叉还是包含。"}},"aspects":[{"title":"按教育职能和组织属性归类","uses":[{"unit":"Q1","role":"解题依据","use":"A项以公办中学为两个类别的共同成员。按题目采用的分类，事业单位和教育机构各有超出交集的成员，因此A项与题干的三词关系一致。","evidence":"公办中学既是事业单位，又是教育机构，第一词与后两词均是种属关系","qids":["江苏 2024 B类 行测#72","江苏 2024 C类 行测#73"]}]}]},"k-3c97a3a4d49bc212":{"review":{"definition":"敬重是恭敬、尊重，鄙视是轻视、看不起。两词表达对待他人或事物的相反态度。","explanation":"D项的“敬重—鄙视”和“洒脱—拘谨”都是反义关系。B项的“敬重—蔑视”同样是反义关系，但“拘束—拘谨”是近义关系，前后两组关系不同。","references":[],"evidence":"“敬重”指恭敬尊重，“鄙视”指轻视、看不起","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f9332274bb93b457":{"review":{"definition":"洒脱指言谈、举止或风格自然、不拘束。拘谨指言语、行动过分谨慎，显得拘束。","explanation":"“洒脱—拘谨”在言行是否自然舒展这一点上相对，与D项“敬重—鄙视”的反义关系一致。A项的“谨慎”侧重小心以免出错，“拘谨”则含有过分约束、显得不自然的意味。","references":[],"evidence":"“拘谨”指（言语、行动）过分谨慎，拘束","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-760b4cfb72c2ec58":{"review":{"definition":"年均进口量是指定时期内各年进口量的算术平均数，等于各年进口量之和除以所含年份数。","explanation":"江苏 2024 B 类行测第 121 题中，2016—2020 年的酱油进口量依次为 1.38、1.46、1.34、1.45、1.18 万吨，合计 6.81 万吨，除以 5 得 1.362 万吨，约为 1.36 万吨。表中 2022 年进口量为 1.17 万吨，比这五年的年均进口量少约 0.19 万吨，选 A。","references":[{"source":"web-d6e01e968d21fa34","location":"第24页，资料分析第121题前的统计表，进口量列的2016—2020年及2022年各行","quote":"进口量（万吨）"}],"evidence":"“十三五”时期（2016-2020年）的年均进口量","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-5d0056d33138db42":{"review":{"definition":"半年数据的同比以去年同一半年为基期，环比以紧邻的上一半年为基期。增速均按现期值除以对应基期值再减1计算。","explanation":"B项的2023年上半年和2022年上半年利润环比分别以各自的上一年下半年为基期，算得678÷504−1≈34.5%和584÷480−1≈21.7%，因此B项可推出。D项中，2019年下半年营收缺失，无法计算2020年下半年同比增速。已有数据也足以否定D项：从2021年下半年到2022年上半年，营收同比增速由约0.4%降至−2.8%，环比增速却由约−2.2%升至−0.7%。本题选不能推出的一项，故选D。","references":[],"evidence":"无法计算出2020年下半年同比增速","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cf55ee87d571e1ed":{"review":{"definition":"民宿集群是多家民宿在同一区域集中发展形成的住宿业态。本题参考答案将打造民宿集群概括为盘活乡村闲置资源、发展旅游的一项举措。","explanation":"按参考答案，本题应把“打造民宿集群”写作举措，把盘活闲置资源、推动旅游发展、吸引本地人返乡和带动就业增收写作成效。所给参考答案支持这一层概括，具体的闲置资源和改造方式需要由对应原材料确认。","references":[],"evidence":"打造民宿集群，盘活闲置资源，推动旅游业发展","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-50799f3d3a4aaf8b":{"review":{"definition":"本题中的“戏曲小镇”指以地方戏曲为文化特色、推动乡村文化传承和文旅发展的建设举措。","explanation":"参考答案把推动戏曲文化传承、提升村子知名度与推动文旅产业发展列为这一举措的成效，并提到人居环境改善和村民增收。归纳时可据此写出文化、产业和民生三方面成效，具体建设内容及戏曲的非遗认定需要由对应原材料确认。","references":[],"evidence":"打造“戏曲小镇”，推动文化传承","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2c60776d472d0ee7":{"review":{"definition":"非物质文化遗产包括各族人民世代相传并视为自身文化遗产组成部分的传统文化表现形式，以及与这些表现形式相关的实物和场所。古遗址、古墓葬、古建筑作为不可移动文物，属于物质文化遗产。","explanation":"非遗可以包含与传统实践相关的实物和场所，其传承也可以在社区或群体与自然、历史的互动中不断再创造，所以C项成立。B项把古遗址、古墓葬、古建筑这几类不可移动文物直接列入非遗范围，符合本题选非要求。","references":[],"evidence":"包括遗址、古墓葬、古建筑等不可移动文物","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3a81b6b0a2451800":{"review":{"definition":"刮目相看指改变原有看法，用新的眼光看待某人或某事，常用于他人的进步或表现超出原先预期的情形。","explanation":"第31题说有所建树者创造了“非凡业绩”，这些业绩会使人重新评价他们，因此第一空可用“刮目相看”。“叹为观止”也能表达对业绩的赞叹，需看第二空。“成就”直接指取得的成绩，与前句的“业绩”呼应，因此选A。","references":[],"evidence":"A项“刮目相看”指用新的眼光来看待","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-16cbc121e6a56841":{"review":{"definition":"心驰神往形容对某个地方、事物或境界十分向往，心思仿佛已经飞到那里。","explanation":"第32题用“神奇的世界、迷人的景象”写极地的吸引力。“心驰神往”表达读者由此产生的向往，与第一空的“人迹罕至”共同构成C项。“赏心悦目”则侧重观看时的愉悦感受。","references":[],"evidence":"神奇的世界、迷人的景象，令人","disposition":"独立词条","basis":"据原题和解析编释。","title":"心驰神往","related":[],"examFocus":{"江苏 2024 A类 行测#33":"结合“却”前后的对照判断首空描写的是哪方面的极地环境，再辨析末空成语各自侧重的感受。"}},"readings":[{"origin":"k-16cbc121e6a56841","title":"心驰神往","qs":["江苏 2024 C类 行测#32"],"definition":"心驰神往形容对某个地方、事物或境界十分向往，心思仿佛已经飞到那里。","explanation":"第32题用“神奇的世界、迷人的景象”写极地的吸引力。“心驰神往”表达读者由此产生的向往，与第一空的“人迹罕至”共同构成C项。“赏心悦目”则侧重观看时的愉悦感受。","evidence":"神奇的世界、迷人的景象，令人","doubt":"","references":[]},{"origin":"k-7faed78da06726ee","title":"心驰神往","qs":["江苏 2024 B类 行测#33"],"definition":"形容内心深切向往某个地方或某件事，思绪仿佛已到了那里。","explanation":"第二空承接“神奇的世界、迷人的景象”，用“心驰神往”写极地景象让人产生前往的愿望。“赏心悦目”侧重看到美景时的愉悦，“心旷神怡”侧重心情开阔、精神愉快。本题还需同时满足第一空，C项的“人迹罕至”贴合极地很少有人到访的特点。","evidence":"神奇的世界、迷人的景象，令人","doubt":"","references":[]},{"origin":"k-c23397166d8098e9","title":"心驰神往","qs":["江苏 2024 A类 行测#33"],"definition":"心驰神往形容内心十分向往某个地方或某种事物。","explanation":"题中“神奇的世界、迷人的景象”让人对极地产生向往，“心驰神往”写出了想亲身探访的感受。“赏心悦目”侧重观赏时的愉悦，可借此区分第二空的表达重心。","evidence":"神奇的世界、迷人的景象","doubt":"","references":[]}]},"k-85e5836961d16d42":{"review":{"definition":"引导指带领或指引，使人朝一定方向行动。激励指激发、鼓励，侧重增强行动的动力。","explanation":"第33题写项目化学习从真实问题情境出发，让学生在一段时间内持续探究。“引导”突出了教学对探究过程的指引，因此第一空选A项用词。C项“激励”侧重调动积极性，题干这一处着重交代的是如何让学生进入探究过程。","references":[],"evidence":"“引导”指带领，或指引、诱导","disposition":"独立词条","basis":"据原题和解析编释。","title":"引导与激励","related":[],"examFocus":{"江苏 2024 B类 行测#34":"结合项目化学习的过程，分别辨析第一空所写的教学作用和第二空对学生解决问题过程的修饰。"}},"readings":[{"origin":"k-85e5836961d16d42","title":"引导与激励","qs":["江苏 2024 C类 行测#33"],"definition":"引导指带领或指引，使人朝一定方向行动。激励指激发、鼓励，侧重增强行动的动力。","explanation":"第33题写项目化学习从真实问题情境出发，让学生在一段时间内持续探究。“引导”突出了教学对探究过程的指引，因此第一空选A项用词。C项“激励”侧重调动积极性，题干这一处着重交代的是如何让学生进入探究过程。","evidence":"“引导”指带领，或指引、诱导","doubt":"","references":[]},{"origin":"k-a00de15cda80491d","title":"引导与激励","qs":["江苏 2024 B类 行测#34"],"definition":"引导指指引方向或带领他人开展行动。激励指激发或增强他人行动的动力。","explanation":"第34题第一空承接“从真实的问题情境出发”，随后写学生“一段时间内持续开展探究”。“引导”说明这种教学方式借助真实问题带领学生进入并持续开展探究，“激励”则会把表述的重心放在增强学生的探究意愿上。","evidence":"“引导”指带领，或指引、诱导","doubt":"","references":[]}]},"k-820239a7053d3939":{"review":{"definition":"尝试指试着做某事。实时强调与事情发生或发展的实际时间相对应，同步强调相关事物在时间或步调上保持一致。","explanation":"第33题先写学生持续探究，再写最终形成项目成果。第二空“尝试”写学生在探究中试着创造性地解决问题。B项“实时”和D项“同步”都引入题干没有交代的时间或步调关系。C项“力求”也能表达努力解决问题的意图，最终由第一空“引导”更贴合探究过程确定A项。","references":[],"evidence":"创造性地解决问题，并最终形成项目成果","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-522fabe8cfa692f4":{"review":{"definition":"平缓指平稳、缓慢，可形容某个过程进行得平稳而不急剧。","explanation":"第34题的“时而……时而猛烈”并列描述太阳向外喷发物质和能量时的两种状态。“平缓”描写喷发较平稳、较缓和的状态，与“猛烈”构成对举，验证了由第二空选出的A项。","references":[],"evidence":"“平缓”指平稳、缓慢，与“猛烈”语义相反","disposition":"独立词条","basis":"据原题和解析编释。","title":"平缓","related":[],"examFocus":{"江苏 2024 A类 行测#35":"第一空结合“时而……时而猛烈”判断词语能否描写喷发强度，第二空比较各词对多种太阳活动发生情形的描述。"}},"readings":[{"origin":"k-522fabe8cfa692f4","title":"平缓","qs":["江苏 2024 C类 行测#34"],"definition":"平缓指平稳、缓慢，可形容某个过程进行得平稳而不急剧。","explanation":"第34题的“时而……时而猛烈”并列描述太阳向外喷发物质和能量时的两种状态。“平缓”描写喷发较平稳、较缓和的状态，与“猛烈”构成对举，验证了由第二空选出的A项。","evidence":"“平缓”指平稳、缓慢，与“猛烈”语义相反","doubt":"","references":[]},{"origin":"k-8d1a88c718e695b0","title":"平缓","qs":["江苏 2024 A类 行测#35"],"definition":"形容事物的变化或进程平稳、缓慢，也可形容地势起伏小、坡度缓。","explanation":"本题用的是变化过程平稳、缓慢的义项。“时而……、时而猛烈”描述太阳向外喷发物质和能量时的不同状态，“平缓”与“猛烈”在喷发的强度和势头上形成对照。","evidence":"“平缓”指平稳、缓慢","doubt":"","references":[]}]},"k-b0aab325a08acc4b":{"review":{"definition":"此起彼伏指这里起来、那里落下，侧重交替起落。接踵而至指紧接着到来，侧重人或事情到来得接连而紧凑。","explanation":"第34题列举黑子、耀斑、日冕物质抛射等多种太阳活动，并写这些活动引发的太阳风暴不断搅动空间环境。A项“此起彼伏”能写出多种活动相继起落的情形。C项“接踵而至”着重描写一件事紧跟着另一件事发生，题干没有突出事件之间的短间隔。","references":[],"evidence":"“此起彼伏”指这里起来，那里落下","disposition":"独立词条","basis":"据原题和解析编释。","title":"此起彼伏与接踵而至","related":[],"examFocus":{"江苏 2024 A类 行测#35":"结合前文对喷发强弱的描述和后文对多种太阳活动的列举，辨析第二空的成语各自强调怎样的变化或发生方式。"}},"readings":[{"origin":"k-b0aab325a08acc4b","title":"此起彼伏与接踵而至","qs":["江苏 2024 C类 行测#34"],"definition":"此起彼伏指这里起来、那里落下，侧重交替起落。接踵而至指紧接着到来，侧重人或事情到来得接连而紧凑。","explanation":"第34题列举黑子、耀斑、日冕物质抛射等多种太阳活动，并写这些活动引发的太阳风暴不断搅动空间环境。A项“此起彼伏”能写出多种活动相继起落的情形。C项“接踵而至”着重描写一件事紧跟着另一件事发生，题干没有突出事件之间的短间隔。","evidence":"“此起彼伏”指这里起来，那里落下","doubt":"","references":[]},{"origin":"k-b10e699b2fec9d24","title":"此起彼伏与接踵而至","qs":["江苏 2024 A类 行测#35"],"definition":"“此起彼伏”形容这里起来、那里落下，一起一落地连续发生。“接踵而至”形容人或事紧接着到来，突出先后相随。","explanation":"题干并列列举黑子、耀斑、日冕物质抛射等多种太阳活动，又说太阳风暴“不断搅动”周围环境。“此起彼伏”能写出多种活动接连发生、彼此起落的情形。“接踵而至”也表示连续，但更突出一件紧接一件到来，题干未交代这些活动到来的间隔。","evidence":"“此起彼伏”指这里起来，那里落下，表示连续不断","doubt":"","references":[]}]},"k-6bdb562d2d62b2af":{"review":{"definition":"置身事外指把自己放在某件事情之外，侧重不参与或不过问这件事。","explanation":"第35题用“面向全民”和“全覆盖”说明国防教育覆盖所有人、行业和领域。“没有一个……可以置身事外”与这种覆盖范围直接呼应。A项“漠不关心”侧重冷淡的态度，C项“袖手旁观”和D项“作壁上观”带有在一旁看着、不出手相助的意味。","references":[],"evidence":"“置身事外”指把自己放在事情之外","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1481fb97776d3f2b":{"review":{"definition":"坚持不懈指持续努力，一直不松懈。","explanation":"第35题写国防意识和国防素养“不可能自发形成”，需要持续推动国防教育进入学校、企业、社区等场所。“坚持不懈”强调这一过程要持续用力。“持之以恒”也可表达长期坚持，整题由第一空“置身事外”与“全覆盖”的对应确定B项。","references":[],"evidence":"“坚持不懈”指坚持到底，一点不松懈","disposition":"独立词条","basis":"据原题和解析编释。","title":"坚持不懈","related":[],"examFocus":{"江苏 2024 A类 行测#34":"第一空结合“面向全民”辨析成语描述的参与状态，第二空结合“不可能自发形成”判断成语能否恰当地修饰“推动”。"}},"readings":[{"origin":"k-1481fb97776d3f2b","title":"坚持不懈","qs":["江苏 2024 C类 行测#35"],"definition":"坚持不懈指持续努力，一直不松懈。","explanation":"第35题写国防意识和国防素养“不可能自发形成”，需要持续推动国防教育进入学校、企业、社区等场所。“坚持不懈”强调这一过程要持续用力。“持之以恒”也可表达长期坚持，整题由第一空“置身事外”与“全覆盖”的对应确定B项。","evidence":"“坚持不懈”指坚持到底，一点不松懈","doubt":"","references":[]},{"origin":"k-30731989854369d2","title":"坚持不懈","qs":["江苏 2024 B类 行测#32"],"definition":"指持续做一件事，始终不松懈。","explanation":"题干说国防意识和国防素养“不可能自发形成”，并列举机关、学校、企业等需要持续推进国防教育的场所。“坚持不懈”与这一长期过程贴合。“持之以恒”也能表达持续推进，但C项第一空“袖手旁观”侧重旁观而不介入，B项两空合起来最恰当。","evidence":"“坚持不懈”指坚持到底，一点不松懈","doubt":"","references":[]},{"origin":"k-837194a6a26a2087","title":"坚持不懈","qs":["江苏 2024 A类 行测#34"],"definition":"坚持不懈指持续努力，始终不松懈。","explanation":"题干指出国防意识和国防素养无法自发形成，并列举机关、学校、企业等多个需要推进国防教育的场所。实现全覆盖需要持续推动，“坚持不懈”强调这一过程。“持之以恒”也有长期坚持之义，本题由第一空的“置身事外”确定B项。","evidence":"“坚持不懈”指坚持到底，一点不松懈","doubt":"","references":[]}]},"k-560dd2d460a80162":{"review":{"definition":"效能侧重事物或措施发挥作用的能力和效率。效果侧重产生的实际结果，效益侧重取得的收益或有益成果。","explanation":"第36题写数字乡村平台将信息和服务送到户、将优质资源送到村，让村民“小事不出门、大事不出村”。第三空概括的是基层治理在提供服务、解决问题上的能力提升，A项“提升基层治理效能”的搭配贴合这层意思。B项“效果”侧重已经产生的结果，C项“效益”更容易让人把重点放在获得的收益上。","references":[],"evidence":"“提升基层治理效能”为常见搭配","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6368a078cc4ee3a6":{"review":{"definition":"你追我赶指彼此追赶、谁也不甘落后，常用来描写竞赛中的情形。","explanation":"第38题写丰收节上的趣味体育比赛，第三空紧接“一较高下”。B项“你追我赶”写出参赛者彼此追赶的动态，与后文“尽情享受、尽情释放”的场景相合。“争先恐后”侧重抢先，“你争我夺”侧重争夺，“不甘示弱”侧重不肯显得比对方差。","references":[],"evidence":"“你追我赶”形容竞赛激烈，大家都不甘落后","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5cd8af400b236ed6":{"review":{"definition":"当仁不让指遇到应该做的事，主动承担，毫不推辞。","explanation":"第38题用“当仁不让的主角”形容农民在自己的丰收节上主动参与、担当主角，后文登台歌舞、参加球赛和展示技艺的描写体现了这种主动性。A项“理所当然”和C项“顺理成章”偏重说明成为主角合乎情理，D项“毋庸置疑”偏重判断的确定性。","references":[],"evidence":"就应积极主动去做，不能推托","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1e85b29b42d2464f":{"review":{"definition":"遏制指阻止、制止某种事态继续发展，可与“趋势”“势头”等搭配。","explanation":"“生物多样性下降趋势尚未得到根本遏制”表示下降势头还没有从根本上得到制止，与下文“植物保护形势仍然十分严峻”呼应。“压制”强调以强力限制，常用于对手、火力等对象，在这里搭配欠妥。“控制”“抑制”也能表达限制下降势头，第一空不足以单独确定C项。","references":[],"evidence":"“遏制”指阻止、制止","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6325bb07762009ed":{"review":{"definition":"“严格”强调执行要求时认真从严，“严密”强调安排周密、没有疏漏，“有效”强调能够产生预期效果。","explanation":"题干提出建立以国家公园为主体的自然保护地体系，让重要自然生态系统得到保护。“最严格的保护”突出保护要求之严，“最严密的保护”也能突出保护安排周全，因此解析在第二空保留A、C两项。“最有效的保护”侧重保护成效，与这段话集中提出建立、建设和构建等举措相比，贴合度稍低。最终由第三空确定C项。","references":[],"evidence":"让重要自然生态系统得到最            的保护","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-478774e3003e6d4f":{"review":{"definition":"“统筹”强调通盘考虑、协调安排，“规划”强调拟定较全面、长远的安排，“调整”强调改动现有安排，“优化”强调使现有安排变得更好。","explanation":"题干把按人口要素安排资源布局与推动城乡区域均衡发展、构建多层级健身设施网络并列，作为公共服务体系系统性建构的具体内容。“统筹资源布局”突出对不同地区和层级的资源作整体安排，“规划资源布局”在第一空也说得通。“调整”“优化”更突出对已有布局的改动或改善。“统筹”也可用于已有资源，题中使它贴切的是全局协调的要求。","references":[],"evidence":"C项“统筹”指通盘筹划","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5a2d30ceb100fc82":{"review":{"definition":"物候指生物随季节变化而周期性出现的现象，如植物开花、昆虫羽化和鸟类迁徙等。","explanation":"第四段先说候鸟南迁寻找鱼虾昆虫等食物，再问候鸟为何还要北归。“鱼虾昆虫也有自己的物候”解释了同一地区可供捕食的食物也会随季节变化，紧接着的“食物最丰富的时间”说明候鸟会选择何时在当地集中觅食。C项只提到热带也可能食物不足，缺少这一时间规律。材料随后另举热带不利于勺嘴鹬等鸟类繁殖作为原因。","references":[],"evidence":"候鸟会选择\n在一个区域食物最丰富的时间集中觅食","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d6ec8735eb684853":{"review":{"definition":"组分的质量分数是该组分的质量占混合物总质量的比例。组分质量等于总质量乘以该组分的质量分数。","explanation":"题目以克给出每颗巧克力的质量，其中含酒2%按质量分数计算，每颗含酒10×2%＝0.2克。500毫升酒按0.9克/毫升折算为450克，可制成450÷0.2＝2250颗，按每颗17.5元计算，销售额为39375元，对应D项。","references":[],"evidence":"每颗巧克力含酒质量=10×2%=0.2克","disposition":"独立词条","basis":"据原题和解析编释。","title":"质量分数","related":[],"examFocus":{"江苏 2024 A类 行测#51":"先辨明含酒比例的计量口径，再用密度统一总酒量和每颗用酒量的单位。"}},"readings":[{"origin":"k-d6ec8735eb684853","title":"质量分数","qs":["江苏 2024 C类 行测#51"],"definition":"组分的质量分数是该组分的质量占混合物总质量的比例。组分质量等于总质量乘以该组分的质量分数。","explanation":"题目以克给出每颗巧克力的质量，其中含酒2%按质量分数计算，每颗含酒10×2%＝0.2克。500毫升酒按0.9克/毫升折算为450克，可制成450÷0.2＝2250颗，按每颗17.5元计算，销售额为39375元，对应D项。","evidence":"每颗巧克力含酒质量=10×2%=0.2克","doubt":"","references":[]},{"origin":"k-e9faef3189cf8646","title":"质量分数","qs":["江苏 2024 B类 行测#51"],"definition":"某组分的质量分数是该组分质量与整体总质量之比，通常用百分数表示。组分质量等于总质量乘以该组分的质量分数。","explanation":"本题按质量分数理解“含酒2%”，每颗10克巧克力含酒0.2克。500毫升酒按0.9克/毫升换算为450克，可制成450÷0.2＝2250颗，按每颗17.5元计算，销售额为39375元。","evidence":"每颗巧克力含酒质量=10×2%=0.2克","doubt":"","references":[]},{"origin":"k-fed01d05c67ff743","title":"质量分数","qs":["江苏 2024 A类 行测#51"],"definition":"质量分数是某组分的质量占混合物总质量的比例，常用百分数表示。组分质量等于总质量乘以该组分的质量分数。","explanation":"第51题的2%以每颗巧克力的10克总质量为基数，每颗用酒10×2%=0.2克。500毫升酒按密度换算为450克，可做2250颗，每颗售价17.5元，销售额为39375元。","evidence":"每颗的质量为10克，其中含酒2%","doubt":"","references":[]}]},"k-7efa2cd90442f578":{"review":{"definition":"商品打几折，指按原价的十分之几付款。优惠比例等于1减去实付比例，优惠金额等于原价乘以优惠比例。","explanation":"小王买2件甲、4件乙，分别达到八折和六折门槛，因此两种商品分别优惠原价的20%和40%。设甲商品原单价为x元，乙为25－x元，由总优惠16元得2×20%×x＋4×40%×(25－x)＝16，解得甲商品原单价为20元，对应D项。","references":[],"evidence":"购买甲商品2件及以上可享受八折优惠，购买乙商品4件及以上可享受六折优惠","disposition":"独立词条","basis":"据原题和解析编释。","title":"折扣","related":[],"examFocus":{"国考 2025 地市级 行测#68":"看销量—收入图像时，比较各计价区间内每多卖一千克所增加的收入与该段图线斜率的关系。","江苏 2024 C类 行测#53":"先按购买件数判断两种商品各自适用的折扣，再结合原单价之和与总优惠额列方程。"}},"readings":[{"origin":"k-7efa2cd90442f578","title":"折扣","qs":["江苏 2024 C类 行测#53"],"definition":"商品打几折，指按原价的十分之几付款。优惠比例等于1减去实付比例，优惠金额等于原价乘以优惠比例。","explanation":"小王买2件甲、4件乙，分别达到八折和六折门槛，因此两种商品分别优惠原价的20%和40%。设甲商品原单价为x元，乙为25－x元，由总优惠16元得2×20%×x＋4×40%×(25－x)＝16，解得甲商品原单价为20元，对应D项。","evidence":"购买甲商品2件及以上可享受八折优惠，购买乙商品4件及以上可享受六折优惠","doubt":"","references":[]},{"origin":"k-e9e779b4e01c1c15","title":"折扣","qs":["国考 2025 地市级 行测#68"],"definition":"商品打几折，表示按原价的十分之几出售。例如，打2折时，售价为原价的20%。","explanation":"第68题按销量分段计价。前60千克按原单价的20%出售，之后60千克按50%出售，最后80千克按100%出售。因此，各段每多卖1千克所增加的收入依次增大。","evidence":"前60千克打2折出售，之后60千克打5折出售，剩余部分原价出售","doubt":"","references":[]}]},"k-3f0f339205dbaee3":{"review":{"definition":"某一时刻的上座率等于该时刻已占用的座位数除以座位总数。","explanation":"20个座位的上座率不得低于80%，所以每个营业时点至少有16人在座。在11:00至14:00的接待时段内，取11:00、11:51、12:42和13:33。相邻时点间隔51分钟，超过同一顾客最多停留的50分钟，因此四次在座的顾客互不重叠，至少需要64人。安排每批16人分别在11:00、11:50、12:40和13:30入座，每批停留50分钟，即可持续覆盖该时段，且所有顾客都在14:00前入场。因此64人可达到，对应C项。","references":[],"evidence":"20×80%=16","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-798eb73977307bd2":{"review":{"definition":"公差是等差数列中每一项减去它的前一项所得的固定差值。","explanation":"按年龄从小到大排列，四人的平均年龄为35.5岁，位于中间两个年龄之间。47岁高于平均年龄，只可能排在最大的两项中，而各选项均给出大于47岁的最大年龄，因此47岁是第二大年龄。它比第三大年龄24岁大23岁，再加一个公差即得最大年龄70岁，对应B项。","references":[],"evidence":"47-24=23岁","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fb0360265486fb6d":{"review":{"definition":"溶质的质量分数是溶质质量与溶液总质量之比，常用百分数表示。","explanation":"甲瓶起初含溶质50×80%＝40克。第一次加水后溶液总质量增至100克，溶质仍为40克，因此浓度为40%。求乙瓶的最终浓度时，把两次倒入的溶质质量16克和9.6克相加，再除以乙瓶的溶液总质量80克，得32%，选B。","references":[],"evidence":"100克浓度为80%÷2=40%的溶液","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1ee9cf0331890677":{"review":{"definition":"吴王喜好剑客，百姓因此多有伤痕。“创瘢”在句中指伤疤。","explanation":"前句交代原因，后句写百姓所受的影响。D项也由前句说明后句，“烽火连三月”解释了“家书抵万金”。B项的前句“问君何能尔”则提出问题，由后句作答。","references":[],"evidence":"吴王喜爱精通剑术的侠客，为此老百姓身上伤痕累累","disposition":"独立词条","basis":"据原题和解析编释。","title":"吴王好剑客，百姓多创瘢","related":[],"examFocus":{"江苏 2024 A类 行测#68":"读准每组诗句的句意，比较前句能否解释后句所写的现象。"}},"readings":[{"origin":"k-1ee9cf0331890677","title":"吴王好剑客，百姓多创瘢","qs":["江苏 2024 C类 行测#67"],"definition":"吴王喜好剑客，百姓因此多有伤痕。“创瘢”在句中指伤疤。","explanation":"前句交代原因，后句写百姓所受的影响。D项也由前句说明后句，“烽火连三月”解释了“家书抵万金”。B项的前句“问君何能尔”则提出问题，由后句作答。","evidence":"吴王喜爱精通剑术的侠客，为此老百姓身上伤痕累累","doubt":"","references":[]},{"origin":"k-f306d601aeb24263","title":"吴王好剑客，百姓多创瘢","qs":["江苏 2024 A类 行测#68"],"definition":"吴王喜爱擅长剑术的人，百姓受这种风气影响，身上多有伤疤。「好」是喜爱，「创瘢」是伤疤。","explanation":"句意把吴王的喜好写成百姓多有伤疤的原因，前句是因，后句是果。D项先交代战火持续，再写家书因而格外珍贵，因果方向相同。","evidence":"吴王喜爱精通剑术的侠客，为此老百姓身上伤痕累累。","doubt":"","references":[]}]},"k-c4a4fca790f433ff":{"review":{"definition":"“海沟”的“海”指海洋，说明海沟位于海底。“海量”的“海”借海的广阔形容数量、酒量或度量很大。","explanation":"题干先用“海”指出海沟的实际所在，再借海的广阔形容量大，排列顺序是本义在前、比喻用法在后。B项的“碑座”和“碑林”都保留了“碑”指石碑的含义，缺少这一变化。","references":[],"evidence":"其中“海”指像海一样，是海的引申义","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c454c530ac6293ee":{"review":{"definition":"“火焰”的“火”取物体燃烧的本义。“火气”在本题取怒气、易动怒的脾气这一义项，由火的炽烈引申。","explanation":"题干的“海沟”直接指涉海洋，“海量”借海的广大形容量大。C项的“火焰”直接指涉燃烧，“火气”借火的炽烈表达怒气，语素层面的对应更具体。辞书也收录“心腹”的身体部位义和亲信义，说明D项同样有引申现象。若只比较后一个词有没有引申义，区分不了C和D。题解选择C所用的更细标准，是比较首字本义所指事物的特征是否直接用来形容后一个词的含义。","references":[{"source":"web-ef742bceaed7dd98","location":"“心腹”条，释义第4项","quote":"親信可靠的人"},{"source":"web-c6be0cc52b2248e5","location":"“火氣”条，释义第2项","quote":"脾氣不佳，遇事容易動怒"}],"evidence":"“火气”多指怒气、暴躁的脾","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-493c009c74f48485":{"review":{"definition":"梅花糕是一种外形像梅花的糕点，名称取自糕点的外形。","explanation":"题干的“梅花”提供命名所据的形状，“糕”指出所属类别。D项的“面包”与“车”分别起同样的作用。A项的“葡萄”指酿制葡萄酒所用的原料。","references":[],"evidence":"“梅花糕”因外形像“梅花”而得名，“梅花糕”是“糕”的一种","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-12a1f0f94376c9f0":{"review":{"definition":"面包车是一类因车身外形像面包而得名的汽车。","explanation":"D项用“面包”比拟车身外形，用“车”指出所属类别，对应题干的“梅花”与“糕”。题解还比较了对象的属性，面包车与梅花糕都是人工制品，这一共同点用于进一步区分D项与B项。","references":[],"evidence":"“面包车”因外形像“面包”而得名，“面包车”是“车”的一种","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e2526631be917dae":{"review":{"definition":"珊瑚树（Viburnum odoratissimum）是荚蒾属的常绿灌木或小乔木。中国科学院华南植物园将这一名称归于其果实形似珊瑚。","explanation":"华南植物园的介绍具体指向由橙红渐变为紫黑色的椭圆形果实。按题目的比较方式，B项具备借外观命名和种属关系这两层对应，但相似点在果实，且珊瑚树是植物。梅花糕与面包车都是人工制品，名称都借用整个制品的外形，所以D项匹配更完整。","references":[{"source":"web-81a9bd72c8884db0","location":"第3卷，荚蒾属“珊瑚树”形态描述","quote":"常绿灌木或小乔木"},{"source":"web-b113d9f8ae9cea8e","location":"正文首段，果实特征与得名","quote":"形似珊瑚，观赏性很高，故而得名"}],"evidence":"“珊瑚树”是“树”的一种","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-f28a04a2b8adebee":{"review":{"definition":"期刊是定期出版的刊物。月刊是按月出版的期刊。","explanation":"月刊按出版周期划分，属于期刊，目录页则是本题所指月刊的组成部分。A项中，公寓属于房屋，天花板是公寓的组成部分，两组关系的顺序一致。","references":[],"evidence":"期刊是定期出版的刊物，月刊是期刊的一种","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-091087790f3288aa":{"review":{"definition":"螳臂当车比喻高估自己的力量，去做力所不能及的事。自不量力指不能正确估量自己的能力，多指去做超出能力范围的事。","explanation":"螳臂当车常用来形容以弱小力量阻挡强大事物，自不量力的适用范围更广。两词都能形容高估自身能力而去做办不到的事，因此A项后半组与前半组同为近义关系。D项的自以为是侧重认定自己的看法或做法正确。","references":[],"evidence":"“螳臂当车”比喻不正确估计自己的力量，去做办不到的事情","disposition":"独立词条","basis":"据原题和解析编释。","title":"螳臂当车与自不量力","related":[],"examFocus":{"江苏 2024 A类 行测#74":"把成语分别代入两空，比较每对成语的含义和使用情境，判断前后两组的词义关系是否一致。"}},"readings":[{"origin":"k-091087790f3288aa","title":"螳臂当车与自不量力","qs":["江苏 2024 C类 行测#74"],"definition":"螳臂当车比喻高估自己的力量，去做力所不能及的事。自不量力指不能正确估量自己的能力，多指去做超出能力范围的事。","explanation":"螳臂当车常用来形容以弱小力量阻挡强大事物，自不量力的适用范围更广。两词都能形容高估自身能力而去做办不到的事，因此A项后半组与前半组同为近义关系。D项的自以为是侧重认定自己的看法或做法正确。","evidence":"“螳臂当车”比喻不正确估计自己的力量，去做办不到的事情","doubt":"","references":[]},{"origin":"k-1b48d3f941d81a5c","title":"螳臂当车与自不量力","qs":["江苏 2024 A类 行测#74"],"definition":"螳臂当车比喻力量不足却试图阻挡强大的对手或事物。自不量力指不能正确估计自己的力量，多指高估自己，去做力所不能及的事。","explanation":"“螳臂当车”突出用弱小的力量去抵挡强大的事物，是自不量力的一种表现。A 项后一组据此构成近义关系，与前一组“杞人忧天”和“庸人自扰”的关系一致。D 项的“自以为是”侧重认定自己的看法或做法正确，和估计自身力量是两回事。","evidence":"“螳臂当车”比喻不正确估计自己的力量，去做办不到的事情","doubt":"","references":[]}]},"k-77a64397a6f6aca8":{"review":{"definition":"按第111题资料的统计口径，直播电商行业渗透率是直播电商行业交易额占同期网络零售交易额的比重。","explanation":"直播电商行业交易额是部分量，网络零售交易额是整体量。用2022年的部分量3.5万亿元除以同期渗透率25.3%，得到网络零售交易额约13.83万亿元，最接近C项的13.8万亿元。","references":[],"evidence":"直播电商行业交易额为3.5万亿元，较2017年增长178倍，直播电商行业渗透率","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-02f95120c4d77597":{"review":{"definition":"年均量是某项指标在指定时期内各年度数量的算术平均值，等于各年度数量之和除以所含年数。","explanation":"第121题的“十三五”时期包含2016—2020年共5个完整年度。据C卷考生回忆版题表，这5年的酱油进口量依次为1.38、1.46、1.34、1.45和1.18万吨，合计6.81万吨，除以5得1.362万吨。2022年进口量为1.17万吨，两者相差0.192万吨，保留两位小数为0.19万吨，选A。","references":[{"source":"web-8b45be6e45595e34","location":"第22页，年份与进口量列，2016—2020年及2022年各行。本题在该版列为第111题。","quote":"表 2015-2022 年我国酱油进出口情况"}],"evidence":"（2016-2020年）的年均进口量","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-8ab3efd4847d5ca0":{"review":{"definition":"进出口均价是同一时期同一商品的单位贸易金额。进口均价等于进口额除以进口量，出口均价等于出口额除以出口量。","explanation":"第125题所附图片是地区社会经济指标表。用世界银行 WITS 公布的2022年中国酱油（HS 210310）对全球贸易数据复算，进口额为19,039.61千美元，进口量为11,673,800千克，出口额为183,844.69千美元，出口量为186,096,000千克。统一换算为美元和吨后，进口均价约为1,631美元/吨，出口均价约为988美元/吨。以出口均价为基准，进口均价高约65.1%，支持A项的“高50%以上”。题干要求选出不能推出的一项，标准答案为D。","references":[{"source":"web-84e413011158f2ba","location":"HS 210310，页面摘要及表格 World 行","quote":"$19,039.61K and quantity 11,673,800Kg"},{"source":"web-3bd3adce2fc5e6fb","location":"HS 210310，页面摘要及表格 World 行","quote":"$183,844.69K and quantity 186,096,000Kg"}],"evidence":"2022年我国酱油进口均价比出口均价高50%以上","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-dee48688f3918eab":{"review":{"definition":"“两个结合”指把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合。","explanation":"江苏2025年A类行测第1题的②同时写出两个结合，并以马克思主义这个魂脉和中华优秀传统文化这个根脉相互贯通，说明习近平新时代中国特色社会主义思想是中华文化和中国精神的时代精华。②属于正确组合B中的表述。","references":[],"evidence":"同中国具体实际相结合，同中华优秀传统文化相结合","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-95491b6a9bb3eff5":{"review":{"title":"高质量充分就业的宏观与微观内涵","type":"概念与词义","definition":"习近平《促进高质量充分就业》指出，宏观层面主要看就业机会是否充分、就业环境是否公平、就业结构是否优化、人岗匹配是否高效、劳动关系是否和谐。微观层面主要看劳动者是否有活干，以及工作是否稳定、收入是否合理、保障是否可靠、职业是否安全。","explanation":"宏观层面关注就业规模、结构和整体运行状况，微观层面关注劳动者获得就业后的实际工作条件和权益保障。文章将实现高质量充分就业视为循序渐进的过程，提出尽力而为、量力而行。","basis":"据关联原题及所列出处编释。","references":[{"source":"jobs","location":"高质量充分就业的内涵"}],"related":["k-c9e54faa00997e23","k-1ee6f0c02f41907a","k-5dfa658086207b9d"],"domain":"公共管理","examFocus":{"江苏 2025 A类 行测#8":"区分高质量充分就业的总体指标与个人就业状况，核对微观表述所覆盖的人群。"}},"aspects":[{"title":"宏观指标与微观层面的适用对象","uses":[{"unit":"Q1","role":"直接考查","use":"本题均选C。①列举了宏观层面的就业指标，②把微观层面的适用对象由文章中的“劳动者”改成了“每个公民”。③的循序渐进要求和④列举的五项部署也符合文章表述。","evidence":"在微观层面，高质量充分就业主要表现\n为劳动者不仅有活干，而且工作稳定、收入合理、保障可靠、职业安全等。","qids":["江苏 2025 A类 行测#8","江苏 2025 B类 行测#8"]}]}]},"k-20983490e2e16d00":{"review":{"definition":"原题引文：通过五年规划、年度政府工作报告等制度性安排形成了前瞻性指引","explanation":"本题给定答案为C，与公开题库的参考答案一致。五年规划等中长期发展规划明确未来发展目标和政策方向，为公众形成稳定预期提供依据，因此C是预期管理的具体实践。就B而言，清晰的政策沟通有助于减少政策不确定性引发的部分市场波动，股票交易风险还受上市公司经营等因素影响。B项说的是“可以降低”，解析反驳的是“单靠预期管理不能降低”。风险来源多样只能说明政策沟通的作用有范围，仍不足以排除它在一定条件下降低部分风险的可能。","references":[{"source":"web-6cfb9bbcfbd30f9a","location":"预期管理部分，张晓晶谈预期管理的时间维度","quote":"通过五年规划、年度政府工作报告等制度性安排形成了前瞻性指引"},{"source":"web-10275d480cf13989","location":"第二部分常识判断，第15题B项及参考答案","quote":"通过预期管理可以降低股票市场的交易风险"},{"source":"web-d00c2c95c7016aea","location":"第82页，表3第3列结果与图5前的讨论","quote":"Equity market volatility does not react significantly to Fed communication events."},{"source":"web-603afe78d94bc6e1","location":"第三节“如何分析业绩大幅波动公司风险”","quote":"随着经营业绩的大幅波动，公司股票价格也大幅变化"}],"evidence":"通过五年规划、年度政府工作报告等制度性安排形成了前瞻性指引","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-1f87802c46c3a661":{"review":{"definition":"逆向思维是从与惯常做法相反的角度思考问题，例如反转奖惩的对象，或改变解决问题的着力点。","explanation":"第18题中，餐厅从向浪费者加收10元改为先提价10元、再向未浪费者奖励10元。两种方案下，同类顾客的实际支出相同，但规则从处罚浪费转为奖励节约。A项司马光砸缸也反转了处理思路，从设法让孩子离开水转为让水离开孩子。","references":[],"evidence":"将价格提高10元，并规定对未浪费食物者奖励10元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7cfe6a4fed5de463":{"review":{"definition":"一路凯歌形容一路接连取得胜利或成绩。一枝独秀形容在同类中格外突出，独占鳌头指在竞争中夺得第一。","explanation":"第36题开头写江苏高端制造“不断刷新纪录，取得创新成果”，随后又写4个集群入选，这些信息能支撑“一路凯歌”所表达的接连取得成绩。题干给出了全国入选总数和江苏入选数，凭这两个数字还无法与其他地区逐一比较，也无法确定江苏的名次。","references":[],"evidence":"江苏高端制造不断刷新纪录，取得创新成果","disposition":"独立词条","basis":"据原题和解析编释。","title":"一路凯歌、一枝独秀与独占鳌头","related":[],"examFocus":{"江苏 2025 A类 行测#36":"首空看动词是否贴合集群进入公布名单的情境，次空看材料能否支撑成语所含的成绩延续性或地区间比较。"}},"readings":[{"origin":"k-7cfe6a4fed5de463","title":"一路凯歌、一枝独秀与独占鳌头","qs":["江苏 2025 A类 行测#36"],"definition":"一路凯歌形容一路接连取得胜利或成绩。一枝独秀形容在同类中格外突出，独占鳌头指在竞争中夺得第一。","explanation":"第36题开头写江苏高端制造“不断刷新纪录，取得创新成果”，随后又写4个集群入选，这些信息能支撑“一路凯歌”所表达的接连取得成绩。题干给出了全国入选总数和江苏入选数，凭这两个数字还无法与其他地区逐一比较，也无法确定江苏的名次。","evidence":"江苏高端制造不断刷新纪录，取得创新成果","doubt":"","references":[]},{"origin":"k-e478549ffaf2f3a6","title":"一路凯歌、一枝独秀与独占鳌头","qs":["江苏 2025 B类 行测#36"],"definition":"一路凯歌形容在前进过程中接连取得好成绩。一枝独秀形容在同类中格外突出，独占鳌头指在竞争中夺得第一。","explanation":"“不断刷新纪录，取得创新成果”写的是江苏接连取得成绩，4个集群入选又是其中一项成果，因此第二空用“一路凯歌”。题中没有给出各地的比较结果，无法据此判断江苏是否在同类中最突出或在评选中排名第一。","evidence":"江苏高端制造不断刷新纪录，取得创新成果","doubt":"","references":[]}]},"k-5b2574f13775e6c6":{"review":{"definition":"大浪淘沙比喻在激烈竞争或严峻考验中经受筛选，有的被淘汰，有的得以留下。","explanation":"第38题把许多产业在技术更迭中被淘汰与出版业始终屹立并列起来，写出了筛选的两种结果。“百舸争流”能描写竞相争先的局面，“大浪淘沙”更直接呼应“被淘汰”。","references":[],"evidence":"出版业却始终屹立不倒","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c5f64b516ff7dab5":{"review":{"definition":"推陈出新指对旧有事物加以取舍和革新，发展出新事物。独辟蹊径指另行开辟一条新的道路，比喻独创方法或风格。","explanation":"第38题列举从纸质到电子介质、从印刷术到激光照排，以及后来应用人工智能、研发推广数字产品等变化，着重说明出版社随技术演进不断更新出版方式和产品。“独辟蹊径”还要求语境能够支撑方法或路径的独创性，而这些例子主要说明持续革新。","references":[],"evidence":"再到人工智能的广泛应用与数字产品的研发推广","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e024251a90fff4b0":{"review":{"definition":"一马当先比喻走在前面、率先行动或发挥带头作用。","explanation":"第39题先说“领导细胞”在修复中发挥主要作用，再写它们迅速闭合伤口，随后细胞才快速增殖。“一马当先”对应先行闭合的作用。“争先恐后”侧重竞相向前，“首当其冲”侧重最先受到冲击。“身先士卒”也可比喻带头，第一空因此还保留了B项。","references":[],"evidence":"迅速闭合伤口，然后细胞快速增殖","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ea520e2231b55fe0":{"review":{"definition":"“生成”侧重由某个过程产生新的事物，“形成”侧重经过发展变化而成为某种事物或状态。两词在描述新组织出现时有语义重叠。","explanation":"题干先说领导细胞迅速闭合伤口，再说细胞增殖，第二空的“生成新组织”着重表达新组织的产生。科技日报原报道第一空用“一马当先”，第二空用“制造新组织”，可为C项第一空提供直接依据。医学报道也有“形成新组织”的用例，第二空的搭配本身不足以排除B项。","references":[{"source":"web-099fc53bca60daab","location":"正文末段","quote":"这些细胞一马当先"},{"source":"web-4129a1cc372d1bf4","location":"正文首段","quote":"细胞则活下来形成新组织"}],"evidence":"肝脏优先考虑闭合伤口，防止细菌进入器官引起广泛感染。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-63684c8c20b96130":{"review":{"title":"一脉相承与源远流长","type":"概念与词义","definition":"一脉相承指从同一脉络继承和发展下来。源远流长本指水源很远、水流很长，比喻历史悠久、根基深厚。","explanation":"一脉相承可用于思想、制度或文化在不同时代之间的承继关系。源远流长可用于文化、习俗等具有久远源头和长期传承的事物。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典一脈相承","location":"“一脈相承”词目"},{"source":"词典源遠流長","location":"“源遠流長”词目"}],"related":[],"examFocus":{"江苏 2025 A类 行测#40":"结合题干梳理的中华法系发展历程，辨析末空各成语与“延续性”的语义搭配。"}},"readings":[{"origin":"k-63684c8c20b96130","title":"一脉相承与源远流长","qs":["江苏 2025 A类 行测#40","江苏 2025 B类 行测#42"],"definition":"一脉相承指从同一脉络继承和发展下来。源远流长本指水源很远、水流很长，比喻历史悠久、根基深厚。","explanation":"一脉相承可用于思想、制度或文化在不同时代之间的承继关系。源远流长可用于文化、习俗等具有久远源头和长期传承的事物。","evidence":"","doubt":"","references":[{"source":"词典一脈相承","location":"“一脈相承”词目"},{"source":"词典源遠流長","location":"“源遠流長”词目"}]},{"origin":"k-cb14e75b6245b8e5","title":"一脉相承与源远流长","qs":["江苏 2025 C类 行测#41"],"definition":"“一脉相承”强调沿同一脉络传承下来。“源远流长”强调起源久远、历史悠久。","explanation":"题干按秦、隋唐、宋元明清梳理中华法系的发展，并以此说明中华文明的“延续性”。第三空用“一脉相承”能直接点出历代之间的承接关系，“源远流长”主要突出历史的长度。","evidence":"应体现连贯性，连续性","doubt":"","references":[]}],"aspects":[{"title":"传统的承续关系与历史渊源","uses":[{"unit":"Q1","role":"直接考查","use":"材料沿秦、隋唐至宋元明清叙述中华法系的发展，末空与“延续性”呼应，突出传统法律文化在各时期的承续，对应B项“一脉相承”。","evidence":"也反映了中华文明          的延续性。","qids":["江苏 2025 A类 行测#40","江苏 2025 B类 行测#42"]}]}]},"k-b4e4259ce98b4134":{"review":{"definition":"功不可没指已经作出的贡献应得到承认，功劳不可抹杀。","explanation":"第41题把“一堆一器”称为核事业的“奠基之作”，并列举它在基础研究、相关研制和和平利用原子能中的作用，“功不可没”概括的是这些具体贡献。“举足轻重”侧重地位或作用足以影响全局，也能适配第二空，A、C两项最终由第三空的情感搭配区分。","references":[],"evidence":"中国核事业的奠基之作","disposition":"独立词条","basis":"据原题和解析编释。","title":"功不可没","related":[],"examFocus":{"江苏 2025 A类 行测#41":"读到第二空时，结合前文列举的用途，辨析各成语是在评价“一堆一器”的地位、作用还是贡献。"}},"readings":[{"origin":"k-b4e4259ce98b4134","title":"功不可没","qs":["江苏 2025 A类 行测#41"],"definition":"功不可没指已经作出的贡献应得到承认，功劳不可抹杀。","explanation":"第41题把“一堆一器”称为核事业的“奠基之作”，并列举它在基础研究、相关研制和和平利用原子能中的作用，“功不可没”概括的是这些具体贡献。“举足轻重”侧重地位或作用足以影响全局，也能适配第二空，A、C两项最终由第三空的情感搭配区分。","evidence":"中国核事业的奠基之作","doubt":"","references":[]},{"origin":"k-d665b6c68c5b4103","title":"功不可没","qs":["江苏 2025 B类 行测#45"],"definition":"功不可没指所作的贡献值得肯定，其功劳不可抹杀。","explanation":"第二空用来评价“一堆一器”对基础研究、“两弹一艇”研制和和平利用原子能的贡献，“功不可没”贴合“奠基之作”的评价。“劳苦功高”还强调做事勤苦，通常用来赞扬付出辛劳的人。题中评价的对象是设施，叙述着重于它发挥的作用。","evidence":"从基础研究，到“两弹一艇”研制，再到和平利用原子能","doubt":"","references":[]}]},"k-d126baba5bc87615":{"review":{"definition":"“夸父逐日”源于夸父追赶太阳的神话，本题取追求目标的决心很大这一义项。“剥茧抽丝”形容分析事物时细致而有层次。","explanation":"第一空修饰“追问”，“难以遏制”突出人们追索文明起源的执着。“剥茧抽丝”所强调的逐层分析更接近下文借遗迹和物证探究历史的过程。第一空还有其他能表达执着的选项，D项由第二空“还原历史的图景”进一步确定。","references":[],"evidence":"“夸父逐日”比喻决心很大","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a288b918ba51fdf5":{"review":{"definition":"“还原”有使事物恢复原状的意思。“还原历史图景”指凭借遗迹、文物等证据重现过去的面貌。","explanation":"第二空将考古发现的物证写成重现历史图景的依据，与“早已湮灭的文明再见天日”呼应。“组合”和“拼合”侧重把若干部分合成整体，“还原”进一步表明合成的目的在于反映历史原貌。","references":[],"evidence":"“还原”指事物恢复原状","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e07591671f29d414":{"review":{"title":"不期而遇与心心相印","type":"概念与词义","definition":"不期而遇指没有事先约定而意外相遇。心心相印形容彼此心意相通。","explanation":"不期而遇可以从人与人的偶遇引申到人与事物的偶然接触。心心相印用于能够彼此理解心意的人或群体，强调双方的默契。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典不期而遇","location":"“不期而遇”词目"},{"source":"词典心心相印","location":"“心心相印”词目"}],"related":[],"examFocus":{"江苏 2025 A类 行测#43":"结合微博留言和教材换图的例子，辨析第二空的成语能否描述公众与探月成果的关系，并留意第三空与“共识”的搭配。"}},"readings":[{"origin":"k-e07591671f29d414","title":"不期而遇与心心相印","qs":["江苏 2025 A类 行测#43","江苏 2025 B类 行测#44"],"definition":"不期而遇指没有事先约定而意外相遇。心心相印形容彼此心意相通。","explanation":"不期而遇可以从人与人的偶遇引申到人与事物的偶然接触。心心相印用于能够彼此理解心意的人或群体，强调双方的默契。","evidence":"","doubt":"","references":[{"source":"词典不期而遇","location":"“不期而遇”词目"},{"source":"词典心心相印","location":"“心心相印”词目"}]},{"origin":"k-f3e8620038663ffc","title":"不期而遇与心心相印","qs":["江苏 2025 C类 行测#44"],"definition":"“不期而遇”指未经约定而意外相遇，可引申为偶然接触。“心心相印”形容双方心意相通。","explanation":"微博上的玉兔和教材里的中国月面图，都是公众在日常生活中接触探月工程的途径。第二空写公众与探月成果的相遇，用“不期而遇”贴切。“成果”“侧面”无法与公众形成“心心相印”所要求的双方心意相通的关系。","evidence":"越来越多的人与探月工程的某项成果、某个侧面","doubt":"","references":[]}],"aspects":[{"title":"偶然接触与心意相通的适用对象","uses":[{"unit":"Q1","role":"直接考查","use":"文段借社交媒体和新版教材等例子写公众在日常生活中接触探月成果。第二空的对象是探月工程的成果或侧面，选C项“不期而遇”。","evidence":"越来越多的人与探月工程的某项成果、某个侧面","qids":["江苏 2025 A类 行测#43","江苏 2025 B类 行测#44"]}]}]},"k-94c2a932f5e06af6":{"review":{"title":"凝聚共识","type":"概念与词义","definition":"使不同主体围绕同一事项形成或巩固共同认识。","explanation":"“共识”可以是对事实的共同判断，也可以是对行动方向的一致认同。它针对特定事项，各方仍可在其他问题上保留分歧。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典凝聚","location":"“凝聚”词目"},{"source":"词典共識","location":"“共識”词目"}],"related":[],"examFocus":{"江苏 2025 A类 行测#43":"结合探月成果走近公众的事例，辨析第二空怎样描述公众与成果的接触，再看末空动词能否与“共识”搭配。"}},"readings":[{"origin":"k-94c2a932f5e06af6","title":"凝聚共识","qs":["江苏 2025 A类 行测#43","江苏 2025 C类 行测#44"],"definition":"使不同主体围绕同一事项形成或巩固共同认识。","explanation":"“共识”可以是对事实的共同判断，也可以是对行动方向的一致认同。它针对特定事项，各方仍可在其他问题上保留分歧。","evidence":"","doubt":"","references":[{"source":"词典凝聚","location":"“凝聚”词目"},{"source":"词典共識","location":"“共識”词目"}]},{"origin":"k-6b39929076145a79","title":"凝聚共识","qs":["江苏 2025 B类 行测#44"],"definition":"凝聚共识指围绕同一问题汇聚各方的认识，逐渐形成共同看法。","explanation":"文中，人们通过玉兔微博、中国月面图进入教材等途径接触探月成果，逐渐形成“我们离月球并不遥远”的共同认识。“一个共识在人们心中不断凝聚”写的是共同看法逐渐形成并得到更多人认同。","evidence":"“凝聚共识”为常见搭配","doubt":"","references":[]}],"aspects":[{"title":"“共识”与“凝聚”的搭配","uses":[{"unit":"Q1","role":"直接考查","use":"本题、C类 行测#44均选C。公众接触探月成果后，逐渐形成“我们离月球并不遥远”的共同认识，因此末空用“凝聚”。","evidence":"“凝聚共识”为常见搭配","qids":["江苏 2025 A类 行测#43","江苏 2025 C类 行测#44"]}]}]},"k-9e1e371e8dd52639":{"review":{"definition":"“篇章”可比喻事业或历史进程中的一段。“开启篇章”侧重开创一个阶段，“谱写篇章”侧重创造值得记载的事迹或成就。","explanation":"题干用“辉煌篇章”概括先民栽培粟黍、烧制陶器、发明冶铁等创造在农业文明中的意义，“开启”和“谱写”都能与之搭配。区分A、D要看第二空，造纸和印刷为文化传承提供的是“依托”，因此选D。","references":[],"evidence":"D项“开启”指开创","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e1d0a963c7041a53":{"review":{"definition":"“依托”指依靠、凭借，也可指所凭借的事物。“借鉴”指参考别人的做法或以往的事例，从中吸取经验或教训。","explanation":"第二空说的是造纸术和雕版印刷为文化传承发展提供技术基础，所以用“提供了重要依托”。“借鉴”需要有可供参照并从中吸取经验的对象，题干交代的是技术对文化传承的支撑作用。","references":[],"evidence":"“依托”指依靠，凭借","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-123546c07808866c":{"review":{"definition":"“挟持”指凭借强力迫使对方服从，也可比喻一方以强力约束另一方。","explanation":"第一空把高原土层对黄河流向的约束拟人化，与黄河越过三门峡后像“野马”一样到处奔流形成对照。“裹挟”强调把别的事物卷入并带着移动。“束缚”也能表示限制，因此还要借第二空区分B、D。","references":[],"evidence":"“挟持”指用威力强迫对方服从","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-338787225a1b8e98":{"review":{"definition":"“肆无忌惮”形容任意妄为、毫无顾忌。“风驰电掣”形容速度极快。","explanation":"第二空用“野马”比喻黄河进入平原后的状态。下文写河水时而向东北流入渤海，时而向东南夺取淮河河道注入黄海，突出河道走向变化、奔流少有约束，因此B项“肆无忌惮”比D项描写速度的“风驰电掣”贴合。","references":[],"evidence":"“肆无忌惮”指恣意妄行，毫无顾忌","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-981b89a50777936e":{"review":{"definition":"“淤积”指水中的泥沙等物质沉积并逐渐堆积。","explanation":"第三空的主语是黄河携带的泥沙，结果是形成华北平原。“淤积”具体写出了泥沙从河水中沉积下来并长期堆积的过程，比只表示数量逐渐增多的“积累”更贴合。","references":[],"evidence":"“淤积”指（水里的泥沙等）沉积","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-330744c5c4e01828":{"review":{"title":"积蓄","type":"概念与词义","definition":"作动词时指逐渐积聚并储存。作名词时通常指积存的钱财。","explanation":"“积蓄力量”强调力量逐渐积聚，留待发挥。“蕴藏力量”着重说明力量存在于内部或尚未显现。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典積蓄","location":"“積蓄”词目"}],"examFocus":{"江苏 2025 A类 行测#46":"结合种子从沉睡到苏醒的描写，辨别不同动词与“生命的力量”搭配时所表达的状态。","江苏 2025 C类 行测#46":"结合种子从沉睡到苏醒的描写，辨别不同动词与“生命的力量”搭配时所表达的状态。"}},"aspects":[{"title":"“积蓄”与“力量”的搭配","uses":[{"unit":"Q1","role":"直接考查","use":"本题选A。第一空用“积蓄”描写种子在土壤中沉睡时储存着生命的力量，第二空用“安家”描写种子在国家作物种质库中得到安置。两空共同确定答案。","evidence":"“积蓄”指积聚、储存","qids":["江苏 2025 A类 行测#46"]},{"unit":"Q2","role":"直接考查","use":"本题选A。第一空用“积蓄”写种子沉睡时储存着生命的力量，第二空的“安家”呼应种质库作为“种子诺亚方舟”的安置作用。","evidence":"“积蓄”指积聚、储存","qids":["江苏 2025 C类 行测#46"]}]}]},"k-fdd4e83034cd31d3":{"review":{"definition":"“甲比乙多 n 倍”表示甲比乙多出的量是乙的 n 倍，因此甲是乙的 (1＋n) 倍。","explanation":"本题以已完成升级的企业数为基准，未完成升级的企业比它多 0.6 倍，所以未完成数是已完成数的 1.6 倍。两类合计 2080 家，相当于已完成数的 2.6 倍，因此已完成的有 2080÷2.6＝800 家，选 B。","references":[],"evidence":"未完成升级的规模以上企业比已完成升级的多0.6倍","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2661966960e6001a":{"review":{"definition":"气象谚语，指天气很热时容易起风，是对天气现象的民间经验概括。","explanation":"《白河县志》将这句话列入气象谚语。题中“热极”表示炎热达到很高程度，“生风”表示随之出现的变化，与“穷极”引出“思变”构成平行关系。谚语表达的是经验性倾向，遇到高温时是否起风还取决于具体气象条件。","references":[{"source":"web-dcbb182dc398869e","location":"第六节“物候”附录“气象谚语”","quote":"热极生风，闷极生雨。"}],"evidence":"因为“热极”所以“生风”，因为“穷极”所以“思变”","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-0f6752901e4dea9d":{"review":{"definition":"穷极思变指处境困顿到极点时，开始设法改变现状。","explanation":"“穷极”说的是处境困顿到了极点，“思变”说的是产生求变的念头。题干据此把“穷极”与“思变”读成前因后果，与“热极”引出“生风”的句内结构相对应。","references":[],"evidence":"因为“穷极”所以“思变”","disposition":"独立词条","basis":"据原题和解析编释。","title":"穷极思变","related":[],"examFocus":{"江苏 2025 A类 行测#73":"拆开题干的两个短语，分别辨认前后部分的含义及其关系，再比较各个词组的结构。"}},"readings":[{"origin":"k-0f6752901e4dea9d","title":"穷极思变","qs":["江苏 2025 A类 行测#73"],"definition":"穷极思变指处境困顿到极点时，开始设法改变现状。","explanation":"“穷极”说的是处境困顿到了极点，“思变”说的是产生求变的念头。题干据此把“穷极”与“思变”读成前因后果，与“热极”引出“生风”的句内结构相对应。","evidence":"因为“穷极”所以“思变”","doubt":"","references":[]},{"origin":"k-bfd67260298c5661","title":"穷极思变","qs":["江苏 2025 C类 行测#73"],"definition":"“穷极思变”指处境极度困顿时，开始设法改变现状。","explanation":"“穷极”交代处境，“思变”写由这种处境产生的求变意愿。它与“热极生风”都可拆成先写达到极端的状态、再写引发的变化。“思”字把后半句的含义限定在想到求变这一阶段。","evidence":"在穷困艰难的时候，就要想办法改变","doubt":"","references":[]}]},"k-438610925b5b677c":{"review":{"definition":"原题引文：因为“人闲”所以“生病”，因为“石闲”所以“生苔”","explanation":"所给答案选C，解析把“人闲→生病”和“石闲→生苔”都读作某种状态持续后出现变化，对应题干的“热极→生风”和“穷极→思变”。C项的“闲”本身没有明示程度达到极点，而且顺序是先人后物。若按题干先写自然现象、后写人的行为来比，A项“鼓空声高：人狂话大”也相符。","references":[{"source":"web-9ef6257528f8a50b","location":"图书目录，正念篇","quote":"人闲生病，石闲生苔。"}],"evidence":"因为“人闲”所以“生病”，因为“石闲”所以“生苔”","disposition":"题内说明","basis":"据原题和解析编释。","title":"人闲生病，石闲生苔","related":[],"examFocus":{"江苏 2025 A类 行测#73":"比较两组短语各自的因果结构，留意原因的程度和前后两句描述的对象。"}},"readings":[{"origin":"k-438610925b5b677c","title":"人闲生病，石闲生苔","qs":["江苏 2025 A类 行测#73"],"definition":"原题引文：因为“人闲”所以“生病”，因为“石闲”所以“生苔”","explanation":"所给答案选C，解析把“人闲→生病”和“石闲→生苔”都读作某种状态持续后出现变化，对应题干的“热极→生风”和“穷极→思变”。C项的“闲”本身没有明示程度达到极点，而且顺序是先人后物。若按题干先写自然现象、后写人的行为来比，A项“鼓空声高：人狂话大”也相符。","evidence":"因为“人闲”所以“生病”，因为“石闲”所以“生苔”","doubt":"未查到招录机关公开的正式答案或命题说明，仍需核对为何优先比较状态引发的变化，以及如何将C项的“闲”与题干的“极”对应。","references":[]},{"origin":"k-545e5b9efdeed0f0","title":"人闲生病，石闲生苔","qs":["江苏 2025 B类 行测#73"],"definition":"原题引文：人闲生病：石闲生苔","explanation":"C项两句均以“闲”作起因，以“生病”“生苔”作后果。给定解析据此类比题干中“热极”引出“生风”、“穷极”引出“思变”。这依赖对“闲”的语义引申，C项字面没有标明程度或时长，且C项先说人后说物，与题干顺序相反。","evidence":"人闲生病：石闲生苔","doubt":"已定位谚语收录。仍需核对是否有可靠的原文释义将“闲”明确限定为闲到极点或长期闲置，以及是否有命题方依据据此优先判C。","references":[{"source":"web-9ef6257528f8a50b","location":"图书目录，正念篇","quote":"人闲生病，石闲生苔。"}]}]},"k-68c134d518d845ad":{"review":{"definition":"鸿雁本指鸟，也可用作书信的代称。","explanation":"题干先取“鸿雁”的鸟类义，使它与“苍鹰”并列，再取它代指书信的含义，使第二词与第三词相连。A项有引申义的是第一词“加油”，B项有引申义的是第二词“上岸”，所以B项与题干的词序相符。","references":[],"evidence":"“鸿雁”是书信的代称","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b5537673d64267f4":{"review":{"definition":"上岸本指从水上登上陆地，在考试或招录语境中也可指考生成功被录取。","explanation":"B项先取“上岸”登上陆地的含义，使它与“下海”同属动作，再取其考试语境中的引申义，对应第三词“录取”。这与题干先以鸟类义并列“苍鹰”和“鸿雁”，再由“鸿雁”代指“书信”的词义转换位置一致。","references":[],"evidence":"“上岸”指舍舟登陆，也指考生被录取","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b655de2428f1f0d3":{"review":{"title":"压舱石","type":"概念与词义","definition":"压舱石本指放在船舱内、用来稳定船体的石块，比喻对维持全局稳定起重要支撑作用的因素。","explanation":"比喻义着重说明某个因素对整体的作用。称就业为社会稳定的压舱石，强调就业对维持社会稳定的支撑作用。","basis":"据关联原题和解析编释。","references":[],"related":[],"examFocus":{"江苏 2025 A类 行测#76":"先判断“压舱石”用来比喻就业对社会稳定起什么作用，再看各组三个词能否构成同样的关系。"}},"readings":[{"origin":"k-b655de2428f1f0d3","title":"压舱石","qs":["江苏 2025 A类 行测#76","江苏 2025 C类 行测#76"],"definition":"压舱石本指放在船舱内、用来稳定船体的石块，比喻对维持全局稳定起重要支撑作用的因素。","explanation":"比喻义着重说明某个因素对整体的作用。称就业为社会稳定的压舱石，强调就业对维持社会稳定的支撑作用。","evidence":"","doubt":"","references":[]},{"origin":"k-c3af39f9c28b3708","title":"压舱石","qs":["江苏 2025 B类 行测#75"],"definition":"压舱石原指用来帮助船舶保持稳定的重物，比喻对某事起稳定或支撑作用的关键因素。","explanation":"题干说就业是社会稳定的“压舱石”，强调就业对社会稳定的支撑作用。B项说耕地是粮食生产的“基本盘”，同样强调一项基础条件对后者的支撑。","evidence":"“压舱石”强调“就业”是维持“社会稳定”的重要基础和关键因素","doubt":"","references":[]}],"aspects":[{"title":"对整体的稳定作用","uses":[{"unit":"Q1","role":"解题依据","use":"题干以就业支撑社会稳定为例，B项中耕地对粮食生产也起基础支撑作用。D项的主阵地表示知识传播的主要场所。（江苏 2025 A类 行测第76题、江苏 2025 C类 行测第76题）","evidence":"“就业”是“社会稳定”的“压舱石”","qids":["江苏 2025 A类 行测#76","江苏 2025 C类 行测#76"]}]}]},"k-dac9603b7edd9ab8":{"review":{"title":"基本盘","type":"概念与词义","definition":"基本盘指一个领域或一项事业得以维持和发展的基础部分。","explanation":"这个词强调所指对象的基础地位。具体所指随语境而变，例如在粮食生产语境中，可用来形容耕地这一基础生产资源。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"江苏 2025 A类 行测#76":"把每组的比喻还原为后两个词的关系，再比较比喻所强调的作用是否一致。"}},"aspects":[{"title":"对生产活动的基础支撑","uses":[{"unit":"Q1","role":"解题依据","use":"B项用基本盘说明耕地是粮食生产的基础，与题干中就业对社会稳定的支撑关系相合。（江苏 2025 A类 行测第76题、江苏 2025 B类 行测第75题、江苏 2025 C类 行测第76题）","evidence":"“耕地”是“粮食生产”的“基本盘”","qids":["江苏 2025 A类 行测#76","江苏 2025 B类 行测#75","江苏 2025 C类 行测#76"]}]}]},"k-9bfa6542668ba4b2":{"review":{"definition":"主阵地本指军事上主要据守和作战的地域，引申为集中开展主要活动或发挥核心作用的场所、领域或平台。","explanation":"D项“学校是知识传播的主阵地”可以成立，强调学校是知识传播的主要场所。题干以就业为社会稳定的“压舱石”，强调稳定和支撑作用。B项以耕地为粮食生产的“基本盘”，同样强调基础和支撑，因此与题干更接近。","references":[],"evidence":"集中力量进行主要活动或发挥主要作用的地方、领域或平台等。","disposition":"独立词条","basis":"据原题和解析编释。","title":"主阵地","related":[],"examFocus":{"江苏 2025 A类 行测#76":"从比喻词入手，辨析第二项对第三项起的是基础支撑作用、场所作用还是其他作用。"}},"readings":[{"origin":"k-9bfa6542668ba4b2","title":"主阵地","qs":["江苏 2025 A类 行测#76"],"definition":"主阵地本指军事上主要据守和作战的地域，引申为集中开展主要活动或发挥核心作用的场所、领域或平台。","explanation":"D项“学校是知识传播的主阵地”可以成立，强调学校是知识传播的主要场所。题干以就业为社会稳定的“压舱石”，强调稳定和支撑作用。B项以耕地为粮食生产的“基本盘”，同样强调基础和支撑，因此与题干更接近。","evidence":"集中力量进行主要活动或发挥主要作用的地方、领域或平台等。","doubt":"","references":[]},{"origin":"k-ed571bc7fddc2dbc","title":"主阵地","qs":["江苏 2025 B类 行测#75"],"definition":"主阵地引申指集中开展某项活动或发挥主要作用的场所、领域或平台。","explanation":"D项称学校为知识传播的“主阵地”，强调知识传播主要在哪里开展。题干称就业为社会稳定的“压舱石”，强调社会稳定靠什么支撑。B项的“耕地是粮食生产的基本盘”与题干的支撑关系更接近。","evidence":"集中力量进行主要活动或发挥主要作用的地方、领域或平台等","doubt":"","references":[]},{"origin":"k-ee4cdf39842aba68","title":"主阵地","qs":["江苏 2025 C类 行测#76"],"definition":"“主阵地”本指主要据守或作战的阵地，引申为集中开展某项主要活动的场所、领域或平台。","explanation":"D项称学校是知识传播的“主阵地”，强调知识传播主要在哪里开展。题干称就业是社会稳定的“压舱石”，强调维持稳定所依靠的支撑条件。B项把耕地称为粮食生产的“基本盘”，同样强调基础和支撑，因此更贴近题干。","evidence":"集中力量进行主要活动或发挥主要作用的地方、领域或平台","doubt":"","references":[]}]},"k-7dcc61d95a50cadd":{"review":{"definition":"十二生肖是传统上用来标记出生年份的十二种动物，各与一个地支配对。传统配对为子鼠、丑牛、寅虎、卯兔、辰龙、巳蛇、午马、未羊、申猴、酉鸡、戌狗、亥猪。","explanation":"子配鼠、丑配牛等固定配对说明，生肖与地支之间有约定俗成的对应。D项后半组“红灯—禁行”也有明确的对应。C项前半组填的是天干，后半组“通行—禁行”则是反义关系。","references":[],"evidence":"子属鼠、丑属牛、寅属虎","disposition":"独立词条","basis":"据原题和解析编释。","title":"十二生肖与十二地支","related":[],"examFocus":{"江苏 2025 A类 行测#80":"把候选词分别与“生肖”和“禁行”组成词对，比较两组词的对应关系和方向是否一致。"}},"readings":[{"origin":"k-7dcc61d95a50cadd","title":"十二生肖与十二地支","qs":["江苏 2025 A类 行测#80"],"definition":"十二生肖是传统上用来标记出生年份的十二种动物，各与一个地支配对。传统配对为子鼠、丑牛、寅虎、卯兔、辰龙、巳蛇、午马、未羊、申猴、酉鸡、戌狗、亥猪。","explanation":"子配鼠、丑配牛等固定配对说明，生肖与地支之间有约定俗成的对应。D项后半组“红灯—禁行”也有明确的对应。C项前半组填的是天干，后半组“通行—禁行”则是反义关系。","evidence":"子属鼠、丑属牛、寅属虎","doubt":"","references":[]},{"origin":"k-b048ceef332491d8","title":"十二生肖与十二地支","qs":["江苏 2025 B类 行测#79"],"definition":"十二生肖是传统上与十二地支配对、用来标记出生年份的十二种动物。固定配对依次为子鼠、丑牛、寅虎、卯兔、辰龙、巳蛇、午马、未羊、申猴、酉鸡、戌狗、亥猪。","explanation":"D项“生肖—地支”体现固定配对，“红灯—禁行”体现交通信号与指令的固定对应，两组都可归为对应关系。A、B项的飞禽、走兽只涵盖部分生肖，分别与生肖形成交叉关系。","evidence":"子属鼠、丑属牛、寅属虎、卯属兔","doubt":"","references":[]}]},"k-68ef744b0f1f4ba4":{"review":{"definition":"增长率是某项数量相对基期同类数量的变动比例。比重是同一时期部分量占整体量的比例。","explanation":"第92题中，甲以折叠屏手机销量连续多年保持两位数增长为据，判断它将成为研发风口。乙用折叠屏手机仅占同期手机总销量1.6%来质疑投入价值。销量增长快与销量占比低可以同时成立。C项采用相似的论证方式，甲根据错别字检出量增加主张增员，乙指出出版总量也增加，而错别字检出率维持在万分之一左右，据此质疑增员的必要性。两段对话都是甲根据某项数量上升提出判断，乙用该数量在相应整体中的低比重来质疑结论。","references":[],"evidence":"折叠屏手机经历多年发展仍只占手机整体销量的1.6%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6893dd42defd2106":{"review":{"title":"进出口平均价格","type":"概念与词义","definition":"同一类商品的进出口金额除以对应进出口数量所得的单位价格。","explanation":"金额、数量须取相同方向和期间。商品结构变化也会改变平均价格，不能直接当成每种商品的价格变化。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"单位价格与平均量","related":["k-5db4b46712552e56"]}},"k-13b373474c418568":{"review":{"definition":"以正数 B 为比较基准，A 是 B 的几倍，用 A÷B 计算。A 比 B 高几倍，用 (A−B)÷B 计算，等于 A÷B−1。","explanation":"柴油机平均价格等于金额除以数量。2023 年进口与出口平均价格之比为 (13.4÷5.7)÷(13.2÷58.9)≈10.49，因此进口均价是出口均价的约 10.49 倍，比出口均价高约 9.49 倍。B 项说「高10倍多」，与计算结果不符，所以第 130 题选 B。","references":[],"evidence":"高几倍=多几倍=是几倍-1","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-04a494b607fd279e":{"review":{"definition":"石墨是碳的一种同素异形体，天然石墨属于非金属矿物。","explanation":"第15题A项前半句说石墨由碳元素组成，这与石墨的成分相符。后半句将石墨归为有色金属矿物，错在矿物分类。","references":[],"evidence":"石墨是一种非金属矿物","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dd6a05a0cddc9cf8":{"review":{"definition":"天然石墨由自然地质过程形成，人造石墨通过人工制备获得。两者按来源区分。","explanation":"天然石墨可见于变质岩等岩石中，人造石墨也可通过工业生产获得。第15题B项的错误落在“不存在人造石墨”。","references":[],"evidence":"石墨既存在于自然界中，也可以通过人工制备得到。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cdc4d0acde10f034":{"review":{"definition":"原题引文：县自然资源和规划局虽未制作回收决定书，但回收土地的决定已生效","explanation":"题中县自然资源和规划局未制作、送达收回决定书，直接交土地储备中心实施。最高人民法院指导案例22号在类似事实下，依据批复已实际执行、对权利人产生影响等事实，认定县政府批复外化并可诉。本题B项所说的“收回土地的决定已生效”还涉及对外生效的是哪个行为，解析仅凭公定力不足以得出该结论。","references":[{"source":"web-cbb6009c824299b2","location":"裁判理由","quote":"该批复已实际执行并外化为对外发生法律效力的具体行政行为"}],"evidence":"县自然资源和规划局虽未制作回收决定书，但回收土地的决定已生效","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-2d9abccc620a6250":{"review":{"definition":"上榜指进入公布的榜单或名单。荣膺指光荣地获得称号、荣誉，或担任重要职务。","explanation":"第一空承接工信部公布的“国家队”名单，后面的“其中江苏有4个入选”也表明，全国35个集群进入了这份名单，因此可用“上榜”。“荣膺”通常要说清获得了什么荣誉或称号，题句在这一空表达的是进入名单。","references":[],"evidence":"“荣膺”指光荣地接受或承当，一般搭配“称号”“荣誉”等","disposition":"独立词条","basis":"据原题和解析编释。","title":"上榜与荣膺","related":[],"examFocus":{"江苏 2025 A类 行测#36":"结合工信部公布名单和后文所说的“入选”，比较第一空的动词能否直接作谓语，是否还需要带宾语。"}},"readings":[{"origin":"k-2d9abccc620a6250","title":"上榜与荣膺","qs":["江苏 2025 B类 行测#36"],"definition":"上榜指进入公布的榜单或名单。荣膺指光荣地获得称号、荣誉，或担任重要职务。","explanation":"第一空承接工信部公布的“国家队”名单，后面的“其中江苏有4个入选”也表明，全国35个集群进入了这份名单，因此可用“上榜”。“荣膺”通常要说清获得了什么荣誉或称号，题句在这一空表达的是进入名单。","evidence":"“荣膺”指光荣地接受或承当，一般搭配“称号”“荣誉”等","doubt":"","references":[]},{"origin":"k-8939e0af99d8c23d","title":"上榜与荣膺","qs":["江苏 2025 A类 行测#36"],"definition":"上榜指名字列入公布的榜单。荣膺指光荣地获得荣誉、称号或担任某一职务。","explanation":"第36题第一空承接工信部公布的名单，下文用“其中江苏有4个入选”说明全国35个集群中有4个来自江苏。此处直接用“上榜”交代列名结果。“荣膺”通常需要交代获得的荣誉或称号，单填在这里没有说明集群获得了什么。","evidence":"其中江苏有4个入选","doubt":"","references":[]}]},"k-2ac722828ebe2ad9":{"review":{"definition":"分庭抗礼指双方地位或实力相当，能够相互抗衡。相提并论指把不同的人或事物放在一起谈论或看待。","explanation":"题干以中生代哺乳动物的“身形娇小”对照“巨无霸”恐龙，又以新生代哺乳动物成为王者形成转折。“无法与恐龙分庭抗礼”写出前一阶段双方在实力和地位上的差距。“无法相提并论”表达的是不宜放在一起谈论或看待，语义焦点不同。","references":[],"evidence":"哺乳动物一直是身形娇小的类群，根本无法与“巨无霸”恐龙","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-39470b4fd8cb0089":{"review":{"definition":"涌现指人或事物在同一时期大量出现。","explanation":"第二空填成“涌现出许多高大威猛的动物”，“涌现”所含的大量出现之意与“许多”呼应。“虽然……却……”进一步写出，即使出现了许多高大威猛的动物，题文仍把哺乳动物称为新生代生物界的王者。","references":[],"evidence":"“涌现”指在同一时期大量地出现","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3ea77d898b749392":{"review":{"definition":"匹配指两个或多个事物在某些方面相适应。供需匹配指供给与需求在数量、类型等方面相适应。","explanation":"首空的“不匹配”概括了人力资源供给与需求不相适应的问题。后文提出挖掘、培育新职业，说明材料把开拓就业机会视为缓解供需错配的一种途径。“不平衡”也能描述供需问题，本题还需用第二空的“多措并举”确定D项。","references":[],"evidence":"发展新职业有利于解决这一问题","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4409465c7cfff35c":{"review":{"definition":"多措并举指同时采取多项措施。齐头并进指多项事务或同一事务的多个方面同步推进。","explanation":"第二空和“创造条件”并列，交代各级政府为引导新职业健康发展应做什么。“多措并举”直接写出政府采取多种办法，“齐头并进”强调多个事项的推进节奏，而句中并未列出哪些事项需要同步推进。","references":[],"evidence":"创造条件，引导新职业健康发展","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-24d4892c0b6905b4":{"review":{"definition":"日臻完善指事物随着时间推移逐步趋于完善，强调持续改进的过程。","explanation":"国际地层委员会每年优化更新地层表，因此“随着国际年代地层表的日臻完善”写的是这张表逐步改进。“精益求精”和“精雕细琢”分别着重追求更好和细致加工，“大功告成”着重任务完成，它们的语义焦点都与此处的逐年改进不同。","references":[],"evidence":"国际地层委员会每年都会对其进行优化更新","disposition":"独立词条","basis":"据原题和解析编释。","title":"日臻完善","related":[],"examFocus":{"江苏 2025 B类 行测#39":"结合地层表的编制背景和后续更新，辨析两空成语各自适用的阶段和对象。"}},"readings":[{"origin":"k-24d4892c0b6905b4","title":"日臻完善","qs":["江苏 2025 B类 行测#39"],"definition":"日臻完善指事物随着时间推移逐步趋于完善，强调持续改进的过程。","explanation":"国际地层委员会每年优化更新地层表，因此“随着国际年代地层表的日臻完善”写的是这张表逐步改进。“精益求精”和“精雕细琢”分别着重追求更好和细致加工，“大功告成”着重任务完成，它们的语义焦点都与此处的逐年改进不同。","evidence":"国际地层委员会每年都会对其进行优化更新","doubt":"","references":[]},{"origin":"k-a48e38b139ce43b4","title":"日臻完善","qs":["江苏 2025 C类 行测#39"],"definition":"日臻完善指随着时间推移逐步趋于完善，强调持续改进的过程。","explanation":"国际地层委员会每年优化更新国际年代地层表，地层表本身随之逐步完善，因此C项可接在“随着国际年代地层表的”之后。“大功告成”侧重任务完成，“精益求精”侧重对更高质量的追求，题中要描述的是地层表持续改进的状态。","evidence":"国际地层委员会每年都会对其进行优化更新","doubt":"","references":[]}]},"k-49afa67bdb82cedd":{"review":{"definition":"纵横交错指不同方向的线状事物相互交叉，常用来描述道路、河道等的分布。","explanation":"“平坦宽敞”已经写出马路的路面和宽度，第一空用“纵横交错”补充道路彼此交叉的布局。“整齐划一”侧重排列或规格一致，“秩序井然”侧重有序，两者都没有写出道路在不同方向上相互交叉的形态。","references":[],"evidence":"横的、竖的交叉在一起","disposition":"独立词条","basis":"据原题和解析编释。","title":"纵横交错","related":[],"examFocus":{"江苏 2025 B类 行测#40":"第一空留意“平坦宽敞”已经交代了马路的哪些特征，第二空辨析形容建筑数量和排列形态的成语。"}},"readings":[{"origin":"k-49afa67bdb82cedd","title":"纵横交错","qs":["江苏 2025 B类 行测#40"],"definition":"纵横交错指不同方向的线状事物相互交叉，常用来描述道路、河道等的分布。","explanation":"“平坦宽敞”已经写出马路的路面和宽度，第一空用“纵横交错”补充道路彼此交叉的布局。“整齐划一”侧重排列或规格一致，“秩序井然”侧重有序，两者都没有写出道路在不同方向上相互交叉的形态。","evidence":"横的、竖的交叉在一起","doubt":"","references":[]},{"origin":"k-e94a158d7ca2e0fb","title":"纵横交错","qs":["江苏 2025 C类 行测#40"],"definition":"纵横交错形容纵向、横向的事物相互交叉，可用于描述道路等的空间布局。","explanation":"“平坦宽敞”已经写了路面的特点，第一空用C项“纵横交错”补充道路在不同方向上相互交叉的布局。B项“整齐划一”强调一致，D项“秩序井然”强调有条理，两者都未写出道路交叉的形态。","evidence":"横的、竖的交叉在一起","doubt":"","references":[]}]},"k-be33ddfe5c99a655":{"review":{"definition":"鳞次栉比形容房屋等像鱼鳞和梳齿一样密集而有序地排列。","explanation":"第二空描写现代化建筑的整体布局，“鳞次栉比”同时写出成片建筑的密度和排列。“比比皆是”着重写随处可见，“巍然挺立”着重写建筑高耸，“错落有致”则着重写布局有变化而有条理。","references":[],"evidence":"“鳞次栉比”形容房屋等密集整齐地排列","disposition":"独立词条","basis":"据原题和解析编释。","title":"鳞次栉比","related":[],"examFocus":{"江苏 2025 B类 行测#40":"首空看成语能否描写道路走向，次空留意成语侧重的是建筑的分布、排列还是形态。"}},"readings":[{"origin":"k-be33ddfe5c99a655","title":"鳞次栉比","qs":["江苏 2025 B类 行测#40"],"definition":"鳞次栉比形容房屋等像鱼鳞和梳齿一样密集而有序地排列。","explanation":"第二空描写现代化建筑的整体布局，“鳞次栉比”同时写出成片建筑的密度和排列。“比比皆是”着重写随处可见，“巍然挺立”着重写建筑高耸，“错落有致”则着重写布局有变化而有条理。","evidence":"“鳞次栉比”形容房屋等密集整齐地排列","doubt":"","references":[]},{"origin":"k-ff26941eebce1988","title":"鳞次栉比","qs":["江苏 2025 C类 行测#40"],"definition":"鳞次栉比原指像鱼鳞和梳齿一样排列，常用来形容房屋等密集而整齐。","explanation":"第二空写现代化建筑，“鳞次栉比”描绘成片建筑密集而整齐的排列，与第一空交叉分布的道路共同构成城市景象。“比比皆是”侧重到处可见，“错落有致”侧重布局富有层次。C项同时贴合道路和建筑的描写。","evidence":"“鳞次栉比”形容房屋等密集整齐地排列","doubt":"","references":[]}]},"k-5386fc58ffc7cd9f":{"review":{"definition":"生产生活方式指人们组织和开展生产、安排和进行日常生活所采取的方法和形式。","explanation":"题干用新能源汽车产业结合人工智能技术拓展交通出行的可能性，举例说明技术变革会改变人们实际怎样出行。首空因此可以填侧重做法的“方式”。“态度”和“观念”在这里侧重人们怎么看、怎么想。“形态”侧重呈现的形式和状态，首空也说得通，C、D两项需要比较第二空。","references":[],"evidence":"科技革命和产业变革正改变着人们的生产生活模式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dfd3b0f732c40674":{"review":{"definition":"叠加指在已有事物或作用之上再加上一层，也可以指多个因素的作用相互叠合。","explanation":"题干分别写到人工智能浪潮来袭和新能源汽车产业发展提速，第二空用“叠加”突出两者结合对交通出行产生的作用。“采用”表示选择并使用某项技术，着眼于产业怎样使用人工智能。两者都在发展这一背景来自题干。","references":[],"evidence":"共同助力交通出行","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cb308106b53c53d4":{"review":{"definition":"大名鼎鼎形容人或事物名气很大、广为人知。","explanation":"文中说读者通过报刊书本、影视荧屏已对“一堆一器”有所了解，首空可用“大名鼎鼎”写其知名度。“举世无双”强调在全世界独一无二，题干中的“我国建设的第一项”只说明它在我国相关建设史上的先后地位。首空也容得下“闻名遐迩”和“声名显赫”，还需用后两空筛选。","references":[],"evidence":"通过报刊书本、影视荧屏，我们对“一堆一器”并不完全陌生","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-71cb95fab96be222":{"review":{"definition":"油然而生形容某种思想或感情自然而然地产生。","explanation":"第三空的主语是“惊喜与感动”。人们此前从报刊书本、影视荧屏了解过“一堆一器”，亲眼看到实物时仍自然生出这两种感情，用“油然而生”正好写出见到实物后的内心反应。","references":[],"evidence":"惊喜与感动依旧","disposition":"独立词条","basis":"据原题和解析编释。","title":"油然而生","related":[],"examFocus":{"江苏 2025 A类 行测#41":"辨析第三空时，注意“惊喜与感动”能与哪些成语搭配，以及前文从间接了解转到亲眼所见的语境。"}},"readings":[{"origin":"k-71cb95fab96be222","title":"油然而生","qs":["江苏 2025 B类 行测#45"],"definition":"油然而生形容某种思想或感情自然而然地产生。","explanation":"第三空的主语是“惊喜与感动”。人们此前从报刊书本、影视荧屏了解过“一堆一器”，亲眼看到实物时仍自然生出这两种感情，用“油然而生”正好写出见到实物后的内心反应。","evidence":"惊喜与感动依旧","doubt":"","references":[]},{"origin":"k-7e7d25791ddaa821","title":"油然而生","qs":["江苏 2025 A类 行测#41"],"definition":"油然而生形容某种思想或情感自然而然地产生，常用来写敬意、感动等感受的生起。","explanation":"第41题先写读者已从报刊书本和影视中有所了解，再写亲眼见到实物时，惊喜和感动依然自然涌现。“油然而生”直接描写这两种感受如何产生，与前两空都能保留的A项相比，更贴合第三空所写的情绪。","evidence":"当它们“活生生”地出现在眼前时，惊喜与感动依旧","doubt":"","references":[]},{"origin":"k-9cdcf8f2e8d8c5ae","title":"油然而生","qs":["江苏 2025 C类 行测#45"],"definition":"“油然而生”形容某种思想或感情自然而然地产生。","explanation":"题中人们虽已从报刊和影视中了解“一堆一器”，亲眼见到实物时仍自然生出惊喜和感动。“惊喜与感动”作主语，第三空用“油然而生”写出现场所见触发的感受。","evidence":"惊喜与感动依旧","doubt":"","references":[]}]},"k-108ba1805b6a73bb":{"review":{"definition":"舍弃事物根本、主要的部分，转而追求细枝末节，形容轻重倒置。","explanation":"拆成“舍本”和“逐末”后，两个动宾短语并列。“舍”和“逐”在成语中分别表示放弃和追求，“本”和“末”分别指根本和末节。C项“避重就轻”的动词与宾语也分别形成对照。","references":[],"evidence":"“舍本逐末”指舍弃事物的根本的、主要的部分，而去追求细枝末节","disposition":"独立词条","basis":"据原题和解析编释。","title":"舍本逐末","related":[],"examFocus":{"江苏 2025 A类 行测#72":"把四字成语拆成两个动宾短语，比较两部分的关系，再分别看动词和宾语之间的语义关系。"}},"readings":[{"origin":"k-108ba1805b6a73bb","title":"舍本逐末","qs":["江苏 2025 B类 行测#72"],"definition":"舍弃事物根本、主要的部分，转而追求细枝末节，形容轻重倒置。","explanation":"拆成“舍本”和“逐末”后，两个动宾短语并列。“舍”和“逐”在成语中分别表示放弃和追求，“本”和“末”分别指根本和末节。C项“避重就轻”的动词与宾语也分别形成对照。","evidence":"“舍本逐末”指舍弃事物的根本的、主要的部分，而去追求细枝末节","doubt":"","references":[]},{"origin":"k-76e5202e18d3dc79","title":"舍本逐末","qs":["江苏 2025 A类 行测#72"],"definition":"舍本逐末指舍弃事物的根本或主要部分，转而追求细枝末节，形容轻重倒置。","explanation":"本题把成语拆成并列的“舍本”和“逐末”。“舍”与“逐”分别表示舍弃和追求，“本”与“末”分别指根本和末节，两组字义都形成对照。C项“避重：就轻”也有两组对照，B项“取长：补短”中“取长”则是为了“补短”。","evidence":"舍弃事物的根本的、主要的部分，而去追求细枝末节","doubt":"","references":[]}]},"k-5093c098d6a15018":{"review":{"definition":"避开重要或繁重的事项，挑次要或轻松的来承担。也指回避主要问题，只谈次要方面。","explanation":"“就”在成语里有趋近、选择的意思，与“避”形成动作上的对照，“重”和“轻”也相对。C项的两组对照与“舍本逐末”相似。B项“取长补短”虽有“长”和“短”的对照，“取长”却是为了“补短”。","references":[],"evidence":"“避重就轻”指避开重要的而拣次要的来承担","disposition":"独立词条","basis":"据原题和解析编释。","title":"避重就轻","related":[],"examFocus":{"江苏 2025 A类 行测#72":"把成语拆成两组动宾结构，分别比较对应的动词和宾语是否相对，再看两组动作之间的关系。"}},"readings":[{"origin":"k-5093c098d6a15018","title":"避重就轻","qs":["江苏 2025 B类 行测#72"],"definition":"避开重要或繁重的事项，挑次要或轻松的来承担。也指回避主要问题，只谈次要方面。","explanation":"“就”在成语里有趋近、选择的意思，与“避”形成动作上的对照，“重”和“轻”也相对。C项的两组对照与“舍本逐末”相似。B项“取长补短”虽有“长”和“短”的对照，“取长”却是为了“补短”。","evidence":"“避重就轻”指避开重要的而拣次要的来承担","doubt":"","references":[]},{"origin":"k-6069ed30bca5e789","title":"避重就轻","qs":["江苏 2025 A类 行测#72"],"definition":"避重就轻指避开重要或负担重的事项，选择次要或负担轻的事项，也指回避主要问题，只谈无关紧要的方面。","explanation":"“就”在成语中表示趋近，和“避”的方向相反。“重”和“轻”也相对，所以C项“避重：就轻”与题干“舍本：逐末”一样，由并列的两个短语构成，且对应的动词和宾语各成一组语义对照。","evidence":"其中“就”指凑近、靠近","doubt":"","references":[]}]},"k-fb80fbbb5c4212b0":{"review":{"definition":"原题引文：因为“热极”所以“生风”，因为“穷极”所以“思变”","explanation":"题干两句都可拆为先有某种状态，再引出后续变化，其中“思变”说的是产生求变的念头。给定解析按这层语义选择C，把“人闲”“石闲”都理解为足以出现后果的状态。若比较两句所说对象的先后顺序，题干先说自然现象，后说人，A也符合这一顺序。","references":[{"source":"web-c4d4f85aeff71121","location":"第27页，朱心和《气象谚语解释》","quote":"当天气太热时，很容易产生风"}],"evidence":"因为“热极”所以“生风”，因为“穷极”所以“思变”","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-783a9555533bfd3b":{"review":{"definition":"石刻在本题中指在石质材料上雕刻而成的作品。","explanation":"题干按“成品、原料、同列材料”的顺序排列。石头是石刻的原料，木头与石头同属可供雕刻的材料。B项以根雕为成品、树根为原料，草根与树根同属植物的根，位置关系与题干一致。","references":[],"evidence":"“石刻”是在“石头”上进行雕刻","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-793ea802a1bd7475":{"review":{"definition":"根雕是以树根为材料，通过雕刻等加工形成的艺术作品。","explanation":"B项中树根是根雕的原料，草根与树根是并列的两类植物根。这与题干中石头是石刻的原料、木头和石头是并列材料的结构一致。C项的茶具在茶道中是用具，前两词属于活动与用具的关系。","references":[],"evidence":"“根雕”是在“树根”上进行雕刻","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5d25a86e39a0923c":{"review":{"title":"鸿雁（书信义）","type":"概念与词义","definition":"鸿雁本指一种雁，在诗文中可借指书信。","explanation":"书信义源于鸿雁传书的典故。诗文写到寄信、盼音信时，鸿雁可指往来的书信。描写雁群飞过或栖息时，则可用其本义。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典鴻雁","location":"“鴻雁”词目"}],"examFocus":{"江苏 2025 B类 行测#78":"核对前两词能否按本义并列，再看第三词与前两词中的哪一个存在借代或引申关系。"}},"aspects":[{"title":"鸟类本义与书信借代义","uses":[{"unit":"Q1","role":"解题依据","use":"题干中，“鸿雁”用本义与“苍鹰”构成鸟类并列，用借代义与“书信”对应。B项的“下海”与“上岸”也是并列关系，第二个词“上岸”又可引申为考生被录取，与题干的关系顺序一致。","evidence":"“苍鹰”和“鸿雁”都是鸟类，二者为并列关系；“鸿雁”是书信的代称","qids":["江苏 2025 B类 行测#78","江苏 2025 C类 行测#74"]}]}]},"k-40b2887f3ea87b24":{"review":{"definition":"“上岸”本指从水上登岸，在考试或招录语境中常引申为考生成功被录取。","explanation":"B项以本义将“下海”和“上岸”归为并列动作，再由第二个词“上岸”引出“录取”，对应题干中“苍鹰”和“鸿雁”同为鸟类、第二个词“鸿雁”代指“书信”的结构。A项中能表示“鼓劲”的是第一个词“加油”，位置不同。","references":[],"evidence":"“上岸”指舍舟登陆，也指考生被录取","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a8318619b8b2f54a":{"review":{"definition":"月饼是中秋节常食用的一种传统中式糕点。","explanation":"B项的“月饼—中式糕点”是具体品类归入上位类别，与“旅游—休闲活动”同为种属关系。A项的“传统节日”指向月饼的食用场景，D项的“家庭团圆”指向月饼的象征意义。","references":[],"evidence":"“月饼”是一种“中式糕点”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2a9a08a39ffbc0b1":{"review":{"definition":"本题中的旅游指以游览、度假等为目的的出游，属于休闲活动。","explanation":"按休闲出游理解，“旅游—休闲活动”与“月饼—中式糕点”都是从具体类别到上位类别，支持B项。“异国风情”是出游中可能体验到的内容，“探索自然”则是某些出游的目的。","references":[],"evidence":"“旅游”是一种“休闲活动”","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-6055e37ddac76471":{"review":{"definition":"中位数是一组数据按大小排序后位于中间的数。数据个数为奇数时，取正中间的一个数；数据个数为偶数时，取中间两个数的算术平均数。","explanation":"第126题给出了2015—2023年共9个年末资产负债率。按数值从小到大排列后，第5位是64.6%，其前后各有4个数据，因此选C。","references":[],"evidence":"共9个数据，则所求中位数为64.6%（第五位）","disposition":"独立词条","basis":"据原题和解析编释。","title":"中位数","related":[],"examFocus":{"江苏 2025 B类 行测#126":"将2015—2023年的年末资产负债率按数值排序，再用奇数个数据的中位数取法确定中间值。","江苏 2025 C类 行测#121":"按题目指定的年份和年末口径选取资产负债率，再按数值排序找中位数。"}},"readings":[{"origin":"k-6055e37ddac76471","title":"中位数","qs":["江苏 2025 B类 行测#126"],"definition":"中位数是一组数据按大小排序后位于中间的数。数据个数为奇数时，取正中间的一个数；数据个数为偶数时，取中间两个数的算术平均数。","explanation":"第126题给出了2015—2023年共9个年末资产负债率。按数值从小到大排列后，第5位是64.6%，其前后各有4个数据，因此选C。","evidence":"共9个数据，则所求中位数为64.6%（第五位）","doubt":"","references":[]},{"origin":"k-9ea10463f0922c1d","title":"中位数","qs":["江苏 2025 C类 行测#121"],"definition":"将一组数值按大小排序，数据个数为奇数时，中位数是正中间的数值。数据个数为偶数时，中位数是中间两个数值的算术平均数。","explanation":"本题取2015至2023年表中列出的9个年末资产负债率，按数值排序后取第5位。64.6%的前后各有4个数，因此中位数是64.6%，选C。材料另列的2024年8月末数据超出题目指定的年份和时点范围。","evidence":"共9个数据，则所求中位数为64.6%（第五位）","doubt":"","references":[]}]},"k-14599d5c611e3b87":{"review":{"title":"营业收入利润率","type":"概念与词义","definition":"营业收入利润率是利润总额占同期营业收入的百分比，等于利润总额除以营业收入再乘以100%。","explanation":"这一指标表示每100元营业收入对应多少元利润总额。计算时，利润总额和营业收入应采用相同的统计范围、时期和金额单位。","basis":"据关联原题及所列出处编释。","references":[{"source":"profit","location":"附注·主要财务指标"}],"related":["k-45392942e1591512","k-9ca0533b7efae951","k-90c98a86d3b2a861"],"examFocus":{"江苏 2025 B类 行测#128":"用同一年份的利润总额和营业收入求比率，再在年份之间作比较。","江苏 2025 C类 行测#123":"用同一年份的利润总额和营业收入求比率，再在年份之间作比较。"}},"aspects":[{"title":"比较各年营业收入利润率","uses":[{"unit":"Q1","role":"直接考查","use":"用表中各年的利润总额除以同年营业收入，比较2016至2023年我国国有企业的营业收入利润率。2021年为4.5÷75.6×100%≈5.95%，在所问年份中最高，选D。","evidence":"2016-2023年，我国国有企业营业收入利润率最高的年份是：","qids":["江苏 2025 B类 行测#128"]},{"unit":"Q2","role":"直接考查","use":"与Q1共用题干和年度数据，最高年份同为2021年，选D。","evidence":"2016-2023年，我国国有企业营业收入利润率最高的年份是：","qids":["江苏 2025 C类 行测#123"]}]}]},"k-c739cbdf7b1db8d1":{"review":{"definition":"农村职业经理人是承担乡村项目策划、资源开发和经营管理等工作的专业人员。材料1中的村民称他们为“乡村CEO”。","explanation":"永安村的经理人把传统梨膏糖开发成新款伴手礼，青山村的经理人引入专业团队规划旅游设施。两例说明专业运营如何把土特产、文旅资源转化为商品和旅游项目。本题据此概括乡村运营领域的新职业及其作用，包括培育新业态、引进项目和投资、带动村级集体经济增收。","references":[],"evidence":"为乡村建设发展进行专业化运营","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-262e4c84d872c539":{"review":{"definition":"观鸟旅游“鸟导”是为游客提供观鸟引导的从业者，依托当地鸟类资源开展生态旅游服务。","explanation":"参考答案将“鸟导”归入乡村旅游领域。观鸟引导把当地丰富的鸟类资源转化为吸引游客的旅游服务，游客到访为村民增加了取得旅游收入的机会。本题概括时要交代从鸟类资源到生态旅游、再到村民增收渠道拓宽的关系。","references":[],"evidence":"依托当地丰富鸟类资源，发展生态旅游，吸引游客，拓宽村民收入渠道","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ef85d813e69bf8bb":{"review":{"definition":"植保无人机飞手是运用无人机承担农业植物保护作业的专业人员。","explanation":"参考答案将这一职业归入农业生产领域。飞手凭借专业技能把无人机等智慧农业工具用到植保作业中，提高作业效率并获得村民认可。本题以这种技术应用及其成效说明新职业对农业现代化的推动作用。","references":[],"evidence":"凭借专业技能，运用智慧农业工具，提升作业效率","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4b97d2768a1c9e2e":{"review":{"definition":"民宿管家是负责民宿接待、住客服务和日常服务协调的从业者。","explanation":"参考答案将民宿管家归入民宿服务领域。管家把专业素养落实到住客服务中，以服务品质改善住宿体验，增强民宿对游客的吸引力。本题据此概括这一职业对乡村民宿行业发展的作用。","references":[],"evidence":"通过提升专业素养和服务品质，增强民宿核心吸引力，促进行业发展","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b14414c323eff44c":{"review":{"definition":"做事须有合适的方法，才有可能取得成功。这里的“法”指做事的方法。","explanation":"题干把全面深化改革称为复杂的系统工程，强调必须以科学的方法论为指导，这与A项把方法视为成事条件的意思相合。B项强调安定时也要想到风险，C项强调事先防备意外，D项强调获取和使用资源要有节制。","references":[],"evidence":"任何事情都有方法，只有找到合适的方法，才能成功。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d904edeef43f03d5":{"review":{"definition":"原题引文：第二张邮票左侧有“立德树人”的文字","explanation":"中国邮政2022年发行的《立德树人》是个性化服务专用邮票，主图用打开的书本组成树形，体现教育主题。按题解和公开回忆版的图像说明，另一枚的“9月10日 教师节”题字可直接确定节日，2014年《教师节》纪念邮票的“师恩难忘”也与之呼应，对应B。","references":[{"source":"web-8c62cb38dc1eefc6","location":"背景资料，发行类别及设计主题","quote":"坚持把立德树人作为教育的根本任务"},{"source":"web-797bd708f4039021","location":"第二枚邮票图名","quote":"师恩难忘"},{"source":"web-c724397a3a8ab268","location":"第15题，图像说明","quote":"9月10日 教师节 中国人民邮政"}],"evidence":"第二张邮票左侧有“立德树人”的文字","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-79626b59f9e67afa":{"review":{"definition":"担当是遇到困难或危机时主动承担责任。奉献是为保障群众利益主动付出。","explanation":"特大暴雨导致社区断水断电断网，附近铁路被冲毁，近千名乘客滞留。孟书记带领党员和居民安置、转运乘客并解决吃住问题，在危急时刻主动担责，为后续救援争取了时间。这些行动最直接对应D项的担当与奉献。","references":[],"evidence":"敢于担当、无私奉献，面对困难奋勇而上，面对危机挺身而出","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-066c0c5ea96598f5":{"review":{"definition":"“名副其实”指名称或名声与实际相符。“当之无愧”指完全当得起某一称号、荣誉或评价，常含赞许意味。","explanation":"公开题目转载显示，第一空在“经济活力”与“的‘风向标’”之间。前句用快递业务量突破1000亿件交代实况，后句说快递物流反映行业发展和经济活力，因此第一空侧重说明“风向标”的称呼与实际作用相符，B项“名副其实”更贴切。第二空用“映照出”表达业务表现反映行业的蓬勃发展。","references":[{"source":"web-fdfbc6e3705058b8","location":"公开题面，第一处横线","quote":"快递物流是经济活力_________的“风向标”"},{"source":"词典名副其實","location":"“名副其實”词目"},{"source":"词典當之無愧","location":"“當之無愧”词目"}],"evidence":"“名副其实”指名称或名声与实际相符合","disposition":"独立词条","basis":"据原题与所列资料编释。","title":"名副其实与当之无愧","related":[],"examFocus":{"江苏 2025 A类 行测#37":"结合快递业务量和“风向标”的比喻，辨析成语的语义侧重，并比较各动词与“出行业的蓬勃跃升”的搭配。"}},"readings":[{"origin":"k-066c0c5ea96598f5","title":"名副其实与当之无愧","qs":["江苏 2025 C类 行测#38"],"definition":"“名副其实”指名称或名声与实际相符。“当之无愧”指完全当得起某一称号、荣誉或评价，常含赞许意味。","explanation":"公开题目转载显示，第一空在“经济活力”与“的‘风向标’”之间。前句用快递业务量突破1000亿件交代实况，后句说快递物流反映行业发展和经济活力，因此第一空侧重说明“风向标”的称呼与实际作用相符，B项“名副其实”更贴切。第二空用“映照出”表达业务表现反映行业的蓬勃发展。","evidence":"“名副其实”指名称或名声与实际相符合","doubt":"","references":[{"source":"web-fdfbc6e3705058b8","location":"公开题面，第一处横线","quote":"快递物流是经济活力_________的“风向标”"}]},{"origin":"k-350b15d568649889","title":"名副其实与当之无愧","qs":["江苏 2025 A类 行测#37","江苏 2025 B类 行测#41"],"definition":"名副其实指名称或名声与实际相符。当之无愧指完全配得上某种称号、荣誉或评价。","explanation":"名副其实着眼于人或事物是否确有其名所指的特征。当之无愧着眼于实际表现或贡献是否足以获得相应的肯定。","evidence":"","doubt":"江苏 2025 A类 行测 · 第 37 题（江苏 2025 A类 行测#37、江苏 2025 B类 行测#41）尚缺正式试卷或原卷页图，需确认两卷第一空是否均在“经济活力”之后、“的”之前。","references":[{"source":"词典名副其實","location":"“名副其實”词目"},{"source":"词典當之無愧","location":"“當之無愧”词目"}]}],"aspects":[{"title":"称谓与事实相符","uses":[{"unit":"Q1","role":"直接考查","use":"所给两卷答案均为B。快递业务量突破千亿件，为经济活力“风向标”这一称谓提供了事实依据，第一空选“名副其实”。所给题干仅显示第二空，两份公开的考生回忆版均将第一空置于“经济活力”之后、“的”之前。正式卷面的空位仍待核实。","evidence":"名副其实 映照","qids":["江苏 2025 A类 行测#37","江苏 2025 B类 行测#41"]}]}]},"k-c5e597d946e05172":{"review":{"definition":"映照本指照射、映现，也可用来形象地表达某种现象呈现出背后的状态或变化。","explanation":"题中以快递业务量突破千亿件呈现行业的发展态势，“映照出行业的蓬勃跃升”延续了“风向标”的形象表达，并与后文“更彰显了我国经济的繁荣活力”形成从行业到整体经济的递进。C项“折射出”也能表达间接反映，第二空可验证B项搭配成立，整组仍须结合第一空比较。","references":[],"evidence":"能形象地表达出快递物流映射出行业的蓬勃跃升","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f3620e2098d68898":{"review":{"definition":"“相继”指一个接着一个，强调人或事物出现、发生的先后顺序。","explanation":"第一空用“相继形成”串联宋、元、明、清各时期成文法典的形成，呼应末尾的“延续性”。“陆续”和“渐次”也能表达时间上的先后，“稳步”则侧重进展平稳、有步骤。本空可排除D项，B项还须结合后两空确定。","references":[],"evidence":"形成了影响深远的成文法典","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6cc589f550ba7df2":{"review":{"definition":"“淬炼”可比喻在反复的考验和磨炼中逐渐成形、成熟。","explanation":"题中中华法系从秦朝形成，到隋唐日趋成熟，再到宋元明清各时期形成法典。“淬炼而成”把这段发展过程与后文的“自我发展、回应挑战”连起来。“积淀”也能写出长期累积，“聚集”只突出汇合，难以表现法系逐步完善。","references":[],"evidence":"自我发展、回应挑战的主体性与生命力","disposition":"独立词条","basis":"据原题和解析编释。","title":"淬炼","related":[],"examFocus":{"江苏 2025 A类 行测#40":"结合各朝代形成法典的叙述，辨析“在历史发展中……而成”一空中的动词各自突出怎样的形成过程。"}},"readings":[{"origin":"k-6cc589f550ba7df2","title":"淬炼","qs":["江苏 2025 C类 行测#41"],"definition":"“淬炼”可比喻在反复的考验和磨炼中逐渐成形、成熟。","explanation":"题中中华法系从秦朝形成，到隋唐日趋成熟，再到宋元明清各时期形成法典。“淬炼而成”把这段发展过程与后文的“自我发展、回应挑战”连起来。“积淀”也能写出长期累积，“聚集”只突出汇合，难以表现法系逐步完善。","evidence":"自我发展、回应挑战的主体性与生命力","doubt":"","references":[]},{"origin":"k-d6974b623de2831e","title":"淬炼","qs":["江苏 2025 A类 行测#40"],"definition":"淬炼在比喻用法中指经受磨炼或考验，并在这一过程中逐步成形或完善。","explanation":"第40题先写中华法系从秦朝形成到隋唐日趋成熟，再写宋元明清各有影响深远的成文法典。“淬炼”承接这段发展过程，也呼应后文的“回应挑战”。“积淀”也能体现长期积累，第二空可以保留A项，最终由第三空的“一脉相承”贴合各阶段相续发展的语意，选出B项。","evidence":"自我发展、回应挑战的主体性与生命力","doubt":"","references":[]}]},"k-435175adf1ccb30d":{"review":{"definition":"“还原”可以指依据现有线索重现事物原来的面貌。“组合”侧重把若干部分组织成整体，“拼合”侧重把分开的部分拼接起来。","explanation":"题中考古发现的物证是重建历史图景的依据，目标是让早已湮灭的文明重新可见。“还原历史的图景”点明了这个目标，“组合”和“拼合”主要写处理各个部分的动作。第二空据此选“还原”。","references":[],"evidence":"用发现的物证来","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-af70400ac1a0cac8":{"review":{"definition":"“功不可没”指所作的贡献不能抹杀。“劳苦功高”同时赞扬付出的辛劳和取得的功绩。","explanation":"题干从基础研究、研制工作和和平利用三个方面列举“一堆一器”的贡献，用“功不可没”可概括这项设施的作用。“劳苦功高”含有对辛勤付出的评价，题干没有这一层意思。","references":[],"evidence":"再到和平利用原子能","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-54de2cb84a462f53":{"review":{"definition":"“安家”本指安置家庭、在一处定居，也可比喻在某处得到较长久的安置。","explanation":"材料把国家作物种质库比作“种子诺亚方舟”，并说明其使命是长久、安全地保存种质资源。给“安家”加引号，把种子写成在库里落户，突出长期安置。“休憩”侧重短时休息，“冬眠”侧重休眠状态。","references":[],"evidence":"长久、安全地保存好这些种质资源","disposition":"独立词条","basis":"据原题和解析编释。","title":"安家","related":[],"examFocus":{"江苏 2025 A类 行测#46":"第一空核对动词与“生命的力量”的搭配，第二空结合“种子诺亚方舟”和后文对种质库用途的说明辨析比喻。","江苏 2025 C类 行测#46":"第一空核对动词与“生命的力量”的搭配，第二空结合“种子诺亚方舟”和后文对种质库用途的说明辨析比喻。"}},"readings":[{"origin":"k-54de2cb84a462f53","title":"安家","qs":["江苏 2025 C类 行测#46"],"definition":"“安家”本指安置家庭、在一处定居，也可比喻在某处得到较长久的安置。","explanation":"材料把国家作物种质库比作“种子诺亚方舟”，并说明其使命是长久、安全地保存种质资源。给“安家”加引号，把种子写成在库里落户，突出长期安置。“休憩”侧重短时休息，“冬眠”侧重休眠状态。","evidence":"长久、安全地保存好这些种质资源","doubt":"","references":[]},{"origin":"k-7c0c39865e13557f","title":"安家","qs":["江苏 2025 A类 行测#46"],"definition":"“安家”指安置家庭或在某处定居，也可用来比喻事物在某处得到稳定安置。","explanation":"材料称国家作物种质库为“种子诺亚方舟”，并说明其使命是长久、安全地保存种质资源。第二空让种子在库里“安家”，把长期保存写成有了稳定的住处。“休憩”侧重短暂休息，“冬眠”侧重休眠状态，两者都少了安置的意味。","evidence":"“安家”指安置家庭","doubt":"","references":[]}]},"k-6cdbb3ee97f86238":{"review":{"definition":"甲比乙多 k 倍，表示甲与乙的差是乙的 k 倍，因此甲是乙的 1+k 倍。","explanation":"本题以已完成升级的企业数为基准。设其为 x 家，未完成升级的企业数就是 x+0.6x=1.6x 家。两类企业共2080家，所以2.6x=2080，解得已完成升级的有800家。","references":[],"evidence":"未完成升级的规模以上企业比已完成升级的多0.6倍","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-57dd40cabf9b2c29":{"review":{"definition":"溶质质量分数等于溶质质量除以溶液总质量。本题以质量百分比表示酒精溶液的浓度。","explanation":"甲瓶先加20克水，再加30克纯酒精，恢复到原浓度，说明净加入的50克中，酒精所占比例与原溶液相同，故原浓度为30÷50=60%。设每瓶原有 m 克。甲瓶只加水时浓度为0.6m/(m+20)，乙瓶加50克30%的酒精溶液后浓度为(0.6m+15)/(m+50)。两式相等，得到 m=100。","references":[],"evidence":"若继续在甲瓶中加入30克纯酒精，溶液又恢复到最初浓度","disposition":"独立词条","basis":"据原题和解析编释。","title":"溶质质量分数","related":[],"examFocus":{"江苏 2025 A类 行测#63":"用溶质质量分数表示两瓶加料后的浓度，分别利用甲瓶加纯酒精后恢复原浓度和两瓶第一次加料后浓度相等的条件。"}},"readings":[{"origin":"k-57dd40cabf9b2c29","title":"溶质质量分数","qs":["江苏 2025 C类 行测#63"],"definition":"溶质质量分数等于溶质质量除以溶液总质量。本题以质量百分比表示酒精溶液的浓度。","explanation":"甲瓶先加20克水，再加30克纯酒精，恢复到原浓度，说明净加入的50克中，酒精所占比例与原溶液相同，故原浓度为30÷50=60%。设每瓶原有 m 克。甲瓶只加水时浓度为0.6m/(m+20)，乙瓶加50克30%的酒精溶液后浓度为(0.6m+15)/(m+50)。两式相等，得到 m=100。","evidence":"若继续在甲瓶中加入30克纯酒精，溶液又恢复到最初浓度","doubt":"","references":[]},{"origin":"k-820539a9a0028374","title":"溶质质量分数","qs":["江苏 2025 A类 行测#63"],"definition":"溶质质量分数是溶质质量占溶液总质量的比例，通常用百分数表示。","explanation":"本题按质量分数计算酒精浓度。设两瓶初始质量均为 m 克、浓度均为 n。甲瓶前后共加入 50 克液体，其中酒精 30 克，恢复原浓度意味着 (mn＋30)÷(m＋50)＝n，得到 n＝60%。第一次加液时，甲瓶只加水，酒精仍为 0.6m 克。乙瓶加入的 50 克溶液含 15 克酒精。两瓶此时浓度相等，故 0.6m÷(m＋20)＝(0.6m＋15)÷(m＋50)，解得 m＝100，选 A。","evidence":"50克浓度为30%的酒精溶液","doubt":"","references":[]}]},"k-04604bafc577351f":{"review":{"definition":"元宇宙依托数字技术形成可供用户参与和互动的虚拟环境。虚拟性是这一概念的基本属性。","explanation":"题干用“元宇宙：虚拟性”表示事物与其必然属性的对应。实验可能着眼于验证已有结论，决策可能缺乏可行性，宣传也可以只面向特定群体。D项“总结：概括性”同样把事物与其必然具有的属性配对。","references":[],"evidence":"元宇宙一定具有虚拟性","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-15883faf9992c8b3":{"review":{"definition":"总结可以指归纳已有材料、经验或情况，提炼出要点或结论，也可以指由此形成的结果。","explanation":"D项取总结所形成的结果这一义项。把具体材料归纳为要点或结论，本身就包含概括，因此“总结：概括性”与“元宇宙：虚拟性”同属必然属性的对应。","references":[],"evidence":"总结指总结后概括出来的结论。","disposition":"独立词条","basis":"据原题和解析编释。","title":"总结","related":[],"examFocus":{"江苏 2025 A类 行测#71":"先辨清各组前一个词的义项，再判断后面的属性是定义所必需的，还是只在某些情况下具备。"}},"readings":[{"origin":"k-15883faf9992c8b3","title":"总结","qs":["江苏 2025 C类 行测#71"],"definition":"总结可以指归纳已有材料、经验或情况，提炼出要点或结论，也可以指由此形成的结果。","explanation":"D项取总结所形成的结果这一义项。把具体材料归纳为要点或结论，本身就包含概括，因此“总结：概括性”与“元宇宙：虚拟性”同属必然属性的对应。","evidence":"总结指总结后概括出来的结论。","doubt":"","references":[]},{"origin":"k-6c97ee5e3728008a","title":"总结","qs":["江苏 2025 A类 行测#71"],"definition":"总结是对已有情况、经验或材料加以归纳概括，也指由此得出的结论。","explanation":"归纳概括是总结的核心，因此D项“总结：概括性”与“元宇宙：虚拟性”同属必然属性关系。相比之下，决策可以追求可行性，但具体决策能否实行还取决于实际条件。","evidence":"总结指总结后概括出来的结论。","doubt":"","references":[]}]},"k-f7df50076623517a":{"review":{"definition":"在本题解析中，“热极生风”字面指天气酷热后起风，也用来表达某种状态达到极端后发生变化。","explanation":"解析将“热极”读作原因，将“生风”读作结果。它与“穷极思变”都有“极”字，分别指酷热和极度困顿，后半句写各自引发的变化。这里说明的是短语的题内含义。","references":[],"evidence":"一个地方热得太厉害，不久便会产生大风","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-9585421d11674de5":{"review":{"definition":"原题引文：因为“人闲”所以“生病”","explanation":"所给解析把C项的“人闲→生病”与“石闲→生苔”都读作一种状态引出变化，并把“闲”读得较重，以对应“热极→生风”和“穷极→思变”。如果按主体排列，题干从自然现象说到人，A项从鼓说到人，也符合这一顺序。","references":[{"source":"web-9ef6257528f8a50b","location":"目录，正念篇","quote":"人闲生病，石闲生苔。"}],"evidence":"因为“人闲”所以“生病”","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-ad630aea021fd44b":{"review":{"definition":"原题引文：闲置的石头很容易长出青苔","explanation":"所给解析把“石闲”当作起始状态，把“生苔”当作随后出现的变化，因此将C项两句并列，与题干中“热极”引出“生风”、“穷极”引出“思变”的结构相配。题干用“极”明示程度，C项的“闲”字只写出闲置状态。","references":[{"source":"web-9ef6257528f8a50b","location":"目录，正念篇","quote":"人闲生病，石闲生苔。"}],"evidence":"闲置的石头很容易长出青苔","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-6cfad6113c8681ea":{"review":{"definition":"“上岸”本指登上陆地。在考试招录语境中，常用来指考生通过选拔并获得录取。","explanation":"B项“下海”和“上岸”按本义都是动作，第二词“上岸”又有“录取”的引申义，和题干第二词“鸿雁”代称第三词“书信”的位置一致。A项可表示“鼓劲”的“加油”位于第一位。","references":[],"evidence":"“上岸”指舍舟登陆，也指考生被录取","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a64c87b891ac4752":{"review":{"definition":"增长幅度反映同一指标在两个时期之间增加了多少，若以百分比表示，则以基期数值为分母。构成比重是同一统计范围内某一部分占总体的比例，以总体数值为分母。","explanation":"第96题中，甲用折叠屏手机销量连续多年保持两位数增长来预测研发趋势，乙用其销量仅占手机整体销量的1.6%来质疑增加投入的必要性。销量基数较小时，增速高与市场份额小可以同时成立。C项同样从数量增长转向相对比例：错别字检出量随出版总量增加而上升，检出率却维持在万分之一左右，乙据此质疑增员的必要性。B项则是把张明的提分幅度与全班平均提分幅度比较，两边衡量的都是增幅。","references":[],"evidence":"仍只占手机整体销量的1.6%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-68e7506e8c8ec295":{"review":{"definition":"平均价格是单位商品对应的平均金额，等于同一统计口径下的总金额除以总数量。","explanation":"第130题 B 项比较2023年我国柴油机的进口均价和出口均价。进口额13.4亿美元除以进口量5.7万台，约为2.35万美元/台。出口额13.2亿美元除以出口量58.9万台，约为0.224万美元/台。分别求出两项均价后，才能比较每台柴油机的价格差异。","references":[],"evidence":"2023年我国柴油机进口数量为5.7万台，进口额为13.4亿美元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4b3b80ca6aa06ae6":{"review":{"definition":"基准量为正时，“甲是乙的几倍”用甲除以乙计算。“甲比乙高几倍”用甲与乙的差除以乙，等于甲与乙的比值减1。","explanation":"第130题按表中原始数据计算，柴油机进口均价是出口均价的约10.49倍，因此进口均价比出口均价高约9.49倍。B 项说“高10倍多”，与计算结果不符。题干问的是“不能从上述资料推出”的选项，所以选 B。","references":[],"evidence":"高几倍=多几倍=是几倍-1","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d5ca84f166dc73e2":{"sources":[{"id":"ad0c15674719fa64","label":"总论 · 哲学的含义","topic":"马克思主义哲学","category":"非时政","text":"一、哲学的含义\n哲学是系统化、理论化的世界观，是世界观和方法论的统一。","source":{"doc":"3ccc56f4000d1642c2d1","first":1,"last":1,"page":1,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-7fbab47291c69048":{"sources":[{"id":"44d62ac04bfed395","label":"唯物论 · 物质","topic":"马克思主义哲学","category":"非时政","text":"一、物质\n1.物质是标志客观实在的哲学范畴，物质的唯一特性是客观实在性。\n2.物质的根本属性和存在方式是运动。\n（粉笔敲黑板：注意区分物质的唯一特性和根本属性分别对应的内容）\n物质和运动是不可分割的，物质是运动着的物质，运动是物质的运动。\n静止是一种特殊的运动。\n世界上一切事物的存在和发展都是绝对运动和相对静止的统一。\n（粉笔敲黑板：此处常见的考法是题干给出古语或材料，问题干是否体现了绝对运动和\n相对静止的统一。因此，大家需要储备一些常见的古语，例如： ①年年岁岁花相似，岁岁\n年年人不同； ②风定花犹落，鸟鸣山更幽）","source":{"doc":"3ccc56f4000d1642c2d1","first":1,"last":2,"page":1,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-8b1bb76921a0884f":{"sources":[{"id":"e1b6cab861af4ddb","label":"认识论 · 实践","topic":"马克思主义哲学","category":"非时政","text":"一、实践\n含义：实践是人类能动地改造世界的客观物质活动。\n特征：客观物质性、直接现实性、自觉能动性、社会历史性。\n基本形式：生产实践、社会实践、科学实验。","source":{"doc":"3ccc56f4000d1642c2d1","first":5,"last":5,"page":5,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-d6674c45a19ed076":{"sources":[{"id":"8c2bf41475ff9995","label":"商品经济理论 · 商品","topic":"马克思主义政治经济学","category":"非时政","text":"一、商品\n商品是用来交换的能满足人们某种需要的劳动产品，具有使用价值和价值两种属性。\n1.使用价值：能满足人们某种需要的物品的效用，即物品的有用性。这是商品本身就有、\n天生自带的属性，叫作自然属性。\n2.价值：凝结在商品中的无差别的人类劳动。是商品的社会属性。\n3.商品二因素之间的关系\n统一性：作为一个商品，必须同时拥有使用价值和价值，其中使用价值是价值的物质承\n担者，没有使用价值的物品则没有价值，价值寓于使用价值之中。\n对立性：生产者只能让渡商品的使用价值来获得其价值，而消费者要让渡商品的价值来\n获得其使用价值，故二者相互排斥，不可兼得。\n（粉笔敲黑板：通过关键词理解商品的含义，区分价值和使用价值）","source":{"doc":"3ccc56f4000d1642c2d1","first":8,"last":8,"page":8,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-7ce6f443ba66ca17":{"sources":[{"id":"71cb8452916f2c46","label":"剩余价值理论 · 剩余价值","topic":"马克思主义政治经济学","category":"非时政","text":"一、剩余价值\n1.含义：剩余价值是雇佣工人所创造的并被资本家无偿占有的超过劳动力价值的那部分\n价值。\n2.生产方法：绝对剩余价值是指在必要劳动时间不变的条件下，通过延长工作时间所获\n得的剩余价值；\n相对剩余价值是指在工作时间不变的条件下，由于缩短必要劳动时间而相对延长剩余劳\n动时间所生产的剩余价值。相对剩余价值是各个资本家追逐超额剩余价值而实现的。\n（超额剩余价值是指单个资本家通过提高劳动生产率使商品的个别价值低于社会价值\n而比一般资本家多得的那部分价值。）\n（粉笔敲黑板：理解并能够区分绝对剩余价值、相对剩余价值和超额剩余价值）","source":{"doc":"3ccc56f4000d1642c2d1","first":9,"last":9,"page":9,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-3d064a3e81bf28f4":{"sources":[{"id":"33f9e33191c8bd04","label":"剩余价值理论 · 资本","topic":"马克思主义政治经济学","category":"非时政","text":"二、资本\n资本在资本主义生产过程中以生产资料和劳动力两种形态存在。根据这两部分资本在剩\n余价值生产中所起的不同作用，可将资本分为不变资本和可变资本。\n不变资本，是指以生产资料形态存在的那部分资本，其价值在生产过程中一次或多次转\n移到新产品中去，不会发生增殖。\n可变资本，是指以劳动力价值形态存在的那部分资本，在生产过程中可以使价值增殖。\n可变资本只有劳动力。\n（粉笔敲黑板：明确不变资本和可变资本以什么形态存在，会不会产生增殖）","source":{"doc":"3ccc56f4000d1642c2d1","first":10,"last":10,"page":10,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-f58189dead60fd23":{"sources":[{"id":"78cbd99234fbb2c0","label":"剩余价值理论 · 资本积累的含义和实质","topic":"马克思主义政治经济学","category":"非时政","text":"三、资本积累的含义和实质\n1.含义：资本积累就是剩余价值的资本化。把榨取的剩余价值作为资本再次投入生产，\n可以给资本家带来更多的剩余价值，简单理解就是“钱生钱”的过程。\n2.实质：资本积累的实质是资本家通过无偿占有工人劳动的一部分，来扩大无偿占有工\n人劳动的权力。","source":{"doc":"3ccc56f4000d1642c2d1","first":10,"last":10,"page":10,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-7ab755a1a31ae304":{"sources":[{"id":"cb5ae3322fd2f638","label":"城镇调查失业率","topic":"经济指标与宏观调控","category":"非时政","text":"2.城镇调查失业率\n调查失业率指根据抽样调查方法测算得到的失业人口占就业人口与失业人口之和的百\n分比，计算方法为：调查失业率=失业人口/（失业人口+就业人口）×100%。调查失业率与\n经济增长率、物价指数和国际收支平衡状况并称为四大宏观经济指标，是分析宏观经济走\n势和就业形势变化的重要依据，在各个国家均是最重要的经济指标之一。\n——国家统计局","source":{"doc":"6cbfb01fe723bba64b75","first":3,"last":3,"page":3,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-0d1e80a0896d9222":{"sources":[{"id":"a36f06caa3089ea0","label":"存款准备金率","topic":"经济指标与宏观调控","category":"非时政","text":"1.存款准备金率\n存款准备金是指金融机构为保证客户提取存款和资金清算需要而准备的资金，金融机构\n按规定向中央银行缴纳的存款准备金占其存款总额的比例就是存款准备金率。\n——中国人民银行","source":{"doc":"6cbfb01fe723bba64b75","first":6,"last":6,"page":6,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-62fa06212681affa":{"sources":[{"id":"f3e3521b38b25759","label":"“两重”建设","topic":"年度政府工作","category":"时政","text":"3.“两重”建设\n“两重”建设，即国家重大战略实施和重点领域安全能力建设。发行超长期特别国债支\n持“两重”建设，是实施一揽子增量政策推动经济高质量发展的一项重大举措。\n——国家发展和改革委员会","source":{"doc":"6cbfb01fe723bba64b75","first":6,"last":6,"page":6,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-1e75d0e7dee24a7f":{"sources":[{"id":"798fc8a6855938e2","label":"美丽中国先行区建设","topic":"生态环境与能源","category":"非时政","text":"美丽中国先行区建设\n建设美丽中国先行区是全面推进美丽中国建设的重要抓手，是构建美丽中国建设新格\n局的关键支撑。要以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二\n十届二中、三中全会精神，全面贯彻习近平生态文明思想，牢固树立和践行绿水青山就是金\n山银山的理念，落实全国生态环境保护大会要求，聚焦全面推进美丽中国建设中心任务，以\n深化污染防治攻坚、改善生态环境质量、增进民生福祉为着力点，坚持改革创新、重点突\n破、示范带动，在区域、省域、城市、县域各层级，聚焦推动绿色低碳发展、促进生态环境\n根本好转、加强生态保护修复、筑牢生态安全底线、深化生态文明体制改革等目标任务，分\n级分类建设美丽中国先行区（以下简称先行区），到 2027 年底前形成一批实践创新和制度\n创新成果，久久为功建成若干各美其美、群众满意的示范样板，为全面推进美丽中国建设积\n累经验、树立标杆。\n——《关于建设美丽中国先行区的实施意见》","source":{"doc":"6cbfb01fe723bba64b75","first":12,"last":12,"page":12,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-cc7318d22d6f2c0a":{"sources":[{"id":"838dc34ef13b66d0","label":"数字中国建设","topic":"产业、科技与对外开放","category":"非时政","text":"5.数字中国建设\n数字中国建设按照“2522”的整体框架进行布局，即夯实数字基础设施和数据资源体系\n“两大基础”，推进数字技术与经济、政治、文化、社会、生态文明建设“五位一体”深度\n融合，强化数字技术创新体系和数字安全屏障“两大能力”，优化数字化发展国内国际“两\n个环境”。","source":{"doc":"6cbfb01fe723bba64b75","first":17,"last":17,"page":17,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-03388787b8da4184":{"sources":[{"id":"fb6306d8b8dc4559","label":"粮食综合生产能力","topic":"农业与城乡治理","category":"非时政","text":"2.粮食综合生产能力\n粮食综合生产能力是指在一定技术条件和生产要素投入下国内可以稳定达到的粮食产\n出能力，是反映国家粮食安全保障能力的重要指标。新设置该指标，有利于引导各方面把提\n高粮食供应保障能力摆在突出位置，守住“谷物基本自给、口粮绝对安全”的底线。","source":{"doc":"6cbfb01fe723bba64b75","first":19,"last":19,"page":19,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-1cbb6557584f8fad":{"sources":[{"id":"f463c54df15594b2","label":"能源综合生产能力","topic":"生态环境与能源","category":"非时政","text":"3.能源综合生产能力\n能源综合生产能力指国内煤炭、石油、天然气、非化石能源等一次能源的综合生产能力，\n是反映国家能源安全保障能力的重要指标。设置该指标，有利于引导提高国内能源供给能力，\n将能源自给率稳定在合理水平。","source":{"doc":"6cbfb01fe723bba64b75","first":19,"last":20,"page":19,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-a07846776ed67c7d":{"sources":[{"id":"f9bf3190221d88e4","label":"新产业新赛道","topic":"产业、科技与对外开放","category":"非时政","text":"1.新产业新赛道\n新赛道新产业是新质生产力的载体，发展新质生产力必然落实到与之相适应的新赛道和\n新产业上。如以国家标准提升和引领传统产业优化升级，必然要以传统产业为基础载体，融\n合智能化、绿色化新技术；完善新一代信息技术、人工智能、新能源、高端装备等战略性新\n兴产业的发展政策和治理体系，建立未来产业投入增长机制，目的是顺畅新质生产力发展的\n体制机制。","source":{"doc":"6cbfb01fe723bba64b75","first":20,"last":20,"page":20,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-70c5a61580d4682c":{"sources":[{"id":"13ce7b4cf5dc114f","label":"新型能源体系","topic":"生态环境与能源","category":"非时政","text":"2.新型能源体系\n建设新型能源体系，就是在传统能源体系基础上，逐步建立以非化石能源为供应主体、\n化石能源为兜底保障、新型电力系统为关键支撑、绿色智慧节约为用能导向，清洁低碳安全\n高效的能源体系。","source":{"doc":"6cbfb01fe723bba64b75","first":20,"last":20,"page":20,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-8895db69aedcad85":{"sources":[{"id":"0a7fde78b5c0c464","label":"新型基础设施","topic":"产业、科技与对外开放","category":"非时政","text":"3.新型基础设施\n新型基础设施是指提供数字转型、智能升级、融合创新等服务的基础设施体系，主要包\n括信息基础设施、融合基础设施和创新基础设施。信息基础设施是指基于新一代信息技术演\n化生成的基础设施，如第五代移动通信技术、物联网、数据中心、人工智能、卫星通信、区\n块链基础设施等。融合基础设施是指传统基础设施应用新一代信息技术进行智能化改造后所\n形成的基础设施形态，包括以工业互联网、智慧交通物流设施、智慧能源系统为代表的新型\n生产性设施，和以智慧民生基础设施、智慧环境资源设施、智慧城市基础设施等为代表的新\n型社会性设施。创新基础设施是指支撑科学研究、技术开发、新产品和新服务研制的具有公\n益属性的基础设施，包括重大科技基础设施、科教基础设施、产业技术基础设施等。","source":{"doc":"6cbfb01fe723bba64b75","first":20,"last":21,"page":20,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-ee8eda54b1ee219c":{"sources":[{"id":"7f66b4d633e357e5","label":"“硬投资”","topic":"经济指标与宏观调控","category":"非时政","text":"4.“硬投资”\n“硬投资”是指必需的基础设施建设，比如，要逐步增加普通高中学位就需要相应的教\n学场所，要实现老有所养、养有所乐，就需要增加养老场所等。","source":{"doc":"6cbfb01fe723bba64b75","first":21,"last":21,"page":21,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-7b20c11c5dec39f4":{"sources":[{"id":"aa3fd0193fc07bf0","label":"“软建设”","topic":"经济指标与宏观调控","category":"非时政","text":"5.“软建设”\n“软建设”是指为保障项目建设而推进的制度建设，并根据需要制定出台相关专项规划\n和实施方案。","source":{"doc":"6cbfb01fe723bba64b75","first":21,"last":21,"page":21,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-153c5d3d04ac27f2":{"sources":[{"id":"565171d1d657d930","label":"赤字率","topic":"经济指标与宏观调控","category":"非时政","text":"2.赤字率\n财政赤字率，是指财政赤字与同期国内生产总值（GDP）的比例。从近年我国赤字率安\n排来看，2024 年为 3%，2025 年提高到 4%左右，今年继续按 4%左右安排。\n赤字率延续 4%左右，是历史上比较高的水平，体现了今年财政政策继续更加积极的取\n向。虽然今年赤字率和去年一样，但由于 GDP 这个分母变大了，所以今年赤字规模比上年增\n加 2300 亿元。","source":{"doc":"6cbfb01fe723bba64b75","first":23,"last":23,"page":23,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-5be423f7eddebe6f":{"sources":[{"id":"2d18c5c2ed0e2deb","label":"服务业","topic":"产业、科技与对外开放","category":"非时政","text":"3.服务业\n第一产业是指农、林、牧、渔业（不含农、林、牧、渔专业及辅助性活动）。第二产业\n是指采矿业（不含开采专业及辅助性活动），制造业（不含金属制品、机械和设备修理业），\n电力、热力、燃气及水生产和供应业，建筑业。第三产业即服务业，是指除第一产业、第二\n产业以外的其他行业，包括：批发和零售业，交通运输、仓储和邮政业，住宿和餐饮业，信\n息传输、软件和信息技术服务业，金融业，房地产业，租赁和商务服务业，科学研究和技术\n服务业，水利、环境和公共设施管理业，居民服务、修理和其他服务业，教育，卫生和社会\n工作，文化、体育和娱乐业，公共管理、社会保障和社会组织，国际组织，以及农、林、牧、\n渔业中的农、林、牧、渔专业及辅助性活动，采矿业中的开采专业及辅助性活动，制造业中\n的金属制品、机械和设备修理业。","source":{"doc":"6cbfb01fe723bba64b75","first":26,"last":26,"page":26,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-cf7af90827570bfd":{"sources":[{"id":"4426c59af6105c80","label":"加快高水平科技自立自强","topic":"年度政府工作","category":"时政","text":"推动科技创新和产业创新深度融合。建设北京（京津冀）、上海（长三角）、粤港澳\n大湾区国际科技创新中心，打造世界级科技创新策源地。强化企业创新主体地位，支持科\n技领军企业牵头组建创新联合体，提高承担国家重大科技项目比例。加强中试验证平台建设，\n完善新兴领域知识产权保护制度，加快重大科技成果高效转化应用。加强科技创新全链条全\n生命周期金融服务，对关键核心技术领域的科技型企业，常态化实施上市融资、并购重组“绿\n色通道”机制，以科技金融支持创新创造。\n一体推进教育科技人才发展。建立健全一体推进的协调机制，强化规划衔接、政策协同、\n资源统筹、评价联动。完善人才培养与经济社会发展需要适配机制，分类推进高校改革，\n动态调整学科专业，启动新一轮“双一流”①建设，建设国家交叉学科中心，加大拔尖创新\n人才自主培养力度。加快建设国家战略人才力量，加强一流科技领军人才和青年人才引育，\n推进卓越工程师、大国工匠、高技能人才培养。高标准推进人才高地和人才平台建设，促\n进人才区域协调发展。深化人才发展体制机制改革，完善以创新能力、质量、实效、贡献为\n导向的评价体系，畅通人才交流通道，促进各类人才竞相成长、各展其能。","source":{"doc":"6cbfb01fe723bba64b75","first":27,"last":27,"page":27,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"08fbc6d8405a3842","label":"高水平科技自立自强","topic":"产业、科技与对外开放","category":"非时政","text":"4.高水平科技自立自强\n在关键核心技术领域实现自主可控，不依赖外部技术供给，同时具备持续创新能力，能\n够引领科技发展方向，为经济社会发展提供坚实科技支撑，是国家发展的战略支撑。","source":{"doc":"6cbfb01fe723bba64b75","first":17,"last":17,"page":17,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"},{"id":"a68d785a35e10e78","label":"加快高水平科技自立自强","topic":"年度政府工作","category":"时政","text":"（三）加快高水平科技自立自强。抓住新一轮科技革命和产业变革历史机遇，全面增\n强自主创新能力，为高质量发展①提供科技支撑。\n加强原始创新和关键核心技术攻关。发挥新型举国体制②优势，全链条推进关键核心技\n术攻关，组织实施好重大科技项目，强化战略前沿领域布局，产出更多原创性成果。继续提\n高基础研究投入比重，加大长期稳定支持。统筹国家战略科技力量建设，深化科研院所改革，\n加强国家实验室和重大科技任务、重大科技基础设施统筹部署，全面强化科技基础条件自主\n保障。加强科学技术普及。弘扬科学家精神③，深化科技评价体系改革，优化有利于原创性、\n颠覆性创新的环境。","source":{"doc":"6cbfb01fe723bba64b75","first":26,"last":27,"page":26,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-08fc74c1c8413b81":{"sources":[{"id":"91979075c3e6c911","label":"“内卷式”竞争","topic":"发展与治理","category":"非时政","text":"3.“内卷式”竞争\n内卷式竞争，主要表现为在同一领域内过度竞争、资源消耗大但效益提升有限的现象。","source":{"doc":"6cbfb01fe723bba64b75","first":28,"last":28,"page":28,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-b2893aaa010ff363":{"sources":[{"id":"a99150c81cc39c7c","label":"国有资本","topic":"发展与治理","category":"非时政","text":"1.国有资本\n国有资本是指国家对企业各种形式的出资所形成的权益，包括国有独资企业、国有控\n股及参股企业的所有者权益中国家享有的份额。","source":{"doc":"6cbfb01fe723bba64b75","first":29,"last":29,"page":29,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-c13bee8b5040c26a":{"sources":[{"id":"c9009f5add19e0d6","label":"数字贸易","topic":"产业、科技与对外开放","category":"非时政","text":"1.数字贸易\n数字贸易是指以数据为关键生产要素、数字服务为核心、数据订购与交付为主要特征的\n贸易，是数字经济和高水平对外开放的重要组成部分。","source":{"doc":"6cbfb01fe723bba64b75","first":31,"last":31,"page":31,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-10a99f13c4dec94d":{"sources":[{"id":"3c5bec9cce016d1d","label":"绿色贸易","topic":"产业、科技与对外开放","category":"非时政","text":"2.绿色贸易\n发展绿色贸易，既要加快发展绿色货物贸易，也要加快发展绿色服务贸易。发展绿色货\n物贸易，就是要在货物生产的整个生命周期中，从原材料生产、货物研发设计、加工制造、\n运输、使用，到最终处置，对环境影响最小化。","source":{"doc":"6cbfb01fe723bba64b75","first":32,"last":32,"page":32,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-819d9438b9d8833a":{"sources":[{"id":"1616b8b5c8fdf88d","label":"重大标志性工程和“小而美”民生项目","topic":"发展与治理","category":"非时政","text":"3.重大标志性工程和“小而美”民生项目\n党的二十届三中全会审议通过的《中共中央关于进一步全面深化改革、推进中国式现代\n化的决定》提出，统筹推进重大标志性工程和“小而美”民生项目。\n重大标志性工程指规模宏大、具有战略意义的基础设施或经济项目，通常为国家长远发\n展提供核心支撑；小而美民生项目指规模较小、直接改善民众日常生活质量的项目，注重实\n效与可感知性，旨在解决民众关心的具体问题。","source":{"doc":"6cbfb01fe723bba64b75","first":32,"last":33,"page":32,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-fce6cdec9af3d2a9":{"sources":[{"id":"e9d0d7601968f8ce","label":"西部陆海新通道","topic":"产业、科技与对外开放","category":"非时政","text":"4.西部陆海新通道\n西部陆海新通道位于中国西部地区腹地，北接丝绸之路经济带，南连 21 世纪海上丝绸\n之路，协同衔接长江经济带，在区域协调发展格局中具有重要战略地位。该通道利用铁路、\n公路、水运、航空等多种运输方式，由重庆向南经贵州等省份，通过广西北部湾等沿海沿边\n口岸，通达新加坡及东盟主要物流节点，运行时间比经东部地区出海节约 10 天左右。向北\n与中欧班列连接，利用兰渝铁路及西北地区主要物流节点，通达中亚、南亚、欧洲等区域。\n“陆海新通道”已与中欧班列和长江黄金水道实现联通，并已初步实现丝绸之路经济带和\n21 世纪海上丝绸之路的有机衔接。","source":{"doc":"6cbfb01fe723bba64b75","first":33,"last":33,"page":33,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-bd50ece837e0f5d4":{"sources":[{"id":"7d9fd781d17f69b8","label":"“三农”","topic":"农业与城乡治理","category":"非时政","text":"1.“三农”\n“三农”，即农村、农业和农民。自 2004 年至 2026 年，中共中央、国务院已连续二十\n三年以中央一号文件的形式聚焦“三农”议题。","source":{"doc":"6cbfb01fe723bba64b75","first":33,"last":33,"page":33,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-399722655bbab774":{"sources":[{"id":"09d945517be41756","label":"开发式帮扶","topic":"农业与城乡治理","category":"非时政","text":"2.开发式帮扶\n开发式帮扶是指以促进农村低收入群体形成自我发展能力为目标的帮扶方式，旨在激发\n农村低收入群体的内生动力，从“被动受助”转向“主动发展”，提高自我“造血”能力。","source":{"doc":"6cbfb01fe723bba64b75","first":35,"last":35,"page":35,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-b58f5cbd6dacffd0":{"sources":[{"id":"8946d0f381a26309","label":"新型农村集体经济","topic":"农业与城乡治理","category":"非时政","text":"3.新型农村集体经济\n新型农村集体经济，是指在社会主义市场经济体制下，依托现代科技与管理理念，以农\n民为主体，对传统集体经济进行创新的经济形态。党的二十大报告提出，巩固和完善农村基\n本经营制度，发展新型农村集体经济。2023 年中央一号文件提出，构建产权关系明晰、治\n理架构科学、经营方式稳健、收益分配合理的运行机制，探索资源发包、物业出租、居间\n服务、资产参股等多样化途径发展新型农村集体经济。","source":{"doc":"6cbfb01fe723bba64b75","first":36,"last":36,"page":36,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-a6c4e4a315a36daa":{"sources":[{"id":"cc7e2aa6219f2cfa","label":"区域协调发展战略、区域重大战略、主体功能区战略和新型城镇化战略","topic":"发展与治理","category":"非时政","text":"1.区域协调发展战略、区域重大战略、主体功能区战略和新型城镇化战略\n区域协调发展战略：党的十八大以来，党中央强化举措推进西部大开发、东北振兴、中\n部崛起和东部率先发展，推动实施区域协调发展战略成为我国空间治理的基础战略。\n——求是网\n区域重大战略：是指党的十八大以来实施的京津冀协同发展、长江经济带发展、粤港澳\n大湾区建设、长三角一体化发展、黄河流域生态保护和高质量发展等若干区域发展战略。区\n域重大战略的实施充分考虑了我国国土空间类型多样、差别巨大的客观实际，旨在从不同空\n间尺度、区域类型和功能定位推动战略重点区域加快发展，发挥对区域经济发展布局的示范\n引领和辐射带动作用。\n——国家发改委\n主体功能区战略：主体功能区是基于不同区域的资源环境承载能力、现有开发密度和发\n展潜力等，将特定区域确定为特定主体功能定位类型的一种空间单元。按开发强度划分为优\n化开发、重点开发、限制开发和禁止开发四类地区，按主体功能划分为城市化地区、农产品\n主产区和重点生态功能区三类地区。2011 年，“十二五”规划纲要明确提出“实施主体功\n能区战略”，将其上升至国家战略层面，此后主体功能区战略一直是指导我国区域经济发展\n的重大战略。\n——国家治理网\n城镇化是现代化的必由之路，是解决农业、农村、农民问题的重要途径，是推动区域协\n调发展的有力支撑，是扩大内需和促进产业升级的重要抓手。深入实施以人为本的新型城镇\n化战略，要坚持以人民为中心的发展思想，坚持稳中求进工作总基调，完整准确全面贯彻\n新发展理念，加快构建新发展格局，着力推动高质量发展，以满足人民日益增长的美好生\n活需要为根本目的，以体制机制改革为动力，因势利导、顺势而为，因地制宜、分类施策，\n稳步提高城镇化质量和水平，充分释放新型城镇化蕴藏的巨大内需潜力，持续推动经济实现\n质的有效提升和量的合理增长，为中国式现代化提供强劲动力和坚实支撑。\n——坚持以人为本。把推进农业转移人口市民化作为新型城镇化首要任务，坚持人民城\n市人民建、人民城市为人民，充分尊重人的意愿，调动和发挥好人的积极性主动性创造性，\n促进人的全面发展和社会公平正义，使全体居民共享现代化发展成果。\n——坚持遵循规律。立足我国国情，遵循自然规律、经济规律特别是城市发展规律，统\n筹新型工业化、新型城镇化和乡村全面振兴，充分发挥市场在资源配置中的决定性作用，更\n好发挥政府作用，提高资源配置效率。\n——坚持分类施策。统筹各地区资源环境承载能力、功能定位、城镇化发展水平和人口\n规模，因地制宜确定城镇化建设重点方向，积极稳妥、扎实推进，不搞齐步走、“一刀切”，\n形成各具特色的发展路径。\n——坚持集约高效。在全国“三区三线”划定成果基础上，有效集聚各类要素，促进城\n镇发展与产业支撑、就业转移、人口集聚相统一，构建科学合理的城镇化格局，推动城乡融\n合、区域协调发展。\n——《深入实施以人为本的新型城镇化战略五年行动计划》","source":{"doc":"6cbfb01fe723bba64b75","first":37,"last":38,"page":37,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-64d365ef64bb0b18":{"sources":[{"id":"15733f04bfae52f3","label":"城市内涵式发展","topic":"农业与城乡治理","category":"非时政","text":"3.城市内涵式发展\n2025 年中央城市工作会议强调，当前和今后一个时期城市工作要“以坚持城市内涵式\n发展为主线”。《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》指出，\n要“坚持城市内涵式发展，大力实施城市更新，建设创新、宜居、美丽、韧性、文明、智\n慧的现代化人民城市”。\n城市内涵式发展是指与“外延式扩张”相对的一种城市发展模式，强调在城镇化进程进\n入中后期后，从依赖规模扩张转向注重内部质量提升、结构优化和效率改善，以实现城市的\n高质量、可持续发展。","source":{"doc":"6cbfb01fe723bba64b75","first":38,"last":38,"page":38,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-a1fb1d1184ce1460":{"sources":[{"id":"43e04b6be1671410","label":"城市治理智慧化精细化","topic":"农业与城乡治理","category":"非时政","text":"4.城市治理智慧化精细化\n城市治理智慧化，就是以大数据、云计算、物联网等技术手段提升城市运行效率、公共\n服务质量和风险应对能力等，通过全域感知、智能研判和精准执行，让城市具备动态响应与\n自我优化的能力。城市治理精细化，则是兼顾科学管理与人本关怀，通过将治理对象、流程、\n责任落到最小单元，使治理更具温度、更加精细、更体现公平性，持续提升人民群众的获得\n感、幸福感、安全感。城市治理智慧化和精细化两者协同，有助于形成科学化、规范化、人\n性化的治理模式，推动城市治理更高效、更有序、更有温度。\n习近平总书记指出：“一流城市要有一流治理，要注重在科学化、精细化、智能化上下\n功夫。既要善于运用现代科技手段实现智能化，又要通过绣花般的细心、耐心、巧心提高\n精细化水平，绣出城市的品质品牌。”推动城市治理智慧化精细化，注重创新城市治理的理\n念、模式、手段，是深入践行人民城市理念的重要举措，是推进以人为本的新型城镇化的\n必然要求，是提升城市治理水平、推进城市治理现代化的重要方面。","source":{"doc":"6cbfb01fe723bba64b75","first":38,"last":39,"page":38,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-fc10ef44d2f50821":{"sources":[{"id":"6e6c48f4e0e6ff3b","label":"构建就业友好型发展方式","topic":"就业、社保与公共服务","category":"非时政","text":"3.构建就业友好型发展方式\n党的二十届四中全会通过的《中共中央关于制定国民经济和社会发展第十五个五年规划\n的建议》对促进高质量充分就业作出重要部署，并提出“构建就业友好型发展方式”。习近\n平总书记深刻指出，“就业是最基本的民生，事关人民群众切身利益，事关经济社会健康发\n展，事关国家长治久安”，深刻揭示了就业与发展的辩证统一关系，为新时代就业工作提供\n了根本遵循。\n所谓就业友好型发展方式，就是将就业优先理念贯穿于经济社会发展全过程各领域，实\n现经济增长与就业扩容良性互动、结构优化与就业提质相互促进、创新驱动与就业赋能有机\n统一，让发展成果更多更公平惠及全体劳动者，为中国式现代化筑牢民生根基。\n——《人民网》","source":{"doc":"6cbfb01fe723bba64b75","first":40,"last":40,"page":40,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-9f369223fd942a5e":{"sources":[{"id":"dbbc0e18499f05a2","label":"加强体育、美育、劳动教育和心理健康教育","topic":"发展与治理","category":"非时政","text":"3.加强体育、美育、劳动教育和心理健康教育\n促进学生健康成长、全面发展。深入实施素质教育，健全德智体美劳全面培养体系，加\n快补齐体育、美育、劳动教育短板。落实健康第一教育理念，实施学生体质强健计划，中小\n学生每天综合体育活动时间不低于 2 小时，加强校园足球建设，有效控制近视率、肥胖率。\n推进学校美育浸润行动。实施劳动习惯养成计划，提升学生动手实践能力、解决复杂问题能\n力和社会适应能力。普及心理健康教育，建立全国学生心理健康监测预警系统，分学段完善\n服务工作机制。\n——《教育强国建设规划纲要（2024—2035 年）》","source":{"doc":"6cbfb01fe723bba64b75","first":41,"last":42,"page":41,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-ac573a06199ca0ed":{"sources":[{"id":"ae9d233d249830ad","label":"爱国卫生运动","topic":"就业、社保与公共服务","category":"非时政","text":"2.爱国卫生运动\n爱国卫生运动是中国共产党于 1952 年发起的群众性卫生活动，是我国历史上持续时间\n最长的群众性运动，其核心要素体现为“爱国是核心、卫生是根本、运动是方式”。该运动\n由毛泽东等老一辈革命家倡导，周恩来担任首任中央防疫委员会主任并主持反细菌战防疫体\n系建设，初期以反细菌战和防疫工作为核心，后发展为涵盖城乡环境治理、卫生设施改善的\n系统性工程。\n70 年来，在党的领导下，爱国卫生运动坚持以人民健康为中心，坚持预防为主，为改\n变城乡环境卫生面貌、有效应对重大传染病疫情、提升社会健康治理水平发挥了重要作用。\n——《习近平总书记在爱国卫生运动开展 70 周年之际作出重要指示》","source":{"doc":"6cbfb01fe723bba64b75","first":42,"last":42,"page":42,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-72ba3cd21ecb1873":{"sources":[{"id":"2456fc71bebec7a5","label":"实施积极应对人口老龄化国家战略","topic":"就业、社保与公共服务","category":"非时政","text":"2.实施积极应对人口老龄化国家战略\n优化居家为基础、社区为依托、机构为专业支撑、医养相结合的养老服务供给格局，强\n化以失能老年人照护为重点的基本养老服务，健全分级分类、普惠可及、覆盖城乡、持续发\n展的养老服务体系。\n——《中共中央 国务院关于深化养老服务改革发展的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":43,"last":43,"page":43,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-f1d0d8ca54f728eb":{"sources":[{"id":"e44bdc8ad38691cf","label":"碳达峰碳中和","topic":"生态环境与能源","category":"非时政","text":"2.碳达峰碳中和\n力争 2030 年前二氧化碳排放达到峰值，努力争取 2060 年前实现碳中和目标。\n——《2020 年 9 月 22 日习近平总书记在第 75 届联合国大会上的讲话》\n实现碳达峰碳中和是一场广泛而深刻的经济社会系统性变革。立足我国能源资源禀赋，\n坚持先立后破，有计划分步骤实施碳达峰行动。完善能源消耗总量和强度调控，重点控制化\n石能源消费，逐步转向碳排放总量和强度“双控”制度。\n——《党的二十大报告》\n习近平宣布中国新一轮国家自主贡献：到 2035 年，中国全经济范围温室气体净排放量\n比峰值下降 7%-10%，力争做得更好。非化石能源消费占能源消费总量的比重达到 30%以上，\n风电和太阳能发电总装机容量达到 2020 年的 6 倍以上、力争达到 36 亿千瓦，森林蓄积\n量达到 240 亿立方米以上，新能源汽车成为新销售车辆的主流，全国碳排放权交易市场覆\n盖主要高排放行业，气候适应型社会基本建成。\n——《2025 年 9 月 24 日习近平在联合国气候变化峰会发表视频致辞》","source":{"doc":"6cbfb01fe723bba64b75","first":46,"last":46,"page":46,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-4abab460b45d8fe7":{"sources":[{"id":"b1ad1404e2a812d0","label":"零碳园区和工厂建设","topic":"生态环境与能源","category":"非时政","text":"6.零碳园区和工厂建设\n零碳工厂建设是指通过技术创新、结构调整和管理优化 等减排措施，实现厂区内二氧\n化碳排放的持续降低、逐步趋 向于近零的过程。\n遵循原则：因业施策，系统推进。创新驱动，技术赋能。应减尽减，持续提升。统一规\n范，公开透明。\n主要目标：2026 年起，遴选一批零碳工厂，做好标杆引领。到 2027 年，在汽车、锂电\n池、光伏、电子电器、轻工、机械、算力设施等行业领域，培育建设一批零碳工厂。到 2030\n年，将零碳工厂建设逐步拓展至钢铁、有色金属、石化化工、建材、纺织等行业领域，探索\n传统高载能产业脱碳新路径，推广零碳工厂设计、融资、改造、管理等综合服务模式和系统\n解决方案，大幅提升产品全生命周期和全产业链管理能力，实现工厂碳排放的稳步下降。\n——《关于开展零碳工厂建设工作的指导意见》","source":{"doc":"6cbfb01fe723bba64b75","first":47,"last":47,"page":47,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-bf181a6c6d68c78b":{"sources":[{"id":"f7940a49cc7f3883","label":"着力稳定房地产市场","topic":"发展与治理","category":"非时政","text":"1.着力稳定房地产市场\n针对着力稳定房地产市场，2026 年的重点是：因城施策控增量、去库存、优供给，结\n合城市更新、城中村改造盘活利用存量用地，推动收购存量商品房用作保障性住房、安置房、\n宿舍、人才房等。优化和精准实施保障性住房供应，实施房屋品质提升工程，有序推进“好\n房子”建设；进一步发挥房地产项目“白名单”制度作用，支持房地产企业合理融资需求。\n——《全国住房城乡建设工作会议》","source":{"doc":"6cbfb01fe723bba64b75","first":48,"last":48,"page":48,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-0a7afca718d2aa93":{"sources":[{"id":"7b62b3ebc327bd69","label":"化解地方政府债务风险","topic":"发展与治理","category":"非时政","text":"2.化解地方政府债务风险\n地方性政府债务指有财政收入的地方政府及地方公共机构发行的债券，是地方政府根据\n信用原则、以承担还本付息责任为前提而筹集资金的债务凭证，其收入列入地方政府预算并\n由地方政府安排调度。\n我国地方政府债务分为法定债务和隐性债务。\n（1）地方政府法定债务：是指地方政府在法定债务限额之内，通过发行债券举借的债\n务，包括一般债和专项债。\n（2）地方政府隐性债务：是指地方政府在法定政府债务限额之外，直接或者承诺以财\n政资金偿还，以及违规提供担保等方式举借的债务。\n——《我国地方政府债务合并监管研究》","source":{"doc":"6cbfb01fe723bba64b75","first":48,"last":48,"page":48,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-62d9c7a7261583bb":{"sources":[{"id":"b3faa643c2c1a8ff","label":"化解金融领域风险","topic":"发展与治理","category":"非时政","text":"3.化解金融领域风险\n坚持把防控风险作为金融工作的永恒主题。金融既有管理和分散风险的功能，又自带风\n险基因。我国金融体量和复杂程度今非昔比，风险的系统性关联性大大增强。必须增强忧患\n意识，做好风险防控，增强金融体系韧性。\n加快建设金融强国的目标：\n金融强国，应当基于强大的经济基础，具有领先世界的经济实力、科技实力和综合国力，\n同时具备一系列关键核心金融要素：拥有强大的货币、强大的中央银行、强大的金融机构、\n强大的国际金融中心、强大的金融监管、强大的金融人才队伍。\n建设金融强国，必须加快构建中国特色现代金融体系：科学稳健的金融调控体系，结构\n合理的金融市场体系，分工协作的金融机构体系，完备有效的金融监管体系，多样化专业性\n的金融产品和服务体系，自主可控、安全高效的金融基础设施体系。\n——《求是》杂志文章《走好中国特色金融发展之路，建设金融强国》","source":{"doc":"6cbfb01fe723bba64b75","first":48,"last":49,"page":48,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-dc7155dea2e89fe0":{"sources":[{"id":"1643e39e38152c55","label":"港澳相关","topic":"发展与治理","category":"非时政","text":"1.港澳相关\n“一国两制”是中国特色社会主义的伟大创举，是香港、澳门回归后保持长期繁荣稳定\n的最佳制度安排，必须长期坚持。\n全面准确、坚定不移贯彻“一国两制”、“港人治港”、“澳人治澳”、高度自治的方\n针，坚持依法治港治澳，维护宪法和基本法确定的特别行政区宪制秩序。坚持和完善“一国\n两制”制度体系，落实中央全面管治权，落实“爱国者治港”、“爱国者治澳”原则，落实\n特别行政区维护国家安全的法律制度和执行机制。\n——《党的二十大报告》","source":{"doc":"6cbfb01fe723bba64b75","first":55,"last":55,"page":55,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-256efa250157e4f5":{"sources":[{"id":"7acd4e47d5931bc8","label":"全面从严治党","topic":"党政制度与理论","category":"非时政","text":"2.全面从严治党\n2014 年 12 月，习近平总书记在江苏考察时明确提出“全面从严治党”，并将其同\n全面建成小康社会、全面深化改革、全面依法治国并列，形成“四个全面”战略布\n局。\n2017 年 10 月，党的十九大将“坚持全面从严治党”确立为新时代坚持和发展中国\n特色社会主义的基本方略之一；十九大党章在总纲部分党的建设总体要求中，将“坚\n持党要管党、从严治党”修改为“坚持党要管党、全面从严治党”，这是“全面从严\n治党”首次写入党章。\n2021 年 11 月，党的十九届六中全会决议将“明确全面从严治党的战略方针”列为\n习近平新时代中国特色社会主义思想“十个明确”的重要内容。\n2022 年 10 月，党的二十大首次提出“健全全面从严治党体系”，强化管党治党全\n面系统布局、协同高效推进。","source":{"doc":"41195a191a57c1c36332","first":3,"last":3,"page":3,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-4cb2ef4d0c5ffc18":{"sources":[{"id":"28e9a3b60750eb3e","label":"“四个全面”战略布局","topic":"党政制度与理论","category":"非时政","text":"3.“四个全面”战略布局\n2014 年 12 月，习近平总书记在江苏调研时首次提出包括全面建成小康社会、全面\n深化改革、全面依法治国、全面从严治党的“四个全面”。\n2020 年 10 月，党的十九届五中全会对“四个全面”战略布局作出新的表述，将\n“全面建成小康社会”调整为“全面建设社会主义现代化国家”。\n——《中华人民共和国司法部》","source":{"doc":"41195a191a57c1c36332","first":4,"last":4,"page":4,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-38ac91bd82934cd1":{"sources":[{"id":"b79e4f5f5e1ba147","label":"国内国际两个大局","topic":"党政制度与理论","category":"非时政","text":"4.国内国际两个大局\n领导干部要胸怀两个大局，一个是中华民族伟大复兴的战略全局，一个是世界百\n年未有之大变局，这是我们谋划工作的基本出发点。\n——《中国共产党新闻网》","source":{"doc":"41195a191a57c1c36332","first":4,"last":4,"page":4,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-421baafeb9ef1283":{"sources":[{"id":"051e0dfed462853c","label":"国防和军队现代化建设","topic":"党政制度与理论","category":"非时政","text":"5.国防和军队现代化建设\n国防和军队现代化新“三步走”战略：到 2027 年实现建军一百年奋斗目标，到\n2035 年基本实现国防和军队现代化，到本世纪中叶把人民军队建成世界一流军队。\n——《解放军报》","source":{"doc":"41195a191a57c1c36332","first":4,"last":4,"page":4,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-958de1051c4f630c":{"sources":[{"id":"2979c5f4d345dad8","label":"党的建设","topic":"党政制度与理论","category":"非时政","text":"2.党的建设\n党的建设是指党为保持自己的性质而从事的一系列自我完善的活动，不仅包括党\n务工作，还包括党的政治建设、思想建设、组织建设、作风建设、纪律建设和制度建\n设等。\n（1）党的政治建设：是党的根本性建设，决定党的建设方向和效果。党的政治建\n设的首要任务是保证全党服从中央，坚持党中央权威和集中统一领导。\n（2）党的思想建设：是党的基础性建设。党的思想建设的首要任务是坚定理想信\n念。\n（3）新时代党的建设总要求是：坚持和加强党的全面领导，坚持党要管党、全面\n从严治党，以加强党的长期执政能力建设、先进性和纯洁性建设为主线，以党的政治\n建设为统领，以坚定理想信念宗旨为根基，以调动全党积极性、主动性、创造性为着\n力点，全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度\n建设贯穿其中，深入推进反腐败斗争，不断提高党的建设质量，把党建设成为始终走\n在时代前列、人民衷心拥护、勇于自我革命、经得起各种风浪考验、朝气蓬勃的马克\n思主义执政党。\n——《共产党员网》","source":{"doc":"41195a191a57c1c36332","first":6,"last":7,"page":6,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-554ebafbe8d1bfe3":{"sources":[{"id":"9e85630e3edf73c6","label":"习近平党建思想","topic":"党政制度与理论","category":"非时政","text":"1.习近平党建思想\n2026 年 6 月 15 日，全国党建工作座谈会在京召开，中共中央政治局常委、中央书\n记处书记蔡奇出席会议并讲话，中共中央政治局常委、中央纪律检查委员会书记李希\n出席会议。会议认为，党的十八大以来，以习近平同志为核心的党中央围绕建设什么\n样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党的重大时代课\n题，提出一系列新理念新思想新战略，形成习近平党建思想。\n习近平党建思想内涵要义可以概括为“十四个坚持”：\n①坚持党的领导是中国特色社会主义最本质的特征；\n②坚持党中央集中统一领导是党的领导的最高原则；\n③坚持全面从严治党是新时代党的建设的战略方针；\n④坚持不忘初心、牢记使命是党的宗旨立场和价值取向；\n⑤坚持以党的政治建设为统领是新时代党的建设的根本要求；\n⑥坚持用党的创新理论凝心铸魂是党的思想建设的根本任务；\n⑦坚持锤炼坚强党性是党员、干部的终身课题；\n⑧坚持健全上下贯通、执行有力的组织体系是党的优势所在、力量所在；\n⑨坚持建设堪当民族复兴重任的高素质干部队伍是关系党和国家事业的关键性问\n题；\n⑩坚持推进作风建设常态化长效化是保持党同人民群众血肉联系的有效途径；\n⑪坚持用严明的纪律管全党治全党是全面从严治党的治本之策；\n⑫坚持一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的\n基本方针；\n⑬坚持制度治党、依规治党是全面从严治党的长远和根本之策；\n⑭坚持落实管党治党政治责任是全面从严治党需要牢牢牵住的“牛鼻子”。","source":{"doc":"41195a191a57c1c36332","first":8,"last":8,"page":8,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-c391010d9a393446":{"sources":[{"id":"b1eb9615fcc7bc1a","label":"“四大考验”","topic":"党政制度与理论","category":"非时政","text":"1.“四大考验”\n执政考验、改革开放考验、市场经济考验、外部环境考验\n——共产党员网","source":{"doc":"41195a191a57c1c36332","first":9,"last":9,"page":9,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-c90bd88c8fb3f8a1":{"sources":[{"id":"279012b3cb08a7ad","label":"“四种危险”","topic":"党政制度与理论","category":"非时政","text":"2.“四种危险”\n精神懈怠危险、能力不足危险、脱离群众危险、消极腐败危险\n——共产党员网","source":{"doc":"41195a191a57c1c36332","first":9,"last":9,"page":9,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-7f5c8e521ac17463":{"sources":[{"id":"acd1720cecb17d6e","label":"自我净化、自我完善、自我革新、自我提高","topic":"党政制度与理论","category":"非时政","text":"2.自我净化、自我完善、自我革新、自我提高\n（1）自我净化，就是要过滤杂质、清除毒素、割除毒瘤。\n（2）自我完善，就是要修复肌体、健全机制、丰富功能。\n（3）自我革新，就是要与时俱进、自我超越。\n（4）自我提高，就是要有新本领、有新境界，永不僵化、永不停滞。\n——求是网","source":{"doc":"41195a191a57c1c36332","first":11,"last":11,"page":11,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-5e448b96b003ad3a":{"sources":[{"id":"84c20e60e45d939e","label":"政治领导力、思想引领力、群众组织力、社会号召力","topic":"党政制度与理论","category":"非时政","text":"3.政治领导力、思想引领力、群众组织力、社会号召力\n（1）党的政治领导力：政治领导力是马克思主义政党第一位的能力，主要体现为对\n党的路线方针政策等重大决策的领导，对国家发展道路、发展阶段、发展布局、国际形势\n等重大判断的领导，对捍卫政治立场、把准政治方向、坚持政治原则以及保持政治定力、\n防范政治风险等方面的领导。\n（2）党的思想引领力：是保证全党全国各族人民思想统一、步调一致的坚实基础，\n主要体现为坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科\n学发展观，全面贯彻习近平新时代中国特色社会主义思想，深入学习贯彻习近平党建思\n想；坚持马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，不断\n开辟马克思主义中国化时代化新境界；坚持用党的创新理论武装全党、教育人民，用马克\n思主义中国化时代化的最新成果引领社会向前发展。\n（3）党的群众组织力：是我们党坚如磐石、坚不可摧的力量根基。主要体现在两个\n方面，一是坚持党的群众路线，一切为了群众、一切依靠群众，从群众中来、到群众中去，\n坚信人民群众是历史的创造者，相信人民群众中蕴藏着无穷的智慧和力量，切实解决人民\n群众急难愁盼问题，不断增强人民群众的获得感、幸福感、安全感。二是党的各级组织和\n党员个人以身作则、率先垂范，处处走在群众的前面，用自身的言行为群众立标杆、作示\n范，以自身的先进性吸引群众、组织群众，巩固深厚的群众基础。\n（4）党的社会号召力：是党的先进性和感召力的重要体现。主要体现为党通过美好\n的愿景来鼓舞社会，以科学的战略安排来引导社会，以健全的组织来动员社会，以可触可\n感的成就来吸引社会，以廉洁亲民的形象来感染社会。\n——中国共产党新闻网","source":{"doc":"41195a191a57c1c36332","first":11,"last":12,"page":11,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-18bf53584dc0d31c":{"sources":[{"id":"47af976e39ce639c","label":"党性","topic":"党政制度与理论","category":"非时政","text":"1.党性\n党性是党员、干部立身、立业、立言、立德的基石。习近平总书记强调：“决定一个\n人如何的是品行，决定一名党员如何的是党性。”党性是党的固有本质属性在每一个党员\n身上的体现，是党的理想信念、立场宗旨、纪律作风等要求在每一个党员思想、言论和行\n为上的具体体现。中国共产党人的坚强党性，是我们党保持先进性和纯洁性、提高领导水\n平和执政能力的重要保证。","source":{"doc":"41195a191a57c1c36332","first":13,"last":13,"page":13,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-15044f3b14150602":{"sources":[{"id":"31dfc159f19dedf2","label":"作风建设","topic":"党政制度与理论","category":"非时政","text":"3.作风建设\n党的作风就是党的形象，关系人心向背，关系党的生死存亡。作风问题本质上\n是党性问题，核心是党同人民群众的关系问题。作风问题具有顽固性、反复性，决\n定了作风建设必须常抓不懈。","source":{"doc":"41195a191a57c1c36332","first":18,"last":18,"page":18,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-db2e693741c98433":{"sources":[{"id":"5e7483966a872659","label":"不敢腐不能腐不想腐","topic":"党政制度与理论","category":"非时政","text":"2.不敢腐不能腐不想腐\n“不敢”是前提，要以严格的执纪执法增强制度刚性，让党员、干部从害怕被查处的\n“不敢”走向敬畏党和人民、敬畏党纪国法的“不敢”;\n“不能”是关键，要科学配置权力，加强重点领域监督机制改革和制度建设，推动\n形成不断完备的制度体系、严格有效的监督体系；\n“不想”是根本，要靠加强理想信念教育、提高党性觉悟、涵养廉洁文化，筑牢拒腐防\n变的思想道德防线，夯实不忘初心、 牢记使命的思想根基。\n一体推进不敢腐、不能腐、不想腐，必须三者同时发力、同向发力、综合发力，把不敢腐\n的强大震慑效能、不能腐的刚性制度约束、不想腐的思想教育优势融于一体。","source":{"doc":"41195a191a57c1c36332","first":18,"last":19,"page":18,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]}}};
